// supervisor, or another working directory.
dotenv.config({ path: path.resolve(path.dirname(fileURLToPath(import.meta.url)), ".env") });

// A few older HR modules were originally written against SQLite and still use
// positional "?" placeholders plus datetime('now'). Keep the compatibility
// conversion at the database boundary so all of those routes execute safely on
// PostgreSQL while newer "$1" queries remain untouched.
function normalizeLegacySql(sql, params) {
  if (!Array.isArray(params) || params.length === 0 || sql.includes("$1") || !sql.includes("?")) {
    return sql.replaceAll("datetime('now')", "CURRENT_TIMESTAMP");
  }
  let index = 0;
  let quote = null;
  let normalized = "";
  for (let cursor = 0; cursor < sql.length; cursor += 1) {
    const character = sql[cursor];
    if ((character === "'" || character === '"') && sql[cursor - 1] !== "\\") {
      quote = quote === character ? null : (quote ?? character);
    }
    if (character === "?" && quote === null) {
      index += 1;
      normalized += `$${index}`;
    } else {
      normalized += character;
    }
  }
  return normalized.replaceAll("datetime('now')", "CURRENT_TIMESTAMP");
}

const query = (sql, params) => postgresQuery(normalizeLegacySql(sql, params), params);
