// Normalize legacy HR handlers that return a payload instead of writing to res.
for (const method of ["get", "post", "put", "patch", "delete"]) {
  const register = api[method].bind(api);
  api[method] = (path, ...handlers) => register(
    path,
    ...handlers.map((handler) => {
      if (!String(path).startsWith("/hr/") || typeof handler !== "function" || handler.length >= 2) {
        return handler;
      }
      return async (req, res, next) => {
        try {
          const payload = await handler(req);
          if (!res.headersSent) res.json(envelope(payload ?? {}));
        } catch (err) {
          if (err?.statusCode && !res.headersSent) {
            return res.status(err.statusCode).json(errorEnvelope(err.code || "VALIDATION", err.message));
          }
          next(err);
        }
      };
    }),
  );
}

