// ═══ P5: MES Integration Adapter (Q9-C) ═══
// Receives equipment runtime data from MES/SCADA, updates equipment status,
// triggers PM alerts and health score recalculation

// MES data ingestion endpoint (called by MES/edge gateway)
api.post('/equipment/mes/ingest', authenticateJWT, async (req, res) => {
  const { equipment_code, event_type, data } = req.body;
  // event_type: runtime_update | status_change | alarm | cycle_count | sensor_reading
  if (!equipment_code || !event_type) {
    return res.status(400).json({ success: false, error: 'equipment_code and event_type required' });
  }
  try {
    // Find equipment
    const eq = await query('SELECT id, asset_code, status, cumulative_runtime_hours FROM equipment_assets WHERE asset_code = $1', [equipment_code]);
    if (!eq.rows.length) return res.status(404).json({ success: false, error: 'Equipment not found' });
    const eqId = eq.rows[0].id;

    if (event_type === 'runtime_update') {
      // Update cumulative runtime hours
      const addedHours = Number(data.runtime_hours) || 0;
      await query('UPDATE equipment_assets SET cumulative_runtime_hours = cumulative_runtime_hours + $1, updated_at = now() WHERE id = $2', [addedHours, eqId]);
      // Check PM triggers (runtime-based)
      const pmDue = await query(`
        SELECT pt.id, pt.name_zh, pt.interval_hours, pt.pm_level
        FROM pm_templates pt
        WHERE pt.equipment_category_id = (SELECT category_id FROM equipment_assets WHERE id = $1)
          AND pt.trigger_type IN ('runtime', 'both')
          AND pt.interval_hours > 0
          AND NOT EXISTS (
            SELECT 1 FROM pm_execution_records pe
            WHERE pe.template_id = pt.id AND pe.asset_id = $1
              AND pe.scheduled_date >= current_date - (pt.interval_hours / 24 || ' days')::interval
          )
      `, [eqId]);
      if (pmDue.rows.length > 0) {
        // Create PM execution records
        for (const pm of pmDue.rows) {
          await query(`
            INSERT INTO pm_execution_records (template_id, asset_id, scheduled_date, pm_type, result)
            VALUES ($1, $2, current_date, $3, 'pending')
            ON CONFLICT DO NOTHING
          `, [pm.id, eqId, pm.pm_level]);
        }
        // Send notification
        await query(`
          INSERT INTO equipment_notifications (event_type, title, body, target_roles, channels, equipment_id, urgency)
          VALUES ('pm_due', $1, $2, '["engineering_manager","technician","line_leader"]', '["in_app","zalo"]', $3, 'high')
        `, [`设备 ${equipment_code} 触发运行时间保养`, `${pmDue.rows.length}个PM模板到期，请安排保养`, eqId]);
      }
      res.json({ success: true, data: { updated: true, pm_triggered: pmDue.rows.length } });

    } else if (event_type === 'status_change') {
      const newStatus = data.status; // active | idle | fault | maintenance | offline
      const oldStatus = eq.rows[0].status;
      await query('UPDATE equipment_assets SET status = $1, updated_at = now() WHERE id = $2', [newStatus, eqId]);
      // If fault, auto-create work order
      if (newStatus === 'fault' && oldStatus !== 'fault') {
        const wo = await query(`
          INSERT INTO maintenance_work_orders (wo_no, equipment_id, fault_description, urgency_level, source, status, issue_time)
          VALUES ('WO-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('maintenance_wo_seq')::text, 4, '0'),
                  $1, $2, $3, 'mes_auto', 'open', now())
          RETURNING wo_no
        `, [eqId, data.alarm_message || 'MES自动上报故障', data.urgency || 'can_continue']);
        // Notify
        await query(`
          INSERT INTO equipment_notifications (event_type, title, body, target_roles, channels, equipment_id, wo_id, urgency)
          VALUES ('wo_created', $1, $2, '["engineering_manager","technician"]', '["in_app","zalo"]', $3,
                  (SELECT id FROM maintenance_work_orders WHERE wo_no = $4), 'critical')
        `, [`🚨 MES自动报修: ${equipment_code}`, data.alarm_message || '设备故障', eqId, wo.rows[0].wo_no]);
        res.json({ success: true, data: { status_changed: true, wo_created: wo.rows[0].wo_no } });
      } else {
        res.json({ success: true, data: { status_changed: true } });
      }

    } else if (event_type === 'cycle_count') {
      // Update fixture/consumable usage counts
      const count = Number(data.count) || 0;
      if (data.fixture_code) {
        await query('UPDATE fixtures SET total_usage_count = total_usage_count + $1, updated_at = now() WHERE fixture_code = $2', [count, data.fixture_code]);
        // Check cleaning interval
        const fix = await query('SELECT id, total_usage_count, cleaning_interval_count, last_cleaning_count FROM fixtures WHERE fixture_code = $1', [data.fixture_code]);
        if (fix.rows.length) {
          const f = fix.rows[0];
          const sinceCleaning = (f.total_usage_count || 0) - (f.last_cleaning_count || 0);
          if (f.cleaning_interval_count > 0 && sinceCleaning >= f.cleaning_interval_count) {
            await query(`
              INSERT INTO equipment_notifications (event_type, title, body, target_roles, channels, urgency)
              VALUES ('fixture_cleaning_due', $1, $2, '["technician","line_leader"]', '["in_app"]', 'high')
            `, [`治具 ${data.fixture_code} 需清洁`, `已使用${sinceCleaning}次，超过清洁周期${f.cleaning_interval_count}次`, ]);
          }
        }
      }
      if (data.consumable_code) {
        await query('UPDATE consumables SET current_count = current_count + $1, updated_at = now() WHERE consumable_code = $2', [count, data.consumable_code]);
      }
      res.json({ success: true, data: { count_updated: true } });

    } else if (event_type === 'sensor_reading') {
      // Store sensor data (temperature, vibration, pressure, etc.)
      await query(`
        INSERT INTO equipment_readings (equipment_id, reading_type, reading_value, unit, recorded_at, source)
        VALUES ($1, $2, $3, $4, now(), 'mes')
      `, [eqId, data.sensor_type, data.value, data.unit]);
      // Check thresholds
      if (data.threshold_max && Number(data.value) > Number(data.threshold_max)) {
        await query(`
          INSERT INTO equipment_notifications (event_type, title, body, target_roles, channels, equipment_id, urgency)
          VALUES ('health_critical', $1, $2, '["engineering_manager","technician"]', '["in_app","zalo"]', $3, 'critical')
        `, [`⚠️ 传感器超限: ${equipment_code}`, `${data.sensor_type}=${data.value}${data.unit} 超过阈值${data.threshold_max}`, eqId]);
      }
      res.json({ success: true, data: { reading_stored: true } });

    } else if (event_type === 'alarm') {
      // Direct alarm from MES/SCADA
      await query(`
        INSERT INTO equipment_notifications (event_type, title, body, target_roles, channels, equipment_id, urgency)
        VALUES ('health_critical', $1, $2, '["engineering_manager","technician","line_leader"]', '["in_app","zalo"]', $3, 'critical')
      `, [`🚨 MES告警: ${equipment_code}`, data.alarm_message || '设备告警', eqId]);
      res.json({ success: true, data: { alarm_received: true } });

    } else {
      res.status(400).json({ success: false, error: 'Unknown event_type' });
    }
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

