// ═══ P5: Reports Export ═══

// Monthly equipment report
api.get('/equipment/reports/monthly', authenticateJWT, async (req, res) => {
  const { year, month, lineId } = req.query;
  const y = Number(year) || new Date().getFullYear();
  const m = Number(month) || new Date().getMonth() + 1;
  const startDate = `${y}-${String(m).padStart(2, '0')}-01`;
  const endDate = m === 12 ? `${y + 1}-01-01` : `${y}-${String(m + 1).padStart(2, '0')}-01`;
  let lineFilter = '';
  const params = [startDate, endDate];
  if (lineId) { lineFilter = 'AND ea.line_id = $3'; params.push(lineId); }

  try {
    // Work order stats
    const woStats = await query(`
      SELECT
        count(*) as total_wos,
        count(*) FILTER (WHERE wo.status IN ('fixed','closed','completed')) as completed_wos,
        count(*) FILTER (WHERE wo.urgency_level = 'line_down') as line_down_wos,
        avg(wo.downtime_minutes) FILTER (WHERE wo.downtime_minutes > 0) as avg_downtime,
        sum(wo.repair_cost) as total_repair_cost,
        avg(EXTRACT(EPOCH FROM (wo.completed_at - wo.issue_time))/3600) FILTER (WHERE wo.completed_at IS NOT NULL) as avg_repair_hours
      FROM maintenance_work_orders wo
      JOIN equipment_assets ea ON ea.id = wo.equipment_id
      WHERE wo.issue_time >= $1 AND wo.issue_time < $2 ${lineFilter}
    `, params);

    // PM compliance
    const pmStats = await query(`
      SELECT
        count(*) as total_pm,
        count(*) FILTER (WHERE pe.result = 'completed') as completed_pm,
        count(*) FILTER (WHERE pe.result = 'overdue') as overdue_pm
      FROM pm_execution_records pe
      JOIN equipment_assets ea ON ea.id = pe.asset_id
      WHERE pe.scheduled_date >= $1 AND pe.scheduled_date < $2 ${lineFilter}
    `, params);

    // Top failure equipment
    const topFailures = await query(`
      SELECT ea.asset_code, ea.name_zh, count(*) as failure_count,
             sum(wo.downtime_minutes) as total_downtime, sum(wo.repair_cost) as total_cost
      FROM maintenance_work_orders wo
      JOIN equipment_assets ea ON ea.id = wo.equipment_id
      WHERE wo.issue_time >= $1 AND wo.issue_time < $2 ${lineFilter}
      GROUP BY ea.id, ea.asset_code, ea.name_zh
      ORDER BY failure_count DESC LIMIT 10
    `, params);

    // Fault code Pareto
    const faultPareto = await query(`
      SELECT fc.code, fc.name_zh, count(*) as count
      FROM maintenance_work_orders wo
      JOIN fault_codes fc ON fc.id = wo.fault_code_id
      JOIN equipment_assets ea ON ea.id = wo.equipment_id
      WHERE wo.issue_time >= $1 AND wo.issue_time < $2 ${lineFilter}
      GROUP BY fc.id, fc.code, fc.name_zh
      ORDER BY count DESC LIMIT 15
    `, params);

    // Spare parts consumption
    const spareUsage = await query(`
      SELECT sp.part_code, sp.name_zh, sum(su.quantity) as total_used, sp.unit_price,
             sum(su.quantity) * sp.unit_price as total_cost
      FROM spare_part_usage su
      JOIN spare_parts sp ON sp.id = su.spare_part_id
      WHERE su.used_at >= $1 AND su.used_at < $2
      GROUP BY sp.id, sp.part_code, sp.name_zh, sp.unit_price
      ORDER BY total_cost DESC LIMIT 10
    `, [startDate, endDate]);

    // Cost breakdown
    const costBreakdown = await query(`
      SELECT
        sum(wo.repair_cost) as repair_cost,
        sum(wo.external_repair_cost) as external_cost,
        (SELECT sum(su.quantity * sp.unit_price) FROM spare_part_usage su JOIN spare_parts sp ON sp.id = su.spare_part_id WHERE su.used_at >= $1 AND su.used_at < $2) as spare_cost,
        (SELECT sum(cu.quantity * c.unit_price) FROM consumable_usage_logs cu JOIN consumables c ON c.id = cu.consumable_id WHERE cu.used_at >= $1 AND cu.used_at < $2) as consumable_cost
      FROM maintenance_work_orders wo
      WHERE wo.issue_time >= $1 AND wo.issue_time < $2
    `, [startDate, endDate]);

    res.json({
      success: true,
      data: {
        period: { year: y, month: m, start: startDate, end: endDate },
        work_orders: woStats.rows[0],
        pm_compliance: pmStats.rows[0],
        top_failures: topFailures.rows,
        fault_pareto: faultPareto.rows,
        spare_parts_usage: spareUsage.rows,
        cost_breakdown: costBreakdown.rows[0],
      }
    });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

// OEE report
api.get('/equipment/reports/oee', authenticateJWT, async (req, res) => {
  const { startDate, endDate, lineId } = req.query;
  const start = startDate || new Date(Date.now() - 30 * 86400000).toISOString().split('T')[0];
  const end = endDate || new Date().toISOString().split('T')[0];
  let lineFilter = '';
  const params = [start, end];
  if (lineId) { lineFilter = 'AND ea.line_id = $3'; params.push(lineId); }

  try {
    // OEE = Availability × Performance × Quality
    // Availability = (Planned Production - Downtime) / Planned Production
    const oeeData = await query(`
      SELECT
        ea.asset_code, ea.name_zh, ea.criticality,
        ea.cumulative_runtime_hours as total_hours,
        COALESCE(sum(wo.downtime_minutes), 0) as total_downtime_min,
        count(wo.id) as wo_count,
        -- Availability: assume 720h/month planned
        GREATEST(0, (720 * 60 - COALESCE(sum(wo.downtime_minutes), 0)) / (720 * 60)) as availability,
        -- Performance: based on cycle count vs target (simplified)
        0.95 as performance,
        -- Quality: based on fault rate
        GREATEST(0, 1 - count(wo.id) * 0.02) as quality
      FROM equipment_assets ea
      LEFT JOIN maintenance_work_orders wo ON wo.equipment_id = ea.id
        AND wo.issue_time >= $1 AND wo.issue_time < $2
      WHERE ea.status != 'scrapped' ${lineFilter}
      GROUP BY ea.id, ea.asset_code, ea.name_zh, ea.criticality, ea.cumulative_runtime_hours
      ORDER BY ea.criticality, ea.asset_code
    `, params);

    const rows = oeeData.rows.map(r => {
      const oee = Number(r.availability) * Number(r.performance) * Number(r.quality);
      return { ...r, oee: Math.round(oee * 10000) / 100, availability_pct: Math.round(Number(r.availability) * 10000) / 100 };
    });

    const avgOee = rows.length ? Math.round(rows.reduce((s, r) => s + r.oee, 0) / rows.length * 100) / 100 : 0;

    res.json({ success: true, data: { period: { start, end }, avg_oee: avgOee, equipment: rows } });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});



