const API_DOMAIN_RULES=[
  ["/api/integration","INTEGRATION"],["/api/wms","WMS"],["/api/smt","STATION"],["/api/station","STATION"],["/api/auth","AUTH"],
  ["/pmc","PMC"],["/mes","MES"],["/wms","WMS"],["/hr","HR"],["/finance","FINANCE"],
  ["/quality","QUALITY"],["/maintenance","MAINTENANCE"],["/sales","SALES"],["/admin","ADMIN"],
  ["/reports","REPORTING"],["/api","CORE"],["/","CORE"]
];
function classifyApiDomain(requestPath){
  const normalized=String(requestPath||"/").toLowerCase();
  return API_DOMAIN_RULES.find(([prefix])=>normalized.startsWith(prefix))[1];
}
app.use((req,res,next)=>{
  const domain=classifyApiDomain(req.path);
  req.apiDomain=domain;
  res.setHeader("X-API-Domain",domain);
  res.setHeader("X-API-Classification","canonical-v1");
  next();
});
