const RESIDENCE_TIMEOUT_MINUTES = Math.max(1, Number(process.env.RESIDENCE_TIMEOUT_MINUTES || 30));

async function touchStationResidence(stationCode, payload = {}) {
  if (!stationCode) return;
  await stationResidenceReady;
  const boards = Array.isArray(payload.subBoards) ? payload.subBoards : [];
  const direct = [payload.sn, payload.pcbSerial, ...(Array.isArray(payload.sns) ? payload.sns : [])]
    .filter(Boolean).map(sn => ({ sn }));
  const products = boards.length ? boards : direct;
  for (const product of products) {
    const sn = String(product.sn || "").trim().toUpperCase();
    if (!sn) continue;
    const state = String(product.result || payload.result || payload.stage || "PROCESSING").toUpperCase();
    const isNg = state.includes("FAIL") || state.includes("NG") || Boolean(product.isConfirmedNG || payload.isConfirmed);
    const defectCode = product.errorCode || product.defectCode || payload.defectCode || null;
    const batchId = String(payload.batchId || product.batchId || "") || null;
    const open = await query(`SELECT residence_id FROM station_product_residence
      WHERE sn=$1 AND station_code=$2 AND status='IN_STATION' ORDER BY entered_at DESC LIMIT 1`, [sn, stationCode]);
    let currentResidenceId;
    if (open.rows.length) {
      currentResidenceId = open.rows[0].residence_id;
      await query(`UPDATE station_product_residence SET last_seen_at=NOW(),batch_id=COALESCE($2,batch_id),
        product_state=$3,is_ng=(is_ng OR $4),defect_code=COALESCE($5,defect_code) WHERE residence_id=$1`,
        [open.rows[0].residence_id, batchId, state, isNg, defectCode]);
    } else {
      const inserted = await query(`INSERT INTO station_product_residence
        (sn,batch_id,station_code,product_state,defect_code,is_ng) VALUES ($1,$2,$3,$4,$5,$6)
        RETURNING residence_id`, [sn, batchId, stationCode, state, defectCode, isNg]);
      currentResidenceId = inserted.rows[0].residence_id;
    }
    // Loss prevention: commit the new IN record first. Only after that succeeds
    // may MES close the previous station's OUT record. A failed new-station
    // write therefore leaves the product safely counted at its old station.
    await query(`UPDATE station_product_residence SET exited_at=NOW(),last_seen_at=NOW(),
      duration_seconds=GREATEST(0,EXTRACT(EPOCH FROM (NOW()-entered_at))::INTEGER),status='LEFT_STATION',
      next_station_code=$2,next_residence_id=$3
      WHERE sn=$1 AND station_code<>$2 AND status='IN_STATION'`, [sn, stationCode, currentResidenceId]);
  }
}

setInterval(async () => {
  try {
    await stationResidenceColumnsReady;
    const overdue = await query(`UPDATE station_product_residence SET alarmed_at=NOW()
      WHERE residence_id IN (SELECT residence_id FROM station_product_residence
        WHERE status='IN_STATION' AND alarmed_at IS NULL
          AND entered_at <= NOW() - ($1::text || ' minutes')::interval)
      RETURNING residence_id,sn,batch_id,station_code,product_state,defect_code,is_ng,
        EXTRACT(EPOCH FROM (NOW()-entered_at))::int AS seconds`, [RESIDENCE_TIMEOUT_MINUTES]);
    for (const row of overdue.rows) {
      const payload = { residenceId: row.residence_id, sn: row.sn, batchId: row.batch_id,
        stationCode: row.station_code, productState: row.product_state, defectCode: row.defect_code,
        isNg: row.is_ng, seconds: row.seconds, thresholdMinutes: RESIDENCE_TIMEOUT_MINUTES };
      neuralBroadcast({ from: "mes_server", to: "*", type: "RESIDENCE_TIMEOUT",
        stationCode: row.station_code, payload, priority: "critical" });
      await commitStationBucket(row.station_code, "process", [{ stage: "RESIDENCE_TIMEOUT", ...payload, updatedAt: Date.now() }]);
    }
  } catch (error) {
    console.error("[RESIDENCE TIMEOUT]", error.message);
  }
}, 15000).unref();

