async function readStationBuckets(stationCode) {
  await stationSnapshotTableReady;
  const result = await query(
    `SELECT bucket_name,payload,version FROM station_bucket_snapshots WHERE station_code=$1`,
    [stationCode]
  );
  const state = { pending_ng: [], confirmed_ng: [], pass: [], scrap: [], process: [], stats: [{ total: 0, pass: 0, fail: 0, dup: 0 }] };
  for (const row of result.rows) state[row.bucket_name] = Array.isArray(row.payload) ? row.payload : [];
  return state;
}

async function commitStationBucket(stationCode, bucketName, records) {
  const result = await query(`
    INSERT INTO station_bucket_snapshots (station_code,bucket_name,version,payload)
    VALUES ($1,$2,1,$3)
    ON CONFLICT (station_code,bucket_name) DO UPDATE SET
      version=station_bucket_snapshots.version+1,payload=EXCLUDED.payload,updated_at=NOW()
    RETURNING version,updated_at`, [stationCode, bucketName, JSON.stringify(records)]);
  const row = result.rows[0];
  neuralBroadcast({
    from: "mes_server", to: "*", type: "BUCKET_SNAPSHOT_UPDATE", stationCode,
    payload: { stationCode, bucketName, version: Number(row.version), records, updatedAt: row.updated_at },
    priority: "info",
  });
}

async function mergeConfirmedMotherboardLayout(stationCode, payload) {
  const boards=Array.isArray(payload?.subBoards)?payload.subBoards:[];
  const isConfirmedFailedBoard=board=>{
    const finalResult=String(board?.result??(Array.isArray(board?.results)?board.results.at(-1):'')).trim().toUpperCase();
    // Every station uses one-step NG. The latest FAIL is the active NG state;
    // a later PASS retest clears it.
    return finalResult==='FAIL';
  };
  // Accept incremental tester facts. A tester may publish one slot, several
  // slots, or a complete panel; MES must never discard valid source results
  // merely because an arbitrary fixed panel size has not been reached yet.
  // ICT owns the motherboard identity and later events update that identity.
  if(!boards.length)return null;
  await confirmedMotherboardLayoutReady;
  await fctMotherboardStagingReady;
  const isAuto=stationCode.startsWith('auto_');
  const autoTable='station_confirmed_motherboard_layouts_auto';
  const tableName=isAuto?autoTable:'station_confirmed_motherboard_layouts';
  const sns=new Set(boards.map(board=>String(board?.sn||'').trim().toUpperCase()).filter(Boolean));
  const candidates=await query(`SELECT motherboard_id,ict_batch_id,fct_batch_id,members
    FROM ${tableName} WHERE status='ACTIVE' ORDER BY updated_at DESC LIMIT 1000`);
  let matched=null;
  const sourceIsFct=stationCode==='manu_fct'||stationCode==='auto_fct';
  const sourceIsIct=stationCode==='manu_ict'||stationCode==='auto_ict';
  const claimedBatchId=String(payload.batchId||payload.motherboardId||'').trim();
  for(const row of candidates.rows){
    const memberSns=new Set((Array.isArray(row.members)?row.members:[])
      .map(member=>String(member?.sn||'').toUpperCase()).filter(Boolean));
    const overlap=[...sns].filter(sn=>memberSns.has(sn)).length;
    // ICT may continue the exact immutable motherboard by its own batch ID.
    if(sourceIsIct&&claimedBatchId&&
        [row.motherboard_id,row.ict_batch_id].some(value=>String(value||'')===claimedBatchId)){
      matched=row;break;
    }
    // FCT may update only when every reported SN resolves to one and the same
    // ICT motherboard. A mixed-board payload must never be partially merged.
    if(sourceIsFct&&sns.size>0&&overlap===sns.size&&row.ict_batch_id){
      matched=row;break;
    }
    if(sourceIsIct&&overlap>0){matched=row;break;}
  }
  // FCT is never an identity authority. If ICT has not registered this exact
  // motherboard yet, keep the FCT result staged and wait; never mint or rename
  // a motherboard from an FCT timestamp/batch.
  if(sourceIsFct&&(!matched||!matched.ict_batch_id)){
    const stagedBatchId=String(payload.batchId||payload.testCycleId||boards[0]?.sn||randomUUID());
    await query(`INSERT INTO station_fct_motherboard_staging
      (station_code,batch_id,members,payload) VALUES($1,$2,$3,$4)
      ON CONFLICT(station_code,batch_id) DO UPDATE SET
        members=EXCLUDED.members,payload=EXCLUDED.payload,updated_at=NOW()`,
      [stationCode,stagedBatchId,JSON.stringify(boards),JSON.stringify(payload)]);
    return {staged:true,stationCode,batchId:stagedBatchId,memberCount:boards.length};
  }
  const motherboardId=String(matched?.motherboard_id||payload.batchId||boards[0]?.sn||randomUUID());
  const priorMembers=Array.isArray(matched?.members)?matched.members:[];
  const priorBySn=new Map(priorMembers.map(member=>[String(member?.sn||'').toUpperCase(),member]));
  const updatedMembers=boards.map((board,index)=>{
    const sn=String(board?.sn||'').trim().toUpperCase();const prior=priorBySn.get(sn)||{};
    // A non-empty string such as "false" is truthy in JavaScript.  Never let
    // that mark a PASS member as NG.  The source station owns and overwrites
    // its own flag so a previously bad projection can also self-heal.
    const confirmed=isConfirmedFailedBoard(board);
    const stationResults=(Array.isArray(board?.results)?board.results:[board?.result])
      .map(value=>String(value??'').trim().toUpperCase()).filter(Boolean);
    const resultConflict=new Set(stationResults).size>1;
    return {...prior,sn,slot:Number(prior.slot||board.slot||index+1),result:String(board.result||prior.result||'PASS').toUpperCase(),
      ictNg:(stationCode==='manu_ict'||stationCode==='auto_ict')?confirmed:Boolean(prior.ictNg),
      fctNg:(stationCode==='manu_fct'||stationCode==='auto_fct')?confirmed:Boolean(prior.fctNg),
      ictResults:(stationCode==='manu_ict'||stationCode==='auto_ict')?stationResults:(prior.ictResults||[]),
      fctResults:(stationCode==='manu_fct'||stationCode==='auto_fct')?stationResults:(prior.fctResults||[]),
      ictResultConflict:(stationCode==='manu_ict'||stationCode==='auto_ict')?resultConflict:Boolean(prior.ictResultConflict),
      fctResultConflict:(stationCode==='manu_fct'||stationCode==='auto_fct')?resultConflict:Boolean(prior.fctResultConflict)};
  });
  // Preserve previously received slots and replace only the slots/SNs present
  // in this event. This makes partial and alternating tester reports safe.
  const updatedBySn=new Map(updatedMembers.map(member=>[String(member.sn||'').toUpperCase(),member]));
  const updatedSlots=new Set(updatedMembers.map(member=>Number(member.slot||0)).filter(Boolean));
  const members=[
    ...priorMembers.filter(member=>!updatedBySn.has(String(member?.sn||'').toUpperCase())
      && !updatedSlots.has(Number(member?.slot||0))),
    ...updatedMembers,
  ].map(member=>({
    ...member,
    // ICT and FCT own independent NG states. A PASS from one test station
    // must never hide an unresolved NG from the other station. The merged
    // result becomes PASS only after both station NG flags have been cleared
    // by their own valid retest/revival result.
    result:(member.ictNg||member.fctNg)?'FAIL':'PASS',
  })).sort((a,b)=>a.slot-b.slot);
  const conflictingMembers=members.filter(member=>(stationCode==='manu_fct'||stationCode==='auto_fct')?member.fctResultConflict:member.ictResultConflict);
  if(conflictingMembers.length){
    await stationConflictColumnsReady;
    const dataset=`${stationCode}_motherboard_test_results`;
    const historyPayload=conflictingMembers.map(member=>({sn:member.sn,slot:member.slot,
      results:(stationCode==='manu_fct'||stationCode==='auto_fct')?member.fctResults:member.ictResults,
      finalResult:member.result}));
    const localHash=createHash('sha256').update(JSON.stringify(historyPayload)).digest('hex');
    const finalPayload=historyPayload.map(item=>({...item,resolutionRule:'LATEST_TEST_RESULT'}));
    const mesHash=createHash('sha256').update(JSON.stringify(finalPayload)).digest('hex');
    const existing=await query(`SELECT 1 FROM station_data_conflicts WHERE station_code=$1 AND dataset=$2
      AND local_hash=$3 AND status='PENDING_INVESTIGATION' LIMIT 1`,[stationCode,dataset,localHash]);
    if(!existing.rows.length)await query(`INSERT INTO station_data_conflicts
      (station_code,dataset,local_hash,mes_hash,local_payload,mes_payload,severity,meeting_required)
      VALUES($1,$2,$3,$4,$5,$6,'HIGH',FALSE)`,[stationCode,dataset,localHash,mesHash,
      JSON.stringify(historyPayload),JSON.stringify(finalPayload)]);
  }
  const ictBatch=(stationCode==='manu_ict'||stationCode==='auto_ict')?String(payload.batchId||''):(matched?.ict_batch_id||null);
  const fctBatch=(stationCode==='manu_fct'||stationCode==='auto_fct')?String(payload.batchId||''):(matched?.fct_batch_id||null);
  const saved=await query(`INSERT INTO ${tableName}(motherboard_id,ict_batch_id,fct_batch_id,members)
    VALUES($1,$2,$3,$4) ON CONFLICT(motherboard_id) DO UPDATE SET ict_batch_id=COALESCE(EXCLUDED.ict_batch_id,${tableName}.ict_batch_id),
    fct_batch_id=COALESCE(EXCLUDED.fct_batch_id,${tableName}.fct_batch_id),members=EXCLUDED.members,updated_at=NOW()
    RETURNING updated_at`,
    [motherboardId,ictBatch,fctBatch,JSON.stringify(members)]);
  const updatedAt=saved.rows[0]?.updated_at||new Date();
  const version=new Date(updatedAt).getTime();
  // NG box counts are mutually exclusive. A member marked by both stations
  // belongs only to ICT_FCT_NG and must never also increment ICT_ONLY_NG or
  // FCT_ONLY_NG.
  const exclusiveCounts=members.reduce((counts,member)=>{
    if(member.ictNg&&member.fctNg)counts.ICT_FCT_NG+=1;
    else if(member.ictNg)counts.ICT_ONLY_NG+=1;
    else if(member.fctNg)counts.FCT_ONLY_NG+=1;
    else counts.PASS+=1;
    return counts;
  },{ICT_ONLY_NG:0,FCT_ONLY_NG:0,ICT_FCT_NG:0,PASS:0});
  const merged={motherboardId,ictBatchId:ictBatch,fctBatchId:fctBatch,members,
    exclusiveCounts,version,updatedAt};
  // Every successful merge is pushed immediately. Depanel persists this
  // complete versioned layout to SQLite before rendering or alarming.
  neuralBroadcast({
    from:'mes_server',to:'depanel_scanner',type:'MOTHERBOARD_LAYOUT_UPDATED',
    stationCode:'manu_depanel',
    priority:members.some(member=>member.ictNg||member.fctNg)?'warning':'info',
    payload:merged,
  });
  if(stationCode==='manu_fct'||stationCode==='auto_fct'){
    await query(`DELETE FROM station_fct_motherboard_staging
      WHERE station_code=$1 AND batch_id=$2`,[stationCode,String(payload.batchId||'')]);
  }else if(stationCode==='manu_ict'||stationCode==='auto_ict'){
    const fctStation=stationCode==='auto_ict'?'auto_fct':'manu_fct';
    const staged=await query(`SELECT station_code,batch_id,members,payload
      FROM station_fct_motherboard_staging WHERE station_code=$1
      ORDER BY updated_at`,[fctStation]);
    const mergedSns=new Set(members.map(member=>String(member.sn||'').toUpperCase()));
    for(const row of staged.rows){
      const overlap=(Array.isArray(row.members)?row.members:[])
        .filter(member=>mergedSns.has(String(member?.sn||'').toUpperCase())).length;
      if(overlap>=2){
        await mergeConfirmedMotherboardLayout(
          row.station_code,
          {...row.payload,batchId:row.batch_id,subBoards:row.members},
        );
      }
    }
  }
  return merged;
}

app.get('/api/station/confirmed-motherboards/search/:code',async(req,res)=>{
  try{
    await confirmedMotherboardLayoutReady;
    const code=String(req.params.code||'').trim().toUpperCase();
    const line=String(req.query.line||'auto').trim().toLowerCase();
    const table=line==='auto'
      ?'station_confirmed_motherboard_layouts_auto'
      :'station_confirmed_motherboard_layouts';
    const found=await query(`SELECT motherboard_id AS "motherboardId",
        ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",
        members,updated_at AS "updatedAt"
      FROM ${table}
      WHERE status='ACTIVE' AND (
        UPPER(motherboard_id)=UPPER($1) OR
        UPPER(COALESCE(ict_batch_id,''))=UPPER($1) OR
        UPPER(COALESCE(fct_batch_id,''))=UPPER($1) OR
        EXISTS(SELECT 1 FROM jsonb_array_elements(members) member
          WHERE UPPER(member->>'sn')=UPPER($1))
      )
      ORDER BY updated_at DESC LIMIT 1`,[code]);
    if(!found.rows.length)return res.status(404).json(
      errorEnvelope('MOTHERBOARD_NOT_FOUND','motherboard or daughter SN not found'));
    res.json({ok:true,...found.rows[0]});
  }catch(error){
    res.status(500).json(errorEnvelope('MOTHERBOARD_SEARCH_FAILED',error.message));
  }
});

app.get('/api/station/confirmed-motherboards/identify/:sn',async(req,res)=>{
  try{await confirmedMotherboardLayoutReady;const sn=String(req.params.sn||'').trim().toUpperCase();
    const requestedLine=String(req.query.line||'').trim().toLowerCase();
    const primaryTable=requestedLine==='auto'
      ?'station_confirmed_motherboard_layouts_auto'
      :'station_confirmed_motherboard_layouts';
    const secondaryTable=requestedLine ? null : 'station_confirmed_motherboard_layouts_auto';
    let found=await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
      FROM ${primaryTable} WHERE status='ACTIVE' AND EXISTS(
      SELECT 1 FROM jsonb_array_elements(members) member WHERE UPPER(member->>'sn')=UPPER($1)) ORDER BY updated_at DESC LIMIT 1`,[sn]);
    // Preserve the old manual-then-auto fallback only for legacy callers that
    // did not declare a line. Station agents always declare their line.
    if(!found.rows.length&&secondaryTable){
      found=await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
        FROM ${secondaryTable} WHERE status='ACTIVE' AND EXISTS(
        SELECT 1 FROM jsonb_array_elements(members) member WHERE UPPER(member->>'sn')=UPPER($1)) ORDER BY updated_at DESC LIMIT 1`,[sn]);
    }
    // Self-heal projection gaps from the authoritative ICT/FCT bucket snapshots.
    // This only reconstructs identity and defect marks; the caller's physical
    // scanner remains the sole confirmation that the board reached depanel.
    if(!found.rows.length){
      const snapshots=[];
      const sourceStations=requestedLine==='auto'
        ?['auto_ict','auto_fct']
        :requestedLine==='manual'
          ?['manu_ict','manu_fct']
          :['manu_ict','manu_fct','auto_ict','auto_fct'];
      for(const sourceStation of sourceStations){
        const state=await readStationBuckets(sourceStation);
        for(const row of [...state.confirmed_ng,...state.pending_ng,...state.pass]){
          if(Array.isArray(row?.subBoards)&&row.subBoards.length===12)snapshots.push({sourceStation,row});
        }
      }
      let wanted=new Set([sn]);
      for(let pass=0;pass<2;pass++){
        for(const candidate of snapshots){
          const members=candidate.row.subBoards.map(x=>String(x?.sn||'').trim().toUpperCase()).filter(Boolean);
          if(!members.some(member=>wanted.has(member)))continue;
          const rebuilt=await mergeConfirmedMotherboardLayout(candidate.sourceStation,candidate.row);
          for(const member of rebuilt?.members||[])wanted.add(String(member?.sn||'').toUpperCase());
        }
      }
      found=await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
        FROM ${primaryTable} WHERE status='ACTIVE' AND EXISTS(
        SELECT 1 FROM jsonb_array_elements(members) member WHERE UPPER(member->>'sn')=UPPER($1)) ORDER BY updated_at DESC LIMIT 1`,[sn]);
      // Also check auto line table after rebuild
      if(!found.rows.length&&secondaryTable){
        found=await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
          FROM ${secondaryTable} WHERE status='ACTIVE' AND EXISTS(
          SELECT 1 FROM jsonb_array_elements(members) member WHERE UPPER(member->>'sn')=UPPER($1)) ORDER BY updated_at DESC LIMIT 1`,[sn]);
      }
    }
    // A valid 12-SN ICT identity can reach the durable staging ledger even if
    // a later result/route projection is rejected. Identity must remain
    // recoverable for FCT and depanel; a business 409 must not erase ancestry.
    if(!found.rows.length){
      const stagedStations=requestedLine==='auto'
        ?['auto_ict','auto_fct']
        :requestedLine==='manual'
          ?['manu_ict','manu_fct']
          :['manu_ict','manu_fct','auto_ict','auto_fct'];
      const staged=await query(`SELECT station_code,normalized_payload->'payload' AS payload
        FROM station_data_staging WHERE status='PROJECTED'
          AND station_code=ANY($2::text[])
          AND jsonb_array_length(COALESCE(normalized_payload->'payload'->'subBoards','[]'::jsonb))=12
          AND EXISTS(SELECT 1 FROM jsonb_array_elements(normalized_payload->'payload'->'subBoards') member
            WHERE UPPER(member->>'sn')=UPPER($1))
        ORDER BY CASE station_code WHEN 'manu_ict' THEN 0 WHEN 'auto_ict' THEN 1 WHEN 'manu_fct' THEN 2 ELSE 3 END,received_at LIMIT 20`,[sn,stagedStations]);
      for(const row of staged.rows)await mergeConfirmedMotherboardLayout(row.station_code,row.payload);
      found=await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
        FROM ${primaryTable} WHERE status='ACTIVE' AND EXISTS(
        SELECT 1 FROM jsonb_array_elements(members) member WHERE UPPER(member->>'sn')=UPPER($1)) ORDER BY updated_at DESC LIMIT 1`,[sn]);
      // Also check auto line table
      if(!found.rows.length&&secondaryTable){
        found=await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
          FROM ${secondaryTable} WHERE status='ACTIVE' AND EXISTS(
          SELECT 1 FROM jsonb_array_elements(members) member WHERE UPPER(member->>'sn')=UPPER($1)) ORDER BY updated_at DESC LIMIT 1`,[sn]);
      }
    }
    if(!found.rows.length)return res.status(404).json(errorEnvelope('MOTHERBOARD_NOT_FOUND','confirmed motherboard not found'));
    res.json({ok:true,...found.rows[0]});}catch(error){res.status(500).json(errorEnvelope('MOTHERBOARD_IDENTIFY_FAILED',error.message));}
});

// Canonical feed for depanel local SQLite. It includes every active complete
// motherboard, not only boards containing NG members.
app.get('/api/station/confirmed-motherboards',async(req,res)=>{
  try{
    await confirmedMotherboardLayoutReady;
    const line=String(req.query.line||'manual').trim().toLowerCase();
    const table=line==='auto'
      ?'station_confirmed_motherboard_layouts_auto'
      :'station_confirmed_motherboard_layouts';
    const since=String(req.query.since||'').trim();
    const limit=Math.min(Math.max(Number(req.query.limit)||1000,1),5000);
    const result=since
      ?await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",
          fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
          FROM ${table} WHERE status='ACTIVE' AND updated_at>$1::timestamptz
          ORDER BY updated_at,motherboard_id LIMIT $2`,[since,limit])
      :await query(`SELECT motherboard_id AS "motherboardId",ict_batch_id AS "ictBatchId",
          fct_batch_id AS "fctBatchId",members,updated_at AS "updatedAt"
          FROM ${table} WHERE status='ACTIVE'
          ORDER BY updated_at,motherboard_id LIMIT $1`,[limit]);
    res.json({ok:true,line,items:result.rows});
  }catch(error){
    res.status(500).json(errorEnvelope('MOTHERBOARD_FEED_FAILED',error.message));
  }
});

app.post('/api/station/shell-bindings/commit',async(req,res)=>{
  const pcbaSn=String(req.body?.pcbaSn||'').trim().toUpperCase();
  const shellSn=String(req.body?.shellSn||'').trim().toUpperCase();
  const stationCode=String(req.body?.stationCode||'manu_shellbinding');
  const operator=String(req.body?.operator||stationCode);
  if(!pcbaSn||!shellSn)return res.status(400).json(errorEnvelope('VALIDATION','pcbaSn and shellSn required'));
  if(!['manu_shellbinding','auto_shellbinding'].includes(stationCode))
    return res.status(409).json(errorEnvelope('BINDING_STATION_INVALID','shell binding station is invalid'));
  if(req.body?.simulate===true){
    const simulation={sn:pcbaSn,pcbaSn,shellSn,result:'SIMULATION_PASS',simulated:true,
      visibleAtStation:true,operator,stationCode,testedAt:Date.now(),expiresAt:Date.now()+5*60*1000};
    await commitStationBucket('manu_shellbinding','simulation',[simulation]);
    neuralBroadcast({from:'mes_server',to:'manu_shellbinding',type:'BINDING_SIMULATION_PASSED',
      stationCode,priority:'info',payload:{...simulation,silent:true,alarm:false}});
    return res.json({ok:true,simulated:true,committed:false,wouldCommit:true,visibleAtStation:true,pcbaSn,shellSn,
      routeFlagged:false,missingSignatures:[],alarm:false});
  }
  const client=await pgPool.connect();
  try{
    await client.query('BEGIN');
    // Transaction-scoped locks serialize both sides even before either code
    // exists in pcb_shell_bindings, closing the concurrent two-station race.
    await client.query(`SELECT pg_advisory_xact_lock(hashtext($1)),pg_advisory_xact_lock(hashtext($2))`,
      [`PCBA:${pcbaSn}`,`SHELL:${shellSn}`].sort());
    const existing=await client.query(`SELECT pcb_sn,shell_sn FROM pcb_shell_bindings
      WHERE UPPER(pcb_sn)=UPPER($1) OR UPPER(shell_sn)=UPPER($2) FOR UPDATE`,[pcbaSn,shellSn]);
    const same=existing.rows.some(row=>String(row.pcb_sn).toUpperCase()===pcbaSn&&String(row.shell_sn).toUpperCase()===shellSn);
    if(!same){
      await client.query(`DELETE FROM pcb_shell_bindings
        WHERE UPPER(pcb_sn)=UPPER($1) OR UPPER(shell_sn)=UPPER($2)`,[pcbaSn,shellSn]);
      await client.query(`INSERT INTO pcb_shell_bindings
      (pcb_sn,shell_sn,operator,station_code,line_name,synced) VALUES($1,$2,$3,$4,$5,TRUE)`,
      [pcbaSn,shellSn,operator,stationCode,stationCode==='auto_shellbinding'?'L002':'L004']);
    }
    await client.query('COMMIT');
    const eventId=`shell-bind:${pcbaSn}:${shellSn}`;
    // The authoritative binding transaction is complete at this point.
    // Bucket projection, trace, and broadcast are downstream bookkeeping and
    // must not hold the operator's scanner for several seconds.
    const acknowledgementId=`ACK:${eventId}`;
    res.json({ok:true,committed:true,idempotent:Boolean(same),eventId,
      acknowledgementId,pcbaSn,shellSn,routeFlagged:false,missingSignatures:[]});
    const payload={sn:pcbaSn,pcbaSn,shellSn,result:'PASS',operator,mappingType:'shell_board_mapping',
      routeFlagged:false,missingSignatures:[],
      bindingLine:stationCode==='auto_shellbinding'?'auto_line':'manual_line',
      mesAuthoritative:true,boundAt:Date.now()};
    void (async()=>{
      const stationState=await readStationBuckets(stationCode);
      const bindingRows=upsertBySn(Array.isArray(stationState.bindings)?stationState.bindings:[],payload);
      await commitStationBucket(stationCode,'bindings',bindingRows);
      await projectStationProductionEvent(eventId,stationCode,'BINDING_COMPLETED',payload);
      await appendCanonicalSnTrace(eventId,stationCode,'BINDING_COMPLETED',payload);
      neuralBroadcast({from:'mes_server',to:'*',type:'BINDING_COMPLETED',priority:'info',stationCode,payload});
    })().catch(error=>console.error('[shell-binding] downstream projection failed:',error.message));
  }catch(error){try{await client.query('ROLLBACK');}catch{};
    res.status(500).json(errorEnvelope('SHELL_BINDING_COMMIT_FAILED',error.message));
  }finally{client.release();}
});

app.get('/api/station/shell-bindings',async(req,res)=>{
  try{
    const limit=Math.min(500,Math.max(1,Number(req.query.limit||100)));
    const result=await query(`SELECT pcb_sn AS "pcbaSn",shell_sn AS "shellSn",operator,
      station_code AS "stationCode",line_name AS "lineName",synced,created_at AS "boundAt"
      FROM pcb_shell_bindings ORDER BY created_at DESC LIMIT $1`,[limit]);
    res.json({ok:true,items:result.rows,total:result.rows.length});
  }catch(error){res.status(500).json(errorEnvelope('SHELL_BINDINGS_QUERY_FAILED',error.message));}
});

app.delete('/api/station/shell-bindings',async(req,res)=>{
  try{
    const pcbaSn=String(req.body?.pcbaSn||'').trim().toUpperCase();
    const shellSn=String(req.body?.shellSn||'').trim().toUpperCase();
    if(!pcbaSn||!shellSn)return res.status(400).json(errorEnvelope('VALIDATION','pcbaSn and shellSn required'));
    const deleted=await query(`DELETE FROM pcb_shell_bindings WHERE UPPER(pcb_sn)=$1 AND UPPER(shell_sn)=$2
      RETURNING pcb_sn AS "pcbaSn",shell_sn AS "shellSn"`,[pcbaSn,shellSn]);
    const state=await readStationBuckets('manu_shellbinding');
    await commitStationBucket('manu_shellbinding','bindings',(state.bindings||[]).filter(item=>
      String(item.pcbaSn||item.sn||'').toUpperCase()!==pcbaSn||String(item.shellSn||'').toUpperCase()!==shellSn));
    res.json({ok:true,deleted:deleted.rowCount>0,item:deleted.rows[0]||null});
  }catch(error){res.status(500).json(errorEnvelope('SHELL_BINDING_DELETE_FAILED',error.message));}
});

app.delete('/api/station/shell-bindings/all',async(req,res)=>{
  try{
    const operatorPrefix=String(req.query.operatorPrefix||'').trim();
    const result=operatorPrefix
      ? await query(`DELETE FROM pcb_shell_bindings WHERE operator LIKE $1 RETURNING pcb_sn`,[`${operatorPrefix}%`])
      : await query(`DELETE FROM pcb_shell_bindings RETURNING pcb_sn`);
    if(operatorPrefix){
      const bucket=await readStationBuckets('manu_shellbinding',['bindings']);
      const kept=(bucket.bindings?.items||[]).filter(item=>!String(item.operator||'').startsWith(operatorPrefix));
      await commitStationBucket('manu_shellbinding','bindings',kept);
    }else await commitStationBucket('manu_shellbinding','bindings',[]);
    res.json({ok:true,deleted:result.rowCount,scope:operatorPrefix||'ALL'});
  }catch(error){res.status(500).json(errorEnvelope('SHELL_BINDINGS_CLEAR_FAILED',error.message));}
});

function upsertBySn(records, record) {
  const next = records.filter(item => item.sn !== record.sn);
  next.push(record);
  return next;
}

async function acceptWaitingHandoverByScan(destinationStationCode, scannedSn) {
  if (!destinationStationCode || !scannedSn) return null;
  await stationHandoverReady;
  const found = await query(`SELECT transfer_id,batch_id,source_station,destination_station,destination_type,motherboard
    FROM station_handover_transfers
    WHERE destination_station=$1 AND status='WAITING_RECEIPT'
      AND EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(motherboard->'subBoards','[]'::jsonb)) board
                  WHERE UPPER(board->>'sn')=UPPER($2))
    ORDER BY sent_at DESC LIMIT 1`, [destinationStationCode, scannedSn]);
  if (!found.rows.length) return null;
  const transfer = found.rows[0];
  const source = await readStationBuckets(transfer.source_station);
  const destination = await readStationBuckets(destinationStationCode);
  const matches = item => String(item.batchId || "") === String(transfer.batch_id);
  const acceptedAt = Date.now();
  const acceptedBoards = Array.isArray(transfer.motherboard?.subBoards) ? transfer.motherboard.subBoards : [];
  await touchStationResidence(destinationStationCode, { batchId: transfer.batch_id, subBoards: acceptedBoards,
    stage: "TRANSFER_RECEIVED" });
  destination.pending_ng = destination.pending_ng.map(item => matches(item)
    ? { ...item, transferStatus: "RECEIVED", receivedAt: acceptedAt,
        acceptedBy: `SCANNER:${destinationStationCode}`, receiptSn: scannedSn }
    : item);
  destination.confirmed_ng = destination.confirmed_ng.map(item => matches(item)
    ? { ...item, transferStatus: "RECEIVED", receivedAt: acceptedAt,
        acceptedBy: `SCANNER:${destinationStationCode}`, receiptSn: scannedSn }
    : item);
  source.pending_ng = source.pending_ng.filter(item => !matches(item));
  source.confirmed_ng = source.confirmed_ng.filter(item => !matches(item));
  source.pass = source.pass.filter(item => !matches(item));
  await query(`UPDATE station_handover_transfers SET status='COMPLETED',received_at=NOW(),accepted_by=$2
    WHERE transfer_id=$1`, [transfer.transfer_id, `SCANNER:${destinationStationCode}`]);
  await stationRouteRequestReady;
  const routeStatus=destinationStationCode==='manu_rework'?'REPAIR_IN_PROGRESS':'COMPLETED';
  await query(`UPDATE station_route_requests SET status=$4::text,completed_at=CASE WHEN $4::text='COMPLETED' THEN NOW() ELSE completed_at END,
      repair_started_at=CASE WHEN $4::text='REPAIR_IN_PROGRESS' THEN NOW() ELSE repair_started_at END,
      processed_at=NOW(),notification_status='RECEIVED'
    WHERE batch_id=$1 AND source_station=$2 AND destination_station=$3 AND status='WAITING_RECEIPT'`,
    [transfer.batch_id,transfer.source_station,destinationStationCode,routeStatus]);
  if(destinationStationCode==='manu_rework'){
    await stationRepairWorkOrderReady;
    await query(`UPDATE station_repair_work_orders SET status='REPAIR_IN_PROGRESS',received_at=NOW(),repair_started_at=NOW(),
      repair_operator=$2,updated_at=NOW() WHERE batch_id=$1 AND status='WAITING_RECEIPT'`,
      [transfer.batch_id,`SCANNER:${destinationStationCode}`]);
    const receivedSns = acceptedBoards.map(board => String(board.sn || '').trim()).filter(Boolean);
    await resolveNgPickupAlarmsForReceipt({
      batchId: transfer.batch_id,
      workOrderId: transfer.motherboard?.workOrderId || transfer.motherboard?.repairWorkOrderId,
      bucketQr: transfer.motherboard?.bucketQr,
      sns: receivedSns,
      stationCode: destinationStationCode,
      reason: 'REPAIR_RECEIVED',
    });
  }
  if(String(transfer.destination_type||'').toUpperCase()==='REPAIR_RETURN'){
    await ngRevivalAuditColumnsReady;
    const memberSns=acceptedBoards.map(board=>String(board.sn||'').trim()).filter(Boolean);
    const assemblyRetestRequired=destinationStationCode==='manu_assem_ate';
    if(assemblyRetestRequired&&memberSns.length){
      await stationRetestReady;
      for(const returnedSn of memberSns){
        await query(`INSERT INTO station_retest_control
          (station_code,sn,batch_id,first_failed_at,max_attempts,armed,armed_at,armed_by,permission_by,permission_reason,updated_at)
          VALUES('manu_assem_ate',$1,$2,NOW(),2,TRUE,NOW(),'MES_REPAIR_RETURN','MES','REPAIR_RETURN_RECEIVED',NOW())
          ON CONFLICT(station_code,sn) DO UPDATE SET batch_id=EXCLUDED.batch_id,armed=TRUE,armed_at=NOW(),
            armed_by='MES_REPAIR_RETURN',permission_by='MES',permission_reason='REPAIR_RETURN_RECEIVED',
            last_result=NULL,updated_at=NOW()`,[returnedSn,transfer.batch_id]);
      }
      await query(`UPDATE ng_revival_audit SET approval_status='RETURN_RECEIVED_RETEST_REQUIRED'
        WHERE approval_status='RETURN_PENDING' AND (batch_id=$1 OR sn=ANY($2::text[]))`,[transfer.batch_id,memberSns]);
      await stationRepairWorkOrderReady;
      await query(`UPDATE station_repair_work_orders SET status='RETURN_RECEIVED_RETEST_REQUIRED',updated_at=NOW()
        WHERE batch_id=$1 AND status IN('PENDING_QUALITY','RETURN_PENDING','REPAIRED')`,[transfer.batch_id]);
      for(const board of acceptedBoards){
        const returnedSn=String(board.sn||'').trim();
        if(!returnedSn)continue;
        destination.pending_ng=upsertBySn(destination.pending_ng,{...board,sn:returnedSn,batchId:transfer.batch_id,
          stage:'RETURN_RECEIVED_RETEST_REQUIRED',transferStatus:'RECEIVED',receivedAt:acceptedAt,
          acceptedBy:`SCANNER:${destinationStationCode}`,receiptSn:scannedSn,mesRetestAuthorized:true});
      }
      neuralBroadcast({from:'mes_server',to:'*',type:'REPAIR_RETURN_RETEST_REQUIRED',priority:'critical',
        stationCode:destinationStationCode,payload:{batchId:transfer.batch_id,sns:memberSns,receiptSn:scannedSn,
          receivedAt:acceptedAt,ngReleased:false,retestArmed:true,ackRequired:true}});
    }
    if(!assemblyRetestRequired){
    const validationRoute=Array.isArray(acceptedBoards[0]?.validationRoute)?acceptedBoards[0].validationRoute:[];
    const currentValidationIndex=validationRoute.indexOf(destinationStationCode);
    const nextValidationStation=currentValidationIndex>=0?validationRoute[currentValidationIndex+1]:null;
    if(nextValidationStation){
      await query(`UPDATE ng_revival_audit SET return_station=$3
        WHERE approval_status='RETURN_PENDING' AND (batch_id=$1 OR sn=ANY($2::text[]))`,
        [transfer.batch_id,memberSns,nextValidationStation]);
      await query(`INSERT INTO station_handover_transfers
        (batch_id,source_station,destination_station,destination_type,motherboard,member_count,status,sent_at)
        VALUES($1,$2,$3,'REPAIR_RETURN',$4,$5,'WAITING_RECEIPT',NOW())
        ON CONFLICT(batch_id,source_station,destination_station) DO UPDATE SET status='WAITING_RECEIPT',
          motherboard=EXCLUDED.motherboard,member_count=EXCLUDED.member_count,sent_at=NOW(),received_at=NULL,accepted_by=NULL,alarmed_at=NULL`,
        [transfer.batch_id,destinationStationCode,nextValidationStation,JSON.stringify(transfer.motherboard),memberSns.length]);
      neuralBroadcast({from:'mes_server',to:'*',type:'NG_VALIDATION_NEXT_POSITION',priority:'critical',
        stationCode:destinationStationCode,payload:{batchId:transfer.batch_id,sns:memberSns,
          completedStation:destinationStationCode,requiredStation:nextValidationStation,ngReleased:false}});
    }else{
    const revived=await query(`UPDATE ng_revival_audit SET approval_status='REVIVED',revived_at=NOW()
      WHERE approval_status='RETURN_PENDING' AND (batch_id=$1 OR sn=ANY($2::text[]))
      RETURNING sn,origin_station,return_station`,[transfer.batch_id,memberSns]);
    const revivedSns=revived.rows.map(row=>String(row.sn).trim()).filter(Boolean);
    if(revivedSns.length){
      await stationNgReleaseReady;
      for(const releasedSn of revivedSns)await query(`INSERT INTO station_ng_release_events(sn,batch_id,origin_station)
        VALUES($1,$2,$3) ON CONFLICT(sn,batch_id,release_reason) DO NOTHING`,[releasedSn,transfer.batch_id,destinationStationCode]);
      // ng_pool and ng_defect_records are historical records — never modified or deleted
      const stations=await query(`SELECT DISTINCT station_code FROM station_bucket_snapshots
        WHERE bucket_name IN ('pending_ng','confirmed_ng')`);
      const revivedSet=new Set(revivedSns.map(value=>value.toUpperCase()));
      for(const station of stations.rows){
        const stationState=await readStationBuckets(station.station_code);
        const keep=item=>!revivedSet.has(String(item.sn||'').trim().toUpperCase());
        const pending=stationState.pending_ng.filter(keep);const confirmed=stationState.confirmed_ng.filter(keep);
        if(pending.length!==stationState.pending_ng.length) await commitStationBucket(station.station_code,'pending_ng',pending);
        if(confirmed.length!==stationState.confirmed_ng.length) await commitStationBucket(station.station_code,'confirmed_ng',confirmed);
      }
      neuralBroadcast({from:'mes_server',to:'*',type:'NG_REVIVED',priority:'critical',stationCode:destinationStationCode,
        payload:{batchId:transfer.batch_id,sns:revivedSns,receiptSn:scannedSn,receivedAt:acceptedAt,
          approved:true,receiptConfirmed:true,removeLocalNg:true,ackRequired:true}});
      await resolveNgAlarmById({
        alarmId: `NG_REVIVAL:${transfer.batch_id}`,
        alarmType: 'NG_REVIVAL',
        reason: 'NG_REVIVED',
        batchId: transfer.batch_id,
        sns: revivedSns,
        stationCode: destinationStationCode,
        detail: { receiptSn: scannedSn, revived: true },
      });
      await resolveNgPickupAlarmsForReceipt({
        batchId: transfer.batch_id,
        bucketQr: transfer.motherboard?.bucketQr,
        sns: revivedSns,
        stationCode: destinationStationCode,
        reason: 'NG_REVIVED',
      });
    }
    }
    }
  }
  if(String(transfer.destination_type||'').toUpperCase()==='PASS_RETURN'){
    await Promise.all([passReturnReady,passShortageReady]);
    const returnId=Number(transfer.motherboard?.passReturnId||0);
    if(returnId){
      const completed=await query(`UPDATE station_pass_return_requests SET status='COMPLETED',received_at=NOW(),received_by=$2
        WHERE return_id=$1 AND status='WAITING_RECEIPT' RETURNING shortage_id`,[returnId,`SCANNER:${destinationStationCode}`]);
      const shortageId=completed.rows[0]?.shortage_id;
      if(shortageId) await query(`UPDATE station_pass_shortages SET status='RESOLVED',resolved_at=NOW() WHERE shortage_id=$1`,[shortageId]);
      neuralBroadcast({from:'mes_server',to:'*',type:'PASS_RETURN_COMPLETED',priority:'info',stationCode:destinationStationCode,
        payload:{returnId,batchId:transfer.batch_id,receiptSn:scannedSn,receivedAt:acceptedAt,shortageId}});
    }
  }
  await commitStationBucket(destinationStationCode, "pending_ng", destination.pending_ng);
  await commitStationBucket(destinationStationCode, "confirmed_ng", destination.confirmed_ng);
  await commitStationBucket(destinationStationCode, "process", [{
    stage: destinationStationCode==='manu_agingcab'?"AGING_IN_PROGRESS":"TRANSFER_RECEIVED_BY_SCAN", batchId: transfer.batch_id,
    sourceStationCode: transfer.source_station, receiptSn: scannedSn, acceptedAt,
    ...(destinationStationCode==='manu_agingcab'?{agingStartedAt:acceptedAt,agingDeadlineAt:acceptedAt+2*60*60*1000,
      agingDurationSeconds:2*60*60,ngMayOccurAnytime:true}:{}),
  }]);
  await commitStationBucket(transfer.source_station, "pending_ng", source.pending_ng);
  await commitStationBucket(transfer.source_station, "confirmed_ng", source.confirmed_ng);
  await commitStationBucket(transfer.source_station, "pass", source.pass);
  await commitStationBucket(transfer.source_station, "process", [{
    stage: "HANDOVER_COMPLETED", batchId: transfer.batch_id,
    destinationStationCode, receiptSn: scannedSn, acceptedAt,
  }]);
  neuralBroadcast({ from: "mes_server", to: "*", type: "HANDOVER_TIMEOUT_RELEASE",
    stationCode: transfer.source_station, payload: { batchId: transfer.batch_id,
      sourceStationCode: transfer.source_station, destinationStationCode, receiptSn: scannedSn }, priority: "info" });
  return { batchId: transfer.batch_id, sourceStationCode: transfer.source_station,
    destinationStationCode, receiptSn: scannedSn, acceptedAt };
}

// MES owns the handover clock so alarms remain consistent across all browsers.
async function reportMesIntegrityLeak(type,stationCode,entityId,detail,severity='critical'){
  await mesIntegrityReady;
  const fingerprint=`${type}:${stationCode||''}:${entityId||''}`;
  const inserted=await query(`INSERT INTO station_mes_integrity_alerts
    (fingerprint,alert_type,station_code,entity_id,severity,detail) VALUES($1,$2,$3,$4,$5,$6)
    ON CONFLICT(fingerprint) DO UPDATE SET last_detected_at=NOW(),status='OPEN',resolved_at=NULL,
      severity=EXCLUDED.severity,detail=EXCLUDED.detail RETURNING alert_id,(first_detected_at=last_detected_at) AS fresh`,
    [fingerprint,type,stationCode||null,entityId||null,severity,JSON.stringify(detail||{})]);
  if(inserted.rows[0]?.fresh)neuralBroadcast({from:'mes_integrity_watchdog',to:'*',type:'MES_INTEGRITY_LEAK',
    priority:severity,stationCode,payload:{alertId:inserted.rows[0].alert_id,alertType:type,entityId,...detail}});
}

setInterval(async()=>{
  try{
    await Promise.all([mesIntegrityReady,packagingBoxAuditReady,stationAgingHistoryReady,stationRepairWorkOrderReady,palletBindingReady]);
    const passNg=await query(`SELECT p.station_code,item->>'sn' sn FROM station_bucket_snapshots p
      CROSS JOIN LATERAL jsonb_array_elements(p.payload) item WHERE p.bucket_name='pass' AND COALESCE(item->>'sn','')<>''
      AND EXISTS(SELECT 1 FROM station_bucket_snapshots n CROSS JOIN LATERAL jsonb_array_elements(n.payload) ng
        WHERE n.station_code=p.station_code AND n.bucket_name='confirmed_ng' AND UPPER(ng->>'sn')=UPPER(item->>'sn')) LIMIT 500`);
    for(const row of passNg.rows)await reportMesIntegrityLeak('SN_IN_PASS_AND_CONFIRMED_NG',row.station_code,row.sn,row);
    const boxes=await query(`SELECT container_id,current_count,jsonb_array_length(items) actual_count,status,capacity
      FROM station_packaging_boxes WHERE current_count<>jsonb_array_length(items) OR current_count>capacity
      OR (status IN('full','sealed') AND current_count<capacity)`);
    for(const row of boxes.rows)await reportMesIntegrityLeak('CASE_COUNT_OR_STATUS_MISMATCH','manu_case_binding',row.container_id,row);
    const pallets=await query(`SELECT p.pallet_code,p.status,p.target_cartons,COUNT(pc.container_id)::int carton_count,
      BOOL_AND(COALESCE(b.status,'missing') IN('full','sealed')) all_cases_closed FROM station_pallets p
      LEFT JOIN station_pallet_cartons pc ON pc.pallet_code=p.pallet_code LEFT JOIN station_packaging_boxes b ON b.container_id=pc.container_id
      GROUP BY p.pallet_code HAVING (p.status='sealed' AND (COUNT(pc.container_id)<>p.target_cartons OR NOT BOOL_AND(COALESCE(b.status,'missing') IN('full','sealed'))))`);
    for(const row of pallets.rows)await reportMesIntegrityLeak('INVALID_SEALED_PALLET','manu_pallet_binding',row.pallet_code,row);
    const aging=await query(`SELECT sn,batch_id,status,latest_result,completed_at FROM station_aging_control
      WHERE status='COMPLETED_AGING' AND completed_at<NOW()-INTERVAL '30 minutes'`);
    for(const row of aging.rows)await reportMesIntegrityLeak('AGING_RELEASE_NOT_RECEIVED','manu_agingcab',row.sn,row,'warning');
    const repairs=await query(`SELECT rwo.work_order_no,rwo.ng_sn,rwo.status,rwo.source_station FROM station_repair_work_orders rwo
      WHERE rwo.status IN('WAITING_RECEIPT','REPAIR_IN_PROGRESS') AND NOT EXISTS(SELECT 1 FROM station_handover_transfers h
        WHERE h.batch_id=rwo.batch_id AND h.destination_station='manu_rework' AND h.status IN('WAITING_RECEIPT','RECEIVED'))`);
    for(const row of repairs.rows)await reportMesIntegrityLeak('REPAIR_WO_WITHOUT_HANDOVER',row.source_station,row.work_order_no,row);
    const leaks=await query(`SELECT residence_id,sn,batch_id,station_code,next_station_code,exited_at FROM station_product_residence
      WHERE exited_at<NOW()-INTERVAL '2 minutes' AND next_station_code IS NOT NULL AND next_residence_id IS NULL
      AND product_state NOT IN('SCRAPPED','REPAIR_QUALITY_HOLD') LIMIT 1000`);
    for(const row of leaks.rows)await reportMesIntegrityLeak('STATION_OUT_WITHOUT_NEXT_IN',row.station_code,row.sn,row);
    const unknownRoute=await query(`SELECT p.root_sn,p.station_code,p.source_sn,p.sequence_order FROM station_sn_route_progress p
      WHERE COALESCE(p.source_sn,'')='' OR NOT EXISTS(SELECT 1 FROM station_sequences s WHERE s.station_code=p.station_code) LIMIT 1000`);
    for(const row of unknownRoute.rows)await reportMesIntegrityLeak('ROUTE_WITHOUT_PROVENANCE',row.station_code,row.root_sn,row);
    const missingDestination=await query(`SELECT r.residence_id,r.sn,r.station_code,r.exited_at FROM station_product_residence r
      JOIN station_sequences s ON s.station_code=r.station_code WHERE r.status='LEFT_STATION' AND r.next_station_code IS NULL
      AND s.sequence_order<(SELECT MAX(sequence_order) FROM station_sequences WHERE line_code=s.line_code)
      AND r.product_state NOT IN('SCRAPPED','REPAIR_QUALITY_HOLD') LIMIT 1000`);
    for(const row of missingDestination.rows)await reportMesIntegrityLeak('STATION_OUT_WITHOUT_DESTINATION',row.station_code,row.sn,row);
  }catch(error){console.error('[MES INTEGRITY WATCHDOG]',error.message);}
},30000);

setInterval(async()=>{
  try{
    await stationAgingHistoryReady;
    const ready=await query(`UPDATE station_aging_control SET status='COMPLETED_AGING',completed_at=NOW(),updated_at=NOW()
      WHERE status IN('AGING_IN_PROGRESS','NG_MARKED') AND aging_deadline_at<=NOW()
      RETURNING sn,batch_id,aging_started_at,aging_deadline_at,latest_result`);
    if(!ready.rows.length)return;
    const state=await readStationBuckets('manu_agingcab');
    for(const row of ready.rows){
      state.pass=upsertBySn(state.pass,{sn:row.sn,batchId:row.batch_id||row.sn,result:'AGING_COMPLETE',agingMark:row.latest_result,time:Date.now(),
        agingStartedAt:new Date(row.aging_started_at).getTime(),agingDeadlineAt:new Date(row.aging_deadline_at).getTime(),
        agingCompleted:true,destinationStationCode:'manu_hivolt_ate'});
      state.pending_ng=state.pending_ng.filter(item=>String(item.sn||'').toUpperCase()!==String(row.sn).toUpperCase());
      await query(`INSERT INTO station_aging_events
        (sn,batch_id,event_type,result,source_type,aging_started_at,aging_deadline_at,destination_station,detail)
        VALUES($1,$2,'RELEASED',$6,'MES_TIMER',$3,$4,'manu_hivolt_ate',$5)`,
        [row.sn,row.batch_id||row.sn,row.aging_started_at,row.aging_deadline_at,
          JSON.stringify({twoHourGateSatisfied:true,mesSupervised:true,agingMark:row.latest_result}),row.latest_result||'UNMARKED']);
    }
    await commitStationBucket('manu_agingcab','pass',state.pass);
    await commitStationBucket('manu_agingcab','pending_ng',state.pending_ng);
    await commitStationBucket('manu_agingcab','process',ready.rows.map(row=>({stage:'AGING_COMPLETED_READY_NEXT',
      sn:row.sn,batchId:row.batch_id||row.sn,destinationStationCode:'manu_hivolt_ate',completedAt:Date.now()})));
    neuralBroadcast({from:'mes_server',to:'*',type:'AGING_COMPLETED_READY_NEXT',priority:'info',stationCode:'manu_agingcab',
      payload:{sns:ready.rows.map(row=>row.sn),destinationStationCode:'manu_hivolt_ate',mesSupervised:true}});
  }catch(error){console.error('aging completion watcher:',error.message);}
},5000);

setInterval(async () => {
  try {
    await stationHandoverAlarmReady;
    const expired = await query(`UPDATE station_handover_transfers
      SET alarmed_at=NOW()
      WHERE status='WAITING_RECEIPT' AND alarmed_at IS NULL AND (
        ((destination_station='manu_rework' OR destination_type='REPAIR_RETURN') AND sent_at <= NOW() - INTERVAL '15 minutes') OR
        (destination_station<>'manu_rework' AND destination_type<>'REPAIR_RETURN' AND sent_at <= NOW() - INTERVAL '2 minutes'))
      RETURNING batch_id,source_station,destination_station,destination_type,sent_at`);
    for (const row of expired.rows) {
      const isRepairReceipt=row.destination_station==='manu_rework'||row.destination_type==='REPAIR_RETURN';
      const payload = { batchId: row.batch_id, sourceStationCode: row.source_station,
        destinationStationCode: row.destination_station, sentAt: row.sent_at,
        timeoutSeconds: isRepairReceipt?900:120,
        message: isRepairReceipt?(row.destination_type==='REPAIR_RETURN'?"维修返回超过15分钟未扫码收货":"送往维修站超过15分钟未扫码收货"):"交接超过2分钟未完成" };
      neuralBroadcast({ from: "mes_server", to: "*", type: "HANDOVER_TIMEOUT",
        stationCode: row.source_station, payload, priority: "critical" });
      await commitStationBucket(row.source_station, "process", [{ stage: "HANDOVER_TIMEOUT", ...payload, updatedAt: Date.now() }]);
      await commitStationBucket(row.destination_station, "process", [{ stage: "HANDOVER_TIMEOUT", ...payload, updatedAt: Date.now() }]);
    }
  } catch (error) {
    console.error("[HANDOVER TIMEOUT]", error.message);
  }
}, 5000);

// MES derives the active maintenance-dispatch batch from each authoritative
// confirmed-NG box, uses its oldest NG as the clock base, and raises one
// critical alarm when the batch has not been submitted within 20 minutes.
setInterval(async()=>{
  try{
    await Promise.all([stationSnapshotTableReady,stationNgDispatchAlarmReady]);
    for(const trackedStation of [
      'manu_depanel','manu_assem_ate',
      'smt_pda_loading','smt_laser_marking','smt_auto_insertion',
      'smt_printer','smt_spi','smt_placement','smt_aoi'
    ]){
      const active=await query(`WITH items AS (
      SELECT item,COALESCE(
        CASE WHEN COALESCE(item->>'firstFailureTime','')~'^[0-9]+$' THEN (item->>'firstFailureTime')::bigint END,
        CASE WHEN COALESCE(item->>'detectedAt','')~'^[0-9]+$' THEN (item->>'detectedAt')::bigint END,
        CASE WHEN COALESCE(item->>'time','')~'^[0-9]+$' THEN (item->>'time')::bigint END,
        (EXTRACT(EPOCH FROM s.updated_at)*1000)::bigint) AS detected_ms
      FROM station_bucket_snapshots s
      CROSS JOIN LATERAL jsonb_array_elements(s.payload) item
      WHERE s.station_code=$1 AND s.bucket_name='confirmed_ng')
      SELECT MD5(STRING_AGG(UPPER(COALESCE(item->>'sn','')),',' ORDER BY UPPER(COALESCE(item->>'sn','')))) signature,
        MIN(detected_ms) oldest_ms,COUNT(*)::int ng_count,
        ARRAY_AGG(UPPER(COALESCE(item->>'sn','')) ORDER BY detected_ms) sns
      FROM items HAVING COUNT(*)>0`,[trackedStation]);
      if(active.rows.length){
      const batch=active.rows[0];
      if(Date.now()-Number(batch.oldest_ms)>=20*60*1000){
        const inserted=await query(`INSERT INTO station_ng_dispatch_alarm
          (batch_signature,station_code,oldest_ng_detected_at,ng_count,detail)
          VALUES($1,$5,TO_TIMESTAMP($2::double precision/1000.0),$3,$4)
          ON CONFLICT(batch_signature) DO NOTHING RETURNING batch_signature`,
          [`${trackedStation}:${batch.signature}`,Number(batch.oldest_ms),Number(batch.ng_count),JSON.stringify({sns:batch.sns}),trackedStation]);
        if(inserted.rows.length){
          const payload={batchSignature:batch.signature,ngCount:Number(batch.ng_count),sns:batch.sns,
            oldestNgDetectedAt:Number(batch.oldest_ms),dispatchDeadlineAt:Number(batch.oldest_ms)+20*60*1000,
            destinationStation:'manu_rework',message:'NG批次最老产品已滞留20分钟，请立即确认发往维修站'};
          neuralBroadcast({from:'mes_server',to:'*',type:'NG_MAINTENANCE_DISPATCH_TIMEOUT',
            stationCode:trackedStation,payload,priority:'critical'});
          const source=await readStationBuckets(trackedStation);
          source.process=[{stage:'NG_MAINTENANCE_DISPATCH_TIMEOUT',...payload,updatedAt:Date.now()},...source.process].slice(0,1000);
          await commitStationBucket(trackedStation,'process',source.process);
          const repair=await readStationBuckets('manu_rework');
          repair.process=[{stage:'INCOMING_NG_BATCH_OVERDUE',...payload,updatedAt:Date.now()},...repair.process].slice(0,1000);
          await commitStationBucket('manu_rework','process',repair.process);
        }
      }
    }
    }
  }catch(error){console.error('[NG DISPATCH TIMEOUT]',error.message);}
},5000);

// Repair deadline is MES-owned and begins at the first NG discovery—not at
// transfer submission or maintenance receipt.  It continues through every
// handover state and alarms once when the fixed deadline is exceeded.
setInterval(async () => {
  try {
    await stationRouteRequestReady;
    const expired=await query(`UPDATE station_route_requests SET repair_alarm_at=NOW()
      WHERE status IN ('WAITING_RECEIPT','REPAIR_IN_PROGRESS')
        AND COALESCE(repair_deadline_at,submitted_at+INTERVAL '2 hours')<=NOW()
        AND repair_alarm_at IS NULL
      RETURNING request_id,batch_id,source_station,destination_station,repair_started_at,
        first_discovered_at,repair_deadline_at`);
    for(const row of expired.rows){
      const payload={requestId:row.request_id,batchId:row.batch_id,sourceStation:row.source_station,
        destinationStation:row.destination_station,repairStartedAt:row.repair_started_at,
        firstDiscoveredAt:row.first_discovered_at,repairDeadlineAt:row.repair_deadline_at,
         timeoutSeconds:7200,message:'NG自首次发现起超过2小时仍未完成维修复活'};
      neuralBroadcast({from:'mes_server',to:'*',type:'REPAIR_TIMEOUT',stationCode:'manu_rework',payload,priority:'critical'});
      await commitStationBucket('manu_rework','process',[{stage:'REPAIR_TIMEOUT',...payload,updatedAt:Date.now()}]);
      await commitStationBucket(row.source_station,'process',[{stage:'REPAIR_TIMEOUT',...payload,updatedAt:Date.now()}]);
    }
  }catch(error){console.error('[REPAIR TIMEOUT]',error.message);}
},5000);

async function projectStationProductionEvent(eventId, stationCode, type, payload) {
  if (!stationCode) return { projected: false, persisted: false };
  await stationEventLedgerReady;
  const inserted = await query(`
    INSERT INTO station_production_events (event_id,station_code,event_type,payload)
    VALUES ($1,$2,$3,$4) ON CONFLICT (event_id) DO NOTHING RETURNING event_id`,
    [eventId, stationCode, type, JSON.stringify(payload || {})]);
  if (!inserted.rows.length) return { projected: false, persisted: true, duplicate: true };
  await recordRouteCompletion(eventId,stationCode,type,payload||{});

  // Every station event is durably acknowledged before HTTP 200. Only the
  // known business events below also mutate bucket read models. This keeps
  // offline replay lossless without coupling new event types to projections.
  if (!["SN_SCAN", "STATION_TEST_RESULT", "NG_DEFECT", "STATION_NG_MARKED", "STATION_NG_PICKED", "DUPLICATE_SN", "DEPANEL_NG_PICKED", "ICT_PROCESS", "FCT_PROCESS", "ICT_ROUTE_SELECTED", "STATION_ROUTE_SELECTED", "REPAIR_STEP_CONFIRMED", "REPAIR_TEST_COMPLETED", "REPAIR_SCRAPPED", "RETEST_ARMED"].includes(type)) {
    return { projected: false, persisted: true };
  }

  const state = await readStationBuckets(stationCode);
  const now = Date.now();
  const stats = state.stats[0] || { total: 0, pass: 0, fail: 0, dup: 0 };
  const changed = new Set();
  let routeTransfer = null;
  let ngBoardStationResults = {};
  // A complete ICT/FCT result is the merge trigger. This runs for PASS, FAIL
  // and retest events; FCT never creates identity when the ICT board is absent.
  if (['manu_ict','manu_fct','auto_ict','auto_fct'].includes(String(stationCode||'').toLowerCase())
      && Array.isArray(payload?.subBoards) && payload.subBoards.length > 0) {
    await mergeConfirmedMotherboardLayout(stationCode, payload);
  }

  if (type === "STATION_NG_PICKED") {
    const sn=String(payload.sn||'').trim().toUpperCase();
    let source=String(payload.sourceStationCode||'').trim();
    if(sn&&!source){
      const snapshots=(await query(`SELECT station_code,bucket_name,payload FROM station_bucket_snapshots
        WHERE bucket_name IN ('pending_ng','confirmed_ng') AND payload @> $1::jsonb`,[JSON.stringify([{sn}])])).rows;
      source=String(snapshots[0]?.station_code||'');
    }
    if(sn&&source){
      const sourceState=await readStationBuckets(source);
      const removeSn=rows=>(Array.isArray(rows)?rows:[]).filter(item=>String(item.sn||'').trim().toUpperCase()!==sn);
      sourceState.pending_ng=removeSn(sourceState.pending_ng);sourceState.confirmed_ng=removeSn(sourceState.confirmed_ng);
      await commitStationBucket(source,'pending_ng',sourceState.pending_ng);
      await commitStationBucket(source,'confirmed_ng',sourceState.confirmed_ng);
      if(source==='manu_agingcab'){
        await stationAgingHistoryReady;
        await query(`UPDATE station_aging_control SET status='PICKED',updated_at=NOW() WHERE UPPER(sn)=UPPER($1)`,[sn]);
      }
      neuralBroadcast({from:'mes_ng_registry',to:'*',type:'STATION_NG_PICKED',priority:'info',stationCode,
        payload:{...payload,sn,sourceStationCode:source,active:false,blocked:false,alarm:false}});
    }
    return {projected:true,ngPicked:true,sn,sourceStationCode:source};
  } else if (type === "DEPANEL_NG_PICKED") {
    const sn = String(payload.sn || "").trim();
    if (sn) {
      state.pending_ng = state.pending_ng.map(item => String(item.sn || "").toUpperCase() === sn.toUpperCase()
        ? { ...item, status: "BOXED", pickedAt: payload.pickedAt || now,
            identifiedBy: payload.identifiedBy || null, batchId: payload.batchId || item.batchId }
        : item);
      state.confirmed_ng = state.confirmed_ng.filter(item => item.sn !== sn);
      changed.add("pending_ng"); changed.add("confirmed_ng");
    }
  } else if (type === "ICT_ROUTE_SELECTED" || type === "STATION_ROUTE_SELECTED") {
    let batchId = String(payload.batchId || payload.sn || "");
    let destination = String(payload.destination || "");
    let workflowCode=String(payload.workflowCode || (destination==="SCRAP_APPROVAL"?"MES_SCRAP_APPROVAL":
      destination==="MAINTENANCE"?"MES_REPAIR_HANDOVER":"MES_NEXT_STATION_HANDOVER"));
    let requestedTarget=payload.destinationStationCode || (destination==="MAINTENANCE"?"manu_rework":
      (destination==="DEPANEL" || stationCode==="manu_fct"?"manu_depanel":"manu_fct"));
    // FCT confirmed NG must be physically split and classified at depanel
    // before any repair WO can be created. Never allow direct FCT -> repair.
    if(stationCode==='manu_fct' && destination==='MAINTENANCE'){
      destination='DEPANEL';requestedTarget='manu_depanel';
      payload.destination='DEPANEL';payload.destinationStationCode='manu_depanel';
      payload.destinationLabel='分板FCT不良箱';payload.workflowCode='MES_DEPANEL_FCT_NG_HANDOVER';
      workflowCode='MES_DEPANEL_FCT_NG_HANDOVER';
      payload.routeOverrideReason='FCT_CONFIRMED_NG_MUST_DEPANEL';
    }
    if(destination==='MAINTENANCE'&&['manu_hivolt_ate','manu_package_ate'].includes(stationCode)){
      await stationRetestReady;
      const specialRetest=(await query(`SELECT attempts_used FROM station_retest_control WHERE station_code=$1 AND UPPER(sn)=UPPER($2)`,[stationCode,String(payload.sn||payload.mainSn||batchId)])).rows[0];
      if(Number(specialRetest?.attempts_used||0)<3){destination='NEXT_STATION';requestedTarget='manu_agingcab';
        payload.destination='NEXT_STATION';payload.destinationStationCode='manu_agingcab';payload.routeOverrideReason='AGING_CAB_RETESTS_REQUIRED';
        neuralBroadcast({from:'mes_server',to:'*',type:'AGING_CAB_RETEST_REQUIRED',priority:'critical',stationCode,
          payload:{sn:payload.sn||payload.mainSn,batchId,destinationStation:'manu_agingcab',attemptsUsed:Number(specialRetest?.attempts_used||0),requiredAttempts:3}});
      }
    }
    if (destination === "SCRAP_APPROVAL" && batchId) {
      const located = [...state.pending_ng, ...state.confirmed_ng, ...state.pass]
        .find(item => String(item.sn || "").toUpperCase() === batchId.toUpperCase());
      if (located?.batchId) batchId = String(located.batchId);
    }
    const applyRoute = records => records.map(item => String(item.batchId || "") === batchId
      ? { ...item, destination, routeSelectedAt: now } : item);
    state.pending_ng = applyRoute(state.pending_ng);
    state.confirmed_ng = applyRoute(state.confirmed_ng);
    state.process = [{ ...payload, stage: "ROUTE_SELECTED", stationCode, updatedAt: now }];
    await stationRouteRequestReady;
    const existingRoute=await query(`SELECT request_id FROM station_route_requests WHERE batch_id=$1 AND source_station=$2
      AND status IN ('SUBMITTED','PENDING_APPROVAL','WAITING_RECEIPT') ORDER BY submitted_at DESC LIMIT 1`,[batchId,stationCode]);
    let routeRequestId=existingRoute.rows[0]?.request_id;
    if(!routeRequestId){
      const createdRoute=await query(`INSERT INTO station_route_requests
        (batch_id,source_station,destination_code,destination_station,workflow_code,motherboard,status,submitted_by,processed_at,notification_status,detail)
        VALUES($1,$2,$3,$4,$5,$6,$7,$8,NOW(),'SENT',$9) RETURNING request_id`,
        [batchId,stationCode,destination,requestedTarget,workflowCode,JSON.stringify(payload.motherboard||{}),
         destination==="SCRAP_APPROVAL"?"PENDING_APPROVAL":"WAITING_RECEIPT",payload.operator||stationCode,JSON.stringify(payload)]);
      routeRequestId=createdRoute.rows[0].request_id;
    }
    neuralBroadcast({from:"mes_server",to:"*",type:"ROUTE_REQUEST_ACCEPTED",priority:"critical",stationCode,
      payload:{requestId:routeRequestId,batchId,destination,destinationStation:requestedTarget,workflowCode}});
    if(destination==="MAINTENANCE" && stationCode.startsWith("smt_")){
      await Promise.all([stationHandoverReady,stationRepairWorkOrderReady]);
      const ngSn=String(payload.sn||payload.mainSn||batchId).trim().toUpperCase();
      const firstDetectedAt=Number(payload.firstDetectedAt||now);
      const repairDeadlineAt=Number(payload.repairDeadlineAt||firstDetectedAt+120*60*1000);
      const workOrderNo=`RWO-SMT-${new Date().toISOString().slice(0,10).replace(/-/g,"")}-${String(routeRequestId).padStart(6,"0")}`;
      const motherboard={sn:ngSn,subBoards:[{sn:ngSn,result:"FAIL"}],sourceStationCode:stationCode,
        defectCode:payload.defectCode||`${stationCode.toUpperCase()}_FAIL`,
        defectDescription:payload.defectDescription||"SMT confirmed NG",
        returnStations:[stationCode],validationRoute:[stationCode]};
      payload.motherboard=motherboard;
      const transferExists=await query(`SELECT transfer_id FROM station_handover_transfers
        WHERE batch_id=$1 AND source_station=$2 AND destination_station='manu_rework'
          AND status='WAITING_RECEIPT' LIMIT 1`,[batchId,stationCode]);
      if(!transferExists.rows.length)await query(`INSERT INTO station_handover_transfers
        (batch_id,source_station,destination_station,destination_type,motherboard,member_count,status,sent_at)
        VALUES($1,$2,'manu_rework','MAINTENANCE',$3,1,'WAITING_RECEIPT',NOW())`,
        [batchId,stationCode,JSON.stringify(motherboard)]);
      await query(`INSERT INTO station_repair_work_orders
        (work_order_no,route_request_id,batch_id,ng_sn,source_station,source_station_name,
         motherboard,created_by,first_discovered_at,repair_deadline_at)
        VALUES($1,$2,$3,$4,$5,$6,$7,$8,TO_TIMESTAMP($9::double precision/1000.0),
          TO_TIMESTAMP($10::double precision/1000.0))
        ON CONFLICT(route_request_id) DO NOTHING`,
        [workOrderNo,routeRequestId,batchId,ngSn,stationCode,stationCode,
         JSON.stringify(motherboard),payload.operator||stationCode,firstDetectedAt,repairDeadlineAt]);
      neuralBroadcast({from:"mes_server",to:"*",type:"MAINTENANCE_HANDOVER_BILL_CREATED",
        priority:"critical",stationCode,payload:{requestId:routeRequestId,repairWorkOrderNo:workOrderNo,
          batchId,ngSn,sourceStation:stationCode,destinationStation:"manu_rework",
          firstDetectedAt,repairDeadlineAt,status:"WAITING_RECEIPT"}});
    }
    if (destination === "SCRAP_APPROVAL") {
      await stationScrapColumnsReady;
      const existingScrap = await query(`SELECT request_id FROM station_scrap_requests
        WHERE batch_id=$1 AND station_code=$2 AND status IN ('PENDING_MES_APPROVAL','SCRAPPED_HELD')
        ORDER BY requested_at DESC LIMIT 1`, [batchId, stationCode]);
      if (!existingScrap.rows.length) {
        const requestReason = String(payload.requestReason || "S99 工位申请报废");
        const reasonCode = (requestReason.match(/^(S\d{2})\b/) || [])[1] || "S99";
        const created = await query(`INSERT INTO station_scrap_requests
          (batch_id,station_code,motherboard,status,requested_at,request_reason,reason_code,reason_detail,
           applicant,responsible_person,equipment_no)
          VALUES($1,$2,$3,'PENDING_MES_APPROVAL',NOW(),$4,$5,$6,$7,$8,$9) RETURNING request_id`,
          [batchId, stationCode, JSON.stringify(payload.motherboard || {}), requestReason, reasonCode,
           String(payload.reasonDetail || requestReason), String(payload.applicant || payload.operator || stationCode),
           payload.responsiblePerson || null, payload.equipmentNo || null]);
        await stationScrapAuditReady;
        await query(`INSERT INTO station_scrap_audit(request_id,action,actor,detail) VALUES($1,'SUBMITTED',$2,$3)`,
          [created.rows[0].request_id, String(payload.applicant || payload.operator || stationCode), JSON.stringify(payload)]);
      }
      state.process = [{ ...payload, stage: "SCRAP_PENDING_MES_APPROVAL", stationCode, batchId, updatedAt: now }];
      neuralBroadcast({ from: "mes_server", to: "*", type: "SCRAP_PENDING_MES_APPROVAL", stationCode,
        payload: { batchId, reason: payload.requestReason || "S99 工位申请报废" }, priority: "critical" });
      routeTransfer = null;
    } else {
      routeTransfer = { batchId, destination, destinationStationCode: payload.destinationStationCode,
        motherboard: payload.motherboard || {} };
    }
    changed.add("pending_ng"); changed.add("confirmed_ng"); changed.add("process");
  } else if (type === "ICT_PROCESS" || type === "FCT_PROCESS") {
    state.process = [{ ...payload, stationCode, updatedAt: now }];
    changed.add("process");
  } else if (type === "SN_SCAN" && stationCode === 'manu_agingcab' && String(payload.result || "PASS").toUpperCase() === "PASS") {
    const sn=String(payload.sn||payload.pcbSerial||'').trim().toUpperCase();
    await stationAgingHistoryReady;
    const aging=(await query(`INSERT INTO station_aging_control(sn,batch_id,aging_started_at,aging_deadline_at,latest_result)
      VALUES($1,$2,NOW(),NOW()+INTERVAL '2 hours','PASS')
      ON CONFLICT(sn) DO UPDATE SET latest_result='PASS',updated_at=NOW()
      RETURNING sn,batch_id,aging_started_at,aging_deadline_at,status`,[sn,payload.batchId||sn])).rows[0];
    await query(`INSERT INTO station_aging_events
      (sn,batch_id,event_type,result,source_type,aging_started_at,aging_deadline_at,detail)
      VALUES($1,$2,'RESULT_OBSERVED','PASS',$3,$4,$5,$6)`,
      [sn,aging.batch_id,String(payload.eventType||'STATION_TEST'),aging.aging_started_at,aging.aging_deadline_at,
        JSON.stringify({testTime:payload.sourceTestTimeIso||now,mesSupervised:true})]);
    if(new Date(aging.aging_deadline_at).getTime()>Date.now()){
      state.process=[{stage:'AGING_PASS_MARKED_WAITING_2_HOURS',sn,batchId:aging.batch_id,
        agingStartedAt:new Date(aging.aging_started_at).getTime(),agingDeadlineAt:new Date(aging.aging_deadline_at).getTime(),
        latestResult:'PASS',mesSupervised:true,updatedAt:now}];
      changed.add('process');state.stats=[stats];
      neuralBroadcast({from:'mes_server',to:'*',type:'AGING_RESULT_MARKED',priority:'info',stationCode,
        payload:{sn,result:'PASS',released:false,agingDeadlineAt:aging.aging_deadline_at}});
    }else{
      await query(`UPDATE station_aging_control SET status='COMPLETED_AGING',completed_at=NOW(),updated_at=NOW() WHERE sn=$1`,[sn]);
      await query(`INSERT INTO station_aging_events
        (sn,batch_id,event_type,result,source_type,aging_started_at,aging_deadline_at,destination_station,detail)
        VALUES($1,$2,'RELEASED','PASS','MES_RESULT_GATE',$3,$4,'manu_hivolt_ate',$5)`,
        [sn,aging.batch_id,aging.aging_started_at,aging.aging_deadline_at,JSON.stringify({twoHourGateSatisfied:true})]);
      state.pass=upsertBySn(state.pass,{sn,batchId:String(payload.batchId||sn),result:'PASS',time:now,
        agingCompleted:true,destinationStationCode:'manu_hivolt_ate'});
      state.process=[];stats.pass+=1;stats.total+=1;state.stats=[stats];
      changed.add('pass');changed.add('process');changed.add('stats');
      neuralBroadcast({from:'mes_server',to:'*',type:'AGING_COMPLETED_READY_NEXT',priority:'info',stationCode,
        payload:{sn,result:'PASS',destinationStationCode:'manu_hivolt_ate',completedAt:now}});
    }
  } else if (type === "STATION_TEST_RESULT" && payload.testMode) {
    // ICT/FCT test mode is a current-state projection. Unlimited executions
    // are allowed and each SN appears in exactly one bucket using its latest
    // result. The immutable event ledger still records delivery/audit facts.
    const boards = Array.isArray(payload.subBoards) && payload.subBoards.length
      ? payload.subBoards : [{...payload, sn: payload.sn || payload.pcbSerial}];
    for (const board of boards) {
      const sn = String(board.sn || "").trim().toUpperCase();
      if (!sn) continue;
      const result = String(board.result || "PASS").toUpperCase() === "FAIL" ? "FAIL" : "PASS";
      const current = {
        ...payload, ...board, sn, result, stationCode, stationName: stationCode,
        batchId: String(payload.batchId || sn), time: now,
        testMode: true, latestResultOnly: true,
      };
      state.pass = state.pass.filter(item => String(item.sn || "").trim().toUpperCase() !== sn);
      state.pending_ng = state.pending_ng.filter(item => String(item.sn || "").trim().toUpperCase() !== sn);
      state.confirmed_ng = state.confirmed_ng.filter(item => String(item.sn || "").trim().toUpperCase() !== sn);
      if (result === "PASS") state.pass = upsertBySn(state.pass, current);
      else state.pending_ng = upsertBySn(state.pending_ng, current);
    }
    state.process = [{
      stage: "TEST_MODE_RESULT", batchId: String(payload.batchId || ""),
      overallResult: String(payload.overallResult || payload.result || ""),
      memberCount: boards.length, updatedAt: now, testMode: true,
    }];
    changed.add("pass"); changed.add("pending_ng"); changed.add("confirmed_ng"); changed.add("process");
  } else if ((type === "SN_SCAN" || type === "STATION_TEST_RESULT")
      && String(payload.result || "PASS").toUpperCase() === "PASS") {
    const sn = String(payload.sn || payload.pcbSerial || "").trim();
    if (sn) {
      const activeNg = await query(`SELECT 1 FROM ng_defect_records WHERE UPPER(sn)=UPPER($1)
        AND result='fail' AND COALESCE(repair_status,'pending') <> 'repaired'
        UNION ALL
        SELECT 1 FROM station_bucket_snapshots s, jsonb_array_elements(s.payload) item
        WHERE s.bucket_name='confirmed_ng' AND UPPER(COALESCE(item->>'sn',''))=UPPER($1)
        LIMIT 1`,[sn]);
      if (activeNg.rows.length && !payload.retestAuthorized) {
        state.process=[{stage:"CONFIRMED_NG_SCAN_BLOCKED",sn,stationCode,updatedAt:now}];
        changed.add("process");
        neuralBroadcast({from:"mes_server",to:"*",type:"CONFIRMED_NG_SCAN_BLOCKED",priority:"critical",
          stationCode,payload:{sn,message:"Confirmed NG can only be released by approved revival"}});
        state.stats=[stats];
        for (const bucketName of changed) await commitStationBucket(stationCode,bucketName,state[bucketName]);
        return {projected:true,blocked:true,reason:"ACTIVE_CONFIRMED_NG"};
      }
      if (payload.retestAuthorized) {
        state.pending_ng = state.pending_ng.filter(item => String(item.sn || "").toUpperCase() !== sn.toUpperCase());
        state.confirmed_ng = state.confirmed_ng.filter(item => String(item.sn || "").toUpperCase() !== sn.toUpperCase());
        // ng_defect_records and mes.ng_pool are historical records — never modified on revival
        if(stationCode==='manu_assem_ate'){
          await Promise.all([ngRevivalAuditColumnsReady,stationRepairWorkOrderReady,stationNgReleaseReady]);
          const revived=await query(`UPDATE ng_revival_audit SET approval_status='REVIVED',revived_at=NOW()
            WHERE UPPER(sn)=UPPER($1) AND approval_status='RETURN_RECEIVED_RETEST_REQUIRED'
            RETURNING batch_id,origin_station`,[sn]);
          const revival=revived.rows[0];
          if(revival)await query(`INSERT INTO station_ng_release_events(sn,batch_id,origin_station)
            VALUES($1,$2,$3) ON CONFLICT(sn,batch_id,release_reason) DO NOTHING`,
            [sn,revival.batch_id,revival.origin_station||stationCode]);
          await query(`UPDATE station_repair_work_orders SET status='CLOSED_RETEST_PASS',updated_at=NOW()
            WHERE UPPER(ng_sn)=UPPER($1) AND status='RETURN_RECEIVED_RETEST_REQUIRED'`,[sn]);
        }
        neuralBroadcast({from:"mes_server",to:"display:*",type:"NG_REVIVED",priority:"info",stationCode,
          payload:{sn,batchId:String(payload.batchId||""),method:"REPAIR_RETURN_RETEST_PASS",revivedAt:now,
            mesSupervised:true,repairWorkOrderClosed:stationCode==='manu_assem_ate'}});
        changed.add("confirmed_ng");
      }
      const channel = String(payload.channel || "").trim().toUpperCase();
      const channelMatch = /^([LR])([1-8])$/.exec(channel);
      const channelSlot = channelMatch ? Number(channelMatch[2]) + (channelMatch[1] === "R" ? 8 : 0) : undefined;
      state.pass = upsertBySn(state.pass, {
        ...payload,
        sn, result: "PASS", time: now, stationCode, stationName: stationCode,
        batchId: String(payload.batchId || sn),
        channel: channel || undefined,
        slot: Number(payload.slot) || channelSlot,
        errorCode: String(payload.errorCode || ""),
        testTime: payload.testTime || payload.sourceTestTimeIso || undefined,
        eventType: payload.eventType || "station_test",
      });
      if(!payload.retestAuthorized){
        await stationSnRegistryReady;
        await query(`INSERT INTO station_sn_registry(station_code,sn,source_type,production_date,first_event_id)
          VALUES($1,$2,$3,$4::date,$5)
          ON CONFLICT(station_code,sn) DO UPDATE SET last_seen_at=NOW(),test_count=station_sn_registry.test_count+1`,
          [stationCode,sn,String(payload.eventType||"production_source"),payload.productionDate,eventId]);
        await factorySnMasterReady;
        await query(`INSERT INTO factory_sn_master(sn,production_date,first_source_station,first_source_type,first_test_time)
          VALUES($1,$2::date,$3,$4,$5::timestamptz)
          ON CONFLICT(sn) DO UPDATE SET last_seen_at=NOW()`,
          [sn,payload.productionDate,stationCode,String(payload.eventType||"production_source"),payload.sourceTestTimeIso]);
      }
      state.pending_ng = state.pending_ng.filter(item => item.sn !== sn);
      if(!payload.retestAuthorized){stats.pass += 1; stats.total += 1;}
      changed.add("pass"); changed.add("pending_ng"); changed.add("stats");
    }
  } else if (type === "NG_DEFECT" || type === "STATION_NG_MARKED") {
    // Batch testers send subBoards; independent ATE stations send one FAIL
    // row per NG_DEFECT.  Project both shapes without discarding Excel fields.
    const boards = Array.isArray(payload.subBoards) && payload.subBoards.length
      ? payload.subBoards : [{ ...payload, result: payload.result || "FAIL" }];
    if(stationCode==='manu_agingcab'){
      await stationAgingHistoryReady;
      const agingSns=(boards.length?boards:[payload]).map(board=>String(board.sn||payload.sn||payload.mainSn||'').trim().toUpperCase()).filter(Boolean);
      for(const agingSn of agingSns){
        const marked=(await query(`INSERT INTO station_aging_control
          (sn,batch_id,aging_started_at,aging_deadline_at,latest_result,status,ng_detected_at)
          VALUES($1,$2,NOW(),NOW()+INTERVAL '2 hours','NG','NG_MARKED',NOW())
          ON CONFLICT(sn) DO UPDATE SET latest_result='NG',status='NG_MARKED',ng_detected_at=COALESCE(station_aging_control.ng_detected_at,NOW()),updated_at=NOW()
          RETURNING batch_id,aging_started_at,aging_deadline_at`,[agingSn,payload.batchId||agingSn])).rows[0];
        await query(`INSERT INTO station_aging_events
          (sn,batch_id,event_type,result,source_type,aging_started_at,aging_deadline_at,detail)
          VALUES($1,$2,'NG_MARKED','NG',$3,$4,$5,$6)`,
          [agingSn,marked.batch_id,String(payload.eventType||'STATION_TEST'),marked.aging_started_at,marked.aging_deadline_at,
            JSON.stringify({ngMarkedAt:now,silent:true,alarm:false,mesSupervised:true})]);
      }
      neuralBroadcast({from:'mes_server',to:'*',type:'ACTIVE_NG_REGISTRY_CHANGED',priority:'critical',stationCode,
        payload:{sns:agingSns,sourceStationCode:stationCode,destinationStationCode:'manu_hivolt_ate',
          ngState:'NG_MARKED',active:true,pickupRequired:true,ngMarkedAt:now,mesSupervised:true}});
      const markedSet=new Set(agingSns);
      state.pending_ng=state.pending_ng.filter(item=>!markedSet.has(String(item.sn||'').trim().toUpperCase()));
      state.confirmed_ng=state.confirmed_ng.filter(item=>!markedSet.has(String(item.sn||'').trim().toUpperCase()));
      state.process=[{stage:'AGING_NG_MARKED_CONTINUE',sns:agingSns,ngMarkedAt:now,
        noNgBox:true,noAlarm:true,destinationStationCode:'manu_hivolt_ate',mesSupervised:true}];
      await commitStationBucket(stationCode,'pending_ng',state.pending_ng);
      await commitStationBucket(stationCode,'confirmed_ng',state.confirmed_ng);
      await commitStationBucket(stationCode,'process',state.process);
      return {projected:true,agingMarked:true,noNgBox:true,continuesAfterTwoHours:true};
    }
    let upstreamBatchId = "";
    let upstreamBySn = new Map();
    if (stationCode === "manu_fct" && boards.length) {
      const ict = await readStationBuckets("manu_ict");
      const ictRows = [...ict.pending_ng, ...ict.confirmed_ng, ...ict.pass];
      upstreamBySn = new Map(ictRows.map(item => [String(item.sn || "").trim(), item]));
      const counts = new Map();
      for (const board of boards) {
        const match = upstreamBySn.get(String(board.sn || "").trim());
        const candidate = String(match?.batchId || "");
        if (candidate) counts.set(candidate, (counts.get(candidate) || 0) + 1);
      }
      const winner = [...counts.entries()].sort((a,b) => b[1] - a[1])[0];
      // Two distinct daughterboard SNs are sufficient to identify the solid motherboard.
      if (winner && winner[1] >= 2) upstreamBatchId = winner[0];
    }
    for (const board of boards) {
      const sn = String(board.sn || "").trim();
      if (!sn || String(board.result).toUpperCase() !== "FAIL") continue;
      const upstream = upstreamBySn.get(sn);
      const channel = String(board.channel || payload.channel || "").trim().toUpperCase();
      const channelMatch = /^([LR])([1-8])$/.exec(channel);
      const channelSlot = channelMatch ? Number(channelMatch[2]) + (channelMatch[1] === "R" ? 8 : 0) : undefined;
      const record = {
        ...payload, ...board,
        sn, result: "FAIL",
        defectCode: String(board.errorCode || payload.errorCode || `${stationCode.replace(/^manu_/, "").toUpperCase()}_FAIL`),
        errorCode: String(board.errorCode || payload.errorCode || ""),
        defectDescription: board.isConfirmedNG ? "Confirmed NG" : "NG",
        time: now, firstDetectedAt: Number(payload.firstDetectedAt || payload.batchStart) || now,
        dispatchDeadlineAt: (Number(payload.firstDetectedAt || payload.batchStart) || now) + 20*60*1000,
        repairDeadlineAt: (Number(payload.firstDetectedAt || payload.batchStart) || now) + 120*60*1000,
        operator: payload.operator || stationCode,
        testCount: Number(board.testCount) || 1,
        firstFailureTime: Number(payload.firstDetectedAt || payload.batchStart) || now,
        isConfirmed: true, channel: channel || undefined, slot: Number(board.slot) || channelSlot,
        testTime: board.testTime || payload.testTime || payload.sourceTestTimeIso || undefined,
        batchId: upstreamBatchId || String(payload.batchId || ""), fctBatchId: String(payload.batchId || ""),
        upstreamBatchId: upstreamBatchId || undefined,
        motherboardIdentityVerified: Boolean(upstreamBatchId),
        identityError: stationCode === "manu_fct" && !upstreamBatchId ? "Two SNs did not match one ICT motherboard" : undefined,
        overallResult: payload.overallResult,
        stationResults: [
          ...(Array.isArray(upstream?.stationResults) ? upstream.stationResults : []),
          { stationCode, results: board.results || [board.result], finalResult: board.result, testCount: Number(board.testCount) || 1 },
        ],
      };
      state.pass = state.pass.filter(item => item.sn !== sn);
      state.pending_ng = state.pending_ng.filter(item => item.sn !== sn);
      state.confirmed_ng = state.confirmed_ng.filter(item => item.sn !== sn);
      state.confirmed_ng.push(record);
      stats.fail += 1; stats.total += 1;
    }
    changed.add("pass"); changed.add("pending_ng"); changed.add("confirmed_ng"); changed.add("stats");
    // Capture per-board stationResults for SSE broadcast (built in the loop above)
    if((type === "NG_DEFECT" || type === "STATION_NG_MARKED") && boards.length){
      ngBoardStationResults = boards.reduce((acc,board)=>{
        const sn=String(board.sn||"").trim().toUpperCase();
        if(sn) acc[sn]={stationCode,results:['FAIL'],finalResult:'FAIL',testCount:1};
        return acc;
      },{});
    }
  } else if (type === "DUPLICATE_SN") {
    stats.dup += 1;
    changed.add("stats");
  }
  state.stats = [stats];
  for (const bucketName of changed) await commitStationBucket(stationCode, bucketName, state[bucketName]);
  if(type === "NG_DEFECT" || type === "STATION_NG_MARKED"){
    const ngSns=(Array.isArray(payload.subBoards)&&payload.subBoards.length?payload.subBoards:[payload])
      .map(board=>String(board?.sn||payload.sn||payload.mainSn||'').trim().toUpperCase()).filter(Boolean);
    // Build stationResults array from the per-board results captured above
    const broadcastStationResults=ngSns.map(sn=>({
      stationCode:ngBoardStationResults[sn]?.stationCode||stationCode,
      results:['FAIL'],finalResult:'FAIL',testCount:1
    }));
    if(ngSns.length) neuralBroadcast({from:'mes_server',to:'*',type:'ACTIVE_NG_REGISTRY_CHANGED',priority:'critical',stationCode,
      payload:{sns:ngSns,sourceStationCode:stationCode,ngState:'CONFIRMED_NG',active:true,
        pickupRequired:true,ngMarkedAt:now,mesSupervised:true,
        stationResults:broadcastStationResults}});
  }
  if (routeTransfer) {
    const targetStation = routeTransfer.destinationStationCode || (routeTransfer.destination === "MAINTENANCE"
      ? "manu_rework"
      : (routeTransfer.destination === "DEPANEL" || stationCode === "manu_fct" ? "manu_depanel" : "manu_fct"));
    const target = await readStationBuckets(targetStation);
    const members = Array.isArray(routeTransfer.motherboard.subBoards)
      ? routeTransfer.motherboard.subBoards : [];
    await closeStationResidence(stationCode, routeTransfer.batchId, members.map(board => board.sn));
    let depanelDefectCode = stationCode === "manu_fct" ? "FCT_ONLY_NG" : "ICT_ONLY_NG";
    let depanelBatchId = routeTransfer.batchId;
    if (targetStation === "manu_depanel") {
      const memberSns = new Set(members.map(board => String(board.sn || "").trim()).filter(Boolean));
      const overlap = target.pending_ng.find(item => memberSns.has(String(item.sn || "").trim()));
      if (overlap) {
        depanelDefectCode = "ICT_FCT_NG";
        depanelBatchId = String(overlap.batchId || routeTransfer.batchId);
        target.pending_ng = target.pending_ng.map(item => memberSns.has(String(item.sn || "").trim())
          ? { ...item, batchId: depanelBatchId, defectCode: "ICT_FCT_NG",
              defectDescription: "NG at both ICT and FCT → Depanel ICT+FCT NG BOX" }
          : item);
      }
    }
    await stationHandoverReady;
    await query(`INSERT INTO station_handover_transfers
      (batch_id,source_station,destination_station,destination_type,motherboard,member_count,status,sent_at)
      VALUES ($1,$2,$3,$4,$5,$6,'WAITING_RECEIPT',NOW())
      ON CONFLICT (batch_id,source_station,destination_station) DO UPDATE SET
        destination_type=EXCLUDED.destination_type,motherboard=EXCLUDED.motherboard,
        member_count=EXCLUDED.member_count,status='WAITING_RECEIPT',sent_at=NOW(),received_at=NULL,accepted_by=NULL`,
      [routeTransfer.batchId, stationCode, targetStation, routeTransfer.destination,
       JSON.stringify(routeTransfer.motherboard), members.length]);
    for (const board of members) {
      const sn = String(board.sn || "").trim();
      if (!sn) continue;
      target.pending_ng = upsertBySn(target.pending_ng, {
        sn, batchId: depanelBatchId, slot: Number(board.slot) || undefined,
        result: String(board.result || "PASS").toUpperCase(),
        isGoodSibling: String(board.result || "PASS").toUpperCase() !== "FAIL",
        sourceStation: stationCode, destination: routeTransfer.destination,
        motherboardId: routeTransfer.batchId, motherboard: routeTransfer.motherboard,
        defectCode: targetStation === "manu_depanel" ? depanelDefectCode : `${stationCode.replace(/^manu_/, "").toUpperCase()}_FAIL`,
        defectDescription: targetStation === "manu_depanel"
          ? (depanelDefectCode === "ICT_FCT_NG" ? "NG at both ICT and FCT → Depanel ICT+FCT NG BOX" : `${depanelDefectCode.replace("_ONLY_NG", "")} Confirmed NG → Depanel`)
          : `${stationCode} motherboard awaiting receipt`,
        time: now, firstFailureTime: now, testCount: Number(board.testCount) || 1,
        isConfirmed: false, receivedAt: null, sentAt: now,
        transferStatus: "WAITING_RECEIPT",
      });
    }
    await commitStationBucket(targetStation, "pending_ng", target.pending_ng);
    await commitStationBucket(targetStation, "process", [{
      stage: "ICT_MOTHERBOARD_WAITING_RECEIPT", batchId: routeTransfer.batchId,
      sourceStation: stationCode, destination: routeTransfer.destination,
      memberCount: members.length, updatedAt: now,
    }]);
  }
  return { projected: true };
}

// neuralBus + neuralBroadcast imported from ./src/shared/neural-bus.js

// SSE endpoint — any agent node subscribes here
// Read-only pickup projection for Team Leader / Line Manager PDA. Feedback
// continues through POST /api/pda/events with the original commandId.
app.get("/mes/repair/pickup-announcements", async (req, res) => {
  const domainCode = String(req.query.domainCode || "").trim().toUpperCase();
  const roleCode = String(req.query.roleCode || "").trim().toUpperCase();
  try {
    await ngPickupAlarmReady;
    const resolved = await query(`SELECT command_id FROM mes_ng_pickup_alarm_resolutions
      WHERE alarm_type='NG_PICKUP' AND resolution_status='RESOLVED'`);
    const resolvedCommands = new Set(resolved.rows.map(row => String(row.command_id || '').replace(/^NG_PICKUP:/, '')));
    const items = recentStationEvents
      .filter((event) => event?.type === "NG_PICKUP_ANNOUNCEMENT")
      .filter((event) => !domainCode || String(event?.payload?.domainCode || event?.processDomain || "").toUpperCase() === domainCode)
      .filter((event) => !roleCode || (Array.isArray(event?.payload?.recipientRoles) && event.payload.recipientRoles.includes(roleCode)))
      .filter((event) => !resolvedCommands.has(String(event?.payload?.commandId || event?.eventId || '').trim()))
      .slice(-100).reverse()
      .map((event) => ({ ...(event.payload || {}), eventId: event.eventId || event.payload?.eventId, eventType: event.type }));
    res.json({ ok: true, data: { items } });
  } catch (error) {
    res.status(503).json(errorEnvelope('PICKUP_ANNOUNCEMENT_QUERY_FAILED', error.message));
  }
});

app.get("/api/pda/events", (req, res) => {
  const { node, types, replay } = req.query; // replay=0 when state was restored from authoritative snapshots
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  // Tag this connection with subscriber info
  const sub = { res, node: node || "anonymous", types: types ? types.split(",") : null };
  neuralBus.add(sub);
  // Send welcome
  res.write(`data: ${JSON.stringify({ type: "CONNECTED", node: sub.node, msg: `Neuron ${sub.node} connected to comm bus` })}\n\n`);
  if (String(replay) !== "0") {
    const replayCutoff = Date.now() - RECENT_EVENT_TTL_MS;
    for (const event of recentStationEvents) {
      if (event._receivedAt >= replayCutoff && (!sub.types || sub.types.includes(event.type))) {
        res.write(`data: ${JSON.stringify(event)}\n\n`);
      }
    }
  }
  const heartbeat = setInterval(() => { try { res.write(": heartbeat\n\n"); } catch { clearInterval(heartbeat); neuralBus.delete(sub); } }, 30000);
  req.on("close", () => { clearInterval(heartbeat); neuralBus.delete(sub); });
});

