// GET /api/finance/gl-journals
api.get('/finance/gl-journals', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { page = 1, limit = 50, period_id, account_id, posting_date_from, posting_date_to, status } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);
    const params = []; let where = "WHERE 1=1";
    if (period_id) { params.push(period_id); where += ` AND j.period_id = $${params.length}`; }
    if (account_id) { params.push(account_id); where += ` AND EXISTS (SELECT 1 FROM gl_journal_lines l WHERE l.entry_id = j.id AND l.account_id = $${params.length})`; }
    if (posting_date_from) { params.push(posting_date_from); where += ` AND j.posting_date >= $${params.length}`; }
    if (posting_date_to) { params.push(posting_date_to); where += ` AND j.posting_date <= $${params.length}`; }
    if (status) { params.push(status); where += ` AND j.status = $${params.length}`; }
    const countResult = await query(`SELECT count(*) FROM gl_journal_entries j ${where}`, params);
    params.push(parseInt(limit), offset);
    const result = await query(
      `SELECT j.id, j.entry_no, j.source_type, j.source_no, j.entry_type, j.posting_date, j.currency_code, j.exchange_rate, j.status,
              j.posted_by, u.display_name AS posted_by_name, j.posted_at,
              (SELECT sum(credit_amount) FROM gl_journal_lines WHERE entry_id = j.id) AS total_credit,
              (SELECT sum(debit_amount) FROM gl_journal_lines WHERE entry_id = j.id) AS total_debit
       FROM gl_journal_entries j LEFT JOIN users u ON u.id = j.posted_by
       ${where} ORDER BY j.created_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params
    );
    res.json(listEnvelope(result.rows, parseInt(countResult.rows[0].count)));
  } catch (err) { console.error("GET /finance/gl-journals:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

