api.post('/production/fg', authenticateJWT, requirePermission('wms.warehouse.write'), async (req, res) => {
  try {
    const { production_order_id, material_code, material_name, quantity, serial_no, batch_no, warehouse_code, location_code, remarks } = req.body ?? {};
    if (!production_order_id || !material_code || !quantity) {
      return res.status(400).json(errorEnvelope("VALIDATION_ERROR", "production_order_id, material_code, quantity required"));
    }
    const seqResult = await pgPool.query(
      `SELECT 'FG-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(NEXTVAL('fg_seq')::TEXT, 4, '0') AS receipt_no`
    );
    const receipt_no = seqResult.rows[0]?.receipt_no || `FG-${Date.now()}`;
    const result = await pgPool.query(
      `INSERT INTO production_finished_goods
        (production_order_id, receipt_no, material_code, material_name, quantity, serial_no, batch_no, warehouse_code, location_code, production_date, status, remarks)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,CURRENT_DATE,'PENDING',$10)
       RETURNING *`,
      [production_order_id, receipt_no, material_code, material_name || '', quantity, serial_no || null, batch_no || null, warehouse_code || 'WH01', location_code || null, remarks || null]
    );
    // Update order output_qty
    await pgPool.query(
      `UPDATE production_orders SET output_qty = output_qty + $1, updated_at = NOW() WHERE id = $2`,
      [quantity, production_order_id]
    );
    res.json({ item: result.rows[0] });
  } catch (err) { console.error("POST /production/fg:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

