api.post('/production/material-issue', authenticateJWT, requirePermission('wms.warehouse.write'), async (req, res) => {
  try {
    const { production_order_id, order_item_id, material_code, quantity, warehouse_code, location_code, reference_no, remarks } = req.body ?? {};
    if (!production_order_id || !material_code || !quantity) {
      return res.status(400).json(errorEnvelope("VALIDATION_ERROR", "production_order_id, material_code, quantity required"));
    }
    // Log transaction
    const txResult = await pgPool.query(
      `INSERT INTO production_material_transactions
        (production_order_id, transaction_type, material_code, warehouse_code, from_location, to_location, quantity, reference_no, remarks)
       VALUES ($1,'MATERIAL_ISSUE',$2,$3,$4,'PRODUCTION',$5,$6,$7)
       RETURNING *`,
      [production_order_id, material_code, warehouse_code || 'WH01', location_code || null, quantity, reference_no || null, remarks || null]
    );
    // Update order item issued_qty
    if (order_item_id) {
      await pgPool.query(
        `UPDATE production_order_items SET issued_qty = issued_qty + $1 WHERE id = $2`,
        [quantity, order_item_id]
      );
    }
    // Update order status to MATERIAL_ISSUED if currently DRAFT or MATERIAL_PENDING
    await pgPool.query(
      `UPDATE production_orders SET status = 'MATERIAL_ISSUED', updated_at = NOW() WHERE id = $1 AND status IN ('DRAFT','MATERIAL_PENDING')`,
      [production_order_id]
    );
    res.json({ item: txResult.rows[0] });
  } catch (err) { console.error("POST /production/material-issue:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});



