api.get('/qms/iqc/mes-locks', async (req, res) => {
  try {
    const { work_order_code, lock_status, factory_id } = req.query;
    let sql = `SELECT ml.*, cl.material_code, cl.supplier_code, ir.lot_no as incoming_lot_no
               FROM iqc_mes_work_order_locks ml
               LEFT JOIN iqc_control_lots cl ON ml.control_lot_id=cl.id
               LEFT JOIN wms_incoming_records ir ON ml.incoming_record_id=ir.id WHERE 1=1`;
    const params = [];
    if (work_order_code) { sql += ` AND ml.work_order_code=$` + (params.length+1); params.push(work_order_code); }
    if (lock_status) { sql += ` AND ml.lock_status=$` + (params.length+1); params.push(lock_status); }
    sql += ` ORDER BY ml.locked_at DESC`;
    const rows = await query(sql, params);
    res.json(rows);
  } catch(e) { res.status(500).json({error: e.message}); }
});

