// IQC 抽样标准查询
api.get('/qms/iqc/sampling-plans', async (req, res) => {
  try {
    const { batch_size, aql_level } = req.query;
    const bs = Number(batch_size) || 0;
    // GB/T 2828.1 simplified lookup
    let sample_size = 50, accept_point = 1, reject_point = 2;
    if (bs <= 50) { sample_size = 8; accept_point = 0; reject_point = 1; }
    else if (bs <= 100) { sample_size = 20; accept_point = 1; reject_point = 2; }
    else if (bs <= 500) { sample_size = 50; accept_point = 1; reject_point = 2; }
    else if (bs <= 1000) { sample_size = 80; accept_point = 2; reject_point = 3; }
    else { sample_size = 125; accept_point = 3; reject_point = 4; }
    res.json({ batch_size: bs, sample_size, accept_point, reject_point, aql_level: aql_level||'II' });
  } catch(e) { res.status(500).json({error: e.message}); }
});

