// 查询 Andon 事件
api.get('/qms/iqc/andon', async (req, res) => {
  try {
    const { status, severity, factory_id } = req.query;
    let sql = `SELECT a.*, cl.material_code, cl.supplier_code, cl.supplier_name,
                      u1.name as created_by_name, u2.name as acknowledged_by_name
               FROM iqc_spc_alerts a
               LEFT JOIN iqc_control_lots cl ON a.control_lot_id = cl.id
               LEFT JOIN users u1 ON a.inspector_id = u1.id
               LEFT JOIN users u2 ON a.acknowledged_by = u2.id
               WHERE a.severity IN ('warning','critical')`;
    const params = [];
    if (status === 'unresolved') { sql += ` AND (a.acknowledged = FALSE OR a.resolved = FALSE)`; }
    if (severity) { sql += ` AND a.severity=$` + (params.length+1); params.push(severity); }
    sql += ` ORDER BY a.created_at DESC LIMIT 100`;
    const rows = await query(sql, params);
    res.json(rows);
  } catch(e) { res.status(500).json({error: e.message}); }
});

