// IQC 超时预警（检验超过24h未完成）
api.get('/qms/iqc/andon/timeout-warnings', async (req, res) => {
  try {
    const rows = await query(`
      SELECT ic.id, ic.lot_no, ic.material_code, ic.supplier_code, ic.supplier_name,
             ic.inspection_date, EXTRACT(EPOCH FROM (NOW()-ic.inspection_date))/3600 as hours_pending,
             u.name as inspector_name
      FROM iqc_inspections ic
      LEFT JOIN users u ON ic.inspector_id = u.id
      WHERE ic.inspection_result IS NULL
        AND EXTRACT(EPOCH FROM (NOW()-ic.inspection_date))/3600 > 24
        AND ic.factory_id = $1
      ORDER BY hours_pending DESC
    `, [req.query.factory_id || 1]);
    res.json(rows);
  } catch(e) { res.status(500).json({error: e.message}); }
});

// 供应商免检到期预警（免检资格30天内到期）
api.get('/qms/iqc/andon/exempt-expiry-warnings', async (req, res) => {
  try {
    // 免检记录来自 iqc_inspections 的 inspection_mode='EXEMPT'
    const rows = await query(`
      SELECT sq.supplier_code, sq.supplier_name, sq.quality_level,
             sq.exempt_expiry_date, sq.aql_level,
             CASE WHEN sq.exempt_expiry_date < NOW() THEN 'expired'
                  WHEN sq.exempt_expiry_date < NOW() + INTERVAL '30 days' THEN 'expiring_soon'
                  ELSE 'valid' END as exempt_status
      FROM supplier_quality sq
      WHERE sq.quality_level IN ('A','B')
        AND sq.exempt_expiry_date IS NOT NULL
        AND sq.exempt_expiry_date < NOW() + INTERVAL '60 days'
      ORDER BY sq.exempt_expiry_date ASC
    `);
    res.json(rows);
  } catch(e) {
    // Table might not have exempt_expiry_date, return empty
    res.json([]);
  }
});

