// Critical不良 → 自动创建 QMS客诉（CAPA触发）
api.post('/qms/iqc/capa/trigger', async (req, res) => {
  try {
    const { inspection_id, lot_no, material_code, supplier_code, supplier_name,
            defect_type, defect_count, severity, description } = req.body;

    // 查询是否有未关闭的相关客诉
    const [existing] = await query(
      `SELECT id FROM qms_complaints
       WHERE product=$1 AND supplier_code=$2 AND status NOT IN ('closed','resolved','cancelled')
       LIMIT 1`,
      [material_code, supplier_code]);

    if (existing) {
      // 追加到现有客诉
      return res.json({ message: 'Existing complaint found, appending', complaint_id: existing.id });
    }

    // 生成投诉编号
    const [seq] = await query(`SELECT COALESCE(MAX(id),0)+1 as n FROM qms_complaints`);
    const complaint_no = `IQC-CAPA-${new Date().getFullYear()}-${String(seq.n).padStart(4,'0')}`;

    const [result] = await query(
      `INSERT INTO qms_complaints (complaint_no, customer, product, quantity, defect_desc, priority,
       defect_images, status, factory_id, created_by, created_at, updated_at,
       source_type, related_inspection_id)
       VALUES ($1,$2,$3,$4,$5,$6,$7,'received',$8,$9,NOW(),NOW(),'iqc',$10)
       RETURNING *`,
      [complaint_no, supplier_name || supplier_code, material_code, defect_count || 1,
       `${defect_type}: ${description}`, severity === 'critical' ? 'high' : 'medium',
       '[]', req.body.factory_id || 1, req.user.id, inspection_id]);

    // 同时创建一个关联的8D
    const [seq8d] = await query(`SELECT COALESCE(MAX(id),0)+1 as n FROM qms_8d_reports`);
    const d0_no = `8D-IQC-${new Date().getFullYear()}-${String(seq8d.n).padStart(4,'0')}`;
    await query(
      `INSERT INTO qms_8d_reports (d0_no, complaint_id, problem_desc, severity, status, factory_id, d0_created_by, d0_created_at)
       VALUES ($1,$2,$3,$4,'d0',$5,$6,NOW())`,
      [d0_no, result.id, `${defect_type}: ${description}`, severity, req.body.factory_id || 1, req.user.id]);

    res.json({ complaint: result, d0_no, message: 'CAPA triggered successfully' });
  } catch(e) { res.status(500).json({error: e.message}); }
});

