// PPM 趋势（供应商月度PPM）
api.get('/qms/iqc/ppm-trends', async (req, res) => {
  try {
    const { supplier_code, months = 12, factory_id } = req.query;
    const m = Number(months) || 12;
    const fid = factory_id || 1;
    let sql = `
      SELECT
        TO_CHAR(ic.inspection_date, 'YYYY-MM') as month,
        ic.supplier_code,
        ic.supplier_name,
        COUNT(DISTINCT ic.id) as total_inspected,
        COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'FAIL') as total_failed,
        CASE WHEN COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'FAIL') > 0
          THEN ROUND(COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'FAIL')::NUMERIC /
                 NULLIF(COUNT(DISTINCT ic.id), 0) * 1000000, 0)
          ELSE 0 END as ppm
      FROM iqc_inspections ic
      WHERE ic.factory_id = $1
        AND ic.inspection_date >= DATE_TRUNC('month', CURRENT_DATE) - (INTERVAL '1 month' * $2)
    `;
    const params = [fid, m];
    if (supplier_code) { sql += ` AND ic.supplier_code = $${params.length + 1}`; params.push(String(supplier_code)); }
    sql += ` GROUP BY TO_CHAR(ic.inspection_date, 'YYYY-MM'), ic.supplier_code, ic.supplier_name ORDER BY month ASC`;
    const rows = await query(sql, params);
    res.json(rows);
  } catch(e) { res.status(500).json({error: e.message}); }
});

// 供应商质量排行
api.get('/qms/iqc/supplier-ranks', async (req, res) => {
  try {
    const { factory_id } = req.query;
    const fid = factory_id || 1;
    const rows = await query(`
      SELECT
        ic.supplier_code,
        ic.supplier_name,
        COUNT(DISTINCT ic.id) as total_inspected,
        COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'FAIL') as total_failed,
        CASE WHEN COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'FAIL') > 0
          THEN ROUND(COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'FAIL')::NUMERIC /
                 NULLIF(COUNT(DISTINCT ic.id), 0) * 1000000, 0)
          ELSE 0 END as ppm,
        ROUND(COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result = 'PASS')::NUMERIC /
               NULLIF(COUNT(DISTINCT ic.id) FILTER (WHERE ic.inspection_result IS NOT NULL), 0) * 100, 1) as pass_rate
      FROM iqc_inspections ic
      WHERE ic.factory_id = $1
      GROUP BY ic.supplier_code, ic.supplier_name
      ORDER BY ppm ASC
      LIMIT 20
    `, [fid]);
    const ranked = rows.rows.map((r, i) => ({ ...r, rank: i + 1 }));
    res.json(ranked);
  } catch(e) { res.status(500).json({error: e.message}); }
});

// IQC 效率分析（日检验量/合格率趋势/平均时长）
api.get('/qms/iqc/efficiency', async (req, res) => {
  try {
    const { days = 14, factory_id } = req.query;
    const d = Number(days) || 14;
    const fid = factory_id || 1;
    const rows = await query(`
      SELECT
        DATE(inspection_date) as date,
        COUNT(*) as inspected,
        COUNT(*) FILTER (WHERE inspection_result = 'PASS') as passed,
        COUNT(*) FILTER (WHERE inspection_result = 'FAIL') as failed,
        ROUND(AVG(EXTRACT(EPOCH FROM (COALESCE(completed_at, NOW()) - inspection_date)) / 3600) FILTER (WHERE completed_at IS NOT NULL), 2) as avg_hours,
        ROUND(COUNT(*) FILTER (WHERE inspection_result = 'PASS')::NUMERIC /
               NULLIF(COUNT(*) FILTER (WHERE inspection_result IS NOT NULL), 0) * 100, 1) as pass_rate
      FROM iqc_inspections
      WHERE factory_id = $1
        AND inspection_date >= CURRENT_DATE - $2
      GROUP BY DATE(inspection_date)
      ORDER BY date ASC
    `, [fid, d]);
    res.json(rows);
  } catch(e) { res.status(500).json({error: e.message}); }
});

