// GET /api/finance/work-order-costs
api.get('/finance/work-order-costs', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { page = 1, limit = 50, cost_status } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);
    const params = []; let where = "WHERE 1=1";
    if (cost_status) { params.push(cost_status); where += ` AND w.cost_status = $${params.length}`; }
    const countResult = await query(`SELECT count(*) FROM work_order_cost_summaries w ${where}`, params);
    params.push(parseInt(limit), offset);
    const result = await query(
      `SELECT w.id, w.work_order_id, wo.code AS work_order_code, p.code AS product_code, p.name_zh AS product_name_zh,
              fl.internal_code AS line_code, fl.name_zh AS line_name_zh,
              w.standard_material_cost, w.standard_labor_cost, w.standard_overhead_cost,
              w.actual_material_cost, w.actual_labor_cost, w.actual_overhead_cost,
              w.scrap_cost, w.total_standard_cost, w.total_actual_cost,
              w.cost_status, w.currency_code, w.updated_at
       FROM work_order_cost_summaries w
       JOIN work_orders wo ON wo.id = w.work_order_id
       JOIN products p ON p.id = wo.product_id
        LEFT JOIN production_lines fl ON fl.id = wo.line_id
        ${where} ORDER BY w.updated_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params
    );
    res.json(listEnvelope(result.rows, parseInt(countResult.rows[0].count)));
  } catch (err) { console.error("GET /finance/work-order-costs:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

// PUT /api/finance/work-order-costs/:woId/post
api.put('/finance/work-order-costs/:woId/post', authenticateJWT, requirePermission("finance.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    const { woId } = req.params;
    await client.query("BEGIN");
    const sumResult = await client.query(`SELECT w.*, wo.code AS wo_code FROM work_order_cost_summaries w JOIN work_orders wo ON wo.id = w.work_order_id WHERE w.work_order_id = $1 AND w.cost_status IN ('open','accumulating')`, [woId]);
    if (!sumResult.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Work order cost summary not found"));
    const sum = sumResult.rows[0];
    const seqResult = await client.query(`SELECT nextval('gl_journal_number_seq')`);
    const entryNo = `GL-WO-${sum.wo_code}`;
    const periodResult = await client.query(`SELECT id FROM fiscal_periods WHERE status = 'open' ORDER BY start_date DESC LIMIT 1`);
    const today = new Date().toISOString().split("T")[0];
    const totalCost = parseFloat(sum.total_actual_cost) || 0;
    const glResult = await client.query(
      `INSERT INTO gl_journal_entries (entry_no, source_type, source_no, entry_type, period_id, posting_date, currency_code, exchange_rate, status, created_by, posted_by, posted_at)
       VALUES ($1,'WO_COST',$2,'WO_COST',$3,$4,'USD',1,'posted',$5,$5,now()) RETURNING id`,
      [entryNo, sum.wo_code, periodResult.rows[0]?.id, today, req.user.id]
    );
    const entryId = glResult.rows[0].id;
    await client.query(`INSERT INTO gl_journal_lines (entry_id, line_no, account_id, work_order_id, description, debit_amount, credit_amount) SELECT $1,1,ga.id,$2,$3,$4,0 FROM gl_accounts ga WHERE ga.code = '5100'`, [entryId, woId, `WO Cost ${sum.wo_code}`, totalCost]);
    await client.query(`INSERT INTO gl_journal_lines (entry_id, line_no, account_id, work_order_id, description, debit_amount, credit_amount) SELECT $1,2,ga.id,$2,$3,0,$4 FROM gl_accounts ga WHERE ga.code = '1410'`, [entryId, woId, `WIP ${sum.wo_code}`, totalCost]);
    await client.query(`UPDATE work_order_cost_summaries SET cost_status = 'posted', last_posted_entry_id = $1, updated_at = now() WHERE work_order_id = $2`, [entryId, woId]);
    await client.query(`UPDATE work_orders SET cost_status = 'posted', cost_posted_at = now() WHERE id = $1`, [woId]);
    await client.query("COMMIT");
    res.json(envelope({ posted: true, entry_id: entryId, total_cost: totalCost }));
  } catch (err) { await client.query("ROLLBACK"); console.error("PUT /finance/work-order-costs/:woId/post:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

// GET /api/finance/ar-aging
api.get('/finance/ar-aging', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { as_of_date } = req.query;
    const asOf = as_of_date || new Date().toISOString().split("T")[0];
    const result = await query(
      `SELECT c.id AS customer_id, c.code AS customer_code, c.name_zh AS customer_name_zh, c.name_en AS customer_name_en, a.currency_code,
              SUM(a.total_amount) AS total_invoiced, SUM(a.paid_amount) AS total_paid, SUM(a.outstanding_amount) AS total_outstanding,
              SUM(CASE WHEN a.due_date >= $1::date - interval '30 days' THEN a.outstanding_amount ELSE 0 END) AS bucket_0_30,
              SUM(CASE WHEN a.due_date < $1::date - interval '30 days' AND a.due_date >= $1::date - interval '60 days' THEN a.outstanding_amount ELSE 0 END) AS bucket_31_60,
              SUM(CASE WHEN a.due_date < $1::date - interval '60 days' AND a.due_date >= $1::date - interval '90 days' THEN a.outstanding_amount ELSE 0 END) AS bucket_61_90,
              SUM(CASE WHEN a.due_date < $1::date - interval '90 days' THEN a.outstanding_amount ELSE 0 END) AS bucket_over_90
       FROM ar_invoices a JOIN customers c ON c.id = a.customer_id
       WHERE a.payment_status NOT IN ('paid','voided')
       GROUP BY c.id, c.code, c.name_zh, c.name_en, a.currency_code ORDER BY c.code`,
      [asOf]
    );
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { console.error("GET /finance/ar-aging:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

