// GET /api/finance/inventory-valuation
api.get('/finance/inventory-valuation', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { material_id } = req.query;
    let where = "WHERE icl.status = 'open' AND icl.remaining_quantity > 0"; const params = [];
    if (material_id) { params.push(material_id); where += ` AND ml.material_id = $${params.length}`; }
    const result = await query(
      `SELECT m.id AS material_id, m.code AS material_code, m.name_zh AS material_name_zh, m.name_en AS material_name_en,
              sl.code AS location_code, sl.name_zh AS location_name_zh,
              SUM(icl.remaining_quantity) AS total_qty, AVG(icl.unit_cost) AS avg_unit_cost,
              SUM(icl.remaining_quantity * icl.unit_cost) AS total_value, icl.currency_code
       FROM inventory_cost_layers icl
       JOIN material_lots ml ON ml.id = icl.material_lot_id
       JOIN materials m ON m.id = ml.material_id
        LEFT JOIN storage_locations sl ON sl.id = ml.storage_location_id
       ${where} GROUP BY m.id, m.code, m.name_zh, m.name_en, sl.code, sl.name_zh, icl.currency_code ORDER BY m.code`,
      params
    );
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { console.error("GET /finance/inventory-valuation:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

// GET /api/finance/wip-valuation — SMT WIP valuation by line, product, and cost element
api.get('/finance/wip-valuation', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { line_id, product_id, cost_status } = req.query;
    let where = "WHERE wo.status IN ('in_progress','on_hold')";
    const params = [];
    if (line_id) { params.push(line_id); where += ` AND wo.line_id = $${params.length}`; }
    if (product_id) { params.push(product_id); where += ` AND wo.product_id = $${params.length}`; }
    if (cost_status) { params.push(cost_status); where += ` AND w.cost_status = $${params.length}`; }
    const result = await query(
      `SELECT wo.id AS work_order_id, wo.code AS work_order_code,
              p.code AS product_code, p.name_zh AS product_name_zh,
              fl.internal_code AS line_code, fl.name_zh AS line_name_zh,
              wo.planned_qty AS wo_qty, wo.completed_qty,
              COALESCE(w.actual_material_cost,0) AS actual_material_cost,
              COALESCE(w.actual_labor_cost,0) AS actual_labor_cost,
              COALESCE(w.actual_overhead_cost,0) AS actual_overhead_cost,
              COALESCE(w.scrap_cost,0) AS scrap_cost,
              COALESCE(w.total_actual_cost,0) AS total_actual_cost,
              COALESCE(w.total_standard_cost,0) AS total_standard_cost,
              COALESCE(w.total_actual_cost,0) - COALESCE(w.total_standard_cost,0) AS cost_variance,
              CASE WHEN COALESCE(w.total_standard_cost,0) != 0
                   THEN (COALESCE(w.total_actual_cost,0) - COALESCE(w.total_standard_cost,0)) / COALESCE(w.total_standard_cost,0) * 100
                   ELSE 0 END AS variance_pct,
              w.cost_status, w.currency_code,
              wo.planned_start_date, wo.due_date, wo.closed_at
       FROM work_orders wo
       JOIN products p ON p.id = wo.product_id
        LEFT JOIN production_lines fl ON fl.id = wo.line_id
        LEFT JOIN work_order_cost_summaries w ON w.work_order_id = wo.id
        ${where}
        ORDER BY fl.internal_code, w.total_actual_cost DESC NULLS LAST`,
      params
    );

    // Summary by line
    const lineSummary = await query(
      `SELECT fl.internal_code AS line_code, fl.name_zh AS line_name_zh,
              COUNT(wo.id) AS wo_count,
              COALESCE(SUM(w.total_actual_cost),0) AS total_actual_cost,
              COALESCE(SUM(w.total_standard_cost),0) AS total_standard_cost,
              COALESCE(SUM(w.scrap_cost),0) AS total_scrap_cost,
              COALESCE(SUM(w.actual_labor_cost),0) AS total_labor_cost,
              COALESCE(SUM(w.actual_overhead_cost),0) AS total_overhead_cost
       FROM work_orders wo
       JOIN products p ON p.id = wo.product_id
       LEFT JOIN production_lines fl ON fl.id = wo.line_id
       LEFT JOIN work_order_cost_summaries w ON w.work_order_id = wo.id
       WHERE wo.status IN ('in_progress','on_hold')
       GROUP BY fl.internal_code, fl.name_zh
       ORDER BY fl.internal_code`,
      []
    );

    res.json(envelope({ workOrders: result.rows, lineSummary: lineSummary.rows }));
  } catch (err) { console.error("GET /finance/wip-valuation:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

// GET /api/finance/material-events
api.get('/finance/material-events', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { page = 1, limit = 50, event_type, status, from_date, to_date } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);
    const params = []; let where = "WHERE 1=1";
    if (event_type) { params.push(event_type); where += ` AND mfe.event_type = $${params.length}`; }
    if (status) { params.push(status); where += ` AND mfe.status = $${params.length}`; }
    if (from_date) { params.push(from_date); where += ` AND mfe.occurred_at >= $${params.length}`; }
    if (to_date) { params.push(to_date); where += ` AND mfe.occurred_at <= $${params.length}`; }
    const countResult = await query(`SELECT count(*) FROM material_financial_events mfe ${where}`, params);
    params.push(parseInt(limit), offset);
    const result = await query(`SELECT mfe.* FROM material_financial_events mfe ${where} ORDER BY mfe.occurred_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`, params);
    res.json(listEnvelope(result.rows, parseInt(countResult.rows[0].count)));
  } catch (err) { console.error("GET /finance/material-events:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

// PUT /api/finance/material-events/:id/acknowledge — posts GL entry for material scrap/loss/compensation
api.put('/finance/material-events/:id/acknowledge', authenticateJWT, requirePermission("finance.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    await client.query("BEGIN");
    const evtResult = await client.query(`SELECT * FROM material_financial_events WHERE id = $1 FOR UPDATE`, [req.params.id]);
    if (!evtResult.rows.length) { await client.query("ROLLBACK"); return res.status(404).json(errorEnvelope("NOT_FOUND", "Material financial event not found")); }
    const evt = evtResult.rows[0];
    if (evt.status !== 'OPEN') { await client.query("ROLLBACK"); return res.status(400).json(errorEnvelope("BAD_REQUEST", "Event already acknowledged")); }

    const totalCost = parseFloat(evt.total_cost_usd) || 0;
    const lossAmt = parseFloat(evt.loss_amount_usd) || 0;
    const proceeds = parseFloat(evt.sale_proceeds_usd) || 0;
    const today = new Date().toISOString().split("T")[0];

    // Resolve fiscal period
    const periodResult = await client.query(`SELECT id FROM fiscal_periods WHERE start_date <= $1::date AND end_date >= $1::date AND status = 'open' LIMIT 1`, [today]);
    const periodId = periodResult.rows[0]?.id || null;

    // Generate journal entry number
    const seqResult = await client.query(`SELECT nextval('gl_journal_number_seq')`);
    const entryNo = `MF-${new Date().getFullYear()}-${String(seqResult.rows[0].nextval).padStart(6, "0")}`;

    // GL auto-post for material financial events:
    // DISPOSAL_GARBAGE / SCRAP: DR 5100 COGS (loss), CR 1410 WIP
    // DISPOSAL_SOLD: DR 1110 Bank (proceeds), DR 5100 COGS (loss), CR 1410 WIP (cost), CR 4100 Gain (proceeds - cost if any)
    // COMPENSATION_APPROVED: DR 1410 WIP (recovery), CR 5100 COGS (cost recovery)
    let lines = [];
    if (["DISPOSAL_GARBAGE", "MATERIAL_RETURN_NG", "MATERIAL_RETURN_DAMAGED"].includes(evt.event_type)) {
      // Full loss: DR COGS, CR WIP
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,1,ga.account_code,$2,$3,0,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '5100'`,
        [entryId, `MF Loss ${evt.work_order_code || ""} ${evt.event_type}`, totalCost, evt.work_order_code, evt.id]
      );
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,2,ga.account_code,$2,0,$3,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '1410'`,
        [entryId, `MF WIP ${evt.work_order_code || ""}`, totalCost, evt.work_order_code, evt.id]
      );
    } else if (["DISPOSAL_SOLD"].includes(evt.event_type)) {
      // Sale: DR Bank (proceeds), DR COGS (net loss), CR WIP (full cost)
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,1,ga.account_code,$2,$3,0,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '1110'`,
        [entryId, `MF Sale Proceeds ${evt.work_order_code || ""}`, proceeds, evt.work_order_code, evt.id]
      );
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,2,ga.account_code,$2,$3,0,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '5100'`,
        [entryId, `MF COGS ${evt.work_order_code || ""}`, Math.max(0, totalCost - proceeds), evt.work_order_code, evt.id]
      );
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,3,ga.account_code,$2,0,$3,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '1410'`,
        [entryId, `MF WIP ${evt.work_order_code || ""}`, totalCost, evt.work_order_code, evt.id]
      );
    } else if (["COMPENSATION_APPROVED"].includes(evt.event_type)) {
      // Supplier compensation: DR WIP, CR COGS recovery
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,1,ga.account_code,$2,$3,0,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '1410'`,
        [entryId, `MF Compensation Recovery ${evt.work_order_code || ""}`, proceeds || totalCost, evt.work_order_code, evt.id]
      );
      await client.query(
        `INSERT INTO gl_journal_lines (entry_id, line_no, account_code, description, debit_amount, credit_amount, currency_code, exchange_rate, work_order_code, reference_id, reference_type)
         SELECT $1,2,ga.account_code,$2,0,$3,'USD',1,$4,$5,'material_financial_event' FROM gl_accounts ga WHERE ga.account_code = '5100'`,
        [entryId, `MF COGS Recovery ${evt.work_order_code || ""}`, proceeds || totalCost, evt.work_order_code, evt.id]
      );
    }

    // Insert GL journal header
    const glResult = await client.query(
      `INSERT INTO gl_journal_entries (entry_no, source_type, source_no, entry_type, period_id, posting_date, currency_code, exchange_rate, status, description, created_by, posted_by, posted_at)
       VALUES ($1,'MATERIAL_EVENT',$2,'MATERIAL_EVENT',$3,$4,'USD',1,'posted',$5,'FINANCE_AI','FINANCE_AI',now()) RETURNING id`,
      [entryNo, String(evt.id), periodId, today, `MF Event ${evt.event_type} ${evt.work_order_code || ""}`]
    );
    const entryId = glResult.rows[0].id;

    // Update event status
    await client.query(
      `UPDATE material_financial_events SET status = 'ACKNOWLEDGED', acknowledged_at = now(), acknowledged_by = 'FINANCE_AI', gl_entry_id = $1 WHERE id = $2`,
      [entryId, req.params.id]
    );
    await client.query("COMMIT");
    res.json(envelope({ acknowledged: true, event_id: evt.id, gl_entry_no: entryNo, gl_entry_id: entryId, total_cost: totalCost, loss_amount: lossAmt }));
  } catch (err) { await client.query("ROLLBACK"); console.error("PUT /finance/material-events/:id/acknowledge:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

// GET /api/finance/exchange-rates
api.get('/finance/exchange-rates', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { base_currency, quote_currency } = req.query;
    let where = "WHERE 1=1"; const params = [];
    if (base_currency) { params.push(base_currency); where += ` AND base_currency_code = $${params.length}`; }
    if (quote_currency) { params.push(quote_currency); where += ` AND quote_currency_code = $${params.length}`; }
    const result = await query(`SELECT * FROM exchange_rates ${where} ORDER BY rate_date DESC LIMIT 100`, params);
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { console.error("GET /finance/exchange-rates:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

// GET /api/finance/fiscal-periods
api.get('/finance/fiscal-periods', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const { status } = req.query;
    let where = "WHERE 1=1"; const params = [];
    if (status) { params.push(status); where += ` AND fp.status = $${params.length}`; }
    const result = await query(`SELECT fp.* FROM fiscal_periods fp ${where} ORDER BY fp.start_date DESC`, params);
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { console.error("GET /finance/fiscal-periods:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

// GET /api/finance/dashboard-summary
api.get('/finance/dashboard-summary', authenticateJWT, requirePermission("finance.view"), async (req, res) => {
  try {
    const today = new Date().toISOString().split("T")[0];
    const arResult = await query(`SELECT COALESCE(SUM(outstanding_amount),0) AS total_receivable, COALESCE(SUM(CASE WHEN due_date < $1 THEN outstanding_amount ELSE 0 END),0) AS overdue_amount FROM ar_invoices WHERE payment_status NOT IN ('paid','voided')`, [today]);
    const apResult = await query(`SELECT COALESCE(SUM(outstanding_amount),0) AS total_payable FROM ap_invoices WHERE payment_status NOT IN ('paid','voided')`);
    const invResult = await query(`SELECT COALESCE(SUM(remaining_quantity * unit_cost),0) AS inventory_value FROM inventory_cost_layers WHERE status = 'open' AND remaining_quantity > 0`);
    const woCostResult = await query(`SELECT COALESCE(SUM(total_actual_cost),0) AS wip_cost FROM work_order_cost_summaries WHERE cost_status IN ('open','accumulating')`);
    const mfeResult = await query(`SELECT count(*) AS open_events FROM material_financial_events WHERE status = 'OPEN'`);
    res.json(envelope({
      totalReceivable: parseFloat(arResult.rows[0].total_receivable) || 0,
      overdueAmount: parseFloat(arResult.rows[0].overdue_amount) || 0,
      totalPayable: parseFloat(apResult.rows[0].total_payable) || 0,
      inventoryValue: parseFloat(invResult.rows[0].inventory_value) || 0,
      wipCost: parseFloat(woCostResult.rows[0].wip_cost) || 0,
      openMaterialEvents: parseInt(mfeResult.rows[0].open_events) || 0,
    }));
  } catch (err) { console.error("GET /finance/dashboard-summary:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

