app.post("/quality/iqc-reinspections", requirePermission("quality.execute"), async(req,res)=>{try{const caseId=Number(req.body?.caseId),qr=String(req.body?.qrDocumentNo||'').trim();if(!caseId||!qr)return res.status(400).json(errorEnvelope("REINSPECTION_REQUIRED","caseId and qrDocumentNo are required"));const c=(await query("SELECT * FROM wms_iqc_defect_cases WHERE id=$1 AND status='REINSPECTION'",[caseId])).rows[0];if(!c)return res.status(409).json(errorEnvelope("REINSPECTION_INVALID_STATE","case is not waiting for reinspection"));const no=`REIQC-${c.case_no}`;const r=await query("INSERT INTO wms_iqc_reinspections(reinspection_no,defect_case_id,lot_no,rework_qr_document_no,inspector) VALUES($1,$2,$3,$4,$5) ON CONFLICT(reinspection_no) DO UPDATE SET rework_qr_document_no=EXCLUDED.rework_qr_document_no RETURNING *",[no,caseId,c.lot_no,qr,String(req.body?.operator||req.user?.username||'operator')]);res.status(201).json(mutateEnvelope(r.rows[0]));}catch(e){res.status(409).json(errorEnvelope("REINSPECTION_CREATE_FAILED",e.message));}});
app.post("/quality/iqc-reinspections/:id/complete", requirePermission("quality.execute"), async(req,res)=>{const result=String(req.body?.result||'').toUpperCase();if(!['PASS','FAIL'].includes(result))return res.status(400).json(errorEnvelope("REINSPECTION_RESULT_REQUIRED","result must be PASS or FAIL"));const client=await pgPool.connect();try{await iqcDefectLoopReady;await client.query('BEGIN');const r=(await client.query("SELECT * FROM wms_iqc_reinspections WHERE id=$1 FOR UPDATE",[req.params.id])).rows[0];if(!r||r.status==='COMPLETED')throw new Error('reinspection is unavailable');const re=(await client.query("UPDATE wms_iqc_reinspections SET status='COMPLETED',result=$1,inspector=$2,remark=$3,completed_at=NOW() WHERE id=$4 RETURNING *",[result,String(req.body?.inspector||req.user?.username||'iqc'),req.body?.remark||null,req.params.id])).rows[0];await client.query("UPDATE wms_iqc_defect_cases SET status=$1,closed_at=CASE WHEN $1='CLOSED' THEN NOW() ELSE NULL END WHERE id=$2",[result==='PASS'?'CLOSED':'IN_MRB',r.defect_case_id]);if(result==='PASS'){await client.query("UPDATE material_lots SET iqc_status='released',updated_at=NOW() WHERE lot_no=$1",[r.lot_no]);}else{await client.query("INSERT INTO wms_iqc_mrb_tasks(defect_case_id,task_no) VALUES($1,$2) ON CONFLICT(defect_case_id) DO UPDATE SET status='OPEN',completed_at=NULL",[r.defect_case_id,`MRB-REIQC-${r.lot_no}`]);}await client.query('COMMIT');res.json(mutateEnvelope(re));}catch(e){await client.query('ROLLBACK');res.status(409).json(errorEnvelope("REINSPECTION_COMPLETE_FAILED",e.message));}finally{client.release();}});

const pdaReceivingDocumentsReady = (async () => { await query("CREATE TABLE IF NOT EXISTS wms_pda_receiving_documents(id BIGSERIAL PRIMARY KEY,material_lot_id BIGINT NOT NULL REFERENCES material_lots(id),document_type VARCHAR(40) NOT NULL,document_qr VARCHAR(240),document_url TEXT,file_name VARCHAR(240),checksum VARCHAR(128),captured_by VARCHAR(120) NOT NULL,notes TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW())"); await query("CREATE INDEX IF NOT EXISTS idx_wms_pda_receiving_documents_lot ON wms_pda_receiving_documents(material_lot_id,captured_at DESC)"); })();
async function procurementAudit(client, req, entityType, entityId, entityNo, action, fromStatus, toStatus, notes = null, payload = {}) {
  await client.query(
    `INSERT INTO procurement_action_history
      (entity_type,entity_id,entity_no,action,from_status,to_status,notes,payload,acted_by)
     VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9)`,
    [entityType, entityId, entityNo, action, fromStatus, toStatus, notes, JSON.stringify(payload || {}), req.user.userId]
  );
}

api.get("/procurement/requisitions", authenticateJWT, requirePermission("procurement.view"), async (_req, res) => {
  try {
    await procurementClosedLoopReady;
    const result = await query(
      `SELECT pr.*, u.display_name AS requester_name,
              COALESCE(json_agg(json_build_object(
                'id',prl.id,'lineNo',prl.line_no,'materialId',prl.material_id,
                'materialCode',prl.material_code,'materialNameZh',prl.material_name_zh,
                'qtyRequested',prl.qty_requested,'qtyOrdered',prl.qty_ordered,
                'unit',prl.unit,'targetUnitCost',prl.target_unit_cost,'notes',prl.notes
              ) ORDER BY prl.line_no) FILTER (WHERE prl.id IS NOT NULL),'[]') AS lines
       FROM purchase_requisitions pr JOIN users u ON u.id=pr.requester_id
       LEFT JOIN purchase_requisition_lines prl ON prl.requisition_id=pr.id
       GROUP BY pr.id,u.display_name ORDER BY pr.created_at DESC LIMIT 200`
    );
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { console.error("GET /procurement/requisitions:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

api.post("/procurement/requisitions", authenticateJWT, requirePermission("procurement.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    await procurementClosedLoopReady;
    const { department, reason, urgency = "normal", target_date, lines = [] } = req.body;
    if (!department || !reason || !Array.isArray(lines) || !lines.length) return res.status(400).json(errorEnvelope("VALIDATION", "department, reason and lines required"));
    await client.query("BEGIN");
    const requisitionNo = `PR-${new Date().toISOString().slice(0,10).replaceAll("-","")}-${String(Date.now()).slice(-6)}`;
    const header = await client.query(
      `INSERT INTO purchase_requisitions(requisition_no,requester_id,department,reason,urgency,target_date,status)
       VALUES($1,$2,$3,$4,$5,$6,'draft') RETURNING *`,
      [requisitionNo, req.user.userId, department, reason, urgency, target_date || null]
    );
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (!line.material_code || Number(line.qty_requested) <= 0) throw new Error("Each line requires material_code and positive qty_requested");
      const material = await client.query(`SELECT id,name_zh,uom FROM materials WHERE code=$1`, [line.material_code]);
      if (!material.rows.length) throw new Error(`Material not found: ${line.material_code}`);
      await client.query(
        `INSERT INTO purchase_requisition_lines
          (requisition_id,line_no,material_id,material_code,material_name_zh,qty_requested,unit,target_unit_cost,notes)
         VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
        [header.rows[0].id, i + 1, material.rows[0].id, line.material_code, material.rows[0].name_zh,
          line.qty_requested, line.unit || material.rows[0].uom, line.target_unit_cost || null, line.notes || null]
      );
    }
    await procurementAudit(client, req, "PR", header.rows[0].id, requisitionNo, "CREATE", null, "draft");
    await client.query("COMMIT"); res.status(201).json(envelope(header.rows[0]));
  } catch (err) { await client.query("ROLLBACK"); console.error("POST /procurement/requisitions:", err.message); res.status(400).json(errorEnvelope("VALIDATION", err.message)); }
  finally { client.release(); }
});

api.put("/procurement/requisitions/:id/submit", authenticateJWT, requirePermission("procurement.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    await procurementClosedLoopReady; await client.query("BEGIN");
    const current = await client.query(`SELECT * FROM purchase_requisitions WHERE id=$1 AND status='draft' FOR UPDATE`, [req.params.id]);
    if (!current.rows.length) { await client.query("ROLLBACK"); return res.status(409).json(errorEnvelope("INVALID_STATE", "Only draft requisitions can be submitted")); }
    const pr = current.rows[0];
    await client.query(`UPDATE purchase_requisitions SET status='submitted',submitted_at=now(),updated_at=now() WHERE id=$1`, [pr.id]);
    await procurementAudit(client, req, "PR", pr.id, pr.requisition_no, "SUBMIT", "draft", "submitted");
    await client.query("COMMIT"); res.json(envelope({ submitted: true }));
  } catch (err) { await client.query("ROLLBACK"); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

api.post("/procurement/requisitions/:id/rfq", authenticateJWT, requirePermission("procurement.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    await procurementClosedLoopReady; await client.query("BEGIN");
    const current = await client.query(`SELECT * FROM purchase_requisitions WHERE id=$1 AND status IN ('submitted','quoted') FOR UPDATE`, [req.params.id]);
    if (!current.rows.length) { await client.query("ROLLBACK"); return res.status(409).json(errorEnvelope("INVALID_STATE", "Requisition must be submitted")); }
    const pr = current.rows[0], rfqNo = `RFQ-${new Date().toISOString().slice(0,10).replaceAll("-","")}-${String(Date.now()).slice(-6)}`;
    const rfq = await client.query(
      `INSERT INTO rfq_headers(rfq_no,requisition_id,title,description,priority,response_deadline,requested_by,department,status,sent_at)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8,'sent',now()) RETURNING *`,
      [rfqNo, pr.id, req.body.title || `${pr.requisition_no} supplier quotation`, req.body.description || pr.reason,
        pr.urgency, req.body.response_deadline || null, req.user.userId, pr.department]
    );
    await client.query(
      `INSERT INTO rfq_lines(rfq_header_id,line_no,material_id,material_code,material_name_zh,qty_requested,unit,target_unit_price,delivery_date,notes)
       SELECT $1,line_no,material_id,material_code,material_name_zh,qty_requested,unit,target_unit_cost,$2,notes
       FROM purchase_requisition_lines WHERE requisition_id=$3 ORDER BY line_no`, [rfq.rows[0].id, pr.target_date, pr.id]
    );
    await client.query(`UPDATE purchase_requisitions SET status='quoted',updated_at=now() WHERE id=$1`, [pr.id]);
    await procurementAudit(client, req, "RFQ", rfq.rows[0].id, rfqNo, "CREATE_AND_SEND", null, "sent", null, { requisitionId: pr.id });
    await client.query("COMMIT"); res.status(201).json(envelope(rfq.rows[0]));
  } catch (err) { await client.query("ROLLBACK"); console.error("POST /procurement/requisitions/:id/rfq:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

api.get("/procurement/rfqs", authenticateJWT, requirePermission("procurement.view"), async (_req, res) => {
  try {
    const result = await query(
      `SELECT rh.*,pr.requisition_no,
        COALESCE((SELECT json_agg(json_build_object('id',rl.id,'lineNo',rl.line_no,'materialCode',rl.material_code,
          'materialNameZh',rl.material_name_zh,'qtyRequested',rl.qty_requested,'unit',rl.unit)
          ORDER BY rl.line_no) FROM rfq_lines rl WHERE rl.rfq_header_id=rh.id),'[]') AS lines,
        COALESCE(json_agg(json_build_object('id',sqh.id,'quoteNo',sqh.quote_no,'supplierId',sqh.supplier_id,
          'supplierName',s.name_zh,'currencyCode',sqh.currency_code,'grandTotal',sqh.grand_total,
          'leadTimeDays',sqh.lead_time_days,'status',sqh.status,'isWinner',sqh.is_winner)
          ORDER BY sqh.grand_total) FILTER(WHERE sqh.id IS NOT NULL),'[]') AS quotes
       FROM rfq_headers rh JOIN purchase_requisitions pr ON pr.id=rh.requisition_id
       LEFT JOIN supplier_quote_headers sqh ON sqh.rfq_header_id=rh.id LEFT JOIN suppliers s ON s.id=sqh.supplier_id
       GROUP BY rh.id,pr.requisition_no ORDER BY rh.created_at DESC LIMIT 200`
    );
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

