api.get("/sales/orders", authenticateJWT, requirePermission("sales.view"), async (req, res) => {
  try {
    const { customer_id, status, from_date, to_date, limit = 50, page = 1 } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);
    let where = "WHERE 1=1"; const params = [];
    if (customer_id) { params.push(customer_id); where += ` AND so.customer_id = $${params.length}`; }
    if (status) { params.push(status); where += ` AND so.status = $${params.length}`; }
    if (from_date) { params.push(from_date); where += ` AND so.created_at >= $${params.length}`; }
    if (to_date) { params.push(to_date); where += ` AND so.created_at <= $${params.length}`; }
    const countResult = await query(`SELECT count(*) FROM sales_orders so ${where}`, params);
    params.push(parseInt(limit), offset);
    const result = await query(
      `SELECT so.id, so.so_no, so.currency, so.total_amount, so.status, so.created_at,
              c.code AS customer_code, c.name_zh AS customer_name_zh,
              sq.quote_no AS quote_no
       FROM sales_orders so JOIN customers c ON c.id = so.customer_id
       LEFT JOIN sales_quotes sq ON sq.id = so.quote_id
       ${where} ORDER BY so.created_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params
    );
    res.json(listEnvelope(result.rows, parseInt(countResult.rows[0].count)));
  } catch (err) { console.error("GET /sales/orders:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

api.get("/sales/orders/:id", authenticateJWT, requirePermission("sales.view"), async (req, res) => {
  try {
    const result = await query(
      `SELECT so.*, c.code AS customer_code, c.name_zh AS customer_name_zh, sq.quote_no
       FROM sales_orders so JOIN customers c ON c.id = so.customer_id
       LEFT JOIN sales_quotes sq ON sq.id = so.quote_id WHERE so.id = $1`,
      [req.params.id]
    );
    if (!result.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Sales order not found"));
    const so = result.rows[0];
    const linesResult = await query(
      `SELECT sol.*, p.code AS product_code, p.name_zh AS product_name_zh,
              (SELECT json_agg(json_build_object('work_order_code', wo.code, 'customer_po_no', cpo.po_number))
               FROM quote_to_workorder_link qwl LEFT JOIN work_orders wo ON wo.id = qwl.work_order_id LEFT JOIN customer_pos cpo ON cpo.id = qwl.customer_po_id
               WHERE qwl.sales_order_line_id = sol.id) AS wo_links
       FROM sales_order_lines sol LEFT JOIN products p ON p.id = sol.product_id
       WHERE sol.so_id = $1 ORDER BY sol.line_no`,
      [req.params.id]
    );
    so.lines = linesResult.rows;
    res.json(envelope(so));
  } catch (err) { console.error("GET /sales/orders/:id:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

api.post("/sales/orders", authenticateJWT, requirePermission("sales.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    const { customer_id, quote_id, currency = 'USD', lines = [] } = req.body;
    if (!customer_id || !lines.length) return res.status(400).json(errorEnvelope("VALIDATION", "customer_id and lines required"));
    await client.query("BEGIN");
    const seqResult = await client.query(`SELECT nextval('so_number_seq')`);
    const soNo = `SO-${new Date().getFullYear()}-${String(seqResult.rows[0].nextval).padStart(6, "0")}`;
    const totalAmount = lines.reduce((s, l) => s + (l.qty * l.unit_price), 0);
    const soResult = await client.query(
      `INSERT INTO sales_orders (so_no, customer_id, quote_id, currency, total_amount, status, created_by)
       VALUES ($1,$2,$3,$4,$5,'open',$6) RETURNING *`,
      [soNo, customer_id, quote_id || null, currency, totalAmount, req.user.id]
    );
    const soId = soResult.rows[0].id;
    for (let i = 0; i < lines.length; i++) {
      const l = lines[i];
      await client.query(
        `INSERT INTO sales_order_lines (so_id, line_no, product_id, qty, fulfilled_qty, unit_price, planned_delivery) VALUES ($1,$2,$3,$4,0,$5,COALESCE($6, CURRENT_DATE + INTERVAL '30 days'))`,
        [soId, i + 1, l.product_id, l.qty, l.unit_price, l.planned_delivery]
      );
    }
    await client.query("COMMIT");
    res.json(envelope(soResult.rows[0]));
  } catch (err) { await client.query("ROLLBACK"); console.error("POST /sales/orders:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

api.put("/sales/orders/:id/lines/:lineId/fulfill", authenticateJWT, requirePermission("sales.manage"), async (req, res) => {
  const { fulfilled_qty } = req.body;
  const client = await pgPool.connect();
  try {
    await client.query("BEGIN");
    const lineResult = await client.query(`SELECT * FROM sales_order_lines WHERE id = $1 AND so_id = $2 FOR UPDATE`, [req.params.lineId, req.params.id]);
    if (!lineResult.rows.length) { await client.query("ROLLBACK"); return res.status(404).json(errorEnvelope("NOT_FOUND", "Order line not found")); }
    const line = lineResult.rows[0];
    const newFulfilled = (line.fulfilled_qty || 0) + (fulfilled_qty || 0);
    if (newFulfilled > line.qty) { await client.query("ROLLBACK"); return res.status(400).json(errorEnvelope("VALIDATION", "Fulfilled qty exceeds ordered qty")); }
    await client.query(`UPDATE sales_order_lines SET fulfilled_qty = $1 WHERE id = $2`, [newFulfilled, req.params.lineId]);
    // Check if all lines fulfilled
    const pendingResult = await client.query(`SELECT count(*) AS cnt FROM sales_order_lines WHERE so_id = $1 AND fulfilled_qty < qty`, [req.params.id]);
    let soStatus = 'partially_fulfilled';
    if (parseInt(pendingResult.rows[0].cnt) === 0) soStatus = 'fulfilled';
    await client.query(`UPDATE sales_orders SET status = $1 WHERE id = $2`, [soStatus, req.params.id]);
    await client.query("COMMIT");
    res.json(envelope({ fulfilled: true, newFulfilledQty: newFulfilled, soStatus }));
  } catch (err) { await client.query("ROLLBACK"); console.error("PUT /sales/orders/:id/lines/:lineId/fulfill:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

