api.post("/sales/orders/:id/invoice", authenticateJWT, requirePermission("sales.manage"), async (req, res) => {
  const actor = req.user?.username ?? null;
  const actorId = req.user?.userId ?? null;
  const client = await pgPool.connect();
  try {
    await client.query("BEGIN");
    const cur = await client.query(
      "SELECT so.id, so.status, so.customer_id, so.currency, so.total_amount FROM sales_orders so WHERE so.id=$1 FOR UPDATE",
      [req.params.id],
    );
    if (cur.rows.length === 0) return res.status(404).json(errorEnvelope("NOT_FOUND", "Sales order not found"));
    const so = cur.rows[0];
    if (so.status !== "delivered") return res.status(409).json(errorEnvelope("INVALID_TRANSITION", `Cannot invoice from ${so.status}`));
    const invNo = "AR-SO-" + so.id + "-" + Date.now();
    const ins = await client.query(
      `INSERT INTO ar_invoices (invoice_no, customer_id, currency_code, invoice_date, total_amount, subtotal_amount, outstanding_amount, sales_order_id, created_by)
       VALUES ($1,$2,$3,CURRENT_DATE,$4,$4,$4,$5,$6) RETURNING id, invoice_no`,
      [invNo, so.customer_id, so.currency || "CNY", so.total_amount, so.id, actorId],
    );
    await client.query("UPDATE sales_orders SET status='invoiced', invoiced_at=now() WHERE id=$1", [so.id]);
    await client.query(
      "INSERT INTO sales_order_status_history (so_id, from_status, to_status, actor, note) VALUES ($1,'delivered','invoiced',$2,$3)",
      [so.id, actor, "AR invoice " + ins.rows[0].invoice_no],
    );
    await client.query("COMMIT");
    res.json(envelope({ invoiced: true, invoice: { id: ins.rows[0].id, invoiceNo: ins.rows[0].invoice_no } }));
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    console.error("POST /sales/orders/:id/invoice:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  } finally {
    client.release();
  }
});

