api.post("/sales/orders/:id/cancel", authenticateJWT, requirePermission("sales.manage"), async (req, res) => {
  const { reason } = req.body ?? {};
  if (!reason) return res.status(400).json(errorEnvelope("VALIDATION", "Cancellation reason required"));
  const client = await pgPool.connect();
  try {
    await client.query("BEGIN");
    const cur = await client.query("SELECT status FROM sales_orders WHERE id=$1 FOR UPDATE", [req.params.id]);
    if (cur.rows.length === 0) return res.status(404).json(errorEnvelope("NOT_FOUND", "Sales order not found"));
    const from = cur.rows[0].status;
    if (!["open", "confirmed", "released"].includes(from)) return res.status(409).json(errorEnvelope("INVALID_TRANSITION", `Cannot cancel from ${from}`));
    await client.query("UPDATE sales_orders SET status='cancelled', cancelled_at=now(), cancel_reason=$2 WHERE id=$1", [req.params.id, reason]);
    await client.query(
      "INSERT INTO sales_order_status_history (so_id, from_status, to_status, actor, note) VALUES ($1,$2,'cancelled',$3,$4)",
      [req.params.id, from, req.user?.username ?? null, reason],
    );
    await client.query("COMMIT");
    res.json(envelope({ cancelled: true }));
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    console.error("POST /sales/orders/:id/cancel:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  } finally {
    client.release();
  }
});

