api.get("/einvoice/invoices", authenticateJWT, requirePermission("einvoice.view"), async (req, res) => {
  try {
    const { status, customer_id, from_date, to_date, limit = 50 } = req.query;
    const tableCheck = await query("SELECT to_regclass('public.einvoice_invoices') AS table_name");
    if (!tableCheck.rows[0]?.table_name) return res.json(listEnvelope([], 0));
    let where = "WHERE 1=1"; const params = [];
    if (status) { params.push(status); where += ` AND ei.status = $${params.length}`; }
    if (customer_id) { params.push(customer_id); where += ` AND ei.customer_id = $${params.length}`; }
    if (from_date) { params.push(from_date); where += ` AND ei.issue_date >= $${params.length}`; }
    if (to_date) { params.push(to_date); where += ` AND ei.issue_date <= $${params.length}`; }
    params.push(parseInt(limit));
    const result = await query(
      `SELECT ei.id, ei.invoice_no, ei.einvoice_reference, ei.issue_date, ei.total_amount, ei.vat_amount, ei.gross_amount, ei.currency_code, ei.status,
              ei.gdt_confirmation_code, ei.published_at, ei.cancelled_at,
              c.name_zh AS customer_name_zh
       FROM einvoice_invoices ei
       LEFT JOIN customers c ON c.id = ei.customer_id
       ${where} ORDER BY ei.issue_date DESC LIMIT $${params.length}`,
      params
    );
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) { console.error("GET /einvoice/invoices:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

