api.post("/einvoice/ar/:arInvoiceId/issue", authenticateJWT, requirePermission("einvoice.manage"), async (req, res) => {
  try {
    // Check if einvoice already exists for this AR invoice
    const existing = await query(`SELECT id, einvoice_reference FROM einvoice_invoices WHERE ar_invoice_id = $1`, [req.params.arInvoiceId]);
    if (existing.rows.length) return res.json(envelope({ already_issued: true, id: existing.rows[0].id, einvoice_reference: existing.rows[0].einvoice_reference }));
    const arResult = await query(
      `SELECT a.*, c.name_zh AS customer_name_zh, c.tax_code AS customer_tax_code, c.address AS customer_address
       FROM ar_invoices a JOIN customers c ON c.id = a.customer_id WHERE a.id = $1`,
      [req.params.arInvoiceId]
    );
    if (!arResult.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "AR invoice not found"));
    const ar = arResult.rows[0];
    // Get config
    const configResult = await query(`SELECT * FROM einvoice_config WHERE is_active = true LIMIT 1`);
    if (!configResult.rows.length) return res.status(400).json(errorEnvelope("CONFIG_MISSING", "E-invoice provider not configured"));
    const config = configResult.rows[0];
    // Issue via provider service
    const { issueEInvoice } = require("./einvoice-service");
    const issued = await issueEInvoice({
      config, invoiceNo: ar.invoice_no, buyerName: ar.customer_name_zh, buyerTaxCode: ar.customer_tax_code, buyerAddress: ar.customer_address || "",
      lineItems: [{ description: "Sales Invoice " + ar.invoice_no, qty: 1, unitPrice: ar.subtotal_amount || ar.total_amount, vatRate: 10 }],
      totalAmount: ar.total_amount, vatAmount: ar.tax_amount, grossAmount: ar.total_amount, currency: ar.currency_code
    });
    const einvoiceResult = await query(
      `INSERT INTO einvoice_invoices (invoice_no, einvoice_reference, provider_name, invoice_type, ar_invoice_id, customer_id, buyer_name, buyer_tax_code, buyer_address, issue_date, total_amount, vat_amount, gross_amount, currency_code, status, xml_payload, pdf_url, gdt_confirmation_code, published_at)
       VALUES ($1,$2,$3,'VAT',$4,$5,$6,$7,$8,CURRENT_DATE,$9,$10,$11,$12,'published',$13,$14,$15,now()) RETURNING *`,
      [ar.invoice_no, issued.einvoice_reference, config.provider_name, req.params.arInvoiceId, ar.customer_id, ar.customer_name_zh, ar.customer_tax_code, ar.customer_address || "",
       ar.total_amount, ar.tax_amount, ar.total_amount, ar.currency_code, issued.xml_payload || '', issued.pdf_url || '', issued.confirmation_code || '']
    );
    res.json(envelope({ issued: true, id: einvoiceResult.rows[0].id, einvoice_reference: issued.einvoice_reference }));
  } catch (err) { console.error("POST /einvoice/ar/:arInvoiceId/issue:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

api.post("/einvoice/:id/cancel", authenticateJWT, requirePermission("einvoice.manage"), async (req, res) => {
  const { reason } = req.body;
  if (!reason) return res.status(400).json(errorEnvelope("VALIDATION", "Cancellation reason required"));
  try {
    const invResult = await query(`SELECT * FROM einvoice_invoices WHERE id = $1 AND status = 'published' FOR UPDATE`, [req.params.id]);
    if (!invResult.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Published e-invoice not found"));
    const inv = invResult.rows[0];
    const configResult = await query(`SELECT * FROM einvoice_config WHERE is_active = true LIMIT 1`);
    if (!configResult.rows.length) return res.status(400).json(errorEnvelope("CONFIG_MISSING", "Provider not configured"));
    const { cancelEInvoice } = require("./einvoice-service");
    await cancelEInvoice({ config: configResult.rows[0], einvoiceReference: inv.einvoice_reference, cancelReason: reason, invoiceNo: inv.invoice_no });
    await query(`UPDATE einvoice_invoices SET status = 'cancelled', cancelled_at = now(), adjustment_reason = $1 WHERE id = $2`, [reason, req.params.id]);
    res.json(envelope({ cancelled: true }));
  } catch (err) { console.error("POST /einvoice/:id/cancel:", err.message); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
});

