async function getPermissionsForRole(roleKey) {
  // The catalog bootstrap is best-effort startup work. Do not make login
  // wait behind it: existing role/permission rows are already authoritative,
  // and the bootstrap can finish in the background.
  const result = await authPool.query(
    `SELECT p.code
     FROM role_permissions rp
     JOIN permissions p ON p.id = rp.permission_id
     JOIN roles r ON r.id = rp.role_id
     WHERE r.code = $1 AND p.status = 'active'
     ORDER BY p.code`,
    [roleKey],
  );
  return result.rows.map((r) => r.code);
}

