// MES-owned PDA identity handshake. The browser/app supplies only a stable
// installation key; MES assigns and persists the human-facing device_code.
api.post("/pda/profile", authenticateJWT, async (req, res) => {
  try {
    const installationKey = String(req.body?.installationKey || "").trim();
    if (!installationKey) return res.status(400).json(errorEnvelope("VALIDATION", "installationKey required"));
    const operator = String(req.body?.operator || req.user?.username || "").trim() || "UNKNOWN";
    const appVersion = String(req.body?.appVersion || "").trim() || null;
    const existing = await query(
      `SELECT device_code AS "deviceId", serial_no AS "installationKey", device_status AS "status", assigned_to AS "assignedTo", line_code AS "lineCode"
         FROM pda_devices WHERE serial_no = $1 LIMIT 1`,
      [installationKey],
    );
    if (existing.rows.length) return res.json(envelope({ ...existing.rows[0], source: "MES", authority: "MES" }));

    const deviceId = `PDA-SMT-${randomUUID().slice(0, 8).toUpperCase()}`;
    const created = await query(
      `INSERT INTO pda_devices (device_code, serial_no, device_model, app_package, app_version, device_status, assigned_to, assigned_at, line_code, created_by, name_zh, name_en, name_vi)
       VALUES ($1, $2, $3, $4, $5, 'ASSIGNED', $6, NOW(), 'SMT', 'MES', $7, $8, $9)
       RETURNING device_code AS "deviceId", serial_no AS "installationKey", device_status AS "status", assigned_to AS "assignedTo", line_code AS "lineCode"`,
      [deviceId, installationKey, "Web/PDA", "ruijing.pda.dashboard", appVersion, operator, "SMT 上料 PDA", "SMT Material Loading PDA", "PDA nạp liệu SMT"],
    );
    res.status(201).json(envelope({ ...created.rows[0], source: "MES", authority: "MES" }));
  } catch (err) {
    if (err?.code === "42P01") return res.status(503).json(errorEnvelope("PDA_REGISTRY_UNAVAILABLE", "MES PDA device registry is not initialized"));
    if (err?.code === "23505") return res.status(409).json(errorEnvelope("PDA_ID_CONFLICT", "MES PDA device identity conflict"));
    console.error("POST /api/pda/profile:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

api.get("/pda/role-catalog", authenticateJWT, requirePermission("admin.view"), async (_req, res) => {
  res.json(envelope({ source: "MES", authority: "MES", roles: Object.keys(PDA_ROLE_DEFINITIONS).map(getPdaRoleDefinition) }));
});

function getPdaRoleDefinition(roleKey) {
  const key = String(roleKey || "").trim().toUpperCase();
  return { roleKey: key, ...(PDA_ROLE_DEFINITIONS[key] || { responsibilities: [], domains: {}, pages: [], actions: [], closedLoop: [] }) };
}

