// Daily PMC/MES loading forecast. PDA reads this published schedule and the
// live loading aggregates below; PDA never edits production schedule locally.
query(`CREATE TABLE IF NOT EXISTS smt_loading_daily_plans (
  id BIGSERIAL PRIMARY KEY,
  plan_date DATE NOT NULL,
  line_code TEXT NOT NULL,
  work_order_code TEXT NOT NULL,
  start_at TIMESTAMPTZ NOT NULL,
  finish_at TIMESTAMPTZ,
  required_pda_count INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'DRAFT',
  created_by TEXT NOT NULL DEFAULT 'PMC',
  published_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (plan_date, line_code, work_order_code)
)`).catch(e => console.error('smt_loading_daily_plans table:', e.message));
query(`ALTER TABLE bom_lines ADD COLUMN IF NOT EXISTS loading_sequence INTEGER`).catch(e => console.error('bom loading sequence:', e.message));
query(`ALTER TABLE material_lots ADD COLUMN IF NOT EXISTS roll_qty NUMERIC(18,6)`).catch(e => console.error('material roll quantity:', e.message));

// Auto-create dispatch tables on startup
query(`CREATE TABLE IF NOT EXISTS material_dispatch_sessions (
  id BIGSERIAL PRIMARY KEY,
  work_order_code VARCHAR(50) NOT NULL,
  line_code VARCHAR(20),
  status VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
)`).catch(() => {});
query(`CREATE TABLE IF NOT EXISTS material_dispatch_assignments (
  id BIGSERIAL PRIMARY KEY,
  dispatch_session_id BIGINT NOT NULL REFERENCES material_dispatch_sessions(id) ON DELETE CASCADE,
  material_code VARCHAR(50) NOT NULL,
  material_name_zh VARCHAR(200),
  smt_flag VARCHAR(20) NOT NULL DEFAULT 'SMT',
  unit VARCHAR(20),
  assigned_operator VARCHAR(100),
  assigned_pda VARCHAR(64),
  claim_operator VARCHAR(100),
  claim_pda VARCHAR(64),
  claimed_at TIMESTAMPTZ,
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  feeder_slot VARCHAR(50),
  lot_no VARCHAR(50),
  loaded_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
)`).catch(() => {});

// activeDispatchPdas: sessionId -> Map<pdaId, { operator, lineCode, lastSeen }>
const activeDispatchPdas = new Map();

// pdaSessions: pdaId -> { sessionId, lineCode } (which session/line each PDA is on)
const pdaSessions = new Map();

function getActivePdas(sessionId) {
  // Try in-memory first (fast, has lastSeen)
  const inMemory = activeDispatchPdas.get(sessionId);
  if (inMemory && inMemory.size > 0) {
    return Array.from(inMemory.entries()).map(([pdaId, info]) => ({
      pdaId,
      operator: info.operator,
      lineCode: info.lineCode,
      lastSeen: info.lastSeen
    }));
  }
  // Fall back to DB-persisted pdas (survives API restarts)
  return query(
    `SELECT pdas FROM material_dispatch_sessions WHERE id = $1`,
    [sessionId]
  ).then(({ rows }) => {
    if (!rows.length || !rows[0].pdas) return [];
    return rows[0].pdas;
  }).catch(() => []);
}

function registerActivePda(sessionId, pdaId, operator, lineCode) {
  if (!activeDispatchPdas.has(sessionId)) activeDispatchPdas.set(sessionId, new Map());
  activeDispatchPdas.get(sessionId).set(pdaId, { operator, lineCode: lineCode || null, lastSeen: Date.now() });
  pdaSessions.set(pdaId, { sessionId, lineCode: lineCode || null });
  // Persist to DB so PDAs survive API restarts
  const pdas = Array.from(activeDispatchPdas.get(sessionId).entries()).map(([id, info]) => ({
    pdaId: id, operator: info.operator, lineCode: info.lineCode
  }));
  query(
    `UPDATE material_dispatch_sessions SET pdas = $1::jsonb, updated_at = NOW() WHERE id = $2`,
    [JSON.stringify(pdas), sessionId]
  ).catch(() => {});
}

function unregisterActivePda(sessionId, pdaId) {
  activeDispatchPdas.get(sessionId)?.delete(pdaId);
  pdaSessions.delete(pdaId);
  // Persist removal to DB
  const pdas = Array.from((activeDispatchPdas.get(sessionId) || new Map()).entries()).map(([id, info]) => ({
    pdaId: id, operator: info.operator, lineCode: info.lineCode
  }));
  query(
    `UPDATE material_dispatch_sessions SET pdas = $1::jsonb, updated_at = NOW() WHERE id = $2`,
    [JSON.stringify(pdas), sessionId]
  ).catch(() => {});
}

function touchActivePda(sessionId, pdaId) {
  activeDispatchPdas.get(sessionId)?.get(pdaId) && (activeDispatchPdas.get(sessionId).get(pdaId).lastSeen = Date.now());
}

// Even-split algorithm: distribute unassigned materials round-robin across PDAs
function evenSplitMaterials(materials, pdas) {
  if (!materials.length || !pdas.length) return [];
  const assignments = [];
  materials.forEach((mat, i) => {
    const pda = pdas[i % pdas.length];
    assignments.push({ ...mat, assignedPda: pda.pdaId, assignedOperator: pda.operator, status: 'pending' });
  });
  return assignments;
}

// Build SSE event with session context (sessionId + lineCode embedded so PDA can filter)
function dispatchEvent(type, payload, from = "mes_dispatcher") {
  // Try to extract sessionId from payload if not present
  const sessionId = payload.sessionId || payload.assignmentId;
  const lineCode = payload.lineCode || null;
  const event = {
    from,
    to: "*",
    type,
    payload: { ...payload, sessionId, lineCode },
    priority: "info"
  };
  neuralBroadcast(event);
  return event;
}

// GET /mes/dispatch/sessions — list all active sessions (for PMC / multi-line overview)
api.get("/dispatch/sessions", async (req, res) => {
  try {
    const { lineCode, status = 'active' } = req.query;
    let cond = "WHERE status = $1";
    const params = [status];
    if (lineCode) { cond += " AND line_code = $2"; params.push(lineCode); }
    const { rows } = await query(
      `SELECT id, work_order_code, line_code, status, created_at FROM material_dispatch_sessions ${cond} ORDER BY created_at DESC`,
      params
    );
    // Attach progress to each session
    const sessions = await Promise.all(rows.map(async (row) => {
      const { rows: assignRows } = await query(
        `SELECT COUNT(*) total, COUNT(*) FILTER (WHERE status = 'loaded') loaded,
                COUNT(*) FILTER (WHERE status = 'pending' AND claim_operator IS NULL) pending
         FROM material_dispatch_assignments WHERE dispatch_session_id = $1`,
        [row.id]
      );
      const prog = assignRows[0];
      return {
        id: row.id,
        workOrderCode: row.work_order_code,
        lineCode: row.line_code,
        status: row.status,
        createdAt: row.created_at,
        pdas: await getActivePdas(row.id),
        progress: {
          total: Number(prog.total),
          loaded: Number(prog.loaded),
          pending: Number(prog.pending)
        }
      };
    }));
    res.json({ success: true, sessions });
  } catch (err) {
    console.error("GET /mes/dispatch/sessions:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

// POST /mes/dispatch/sessions — create or get active dispatch session for a WO
api.post("/dispatch/sessions", async (req, res) => {
  try {
    const { workOrderCode, lineCode, pdaId, operator } = req.body ?? {};
    if (!workOrderCode) return res.status(400).json({ success: false, error: "workOrderCode required" });

    // Check if active session already exists for this WO
    const existing = await query(
      "SELECT id, line_code FROM material_dispatch_sessions WHERE work_order_code = $1 AND status = 'active' LIMIT 1",
      [workOrderCode]
    );
    if (existing.rows.length > 0) {
      const sessId = existing.rows[0].id;
      const sessLineCode = existing.rows[0].line_code;
      if (pdaId && operator) registerActivePda(sessId, pdaId, operator, sessLineCode);
      const session = await getSessionWithAssignments(sessId);
      return res.json({ success: true, session, isExisting: true });
    }

    // Fetch BOM for the work order's product (join pattern used everywhere in this codebase)
    const woR = await query(
      `SELECT wo.planned_qty,
              bl.material_id, m.code AS material_code, m.name_zh AS material_name_zh,
              bl.qty_per, bl.loss_rate
       FROM work_orders wo
       JOIN boms b ON b.product_id = wo.product_id AND b.status = 'active'
       JOIN bom_lines bl ON bl.bom_id = b.id
       JOIN materials m ON m.id = bl.material_id
       WHERE wo.code = $1`,
      [workOrderCode]
    );
    const bomRows = woR.rows;
    if (!bomRows.length) return res.status(404).json({ success: false, error: "Work order not found or has no BOM" });

    const plannedQty = bomRows[0]?.planned_qty || 1;
    const materials = bomRows.map(row => ({
      materialCode: row.material_code,
      materialNameZh: row.material_name_zh,
      smtFlag: 'SMT',
      unit: null,
      requiredQty: Math.ceil(row.qty_per * plannedQty * (1 + (row.loss_rate || 0)))
    }));

    // Create session
    const sessR = await query(
      "INSERT INTO material_dispatch_sessions (work_order_code, line_code, status) VALUES ($1,$2,'active') RETURNING id",
      [workOrderCode, lineCode || null]
    );
    const sessionId = sessR.rows[0].id;

    // Register PDA if provided
    if (pdaId && operator) registerActivePda(sessionId, pdaId, operator, lineCode || null);

    // Generate assignments with even split
    const pdasForSplit = (pdaId && operator) ? [{ pdaId, operator }] : [];
    const assignments = evenSplitMaterials(materials, pdasForSplit);

    for (const a of assignments) {
      await query(
        `INSERT INTO material_dispatch_assignments
         (dispatch_session_id, material_code, material_name_zh, smt_flag, unit, assigned_pda, assigned_operator, status)
         VALUES ($1,$2,$3,$4,$5,$6,$7,'pending')`,
        [sessionId, a.materialCode, a.materialNameZh, a.smtFlag, a.unit, a.assignedPda || null, a.assignedOperator || null]
      );
    }

    dispatchEvent("DISPATCH_SESSION_STARTED", { sessionId, workOrderCode, lineCode });

    const session = await getSessionWithAssignments(sessionId);
    res.json({ success: true, session, isExisting: false });
  } catch (err) {
    console.error("POST /mes/dispatch/sessions:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /mes/dispatch/sessions/:id
