// Helper: fetch session with assignments
async function getSessionWithAssignments(sessionId) {
  const sessR = await query("SELECT * FROM material_dispatch_sessions WHERE id = $1", [sessionId]);
  if (!sessR.rows.length) return null;
  const sess = sessR.rows[0];

  const assignR = await query(
    "SELECT * FROM material_dispatch_assignments WHERE dispatch_session_id = $1 ORDER BY id",
    [sessionId]
  );

  const total = assignR.rows.length;
  const loaded = assignR.rows.filter(r => r.status === 'loaded').length;
  const pending = assignR.rows.filter(r => r.status === 'pending').length;

  return {
    id: sess.id,
    workOrderCode: sess.work_order_code,
    lineCode: sess.line_code,
    status: sess.status,
    createdAt: sess.created_at,
    pdas: await getActivePdas(sessionId),
    assignments: assignR.rows.map(r => ({
      id: r.id,
      materialCode: r.material_code,
      materialNameZh: r.material_name_zh,
      smtFlag: r.smt_flag,
      unit: r.unit,
      assignedOperator: r.assigned_operator,
      assignedPda: r.assigned_pda,
      claimOperator: r.claim_operator,
      claimPda: r.claim_pda,
      claimedAt: r.claimed_at,
      status: r.status,
      feederSlot: r.feeder_slot,
      lotNo: r.lot_no,
      loadedAt: r.loaded_at
    })),
    progress: { total, loaded, pending }
  };
}

// ── Auth ──

api.post("/auth/login", async (req, res) => {
  try {
    const { username, password } = req.body ?? {};
    if (!username || !password) {
      return res.status(400).json(errorEnvelope("VALIDATION", "username and password required"));
    }
    const loginName = String(username).trim() === "蒙营" ? "MENG_YING" : String(username).trim() === "莫立斌" ? "MO_LI_BIN" : String(username).trim();
    const result = await authPool.query(
      `SELECT u.id, u.username, u.display_name, u.locale, r.code AS role_key, u.status
       FROM users u JOIN roles r ON r.id = u.role_id WHERE u.username = $1`,
      [loginName],
    );
    if (result.rows.length === 0) {
      return res.status(401).json(errorEnvelope("AUTH_FAILED", "Invalid credentials"));
    }
    const user = result.rows[0];
    const passwordValid = user.username === "MENG_YING"
      ? password === "my"
      : user.username === "HWG"
        ? password === "hwg"
        : password === "Factory@123";
    if (!passwordValid) {
      return res.status(401).json(errorEnvelope("AUTH_FAILED", "Invalid credentials"));
    }
    if (user.status !== "active") {
      return res.status(403).json(errorEnvelope("ACCOUNT_LOCKED", "Account is not active"));
    }
    const permissions = await getPermissionsForRole(user.role_key);
    const expiresAt = new Date(Date.now() + JWT_EXPIRY_MS);
    const token = jwt.sign(
      { userId: user.id, username: user.username, roleKey: user.role_key, permissions },
      JWT_SECRET,
      { expiresIn: "24h" },
    );
    // Log audit event (fire-and-forget)
    writeAuditLog({
      actorId: user.id,
      action: "LOGIN",
      entityType: "auth",
      referenceNo: `jwt.${token.slice(-16)}`,
      ipAddress: req.ip,
      userAgent: req.headers["user-agent"],
    }).catch((e) => console.error("audit log error:", e.message));
    res.json(envelope({
      token,
      roleDefinition: getPdaRoleDefinition(user.role_key),
      user: { id: user.id, username: user.username, displayName: user.display_name, locale: user.locale, roleKey: user.role_key, permissions, roleDefinition: getPdaRoleDefinition(user.role_key) },
      expiresAt: expiresAt.toISOString(),
    }));
  } catch (err) {
    console.error("POST /api/auth/login:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

api.get("/auth/session", async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    const token = authHeader?.startsWith("Bearer ") ? authHeader.slice(7) : null;
    if (!token) {
      return res.status(401).json(errorEnvelope("UNAUTHORIZED", "Not authenticated"));
    }
    const payload = jwt.verify(token, JWT_SECRET);
    const userResult = await pgPool.query(
      `SELECT u.id, u.username, u.display_name, u.locale, r.code AS role_key, u.status
       FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = $1`,
      [payload.userId],
    );
    if (userResult.rows.length === 0) {
      return res.status(401).json(errorEnvelope("AUTH_FAILED", "User not found"));
    }
    const user = userResult.rows[0];
    const permissions = Array.isArray(payload.permissions) ? payload.permissions : [];
    res.json(envelope({
      session: {
        userId: user.id,
        username: user.username,
        displayName: user.display_name,
        locale: user.locale,
        roleKey: user.role_key,
        issuedAt: new Date(payload.iat * 1000).toISOString(),
        expiresAt: new Date(payload.exp * 1000).toISOString(),
      },
      permissions,
      roleDefinition: getPdaRoleDefinition(user.role_key),
    }));
  } catch (err) {
    if (err.name === "JsonWebTokenError" || err.name === "TokenExpiredError") {
      return res.status(401).json(errorEnvelope("TOKEN_INVALID", err.message));
    }
    console.error("GET /auth/session:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

api.post("/auth/logout", async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    let actorId = null;
    if (authHeader?.startsWith("Bearer ")) {
      try {
        const payload = jwt.verify(authHeader.slice(7), JWT_SECRET);
        actorId = payload.userId;
      } catch { /* token may already be expired — that's fine */ }
    }
    writeAuditLog({
      actorId,
      action: "LOGOUT",
      entityType: "auth",
      ipAddress: req.ip,
      userAgent: req.headers["user-agent"],
    }).catch((e) => console.error("audit log error:", e.message));
    res.json(envelope({ revoked: true }));
  } catch (err) {
    console.error("POST /auth/logout:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

