async function fetchDashboardSummary() {
  const cached = dashboardCache.get("summary");
  if (cached) return cached;
  const [woRes, lineRes, matRes, inspRes] = await Promise.all([
    query("SELECT status, count(*)::int as cnt FROM work_orders GROUP BY status"),
    query("SELECT status, count(*)::int as cnt FROM production_lines GROUP BY status"),
    query("SELECT iqc_status, count(*)::int as cnt FROM material_lots GROUP BY iqc_status"),
    query("SELECT result, count(*)::int as cnt FROM quality_inspections GROUP BY result"),
  ]);
  const data = envelope({
    workOrders: woRes.rows,
    lines: lineRes.rows,
    materialLots: matRes.rows,
    inspections: inspRes.rows,
  });
  dashboardCache.set("summary", data);
  return data;
}

