// ── Factory Simulation Status ────────────────────────────────────────
api.get("/factory-sim/status", async (_req, res) => {
  try {
    const [runsRes, stagRes, scrapRes, downtimeRes] = await Promise.all([
      query(`
        SELECT line_id, pl.internal_code AS line_code,
               COUNT(*) FILTER (WHERE mr.status = 'running') AS running,
               COUNT(*) FILTER (WHERE mr.status = 'idle')    AS idle,
               COUNT(*) FILTER (WHERE mr.status = 'paused')  AS paused,
               COUNT(*) FILTER (WHERE mr.status = 'completed') AS completed,
               SUM(mr.completed_qty)::int AS total_output,
               MAX(mr.started_at) AS last_started
        FROM mes_runs mr
        JOIN production_lines pl ON pl.id = mr.line_id
        GROUP BY mr.line_id, pl.internal_code
      `),
      query(`
        SELECT COUNT(*)::int AS total,
               COUNT(*) FILTER (WHERE status = 'open') AS open,
               COUNT(*) FILTER (WHERE stagnation_level IN ('red','critical')) AS critical
        FROM stagnation_log
        WHERE created_at > NOW() - INTERVAL '24 hours'
      `),
      query(`
        SELECT COUNT(*)::int AS total,
               COUNT(*) FILTER (WHERE status = 'pending') AS pending,
               COUNT(*) FILTER (WHERE status = 'approved') AS approved
        FROM scrap_records
        WHERE created_at > NOW() - INTERVAL '24 hours'
      `),
      query(`
        SELECT COUNT(*)::int AS total,
               COUNT(*) FILTER (WHERE status = 'open') AS open_dt,
               COUNT(*) FILTER (WHERE status = 'escalated') AS escalated,
               SUM(EXTRACT(EPOCH FROM (COALESCE(end_at, NOW()) - start_at))::integer / 60)::int AS downtime_min_24h
        FROM downtime_records
        WHERE start_at > NOW() - INTERVAL '24 hours'
      `),
    ]);
    res.json(envelope({
      runs: runsRes.rows,
      stagnation: stagRes.rows[0] ?? { total: 0, open: 0, critical: 0 },
      scrap: scrapRes.rows[0] ?? { total: 0, pending: 0, approved: 0 },
      downtime: downtimeRes.rows[0] ?? { total: 0, open_dt: 0, escalated: 0, downtime_min_24h: 0 },
    }));
  } catch (err) {
    console.error("GET /api/factory-sim/status:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// ── Station Heartbeat (no JWT required — called by station-agent every 30s) ──

// POST /mes/heartbeat/:stationCode — station ping to register liveness
app.post("/mes/heartbeat/:stationCode", async (req, res) => {
  try {
    const { stationCode } = req.params;
    const { operator, lineCode } = req.body ?? {};

    if (!stationCode) {
      return res.status(400).json(errorEnvelope("VALIDATION", "stationCode required"));
    }

    const now = new Date();
    const result = await query(`
      INSERT INTO station_heartbeats (station_code, last_seen, line_code, last_operator)
      VALUES ($1, $2, $3, $4)
      ON CONFLICT (station_code) DO UPDATE SET
        last_seen = EXCLUDED.last_seen,
        line_code = COALESCE(EXCLUDED.line_code, station_heartbeats.line_code),
        last_operator = COALESCE(EXCLUDED.last_operator, station_heartbeats.last_operator)
      RETURNING station_code, last_seen, line_code, last_operator
    `, [stationCode, now, lineCode ?? null, operator ?? null]);

    res.json(envelope({ stationCode, lastSeen: now.toISOString(), lineCode, operator }));
  } catch (err) {
    console.error("POST /mes/heartbeat:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /mes/heartbeats — all station heartbeat statuses
// Query params: lineCode (optional filter)
// Returns: { stationCode, lastSeen, lineCode, lastOperator, status: 'alive'|'warning'|'dead' }
app.get("/mes/heartbeats", async (req, res) => {
  try {
    const { lineCode } = req.query;
    const now = Date.now();
    const WARN_MS  = 30_000;  // 30 s  → yellow
    const DEAD_MS  = 60_000;  // 60 s  → red

    let sql = `
      SELECT
        sh.station_code  AS "stationCode",
        sh.last_seen      AS "lastSeen",
        sh.line_code      AS "lineCode",
        sh.last_operator  AS "lastOperator",
        ss.sequence_order AS "sequenceOrder"
      FROM station_heartbeats sh
      LEFT JOIN station_sequences ss ON ss.station_code = sh.station_code
    `;
    const params = [];
    if (lineCode) {
      sql += ` WHERE sh.line_code = $1`;
      params.push(lineCode);
    }
    sql += ` ORDER BY sh.line_code NULLS LAST, ss.sequence_order NULLS LAST, sh.station_code`;

    const rows = (await query(sql, params)).rows;
    const heartbeats = rows.map(r => {
      const elapsed = now - new Date(r.lastSeen).getTime();
      const status  = elapsed > DEAD_MS  ? 'dead'
                     : elapsed > WARN_MS  ? 'warning'
                     :                     'alive';
      return { ...r, status, elapsedMs: elapsed };
    });

    // Summary by line
    const byLine = {};
    for (const h of heartbeats) {
      const lc = h.lineCode ?? 'unknown';
      if (!byLine[lc]) byLine[lc] = { alive: 0, warning: 0, dead: 0 };
      byLine[lc][h.status]++;
    }

    res.json(envelope({ heartbeats, byLine, total: heartbeats.length, now: new Date(now).toISOString() }));
  } catch (err) {
    console.error("GET /mes/heartbeats:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// ── Equipment result ingestion (AOI/ICT/FCT/ATE on MES) ──────────────────
// No JWT — equipment devices push results directly
// POST /api/mes/equipment-result
// Body: { stationCode, sn, result: "pass"|"fail", errorCode?, operator?, model? }
app.post("/api/mes/equipment-result", async (req, res) => {
  try {
    const { stationCode, sn, result, errorCode, operator, model } = req.body ?? {};
    if (!stationCode || !sn || !result) {
      return res.status(400).json(errorEnvelope("VALIDATION", "stationCode, sn, result required"));
    }
    const normalizedResult = result === 'PASS' || result === 'pass' ? 'pass' : 'fail';

    // Resolve station and line
    const stationR = await query("SELECT id, line_id FROM stations WHERE code = $1", [stationCode]);
    if (stationR.rows.length === 0) return res.status(400).json(errorEnvelope("VALIDATION", `station ${stationCode} not found`));
    const { id: stationId, line_id: lineId } = stationR.rows[0];

    const lineR = await query("SELECT internal_code FROM production_lines WHERE id = $1", [lineId]);
    const lineCode = lineR.rows[0]?.internal_code ?? 'unknown';

    // Resolve or create PCB serial
    let pcbId = null;
    const pcbR = await query("SELECT id FROM pcb_serials WHERE serial_no = $1", [sn]);
    if (pcbR.rows.length > 0) {
      pcbId = pcbR.rows[0].id;
    } else {
      const newPcb = await query("INSERT INTO pcb_serials (serial_no, work_order_id, status) VALUES ($1, NULL, 'wip') RETURNING id", [sn]);
      pcbId = newPcb.rows[0]?.id;
    }

    // Resolve operator
    let operatorId = null;
    if (operator) {
      const opR = await query("SELECT id FROM users WHERE username = $1", [operator]);
      if (opR.rows.length > 0) operatorId = opR.rows[0].id;
    }

    // Record NG if failed
    let ngDefectId = null;
    if (normalizedResult === 'fail') {
      ngDefectId = await recordNgDefect({
        lineName: lineCode, stationCode, sn,
        result: 'fail', defectCode: errorCode ?? null,
        defectDesc: null, operator: operator ?? null,
      });
      neuralBroadcast({
        from: stationCode, to: "*", type: "NG_DEFECT", priority: "critical",
        payload: { sn, stationCode, defectCode: errorCode, operator, lineCode },
      });
      await query("UPDATE pcb_serials SET status = 'failed' WHERE serial_no = $1", [sn]);
    }

    // Record station event
    const stationEventId = await createStationEvent({
      pcbSerialId: pcbId, stationId, machineId: null, operatorId,
      eventType: normalizedResult === 'fail' ? 'ng' : 'pass',
      result: normalizedResult,
      traceabilityKey: null,
    });

    res.status(201).json({
      success: true,
      stationEventId,
      ngDefectId: ngDefectId ?? undefined,
      result: normalizedResult,
    });
  } catch (err) {
    console.error("POST /api/mes/equipment-result:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

