// Read-only material list assigned by MES to one PDA. The PDA must not fall
// back to the complete BOM: an empty result means MES has not allocated work.
api.get("/dispatch/assignments", async (req, res) => {
  try {
    const pdaId = String(req.query.pdaId || "").trim();
    const workOrderCode = String(req.query.workOrderCode || "").trim();
    const lineCode = String(req.query.lineCode || "").trim().toUpperCase();
    if (!pdaId) return res.status(400).json({ success: false, error: "pdaId required" });
    const params = [pdaId];
    const where = ["a.assigned_pda = $1", "s.status = 'active'"];
    if (workOrderCode) { params.push(workOrderCode); where.push(`s.work_order_code = $${params.length}`); }
    if (lineCode) { params.push(lineCode); where.push(`UPPER(COALESCE(s.line_code,'')) = $${params.length}`); }
    const { rows } = await query(
      `SELECT a.id, a.dispatch_session_id AS "sessionId", s.work_order_code AS "workOrderCode",
              s.line_code AS "lineCode", a.material_code AS "materialCode",
              a.material_name_zh AS "materialNameZh", a.status, a.feeder_slot AS "feederSlot",
              a.lot_no AS "lotNo", a.loaded_at AS "loadedAt"
         FROM material_dispatch_assignments a
         JOIN material_dispatch_sessions s ON s.id = a.dispatch_session_id
        WHERE ${where.join(" AND ")}
        ORDER BY a.id`, params);
    res.json({ success: true, pdaId, workOrderCode: workOrderCode || null, lineCode: lineCode || null, assignments: rows });
  } catch (err) {
    console.error("GET /api/dispatch/assignments:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});
// PDA dispatch assignment reads are station-scoped, read-only MES data.  The
// unified PDA uses its device identity (pdaId + lineCode) for this handshake
// before an operator JWT exists, so keep this one endpoint available to the
// station adapter while retaining JWT enforcement for every other API route.
app.use((req, res, next) => {
  if (req.path === "/dispatch/assignments" && req.method === "GET") return next();
  return authenticateJWT(req, res, next);
});

