// GET /mes/andon-board — Andon实时看板： MANUAL-LINE 13工位实时状态
app.get("/mes/andon-board", async (req, res) => {
  try {
    const { line = 'MANUAL-LINE' } = req.query;

    // 1. Latest heartbeat per station (online check)
    const heartR = await query(`
      SELECT station_code, MAX(occurred_at) as last_heartbeat
      FROM station_heartbeats
      WHERE occurred_at > NOW() - INTERVAL '5 minutes'
      GROUP BY station_code
    `);
    const heartbeatMap = {};
    for (const r of heartR.rows) heartbeatMap[r.station_code] = r.last_heartbeat;

    // 2. NG count per station (last 2 hours) — use ng_defect_records (sn-level)
    const ngR = await query(`
      SELECT station_code, COUNT(*)::int as ng_count
      FROM ng_defect_records
      WHERE occurred_at > NOW() - INTERVAL '2 hours'
        AND result IN ('fail', 'ng', 'rework')
      GROUP BY station_code
    `);
    const ngMap = {};
    for (const r of ngR.rows) ngMap[r.station_code] = r.ng_count;

    // 3. Latest event per station from station_sequences (authoritative station list)
    const latestR = await query(`
      SELECT
        ss.station_code,
        ss.sequence_order,
        ss.station_name_zh,
        se.result      AS event_result,
        se.event_type,
        se.occurred_at,
        CASE
          WHEN se.occurred_at > NOW() - INTERVAL '30 minutes' THEN 'active'
          ELSE 'stale'
        END AS activity
      FROM station_sequences ss
      LEFT JOIN LATERAL (
        SELECT se.result, se.event_type, se.occurred_at
        FROM station_events se
        JOIN stations s ON se.station_id = s.id
        WHERE s.code = ss.station_code
        ORDER BY se.occurred_at DESC
        LIMIT 1
      ) se ON true
      WHERE ss.line_code = $1
      ORDER BY ss.sequence_order
    `, [line]);

    // 4. Build station list with status
    const stations = [];
    let totalNG = 0;
    for (const row of latestR.rows) {
      const lastHeartbeat = heartbeatMap[row.station_code];
      const ngCount = ngMap[row.station_code] ?? 0;
      totalNG += ngCount;

      let status = 'offline';
      if (lastHeartbeat) {
        if (ngCount > 0) {
          status = 'ng';
        } else if (row.activity === 'active' && row.event_result === 'pass') {
          status = 'running';
        } else if (row.activity === 'active') {
          status = 'idle';
        } else {
          status = 'stale';
        }
      }

      stations.push({
        stationCode: row.station_code,
        stationName: row.station_name_zh,
        sequenceOrder: row.sequence_order,
        status,
        lastEvent: row.occurred_at ? new Date(row.occurred_at).toISOString() : null,
        ngCount,
        isOnline: !!lastHeartbeat,
      });
    }

    // 5. Line-level status
    let lineStatus = 'ok';
    if (totalNG > 0) lineStatus = 'ng';
    else if (stations.some(s => s.status === 'running')) lineStatus = 'running';
    else if (stations.some(s => s.status === 'idle')) lineStatus = 'idle';

    res.json({
      lineCode: line,
      lineNameZh: line === 'MANUAL-LINE' ? '手动线' : line,
      updatedAt: new Date().toISOString(),
      lineStatus,
      totalNG,
      stations,
    });
  } catch (err) {
    console.error("GET /mes/andon-board:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

