async function evaluatePurchaseOrderClosure(poId) {
  const poResult = await query(`SELECT * FROM purchase_order_headers WHERE id=$1`, [poId]);
  if (!poResult.rows.length) return null;
  const po = poResult.rows[0];
  const ordered = await query(`SELECT COALESCE(sum(qty_ordered),0)::numeric ordered_qty,COALESCE(sum(line_total),0)::numeric ordered_value FROM purchase_order_lines WHERE po_header_id=$1`, [poId]);
  const receipts = await query(
    `SELECT COALESCE(sum(rol.received_qty),0)::numeric received_qty,
            count(DISTINCT ro.id)::int receipt_count,
            count(rol.id) FILTER(WHERE ii.id IS NULL OR ii.result NOT IN ('pass','conditional'))::int iqc_unreleased
     FROM receiving_orders ro JOIN receiving_order_lines rol ON rol.receiving_order_id=ro.id
     LEFT JOIN LATERAL (
       SELECT id,result FROM iqc_inspections x WHERE x.receiving_order_line_id=rol.id ORDER BY occurred_at DESC LIMIT 1
     ) ii ON true
     WHERE ro.document_no=$1 AND ro.status NOT IN ('cancelled','voided')`, [po.po_no]
  );
  const invoices = await query(
    `SELECT COALESCE(sum(ai.total_amount),0)::numeric invoice_value,
            COALESCE(sum(ai.outstanding_amount),0)::numeric outstanding_value,
            count(*) FILTER(WHERE ai.posting_status<>'posted')::int unposted_count
     FROM ap_invoices ai JOIN receiving_orders ro ON ro.id=ai.receiving_order_id WHERE ro.document_no=$1`, [po.po_no]
  );
  const o = ordered.rows[0], r = receipts.rows[0], i = invoices.rows[0];
  const orderedQty = Number(o.ordered_qty), receivedQty = Number(r.received_qty);
  const orderedValue = Number(o.ordered_value), invoiceValue = Number(i.invoice_value);
  const tolerance = Math.max(0.01, orderedValue * 0.005);
  const gates = {
    supplierAcknowledged: Boolean(po.acknowledged_at) || ["acknowledged","partially_received","received","closed"].includes(po.status),
    receiptComplete: orderedQty > 0 && receivedQty >= orderedQty,
    iqcReleased: Number(r.receipt_count) > 0 && Number(r.iqc_unreleased) === 0,
    threeWayMatch: orderedQty > 0 && receivedQty >= orderedQty && Number(i.unposted_count) === 0 && invoiceValue > 0 && Math.abs(invoiceValue - orderedValue) <= tolerance,
    paymentSettled: invoiceValue > 0 && Number(i.outstanding_value) <= 0.01
  };
  return { po, gates, metrics: { orderedQty, receivedQty, orderedValue, invoiceValue, outstandingValue:Number(i.outstanding_value), tolerance }, canClose:Object.values(gates).every(Boolean) };
}

// Unified read model for plant/line management and the manual-line PDA.
// MES remains authoritative: this route only projects current server state.
api.get("/pda/management/overview", requirePermission("pda.view"), async (req, res) => {
  const scope = String(req.query.scope || "operator").trim().toLowerCase();
  const lineCode = String(req.query.lineCode || "").trim().toUpperCase();
  const role = String(req.user?.roleKey || "").trim().toLowerCase();
  const plantRoles = new Set(["admin", "management", "plant_manager", "factory_manager"]);
  const lineRoles = new Set([...plantRoles, "line_leader", "quality", "warehouse", "smt_operator"]);
  if (!["plant", "line", "operator"].includes(scope)) return res.status(400).json(errorEnvelope("VALIDATION", "scope must be plant, line, or operator"));
  if (scope === "plant" && !plantRoles.has(role)) return res.status(403).json(errorEnvelope("FORBIDDEN", "Plant scope requires plant-management authorization"));
  if (scope === "line" && !lineRoles.has(role)) return res.status(403).json(errorEnvelope("FORBIDDEN", "Line scope requires line authorization"));
  try {
    let heartbeatRows = [];
    try { heartbeatRows = (await query(`SELECT station_code,line_code,operator,status,last_seen_at,payload FROM mes_station_heartbeats ORDER BY station_code`)).rows; } catch (_) { /* first heartbeat may not have created the table */ }
    const now = Date.now();
    const memoryRows = Array.from(stationHeartbeatSnapshot.values()).map((item) => ({ station_code: item.stationCode, line_code: item.payload?.lineCode || null, operator: item.payload?.operator || null, status: item.payload?.status || "running", last_seen_at: new Date(item.receivedAt).toISOString(), payload: item.payload || {}, _receivedAt: item.receivedAt }));
    const byStation = new Map();
    for (const row of heartbeatRows) byStation.set(String(row.station_code).toUpperCase(), row);
    for (const row of memoryRows) byStation.set(String(row.station_code).toUpperCase(), row);
    let stations = Array.from(byStation.values()).map((row) => { const seen = row._receivedAt || Date.parse(row.last_seen_at || "") || 0; const payload = row.payload || {}; return { station_code: String(row.station_code), line_code: String(row.line_code || payload.lineCode || ""), device_id: String(payload.deviceId || payload.device_id || row.station_code || "UNREGISTERED"), status: seen > 0 && now - seen < 45000 ? "ONLINE" : "OFFLINE", operator_name: row.operator || payload.operator || null, last_heartbeat_at: row.last_seen_at || null, pending_outbox: Number(payload.pendingOutbox || payload.pending_outbox || 0) }; });
    if (scope === "line" && lineCode) stations = stations.filter((row) => row.line_code.toUpperCase() === lineCode);
    if (scope === "operator") { const identity = String(req.user?.username || req.user?.userId || "").toUpperCase(); stations = stations.filter((row) => String(row.operator_name || "").toUpperCase() === identity); }
    const visibleLines = [...new Set(stations.map((row) => row.line_code).filter(Boolean))];
    const workParams = []; const workWhere = ["LOWER(wo.status) IN ('released','running')"];
    if (scope === "line" && lineCode) { workParams.push(lineCode); workWhere.push(`UPPER(pl.internal_code)=UPPER($${workParams.length})`); }
    if (scope === "operator") { if (!visibleLines.length) return res.json(envelope({ process_domain: "manual-line", generated_at: new Date().toISOString(), mes_online: false, stations: [], work_orders: [] })); workParams.push(visibleLines); workWhere.push(`UPPER(pl.internal_code)=ANY($${workParams.length}::text[])`); }
    const workOrders = (await query(`SELECT wo.code, p.code AS product_code, COALESCE(p.revision,'') AS product_revision, wo.status, wo.completed_qty AS loaded_quantity, wo.planned_qty AS required_quantity FROM work_orders wo JOIN products p ON p.id=wo.product_id JOIN production_lines pl ON pl.id=wo.line_id WHERE ${workWhere.join(" AND ")} ORDER BY wo.created_at DESC LIMIT 100`, workParams)).rows;
    res.json(envelope({ process_domain: "manual-line", generated_at: new Date().toISOString(), mes_online: stations.some((row) => row.status === "ONLINE"), stations, work_orders: workOrders }));
  } catch (error) { res.status(500).json(errorEnvelope("PDA_MANAGEMENT_OVERVIEW_FAILED", error.message)); }
});

