api.put("/procurement/pos/:id/close", authenticateJWT, requirePermission("procurement.manage"), async (req, res) => {
  const client = await pgPool.connect();
  try {
    await procurementClosedLoopReady;
    const evaluation = await evaluatePurchaseOrderClosure(req.params.id);
    if (!evaluation) return res.status(404).json(errorEnvelope("NOT_FOUND", "Purchase order not found"));
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO purchase_order_closure_reviews(po_header_id,review_result,gates,notes,reviewed_by)
       VALUES($1,$2,$3::jsonb,$4,$5)`,
      [req.params.id,evaluation.canClose ? "passed" : "blocked",JSON.stringify({ gates:evaluation.gates,metrics:evaluation.metrics }),req.body?.notes || null,req.user.userId]
    );
    if (!evaluation.canClose) {
      await procurementAudit(client, req, "PO", evaluation.po.id, evaluation.po.po_no, "CLOSE_BLOCKED", evaluation.po.status, evaluation.po.status, req.body?.notes || null, evaluation);
      await client.query("COMMIT");
      return res.status(409).json(errorEnvelope("CLOSURE_BLOCKED", JSON.stringify(evaluation.gates)));
    }
    await client.query(`UPDATE purchase_order_headers SET status='closed',closed_at=now(),updated_at=now() WHERE id=$1`, [req.params.id]);
    await client.query(`UPDATE purchase_requisitions SET status='closed',closed_at=now(),updated_at=now() WHERE id=$1`, [evaluation.po.requisition_id]);
    await procurementAudit(client, req, "PO", evaluation.po.id, evaluation.po.po_no, "CLOSE", evaluation.po.status, "closed", req.body?.notes || null, evaluation);
    await client.query("COMMIT"); res.json(envelope({ closed:true, ...evaluation }));
  } catch (err) { await client.query("ROLLBACK"); res.status(500).json(errorEnvelope("SERVER_ERROR", err.message)); }
  finally { client.release(); }
});

