app.get("/wms/material-rolls/resolve", async (req, res) => {
  try {
    const qr = String(req.query.qr || "").trim();
    if (!qr) return res.status(400).json(errorEnvelope("ROLL_QR_REQUIRED", "qr is required"));
    const result = await query(
      `SELECT ml.id, ml.label_id AS "rollQr", ml.lot_no AS "lotNo",
              m.code AS "materialCode", m.name_zh AS "materialName",
              ml.received_qty AS "receivedQty", COALESCE(ml.reserved_qty, 0) AS "reservedQty",
              GREATEST(ml.received_qty - COALESCE(ml.reserved_qty, 0), 0) AS "availableQty",
              ml.iqc_status AS "iqcStatus", ml.lot_status AS "lotStatus",
              ml.lifecycle_status AS "lifecycleStatus", sl.code AS "locationCode",
              sc.shelf_code AS "shelfCode", sc.cell_number AS "cellNumber"
       FROM material_lots ml
       JOIN materials m ON m.id = ml.material_id
       LEFT JOIN storage_locations sl ON sl.id = ml.storage_location_id
       LEFT JOIN shelf_cells sc ON sc.material_lot_id = ml.id AND sc.cell_status = 'occupied'
       WHERE UPPER(COALESCE(ml.label_id, '')) = UPPER($1)
          OR UPPER(ml.lot_no) = UPPER($1)
       ORDER BY CASE WHEN UPPER(COALESCE(ml.label_id, '')) = UPPER($1) THEN 0 ELSE 1 END
       LIMIT 1`, [qr]
    );
    const roll = result.rows[0];
    if (!roll) return res.status(404).json(errorEnvelope("ROLL_NOT_FOUND", "WMS roll QR/lot was not found"));
    const available = Number(roll.availableQty || 0);
    const canIssue = roll.iqcStatus === "released" && roll.lotStatus === "open" && available > 0;
    res.json({ success: true, data: { ...roll, canIssue, validation: canIssue ? "READY" : "BLOCKED" } });
  } catch (err) {
    console.error("GET /wms/material-rolls/resolve:", err.message);
    res.status(500).json(errorEnvelope("ROLL_RESOLVE_FAILED", err.message));
  }
});

