app.post("/wms/material-msd-bindings/check-and-bind", requirePermission("wms.execute"), async (req,res) => {
  try {
    await materialMsdBindingReady;
    const materialCode=String(req.body?.materialCode||"").trim().toUpperCase();
    const msdLevel=String(req.body?.msdLevel||"").trim().toUpperCase();
    if(!materialCode||!msdLevel)return res.status(400).json(errorEnvelope("MSD_BINDING_REQUIRED","materialCode and msdLevel are required"));
    const existing=(await query("SELECT * FROM wms_material_msd_bindings WHERE material_code=$1",[materialCode])).rows[0];
    if(existing && existing.msd_level!==msdLevel)return res.status(409).json(errorEnvelope("MSD_MATERIAL_CONFLICT",`Material ${materialCode} is permanently bound to ${existing.msd_level}`,{binding:existing}));
    const row=(await query(`INSERT INTO wms_material_msd_bindings(material_code,msd_level,floor_life_hours,bound_by) VALUES($1,$2,$3,$4)
      ON CONFLICT(material_code) DO UPDATE SET updated_at=NOW() RETURNING *`,[materialCode,msdLevel,req.body?.floorLifeHours||null,String(req.user?.username||"operator")])).rows[0];
    res.status(existing?200:201).json(mutateEnvelope({binding:row,created:!existing}));
  } catch(err) { res.status(409).json(errorEnvelope("MSD_BINDING_FAILED",err.message)); }
});

