app.get("/mes/material-roll-bindings", async (req, res) => {
  try {
    await materialRollLabelLedgerReady;
    const workOrderCode = String(req.query.workOrderCode || "").trim();
    const rows = (await query(`SELECT f.id,f.work_order_code AS "workOrderCode",f.line_code AS "lineCode",
      f.machine_code AS "machineCode",f.channel_code AS "channelCode",f.feeder_code AS "feederCode",
      f.material_code AS "materialCode",f.material_name_zh AS "materialName",f.material_sn AS "materialSn",
      COALESCE(d.qty_per_roll,f.qty)::float8 AS "quantityPerRoll",COALESCE(d.roll_count,1)::int AS "rollCount",
      f.operator_name AS operator,f.status,f.bound_at AS "boundAt",
      (EXISTS(SELECT 1 FROM feeder_binding_events old WHERE old.work_order_code=f.work_order_code
        AND old.machine_code=f.machine_code AND COALESCE(old.channel_code,old.slot_no)=COALESCE(f.channel_code,f.slot_no)
        AND old.status='replaced' AND old.id<>f.id)
       OR EXISTS(SELECT 1 FROM smt_loading_roll_changes rc JOIN feeder_binding_events old ON old.id=rc.old_binding_id
        WHERE rc.new_binding_id=f.id AND old.feeder_code IS DISTINCT FROM f.feeder_code)) AS "feederChanged",
      COALESCE((SELECT old.feeder_code FROM smt_loading_roll_changes rc JOIN feeder_binding_events old ON old.id=rc.old_binding_id
        WHERE rc.new_binding_id=f.id AND old.feeder_code IS DISTINCT FROM f.feeder_code ORDER BY rc.changed_at DESC LIMIT 1),
      (SELECT old.feeder_code FROM feeder_binding_events old WHERE old.work_order_code=f.work_order_code
        AND old.machine_code=f.machine_code AND COALESCE(old.channel_code,old.slot_no)=COALESCE(f.channel_code,f.slot_no)
        AND old.status='replaced' AND old.id<>f.id ORDER BY old.updated_at DESC LIMIT 1)) AS "previousFeederCode"
      FROM feeder_binding_events f LEFT JOIN mes_material_binding_details d ON d.binding_id=f.id
      WHERE ($1='' OR f.work_order_code=$1) AND f.status='active'
      ORDER BY f.bound_at DESC,f.id DESC`, [workOrderCode])).rows;
    res.json(listEnvelope(rows));
  } catch (err) {
    res.status(500).json(errorEnvelope("MATERIAL_BINDING_MAP_FAILED", err.message));
  }
});

app.get("/wms/material-lots", async (req, res) => {
  try {
    const { lotNo, labelId, iqcStatus, q, limit = 50, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;
    if (lotNo) { conditions.push(`ml.lot_no = $${idx++}`); params.push(lotNo); }
    if (labelId) { conditions.push(`ml.label_id = $${idx++}`); params.push(labelId); }
    if (iqcStatus) { conditions.push(`ml.iqc_status = $${idx++}`); params.push(iqcStatus); }
    if (q) { conditions.push(`(ml.lot_no ILIKE $${idx} OR ml.label_id ILIKE $${idx} OR m.code ILIKE $${idx})`); params.push(`%${q}%`); idx++; }
    const joins = "JOIN materials m ON m.id = ml.material_id LEFT JOIN storage_locations sl ON sl.id = ml.storage_location_id LEFT JOIN suppliers s ON s.id = ml.supplier_id";
    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const countRes = await query(`SELECT count(*)::int AS total FROM material_lots ml ${joins} ${where}`, params);
    const data = await query(
      `SELECT ml.id, ml.lot_no AS "lotNo", ml.label_id AS "labelId", ml.label_id AS "rollQr", ml.received_qty AS qty,
              GREATEST(ml.received_qty - COALESCE(ml.reserved_qty, 0), 0) AS "availableQty",
              COALESCE(ml.reserved_qty, 0) AS "reservedQty", ml.iqc_status AS "iqcStatus",
              m.code AS "materialCode", m.name_zh, m.name_en, m.name_vi,
              m.uom,
              sl.code AS "locationCode", s.code AS "supplierCode", s.name_zh AS "supplierName",
              ml.manufacturing_date AS "manufacturingDate",
              ml.expiry_date AS "expiryDate",
              ml.created_at AS "receivedDate",
              ml.lot_status AS "lotStatus", ml.lifecycle_status AS "lifecycleStatus",
              ml.po_no AS "poNo",
              (SELECT b.pallet_qr FROM wms_receiving_pallet_box_bindings b WHERE UPPER(b.lot_no)=UPPER(ml.lot_no) ORDER BY b.bound_at DESC LIMIT 1) AS "palletQr",
              (SELECT b.box_qr FROM wms_receiving_pallet_box_bindings b WHERE UPPER(b.lot_no)=UPPER(ml.lot_no) ORDER BY b.bound_at DESC LIMIT 1) AS "boxQr",
              ml.reserved_qty AS "reservedQty"
       FROM material_lots ml ${joins} ${where} ORDER BY ml.created_at DESC LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)],
    );
    res.json(listEnvelope(data.rows, countRes.rows[0]?.total ?? 0));
  } catch (err) {
    console.error("GET /wms/material-lots:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

