    let where = "WHERE 1=1";
    const params = [];
    if (acknowledged !== undefined) { params.push(acknowledged === 'true'); where += ` AND ca.acknowledged = $${params.length}`; }
    if (alert_type) { params.push(alert_type); where += ` AND ca.alert_type = $${params.length}`; }
