// GET /api/solder-paste/lots — 锡膏批次列表
app.get("/api/solder-paste/lots", requirePermission("wms.read"), async (req, res) => {
  try {
    const { status, q, limit = 100, offset = 0 } = req.query;
    const cond = [], p = [];
    let i = 1;
    if (status) { p.push(status); cond.push(`spl.status = $${i++}`); }
    if (q) { p.push(`%${q}%`); cond.push(`(spl.lot_no ILIKE $${i++} OR spl.material_code ILIKE $${i++} OR spl.supplier ILIKE $${i++})`); }
    const where = cond.length ? "WHERE " + cond.join(" AND ") : "";
    p.push(Number(limit), Number(offset));
    const r = await query(`
      SELECT spl.id, spl.lot_no, spl.material_code, spl.material_name_zh,
             spl.supplier, spl.supplier_name, spl.received_at,
             spl.shelf_life_days, spl.msd_level, spl.qty_kg, spl.qty_remaining_kg,
             spl.status, spl.iqc_status, spl.notes,
             spl.created_by, spl.created_at, spl.updated_at,
             FLOOR(EXTRACT(EPOCH FROM (spl.received_at + (spl.shelf_life_days||' days')::interval - NOW()))/86400)::int AS remaining_days
      FROM solder_paste_lots spl
      ${where}
      ORDER BY spl.received_at DESC
      LIMIT $${p.length-1} OFFSET $${p.length}
    `, p);
    const cnt = await query(`SELECT count(*)::int AS total FROM solder_paste_lots spl ${where}`, p.slice(0,-2));
    res.json({ items: r.rows, total: Number(cnt.rows[0]?.total ?? 0) });
  } catch (err) {
    console.error("GET /api/solder-paste/lots:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /api/solder-paste/lots — 登记锡膏批次
app.post("/api/solder-paste/lots", requirePermission("wms.execute"), async (req, res) => {
  try {
    const { lotNo, materialCode, materialNameZh, supplier, supplierName, receivedAt,
            shelfLifeDays, msdLevel, qtyKg, notes } = req.body;
    if (!lotNo || !materialCode || !qtyKg) {
      return res.status(400).json(errorEnvelope("VALIDATION", "lotNo, materialCode, qtyKg required"));
    }
    const r = await query(`
      INSERT INTO solder_paste_lots (lot_no, material_code, material_name_zh, supplier, supplier_name,
        received_at, shelf_life_days, msd_level, qty_kg, qty_remaining_kg, notes, created_by)
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,$9,$10,$11)
      RETURNING *
    `, [lotNo, materialCode, materialNameZh ?? null, supplier ?? null, supplierName ?? null,
        receivedAt ?? new Date().toISOString(), shelfLifeDays ?? 90, msdLevel ?? "3",
        qtyKg, notes ?? null, req.user?.name ?? null]);
    res.status(201).json({ data: r.rows[0] });
  } catch (err) {
    if (err.code === "23505") return res.status(409).json(errorEnvelope("CONFLICT", "批次号已存在"));
    console.error("POST /api/solder-paste/lots:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// PATCH /api/solder-paste/lots/:id — 更新锡膏批次
app.patch("/api/solder-paste/lots/:id", requirePermission("wms.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const { qtyRemainingKg, status, iqcStatus, notes } = req.body;
    const sets = ["updated_at = NOW()"], p = [];
    if (qtyRemainingKg !== undefined) { p.push(qtyRemainingKg); sets.push(`qty_remaining_kg = $${p.length}`); }
    if (status) { p.push(status); sets.push(`status = $${p.length}`); }
    if (iqcStatus) { p.push(iqcStatus); sets.push(`iqc_status = $${p.length}`); }
    if (notes !== undefined) { p.push(notes); sets.push(`notes = $${p.length}`); }
    if (!sets.length) return res.status(400).json(errorEnvelope("VALIDATION", "No fields to update"));
    p.push(id);
    const r = await query(`UPDATE solder_paste_lots SET ${sets.join(", ")} WHERE id = $${p.length} RETURNING *`, p);
    if (!r.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Lot not found"));
    res.json({ data: r.rows[0] });
  } catch (err) {
    console.error("PATCH /api/solder-paste/lots/:id:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

