// POST /api/solder-paste/openings — 开封锡膏（MES+QMS 联动）
app.post("/api/solder-paste/openings", requirePermission("wms.execute"), async (req, res) => {
  try {
    const { lotId, shelfLifeHours, openTemp, openHumidity, openImageUrl, lineCode, machineCode } = req.body;
    if (!lotId) return res.status(400).json(errorEnvelope("VALIDATION", "lotId required"));
    const shelfH = shelfLifeHours ?? 24;
    // Update lot status
    await query(`UPDATE solder_paste_lots SET status = 'opened', updated_at = NOW() WHERE id = $1 AND status = 'frozen'`, [lotId]);
    const r = await query(`
      INSERT INTO solder_paste_openings (lot_id, opened_by, opened_by_name, shelf_life_hours, expires_at,
        open_temp, open_humidity, open_image_url, line_code, machine_code)
      VALUES ($1, $2, $3, $4, NOW() + ($4 || ' hours')::interval, $5, $6, $7, $8, $9)
      RETURNING *
    `, [lotId, req.user?.name ?? null, req.user?.display_name ?? null, shelfH,
        openTemp ?? null, openHumidity ?? null, openImageUrl ?? null, lineCode ?? null, machineCode ?? null]);
    // QMS alert check: if temp > 30°C or humidity > 60%, flag alert
    if (openTemp !== undefined || openHumidity !== undefined) {
      const alerts = [];
      if (openTemp !== undefined && openTemp > 30) alerts.push(`开封温度${openTemp}°C超标（阈值30°C）`);
      if (openHumidity !== undefined && openHumidity > 60) alerts.push(`开封湿度${openHumidity}%超标（阈值60%）`);
      if (alerts.length > 0) {
        await query(`
          INSERT INTO solder_paste_alerts (alert_type, severity, lot_id, message)
          VALUES ('SOLDER_PASTE_QC', 'warning', $1, $2)
        `, [lotId, alerts.join("; ")]);
      }
    }
    res.status(201).json({ data: r.rows[0] });
  } catch (err) {
    console.error("POST /api/solder-paste/openings:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// PATCH /api/solder-paste/openings/:id — 关闭/消耗开封（MES+QMS 联动）
app.patch("/api/solder-paste/openings/:id", requirePermission("wms.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const { action, qtyKg, workOrderCode, lineCode, machineCode, consumeImageUrl } = req.body;
    if (action === "consume") {
      if (qtyKg === undefined) return res.status(400).json(errorEnvelope("VALIDATION", "qtyKg required for consume"));
      const opR = await query(`SELECT lot_id, consumption_kg FROM solder_paste_openings WHERE id = $1`, [id]);
      if (!opR.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Opening not found"));
      // MES: Record consumption with work order linkage
      await query(`
        INSERT INTO solder_paste_consumption (opening_id, lot_id, qty_kg, work_order_code, line_code, machine_code, consumed_by, consumed_by_name, consume_image_url)
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
      `, [id, opR.rows[0].lot_id, qtyKg, workOrderCode ?? null, lineCode ?? null, machineCode ?? null, req.user?.name ?? null, req.user?.display_name ?? null, consumeImageUrl ?? null]);
      // Update opening accumulated consumption
      await query(`UPDATE solder_paste_openings SET consumption_kg = consumption_kg + $1, updated_at = NOW() WHERE id = $2`, [qtyKg, id]);
      // Update lot remaining
      await query(`UPDATE solder_paste_lots SET qty_remaining_kg = qty_remaining_kg - $1, updated_at = NOW() WHERE id = $2`, [qtyKg, opR.rows[0].lot_id]);
      res.json({ data: { consumed: qtyKg } });
    } else if (action === "close") {
      const { reason } = req.body;
      await query(`UPDATE solder_paste_openings SET status = 'closed', closed_at = NOW(), close_reason = $1, updated_at = NOW() WHERE id = $2`, [reason ?? "used", id]);
      res.json({ data: { closed: true } });
    } else {
      res.status(400).json(errorEnvelope("VALIDATION", "action must be consume or close"));
    }
  } catch (err) {
    console.error("PATCH /api/solder-paste/openings/:id:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

