// GET /api/solder-paste/summary — 锡膏看板摘要
app.get("/api/solder-paste/summary", requirePermission("wms.read"), async (req, res) => {
  try {
    const [frozenR, openedR, expiringR, todayConsumeR] = await Promise.all([
      query(`SELECT count(*)::int AS cnt FROM solder_paste_lots WHERE status = 'frozen'`),
      query(`SELECT count(*)::int AS cnt FROM solder_paste_openings WHERE status = 'active'`),
      query(`SELECT count(*)::int AS cnt FROM solder_paste_openings WHERE status = 'active' AND expires_at <= NOW() + interval '2 hours'`),
      query(`SELECT coalesce(sum(qty_kg),0)::numeric AS total FROM solder_paste_consumption WHERE consumed_at >= CURRENT_DATE`),
    ]);
    res.json({
      frozenLots: Number(frozenR.rows[0]?.cnt ?? 0),
      activeOpenings: Number(openedR.rows[0]?.cnt ?? 0),
      expiringSoon: Number(expiringR.rows[0]?.cnt ?? 0),
      todayConsumptionKg: Number(todayConsumeR.rows[0]?.total ?? 0),
    });
  } catch (err) {
    console.error("GET /api/solder-paste/summary:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

