// GET /api/mes/solder-paste/consumption — MES 锡膏消耗报表（按工单/线别）
app.get("/api/mes/solder-paste/consumption", requirePermission("mes.read"), async (req, res) => {
  try {
    const { workOrderCode, lineCode, dateFrom, dateTo, limit = 100, offset = 0 } = req.query;
    const cond = [];
    const p = [];
    let i = 1;
    if (workOrderCode) { p.push(workOrderCode); cond.push(`spc.work_order_code = $${i++}`); }
    if (lineCode) { p.push(lineCode); cond.push(`spc.line_code = $${i++}`); }
    if (dateFrom) { p.push(dateFrom); cond.push(`spc.consumed_at >= $${i++}`); }
    if (dateTo) { p.push(dateTo); cond.push(`spc.consumed_at <= $${i++}`); }
    const where = cond.length ? "WHERE " + cond.join(" AND ") : "";
    p.push(Number(limit), Number(offset));
    const r = await query(`
      SELECT spc.id, spc.qty_kg, spc.work_order_code, spc.line_code, spc.machine_code,
             spc.consumed_at, spc.consumed_by, spc.consumed_by_name, spc.consume_image_url,
             spl.lot_no, spl.material_code, spl.material_name_zh,
             spo.opened_at, spo.expires_at, spo.open_temp, spo.open_humidity
      FROM solder_paste_consumption spc
      JOIN solder_paste_lots spl ON spl.id = spc.lot_id
      LEFT JOIN solder_paste_openings spo ON spo.id = spc.opening_id
      ${where}
      ORDER BY spc.consumed_at DESC
      LIMIT $${p.length-1} OFFSET $${p.length}
    `, p);
    const cnt = await query(`SELECT count(*)::int AS total FROM solder_paste_consumption spc ${where}`, p.slice(0,-2));
    // Summary by work order
    const summaryR = await query(`
      SELECT spc.work_order_code, sum(spc.qty_kg) AS total_kg, count(*) AS records
      FROM solder_paste_consumption spc ${where} GROUP BY spc.work_order_code HAVING spc.work_order_code IS NOT NULL
    `, p.slice(0,-2));
    res.json({ items: r.rows, total: Number(cnt.rows[0]?.total ?? 0), byWorkOrder: summaryR.rows });
  } catch (err) {
    console.error("GET /api/mes/solder-paste/consumption:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/mes/work-orders/active — MES 查询进行中的工单（用于锡膏消耗关联）
app.get("/api/mes/work-orders/active", requirePermission("mes.read"), async (req, res) => {
  try {
    const { q, limit = 50, offset = 0 } = req.query;
    const cond = [`wo.status IN ('in_progress','released')`];
    const p = [];
    let i = 1;
    if (q) { p.push(`%${q}%`); cond.push(`(wo.code ILIKE $${i++} OR p.code ILIKE $${i++})`); }
    const where = "WHERE " + cond.join(" AND ");
    p.push(Number(limit), Number(offset));
    const r = await query(`
      SELECT wo.id, wo.code AS work_order_code, wo.planned_qty, wo.completed_qty, wo.status,
             p.code AS product_code, p.name_zh AS product_name_zh,
             pl.internal_code AS line_code, pl.name_zh AS line_name_zh
      FROM work_orders wo
      JOIN products p ON p.id = wo.product_id
      JOIN production_lines pl ON pl.id = wo.line_id
      ${where}
      ORDER BY wo.created_at DESC
      LIMIT $${p.length-1} OFFSET $${p.length}
    `, p);
    res.json({ items: r.rows });
  } catch (err) {
    console.error("GET /api/mes/work-orders/active:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

