// PATCH /api/materials/:id —更新物料主数据（如iqc_required标志）
app.patch("/api/materials/:id", requirePermission("wms.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const { iqcRequired, nameZh, nameEn, nameVi, shelfLifeDays, uom, materialType, status } = req.body;
    const sets = [], params = [];
    if (iqcRequired !== undefined) { params.push(iqcRequired); sets.push(`iqc_required = $${params.length}`); }
    if (nameZh !== undefined) { params.push(nameZh); sets.push(`name_zh = $${params.length}`); }
    if (nameEn !== undefined) { params.push(nameEn); sets.push(`name_en = $${params.length}`); }
    if (nameVi !== undefined) { params.push(nameVi); sets.push(`name_vi = $${params.length}`); }
    if (shelfLifeDays !== undefined) { params.push(shelfLifeDays); sets.push(`shelf_life_days = $${params.length}`); }
    if (uom !== undefined) { params.push(uom); sets.push(`uom = $${params.length}`); }
    if (materialType !== undefined) { params.push(materialType); sets.push(`material_type = $${params.length}`); }
    if (status !== undefined) { params.push(status); sets.push(`status = $${params.length}`); }
    if (!sets.length) return res.status(400).json(errorEnvelope("VALIDATION", "No fields to update"));
    params.push(id);
    const r = await query(`UPDATE materials SET ${sets.join(", ")}, updated_at = NOW() WHERE id = $${params.length} RETURNING id, code, name_zh, iqc_required`, params);
    if (!r.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Material not found"));
    res.json({ data: r.rows[0] });
  } catch (err) {
    console.error("PATCH /api/materials/:id:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});


