// ── Public station list for factory-floor tablet UI (no auth) ──────────
app.get("/api/stations", async (req, res) => {
  try {
    const rows = await query(`
      SELECT s.code, s.name_zh, s.name_en, s.name_vi,
             pl.internal_code AS line_code, pl.name_zh AS line_name_zh,
             st.code AS station_type
      FROM stations s
      JOIN production_lines pl ON pl.id = s.line_id
      LEFT JOIN station_types st ON st.id = s.station_type_id
      WHERE s.status IN ('running', 'idle') AND pl.status IN ('running', 'idle')
      ORDER BY pl.internal_code, s.code
    `);
    res.json(listEnvelope(rows.rows));
  } catch (err) {
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

