api.post('/finance/bom-cost-snapshots', requirePermission("finance.cost.write"), async(req,res)=>{
  const client=await getClient();
  try{
    const p=req.body?.payload??req.body??{};
    if(!p.bomId||!p.currencyCode)return res.status(400).json(errorEnvelope("VALIDATION","bomId and currencyCode required"));
    await client.query("BEGIN");
    const bom=(await client.query("SELECT id,revision FROM boms WHERE id=$1 AND status='active' FOR SHARE",[p.bomId])).rows[0];
    if(!bom){await client.query("ROLLBACK");return res.status(409).json(errorEnvelope("BOM_NOT_ACTIVE","Active BOM required"));}
    const lines=(await client.query(`SELECT bl.id AS bom_line_id,bl.material_id,bl.qty_per,bl.loss_rate,
        m.naming_version,m.domain_code,m.standard_unit_cost,cv.id AS cost_version_id,cv.unit_cost AS version_unit_cost
      FROM bom_lines bl JOIN materials m ON m.id=bl.material_id
      LEFT JOIN LATERAL(SELECT id,unit_cost FROM material_standard_cost_versions
        WHERE material_id=m.id AND status='ACTIVE' AND currency_code=$2
          AND effective_from<=COALESCE($3::date,CURRENT_DATE)
          AND(effective_to IS NULL OR effective_to>=COALESCE($3::date,CURRENT_DATE))
        ORDER BY effective_from DESC,cost_version DESC LIMIT 1)cv ON true
      WHERE bl.bom_id=$1 ORDER BY bl.id`,[p.bomId,p.currencyCode,p.effectiveFrom??null])).rows;
    if(!lines.length){await client.query("ROLLBACK");return res.status(409).json(errorEnvelope("BOM_EMPTY","BOM has no material lines"));}
    if(lines.some(l=>l.domain_code!=="RAW_MATERIAL")){await client.query("ROLLBACK");return res.status(409).json(errorEnvelope("BOM_DOMAIN_MISMATCH","All BOM materials must be RAW_MATERIAL"));}
    if(lines.some(l=>l.version_unit_cost==null&&l.standard_unit_cost==null)){await client.query("ROLLBACK");return res.status(409).json(errorEnvelope("MATERIAL_COST_MISSING","Every BOM material requires an approved or standard unit cost"));}
    const snapshotNo=p.snapshotNo??`BOMCOST_${p.bomId}_${Date.now()}`;
    const header=await client.query(`INSERT INTO bom_cost_snapshots(snapshot_no,bom_id,bom_revision,currency_code,labor_cost,overhead_cost,effective_from,effective_to,status,created_by)
      VALUES($1,$2,$3,$4,$5,$6,COALESCE($7,CURRENT_DATE),$8,'DRAFT',$9) RETURNING id`,[snapshotNo,bom.id,bom.revision,p.currencyCode,Number(p.laborCost??0),Number(p.overheadCost??0),p.effectiveFrom??null,p.effectiveTo??null,req.user?.userId??10]);
    let total=0;
    for(const line of lines){const unit=Number(line.version_unit_cost??line.standard_unit_cost);const extended=Number(line.qty_per)*(1+Number(line.loss_rate))*unit;total+=extended;await client.query(`INSERT INTO bom_cost_snapshot_lines(snapshot_id,bom_line_id,material_id,material_naming_version,material_cost_version_id,qty_per,loss_rate,unit_cost,extended_cost)VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,[header.rows[0].id,line.bom_line_id,line.material_id,line.naming_version,line.cost_version_id,line.qty_per,line.loss_rate,unit,extended]);}
    await client.query("UPDATE bom_cost_snapshots SET material_cost=$2 WHERE id=$1",[header.rows[0].id,total]);
    await client.query("COMMIT");
    res.status(201).json(mutateEnvelope({id:header.rows[0].id,snapshotNo,materialCost:total,status:"DRAFT"}));
  }catch(err){await client.query("ROLLBACK").catch(()=>{});res.status(400).json(errorEnvelope("BOM_COST_ERROR",err.message));}
  finally{client.release();}
});

api.post('/finance/bom-cost-snapshots/:id/decision', requirePermission("finance.cost.write"), async(req,res)=>{
  const client=await getClient();
  try{const decision=String((req.body?.payload??req.body??{}).decision??"").toUpperCase();if(!["APPROVE","REJECT"].includes(decision))return res.status(400).json(errorEnvelope("VALIDATION","APPROVE or REJECT required"));await client.query("BEGIN");const rec=(await client.query("SELECT * FROM v_bom_cost_reconciliation WHERE snapshot_id=$1",[req.params.id])).rows[0];if(!rec){await client.query("ROLLBACK");return res.status(404).json(errorEnvelope("NOT_FOUND","Cost snapshot not found"));}if(decision==="APPROVE"&&(!rec.revision_matches||!rec.total_matches||!rec.all_material_domains_valid||!rec.all_naming_versions_current||!rec.all_line_costs_match)){await client.query("ROLLBACK");return res.status(409).json(errorEnvelope("COST_RECONCILIATION_FAILED","BOM cost comparison is not fully consistent",rec));}if(decision==="APPROVE")await client.query("UPDATE bom_cost_snapshots SET status='SUPERSEDED',effective_to=CURRENT_DATE-1 WHERE bom_id=$1 AND status='ACTIVE' AND id<>$2",[rec.bom_id,req.params.id]);const row=await client.query("UPDATE bom_cost_snapshots SET status=$2::varchar,approved_by=CASE WHEN $2::varchar='ACTIVE' THEN $3::bigint ELSE NULL::bigint END,approved_at=CASE WHEN $2::varchar='ACTIVE' THEN now() ELSE NULL::timestamptz END WHERE id=$1 AND status='DRAFT' RETURNING id,status",[req.params.id,decision==="APPROVE"?"ACTIVE":"REJECTED",req.user?.userId??10]);if(!row.rows[0]){await client.query("ROLLBACK");return res.status(409).json(errorEnvelope("INVALID_STATE","Only DRAFT snapshots can be decided"));}await client.query("COMMIT");res.json(mutateEnvelope(row.rows[0]));}catch(err){await client.query("ROLLBACK").catch(()=>{});res.status(500).json(errorEnvelope("SERVER_ERROR",err.message));}finally{client.release();}
});

api.post('/finance/work-orders/:workOrderId/bom-cost-binding', requirePermission("finance.cost.write"), async(req,res)=>{
  try{const p=req.body?.payload??req.body??{};if(!p.bomId||!p.costSnapshotId||!p.reason)return res.status(400).json(errorEnvelope("VALIDATION","bomId, costSnapshotId and reason required"));const row=await query(`INSERT INTO work_order_bom_cost_bindings(work_order_id,bom_id,cost_snapshot_id,bound_by,reason)VALUES($1,$2,$3,$4,$5)RETURNING *`,[req.params.workOrderId,p.bomId,p.costSnapshotId,req.user?.userId??10,p.reason]);res.status(201).json(mutateEnvelope(row.rows[0]));}catch(err){res.status(409).json(errorEnvelope("BOM_COST_BINDING_BLOCKED",err.message));}
});

