app.post("/mes/work-orders/:workOrderId/bom-writeoffs", requirePermission("mes.execute"), async(req,res)=>{
  const client=await pgPool.connect();
  try{
    const workOrderId=Number(req.params.workOrderId),p=req.body||{};
    const materialCode=String(p.materialCode||'').trim().toUpperCase();
    const qty=Number(p.qty||0),stage=String(p.stage||'PRODUCTION').toUpperCase();
    if(!materialCode||!(qty>0))return res.status(400).json(errorEnvelope("VALIDATION","materialCode and positive qty required"));
    await client.query('BEGIN');
    await client.query(`SELECT freeze_work_order_bom_requirements($1)`,[workOrderId]);
    const requirement=(await client.query(`SELECT r.id FROM work_order_bom_requirements r
      JOIN materials m ON m.id=r.material_id WHERE r.work_order_id=$1 AND UPPER(m.code)=$2`,[workOrderId,materialCode])).rows[0];
    if(!requirement){await client.query('ROLLBACK');return res.status(409).json(errorEnvelope(
      "MATERIAL_NOT_IN_WORK_ORDER_BOM","material is absent from the frozen work-order BOM"));}
    const eventNo=String(p.eventNo||`BOMWO-${workOrderId}-${Date.now()}`);
    await client.query(`INSERT INTO work_order_bom_writeoffs
      (event_no,work_order_id,requirement_id,material_lot_id,stage,qty,status,source_reference,actor,detail)
      VALUES($1,$2,$3,$4,$5,$6,'POSTED',$7,$8,$9)`,[eventNo,workOrderId,requirement.id,p.materialLotId||null,
      stage,qty,p.sourceReference||null,p.actor||'MES',JSON.stringify(p.detail||{})]);
    const gate=(await client.query(`SELECT * FROM v_work_order_bom_gate WHERE work_order_id=$1`,[workOrderId])).rows[0];
    await client.query('COMMIT');res.status(201).json({ok:true,eventNo,gate});
  }catch(error){await client.query('ROLLBACK');res.status(409).json(errorEnvelope("BOM_WRITEOFF_REJECTED",error.message));}
  finally{client.release();}
});

