// PATCH /mes/ng-compensations/:id — PMC approve or dispute a compensation request
app.patch("/mes/ng-compensations/:id", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const { status, reviewNote, reviewedBy, reviewedByName } = req.body?.payload ?? req.body ?? {};

    if (!status || !["APPROVED", "DISPUTED", "ISSUED", "CLOSED"].includes(status)) {
      return res.status(400).json(errorEnvelope("VALIDATION", "status required: APPROVED | DISPUTED | ISSUED | CLOSED"));
    }

    const existing = await query(
      `SELECT id, status, compensation_qty, material_code, lot_no, reason_code,
              unit_cost_usd, work_order_code
       FROM ng_compensation_requests WHERE id = $1`,
      [id],
    );
    if (!existing.rows[0]) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "Compensation request not found"));
    }

    const rec = existing.rows[0];
    const validTransitions = {
      PENDING:  ["APPROVED", "DISPUTED"],
      APPROVED: ["ISSUED", "DISPUTED"],
      DISPUTED: ["APPROVED"],
      ISSUED:   ["CLOSED"],
    };
    if (!validTransitions[rec.status]?.includes(status)) {
      return res.status(409).json(errorEnvelope(
        "INVALID_TRANSITION",
        `Cannot transition from "${rec.status}" to "${status}"`,
      ));
    }

    // Resolve reviewer
    const opR = await query("SELECT id FROM users WHERE username = $1", [reviewedBy ?? "UNKNOWN"]);
    const reviewerId = opR.rows[0]?.id ?? null;

    const upd = await query(
      `UPDATE ng_compensation_requests
       SET status = $1, review_note = $2,
           reviewed_by = $3, reviewed_by_name = $4, reviewed_at = NOW(),
           updated_at = NOW()
       WHERE id = $5
       RETURNING
         id, request_no AS "requestNo", status,
         reviewed_by_name AS "reviewedByName", reviewed_at AS "reviewedAt",
         review_note AS "reviewNote"`,
       [status, reviewNote ?? null, reviewerId, reviewedByName ?? reviewedBy ?? "PMC", id],
    );

    // ── Log financial event for APPROVED/DISPUTED ──
    if (status === "APPROVED") {
      const unitCost = parseFloat(rec.unit_cost_usd) || 0;
      await logMaterialFinancialEvent({
        eventType: "COMPENSATION_APPROVED",
        workOrderCode: rec.work_order_code,
        materialCode: rec.material_code,
        lotNo: rec.lot_no,
        qty: parseInt(rec.compensation_qty),
        unitCostUsd: unitCost,
        lossAmountUsd: parseInt(rec.compensation_qty) * unitCost,
        reasonCode: rec.reason_code,
        refId: parseInt(id),
        refType: "COMPENSATION",
        operatorName: reviewedByName ?? reviewedBy ?? "PMC",
      });
    } else if (status === "DISPUTED") {
      await logMaterialFinancialEvent({
        eventType: "COMPENSATION_DISPUTED",
        workOrderCode: rec.work_order_code,
        materialCode: rec.material_code,
        lotNo: rec.lot_no,
        qty: parseInt(rec.compensation_qty),
        reasonCode: rec.reason_code,
        reasonNote: reviewNote,
        refId: parseInt(id),
        refType: "COMPENSATION",
        operatorName: reviewedByName ?? reviewedBy ?? "PMC",
      });
    }

    res.json(envelope(upd.rows[0]));
  } catch (err) {
    console.error("PATCH /mes/ng-compensations/:id:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /mes/material-financial-events — Finance manager dashboard
app.get("/mes/material-financial-events", requirePermission("mes.view"), async (req, res) => {
  try {
    const { eventType, fromDate, toDate, refType, limit = 200 } = req.query;
    let sql = `
      SELECT id, event_type AS "eventType", work_order_code AS "workOrderCode",
             line_code AS "lineCode", material_code AS "materialCode",
             material_name_zh AS "materialNameZh", lot_no AS "lotNo",
             qty, unit_cost_usd AS "unitCostUsd", total_cost_usd AS "totalCostUsd",
             sale_proceeds_usd AS "saleProceedsUsd", loss_amount_usd AS "lossAmountUsd",
             supplier_code AS "supplierCode", supplier_name AS "supplierName",
             buyer_code AS "buyerCode", buyer_name AS "buyerName",
             reason_code AS "reasonCode", reason_note AS "reasonNote",
             ref_id AS "refId", ref_type AS "refType",
              operator_name AS "operatorName", occurred_at AS "createdAt"
      FROM material_financial_events
      WHERE 1=1`;
    const params = [];
    let p = 1;
    if (eventType) { sql += ` AND event_type = $${p++}`; params.push(eventType); }
    if (refType)   { sql += ` AND ref_type = $${p++}`;   params.push(refType); }
    if (fromDate)  { sql += ` AND occurred_at >= $${p++}`; params.push(fromDate); }
    if (toDate)    { sql += ` AND occurred_at <= $${p++}`; params.push(toDate); }
    sql += ` ORDER BY occurred_at DESC LIMIT $${p++}`;
    params.push(parseInt(limit));
    const r = await query(sql, params);

    // 30-day stats by event type
    const statsR = await query(`
      SELECT event_type                                    AS "eventType",
             COUNT(*)::int                                 AS "count",
             COALESCE(SUM(loss_amount_usd),0)::numeric     AS "totalLoss",
             COALESCE(SUM(sale_proceeds_usd),0)::numeric   AS "totalProceeds",
             COALESCE(SUM(total_cost_usd),0)::numeric      AS "totalCost"
      FROM material_financial_events
      WHERE occurred_at >= NOW() - INTERVAL '30 days'
      GROUP BY event_type
    `);

    res.json(envelope({
      items: r.rows,
      stats: statsR.rows,
      total: r.rows.length,
    }));
  } catch (err) {
    console.error("GET /mes/material-financial-events:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

