// FCT batch — POST /api/mes/stations/fct/batch
// Payload: { stationCode, machineCode?, records: [{pcbSerial, result, channel, testTime, errorCode?, failedTests?, defectDescription?}] }
// MES work: stationId lookup once + batch INSERT station_events + ng_defect + trace_event
api.post("/mes/stations/fct/batch", async (req, res) => {
  try {
    const { stationCode, machineCode, records } = req.body ?? {};
    if (!stationCode || !Array.isArray(records) || records.length === 0) {
      return res.status(400).json(errorEnvelope("VALIDATION", "stationCode and records[] required"));
    }

    // Resolve station + line once
    const stationRow = await query(`
      SELECT st.id AS station_id, st.line_id, pl.name_zh AS line_name, pl.internal_code AS line_code
      FROM stations st
      JOIN production_lines pl ON pl.id = st.line_id
      WHERE st.code = $1`, [stationCode]);
    if (!stationRow.rows[0]?.station_id) {
      return res.status(400).json(errorEnvelope("VALIDATION", `Station '${stationCode}' not found`));
    }
    const stationId = stationRow.rows[0].station_id;
    const lineName = stationRow.rows[0].line_name;
    const lineCode = stationRow.rows[0].line_code;

    // Resolve machineCode once if provided
    let machineId = null;
    if (machineCode) {
      const mRow = await query("SELECT id FROM machines WHERE code = $1", [machineCode]);
      machineId = mRow.rows[0]?.id ?? null;
    }

    let inserted = 0;
    let failed = 0;

    for (const rec of records) {
      const { pcbSerial, result, channel, testTime, errorCode, failedTests, defectDescription } = rec;
      const normResult = (String(result).toLowerCase().includes("pass")) ? "pass" : "fail";

      // Station event
      await query(
        `INSERT INTO station_events (pcb_serial_id, station_id, machine_id, operator_id, event_type, result, traceability_key)
         VALUES (NULL,$1,$2,NULL,'fct_test',$3,NULL) RETURNING id`,
        [stationId, machineId ?? null, normResult]
      );
      inserted++;

      if (normResult === "fail") {
        failed++;
        const primaryFail = Array.isArray(failedTests) ? failedTests[0] : null;
        const defectDesc = defectDescription
          ?? (primaryFail ? `${primaryFail.name ?? "test"}: ${primaryFail.reason ?? primaryFail.status ?? "fail"}` : null)
          ?? `FCT fail: ${errorCode ?? "unknown"}`;

        await recordNgDefect({
          lineName: lineName ?? "unknown",
          stationCode,
          sn: pcbSerial || "unknown",
          result: "fail",
          channel: channel ?? null,
          errorCode: errorCode ?? null,
          defectCode: null,
          defectDesc,
          source: "fct_batch",
          operator: null,
        });
      }

      // Trace event
      if (pcbSerial) {
        await query(
          `INSERT INTO traceability_events (trace_key, event_type, reference_no, status, actor, event_payload, occurred_at)
           VALUES ($1, 'fct_test', $1, 'active', 'system', $2, NOW())`,
          [pcbSerial, JSON.stringify({ failedTests: failedTests ?? [], testTime, errorCode, channel, machineCode })]
        );
      }
    }

    res.status(201).json(mutateEnvelope({ inserted, failed, total: records.length }));
  } catch (err) {
    console.error("POST /mes/stations/fct/batch:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

