// Shell Bind event — POST /api/mes/stations/shell-bind
api.post("/mes/stations/shell-bind", async (req, res) => {
  try {
    const { stationCode, pcbSerial, workOrderCode, machineCode, operatorUsername, result, shellSerial, imei, failedItems, bindMethod } = req.body?.payload ?? {};
    if (!stationCode || !result) return res.status(400).json(errorEnvelope("VALIDATION", "stationCode and result required"));
    const ids = await resolveIds({ stationCode, pcbSerial, workOrderCode, machineCode, operatorUsername });
    if (!ids.stationId) return res.status(400).json(errorEnvelope("VALIDATION", "Station not found"));
    const primaryFail = failedItems?.[0];
    let ngDefectId = null;
    if (result === "fail" && primaryFail) {
      ngDefectId = await recordNgDefect({ lineName: ids.lineCode ?? "unknown", stationCode, sn: pcbSerial, result: "fail", defectCode: primaryFail, defectDesc: "Shell bind: " + (failedItems?.join(", ") ?? "unknown"), operator: operatorUsername });
    } else if (result === "fail") {
      ngDefectId = await recordNgDefect({ lineName: ids.lineCode ?? "unknown", stationCode, sn: pcbSerial, result: "fail", defectCode: "SHELL-BIND-FAIL", defectDesc: "Shell bind failed", operator: operatorUsername });
    }

    // Record PCBA→Shell binding in pcb_shell_bindings (for NG propagation downstream)
    if (pcbSerial && shellSerial && result === "pass") {
      try {
        await query(
          `INSERT INTO pcb_shell_bindings (pcb_sn, shell_sn, operator, station_code, line_name, synced)
           VALUES ($1, $2, $3, $4, $5, true)
           ON CONFLICT (shell_sn) DO UPDATE SET
             pcb_sn = EXCLUDED.pcb_sn,
             operator = EXCLUDED.operator,
             station_code = EXCLUDED.station_code,
             updated_at = NOW()`,
          [pcbSerial, shellSerial, operatorUsername ?? "system", stationCode, ids.lineCode ?? "L004"],
        );
      } catch (bindErr) {
        console.error("pcb_shell_bindings insert failed:", bindErr.message);
      }
    }

    await createTraceEvent({ traceKey: pcbSerial, eventType: "shell_bind", referenceNo: pcbSerial, actor: operatorUsername ?? "system", eventPayload: { shellSerial, imei, failedItems: failedItems ?? [], bindMethod } });
    const stationEventId = await createStationEvent({ pcbSerialId: ids.pcbSerialId ?? null, stationId: ids.stationId, machineId: ids.machineId ?? null, operatorId: ids.operatorId ?? null, eventType: "shell_bind", result });
    res.status(201).json(mutateEnvelope({ stationEventId, ngDefectId: ngDefectId ?? undefined }));
  } catch (err) {
    console.error("POST /mes/stations/shell-bind:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// Station IP registration — PATCH /api/mes/stations/:code/ip
// Station calls this on startup to report its host IP address.
api.patch("/mes/stations/:code/ip", async (req, res) => {
  try {
    const { code } = req.params;
    const { ip_address } = req.body?.payload ?? req.body ?? {};
    if (!ip_address) return res.status(400).json(errorEnvelope("VALIDATION", "ip_address required"));
    const result = await query(
      `UPDATE stations SET ip_address = $1 WHERE code = $2 RETURNING id, code, ip_address`,
      [ip_address, code]
    );
    if (!result.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", `Station ${code} not found`));
    res.json(mutateEnvelope({ ok: true, station: result.rows[0] }));
  } catch (err) {
    console.error("PATCH /mes/stations/:code/ip:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

