// Pack station event — POST /api/mes/stations/pack
// Handles packaging line NG events from 包装ATE station.py
// Payload: { action, payload: { stationCode, pcbSerial, machineCode, operator, result, errorCode, channel } }
api.post("/mes/stations/pack", async (req, res) => {
  try {
    const outer = req.body ?? {};
    const { pcbSerial, stationCode, machineCode, operator, operatorUsername, eventType, result,
            errorCode, channel, defectCode, defectDescription } = outer.payload ?? {};
    const act = outer.action || eventType;
    if (!result || !act) return res.status(400).json(errorEnvelope("VALIDATION", "result and action required"));
    if (!stationCode) return res.status(400).json(errorEnvelope("VALIDATION", "stationCode required"));

    const op = operatorUsername || operator || "system";
    const ids = await resolveIds({ stationCode, pcbSerial, machineCode, operatorUsername: op });

    let ngDefectId = null;
    if (result === "fail" && (errorCode || defectCode)) {
      ngDefectId = await recordNgDefect({
        lineName: ids.lineCode ?? "unknown",
        stationCode,
        sn: pcbSerial || "unknown",
        result,
        channel: channel ?? null,
        errorCode: errorCode ?? null,
        defectCode: defectCode ?? null,
        defectDesc: defectDescription ?? null,
        operator: op,
      });
    }

    await createTraceEvent({ traceKey: pcbSerial, eventType: act, referenceNo: pcbSerial, actor: op });
    const stationEventId = await createStationEvent({
      pcbSerialId: ids.pcbSerialId ?? null, stationId: ids.stationId,
      machineId: ids.machineId ?? null, operatorId: ids.operatorId ?? null,
      eventType: act, result,
    });

    res.status(201).json(mutateEnvelope({ stationEventId, ngDefectId: ngDefectId ?? undefined }));
  } catch (err) {
    console.error("POST /mes/stations/pack:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

