// Barcode scan event — POST /api/mes/stations/scan
api.post("/mes/stations/scan", async (req, res) => {
  try {
    const { stationCode, barcode, barcodeType, workOrderCode, operatorUsername, machineCode, lineCode } = req.body?.payload ?? {};
    if (!stationCode || !barcode || !barcodeType) return res.status(400).json(errorEnvelope("VALIDATION", "stationCode, barcode, and barcodeType required"));

    const ids = await resolveIds({ stationCode, workOrderCode, machineCode, operatorUsername, lineCode });
    if (!ids.stationId) return res.status(400).json(errorEnvelope("VALIDATION", `Station '${stationCode}' not found`));

    const eventTypeMap = { pcb_serial: "pcb_scan", work_order: "wo_scan", material_reel: "material_scan", feeder: "feeder_scan", location: "location_scan" };
    const eventType = eventTypeMap[barcodeType] ?? "scan";

    // For PCB serial scans, check duplicate
    if (barcodeType === "pcb_serial") {
      const dup = await query("SELECT id, serial_no, status FROM pcb_serials WHERE serial_no = $1", [barcode]);
      if (dup.rows.length > 0) {
        const snDupId = await logSnDuplicate({
          lineName: ids.lineCode ?? lineCode ?? "unknown",
          stationCode,
          sn: barcode,
          action: eventType,
          decision: "allowed",
          operator: operatorUsername,
        });
        await createTraceEvent({ traceKey: barcode, eventType, referenceNo: barcode, actor: operatorUsername ?? "system", eventPayload: { barcode, barcodeType, stationCode } });
        const stationEventId = await createStationEvent({ pcbSerialId: dup.rows[0].id, stationId: ids.stationId, machineId: ids.machineId ?? null, operatorId: ids.operatorId ?? null, eventType, result: "pass" });
        return res.status(201).json(mutateEnvelope({ stationEventId, snDuplicateId: snDupId, barcodeType }));
      }
    }

    await createTraceEvent({ traceKey: barcode, eventType, referenceNo: barcode, actor: operatorUsername ?? "system", eventPayload: { barcode, barcodeType, stationCode } });
    const stationEventId = await createStationEvent({ pcbSerialId: ids.pcbSerialId ?? null, stationId: ids.stationId, machineId: ids.machineId ?? null, operatorId: ids.operatorId ?? null, eventType, result: "pass" });
    res.status(201).json(mutateEnvelope({ stationEventId, barcodeType }));
  } catch (err) {
    console.error("POST /mes/stations/scan:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

