// ── Smart Shelf rack API ──────────────────────────────────────────
// Proxies to real shelf controller hardware at SHELF_CONTROLLER_URL
// Docs: 感应式料架接口文档.docx
//   POST /api/shelf/ShelfIn               { shelfCode, labelId }
//   POST /api/shelf/ShelfOut               { labelIdList / labelIdListJson, color }
//   POST /api/shelf/LightOnAllEmptyLocation { shelfCode, color }
//   POST /api/shelf/InventoryRemoveLable   { labelId }

const SHELF_CONTROLLER_URL = process.env.SHELF_CONTROLLER_URL ?? "http://192.168.6.118:8093";
const MOCK_SHELF = process.env.MOCK_SHELF === "1";

// In-memory mock shelf state for local dev / when backend is unreachable
const SHELF_CODES = ["L001A","L001B","L002A","L002B","L003A","L003B"];
const mockShelfState = {};
for (const code of SHELF_CODES) {
  mockShelfState[code] = {
    labels: [],       // {labelId, materialCode, lotNo, qty, putTime}
    cellLights: {},   // cellLabel → color (null = off)
  };
}

function isShelfBackendReachable() {
  return !MOCK_SHELF;
}

// Light up (or turn off) all empty shelf cells for materials in a dispatch session
// color 6 = cyan = "loading in progress", color 0 = off
// Uses LightOnAllEmptyLocation per shelf_code (the only LED API that works reliably)
async function lightSessionMaterials(sessionId, color) {
  try {
    // Get distinct shelf_codes for this session's materials via shelf_cells
    const shelfR = await query(`
      SELECT DISTINCT sc.shelf_code
      FROM material_dispatch_assignments mda
      JOIN materials mat ON mat.code = mda.material_code
      JOIN material_lots ml ON ml.material_id = mat.id
      JOIN shelf_cells sc ON sc.material_lot_id = ml.id
      WHERE mda.dispatch_session_id = $1
    `, [sessionId]);

    const shelfCodes = shelfR.rows.map(r => r.shelf_code).filter(Boolean);
    if (!shelfCodes.length) {
      console.log(`[ShelfLight] session ${sessionId}: no shelf_codes found`);
      return;
    }

    console.log(`[ShelfLight] session=${sessionId} color=${color} shelves=${shelfCodes.join(',')}`);

    if (!isShelfBackendReachable()) return;

    // Call LightOnAllEmptyLocation for each shelf — this is the working LED API
    await Promise.all(
      shelfCodes.map(shelfCode =>
        fetch(`${SHELF_CONTROLLER_URL}/api/shelf/LightOnAllEmptyLocation`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ shelfCode, color }),
          signal: AbortSignal.timeout(8000),
        }).catch(err => console.error(`[ShelfLight] ${shelfCode} error:`, err.message))
      )
    );
  } catch (err) {
    console.error(`[ShelfLight] session ${sessionId} error:`, err.message);
  }
}

// Light a specific label on the rack (e.g., when a material is loaded, turn its light off)
async function lightLabelOff(labelId) {
  if (!labelId) return;
  try {
    if (!isShelfBackendReachable()) return;
    await fetch(`${SHELF_CONTROLLER_URL}/api/shelf/ShelfOut`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ labelIdList: [labelId], color: 0 }),
      signal: AbortSignal.timeout(5000),
    });
  } catch (err) {
    console.error(`[ShelfLight] labelOff ${labelId} error:`, err.message);
  }
}

// Helper: proxy to shelf controller
async function proxyShelf(req, res, shelfPath, body) {
  const url = `${SHELF_CONTROLLER_URL}/api/shelf/${shelfPath}`;
  try {
    const controllerRes = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(8000),
    });
    const data = await controllerRes.json();
    res.status(controllerRes.status).json(data);
  } catch (err) {
    console.error(`POST /api/wms/shelf/${shelfPath}:`, err.message);
    res.status(502).json({ Result: "NG", ErrorCode: "PROXY_ERROR", Message: err.message });
  }
}

// POST /api/wms/shelf/light-on  →  LightOnAllEmptyLocation
api.post("/wms/shelf/light-on", async (req, res) => {
  const { shelfCode, color } = req.body ?? {};
  if (!shelfCode || color === undefined) {
    return res.status(400).json({ Result: "NG", ErrorCode: "BAD_REQUEST", Message: "shelfCode and color are required" });
  }
  if (!isShelfBackendReachable()) {
    // Mock: just return OK, track lights in memory
    const state = mockShelfState[shelfCode.toUpperCase()];
    if (state) {
      for (const [cellLabel] of Object.entries(state.cellLights)) {
        state.cellLights[cellLabel] = color;
      }
    }
    return res.json({ Result: "OK", Message: "Mock: light-on succeeded", shelfCode, color });
  }
  await proxyShelf(req, res, "LightOnAllEmptyLocation", { shelfCode, color });
});

  // POST /api/wms/shelf/shelf-in  →  ShelfIn
  api.post("/wms/shelf/shelf-in", async (req, res) => {
    const { shelfCode, labelId } = req.body ?? {};
    if (!shelfCode || !labelId) {
      return res.status(400).json({ Result: "NG", ErrorCode: "BAD_REQUEST", Message: "shelfCode and labelId are required" });
    }
    if (!isShelfBackendReachable()) {
      const state = mockShelfState[shelfCode.toUpperCase()];
      if (!state) return res.status(400).json({ Result: "NG", ErrorCode: "INVALID_SHELF", Message: `Unknown shelfCode: ${shelfCode}` });
      const existing = state.labels.find(l => l.labelId === labelId);
      if (!existing) {
        state.labels.push({ labelId, materialCode: "MOCK-MAT", lotNo: labelId, qty: 100, putTime: new Date().toISOString() });
      }
      return res.json({ Result: "OK", Message: "Mock: shelf-in succeeded", shelfCode, labelId });
    }
    await proxyShelf(req, res, "ShelfIn", { shelfCode, labelId });
  });

  // POST /api/wms/shelf/shelf-out  →  ShelfOut
  api.post("/wms/shelf/shelf-out", async (req, res) => {
    const { labelIdList, labelIdListJson, color } = req.body ?? {};
    if ((!labelIdList || labelIdList.length === 0) && !labelIdListJson) {
      return res.status(400).json({ Result: "NG", ErrorCode: "BAD_REQUEST", Message: "labelIdList or labelIdListJson is required" });
    }
    const ids = labelIdList ?? (labelIdListJson ? JSON.parse(labelIdListJson) : []);
    if (!isShelfBackendReachable()) {
      for (const code of SHELF_CODES) {
        mockShelfState[code].labels = mockShelfState[code].labels.filter(l => !ids.includes(l.labelId));
      }
      return res.json({ Result: "OK", Message: "Mock: shelf-out succeeded", removedCount: ids.length });
    }
    await proxyShelf(req, res, "ShelfOut", { labelIdList, labelIdListJson, color });
  });

// POST /api/wms/shelf/remove-label  →  InventoryRemoveLable
api.post("/wms/shelf/remove-label", async (req, res) => {
  const { labelId } = req.body ?? {};
  if (!labelId) {
    return res.status(400).json({ Result: "NG", ErrorCode: "BAD_REQUEST", Message: "labelId is required" });
  }
  if (!isShelfBackendReachable()) {
    for (const code of SHELF_CODES) {
      mockShelfState[code].labels = mockShelfState[code].labels.filter(l => l.labelId !== labelId);
    }
    return res.json({ Result: "OK", Message: "Mock: remove-label succeeded", labelId });
  }
  await proxyShelf(req, res, "InventoryRemoveLable", { labelId });
});

// GET /api/wms/shelf/status  →  current in-memory mock state (seeded from DB)
// NOTE: smart-shelf src is TypeScript (.ts) — not compiled here.
// Real shelf controller at SHELF_CONTROLLER_URL; mock tracks in-memory state only.
api.get("/wms/shelf/status", async (req, res) => {
  try {
    if (!isShelfBackendReachable()) {
      // Return mock state — 6 shelves with in-memory label data
      const shelves = SHELF_CODES.map(code => {
        const state = mockShelfState[code];
        const totalCells = 24;
        return {
          code,
          area: SHELF_CODES.indexOf(code) + 1,
          totalCells,
          occupiedCells: state.labels.length,
          labelCount: state.labels.length,
          layers: 3,
          cols: 8,
        };
      });
      return res.json({ data: { shelves, totalShelves: shelves.length } });
    }
    const [cells, labels] = await Promise.all([
      sqlQuery(`SELECT Area, Colu, Layer, SerialNumber, MaterialCode, Used
                 FROM Sys_CellsInfo ORDER BY Area, Layer, Colu`),
      sqlQuery(`SELECT ShelfCode, SerialNumber, Status FROM T_ShelfAndLabelInfo`),
    ]);
    const AREA_MAP = { 1:"L001A", 2:"L001B", 3:"L002A", 4:"L002B", 5:"L003A", 6:"L003B" };
    const shelves = {};
    for (const [area, code] of Object.entries(AREA_MAP)) {
      const areaCells = cells.filter(c => c.Area === Number(area));
      const shelfLabels = labels.filter(l => l.ShelfCode === code);
      const uniqueLayers = [...new Set(areaCells.map(c => c.Layer))].sort((a,b) => a-b);
      const cols = Math.max(...areaCells.map(c => c.Colu), 0);
      shelves[code] = {
        code,
        area: Number(area),
        totalCells: areaCells.length,
        occupiedCells: areaCells.filter(c => c.Used === 3).length,
        labelCount: shelfLabels.length,
        layers: uniqueLayers.length,
        cols,
      };
    }
    res.json({ data: { shelves: Object.values(shelves), totalShelves: Object.keys(shelves).length } });
  } catch (err) {
    console.error("GET /api/wms/shelf/status:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/wms/shelf/list — list all shelves with SmartRack summary (PDA dashboard)
api.get("/wms/shelf/list", async (req, res) => {
  try {
    if (!isShelfBackendReachable()) {
      const shelves = SHELF_CODES.map(code => {
        const state = mockShelfState[code];
        const totalCells = 24;
        const occupied = state.labels.length;
        return {
          shelfCode: code,
          totalCells,
          emptyCount: totalCells - occupied,
          occupiedCount: occupied,
          reservedCount: 0,
          faultCount: 0,
          connectionStatus: "mock",
        };
      });
      const totalOccupied = shelves.reduce((s, sh) => s + sh.occupiedCount, 0);
      const totalEmpty = shelves.reduce((s, sh) => s + sh.emptyCount, 0);
      return res.json({
        success: true,
        data: {
          shelves,
          summary: { totalRacks: 6, onlineRacks: 6, totalOccupiedCells: totalOccupied, totalEmptyCells: totalEmpty, todayTransactions: 0 },
        },
      });
    }
    const AREA_MAP = { 1:"L001A", 2:"L001B", 3:"L002A", 4:"L002B", 5:"L003A", 6:"L003B" };
    const cells = await sqlQuery(`
      SELECT Area, Layer, Colu, Point, SerialNumber, Used, UsedCode, MaterialCode, Qty
      FROM Sys_CellsInfo ORDER BY Area, Layer, Colu, Point
    `);
    const shelves = {};
    for (const [area, shelfCode] of Object.entries(AREA_MAP)) {
      const areaCells = cells.filter(c => c.Area === Number(area));
      const occupied = areaCells.filter(c => c.Used === 3);
      shelves[shelfCode] = {
        shelfCode,
        totalCells: areaCells.length,
        emptyCount: areaCells.length - occupied.length,
        occupiedCount: occupied.length,
        reservedCount: 0,
        faultCount: 0,
        connectionStatus: occupied.length > 0 ? "online" : "offline",
      };
    }
    const summary = {
      totalRacks: Object.keys(shelves).length,
      onlineRacks: Object.values(shelves).filter(s => s.connectionStatus === "online").length,
      totalOccupiedCells: Object.values(shelves).reduce((sum, s) => sum + s.occupiedCount, 0),
      totalEmptyCells: Object.values(shelves).reduce((sum, s) => sum + s.emptyCount, 0),
      todayTransactions: 0,
    };
    res.json({ success: true, data: { shelves: Object.values(shelves), summary } });
  } catch (err) {
    console.error("GET /api/wms/shelf/list:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/wms/shelf/:shelfCode — cells for a specific shelf (PDA rack detail)
api.get("/wms/shelf/:shelfCode", async (req, res) => {
  try {
    const { shelfCode } = req.params;
    const areaMap = { L001A:1, L001B:2, L002A:3, L002B:4, L003A:5, L003B:6 };
    const area = areaMap[shelfCode.toUpperCase()];
    if (!area) {
      return res.status(400).json({ success: false, error: `Invalid shelfCode: ${shelfCode}` });
    }
    if (!isShelfBackendReachable()) {
      const state = mockShelfState[shelfCode.toUpperCase()];
      const totalCells = 24;
      const cells = Array.from({ length: totalCells }, (_, i) => {
        const label = state.labels[i % Math.max(state.labels.length, 1)];
        const cellNum = i + 1;
        return {
          shelfCode: shelfCode.toUpperCase(),
          cellNumber: String(cellNum),
          cellLabel: `${shelfCode.toUpperCase()}-${String(cellNum).padStart(2, "0")}`,
          materialCode: label?.materialCode,
          lotNo: label?.lotNo,
          labelId: label?.labelId,
          cellStatus: label ? "occupied" : "empty",
          qty: label?.qty ?? 0,
        };
      });
      return res.json({
        success: true,
        data: {
          shelf: { shelfCode: shelfCode.toUpperCase(), totalCells, emptyCount: totalCells - state.labels.length, occupiedCount: state.labels.length, reservedCount: 0, faultCount: 0, connectionStatus: "mock" },
          cells,
        },
      });
    }
    const rows = await sqlQuery(`
      SELECT Area, Layer, Colu, Point, SerialNumber, Used, UsedCode, MaterialCode, Qty
      FROM Sys_CellsInfo WHERE Area = @p1 ORDER BY Layer, Colu, Point
    `, [area]);
    const occupied = rows.filter(r => r.Used === 3);
    const shelf = {
      shelfCode,
      totalCells: rows.length,
      emptyCount: rows.length - occupied.length,
      occupiedCount: occupied.length,
      reservedCount: 0,
      faultCount: 0,
      connectionStatus: occupied.length > 0 ? "online" : "offline",
    };
    let cellNum = 1;
    const cells = rows.map(r => ({
      shelfCode,
      cellNumber: String(cellNum++),
      cellLabel: `${shelfCode}-${String(cellNum - 1).padStart(2, "0")}`,
      materialCode: r.Used === 3 ? (r.UsedCode || r.MaterialCode) : undefined,
      lotNo: r.Used === 3 ? r.UsedCode : undefined,
      labelId: r.Used === 3 ? r.SerialNumber : undefined,
      cellStatus: r.Used === 3 ? "occupied" : "empty",
      qty: r.Qty || 0,
    }));
    res.json({ success: true, data: { shelf, cells } });
  } catch (err) {
    console.error("GET /api/wms/shelf/:shelfCode:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

