// POST /api/rework/local-ng — persist a routed NG in the repair station SQLite
api.post("/rework/local-ng", async (req, res) => {
  const { sn, sourceStation, batchId, slot, defectCode, defectReason } = req.body?.payload ?? req.body ?? {};
  if (!sn) return res.status(400).json(errorEnvelope("VALIDATION", "sn required"));

  const repairDataDir = path.resolve(
    __dirname,
    "../../../瑞晶越南工位-正式命名/005-回修站质量工位/data",
  );
  const repairDbPath = path.join(repairDataDir, "rework.db");
  try {
    fs.mkdirSync(repairDataDir, { recursive: true });
    const sqlite3 = require("sqlite3").verbose();
    const db = new sqlite3.Database(repairDbPath);
    await new Promise((resolve, reject) => {
      db.serialize(() => {
        db.run(`CREATE TABLE IF NOT EXISTS incoming_ng (
          sn TEXT PRIMARY KEY,
          source_station TEXT NOT NULL,
          batch_id TEXT,
          slot INTEGER,
          defect_code TEXT,
          defect_reason TEXT,
          status TEXT NOT NULL DEFAULT 'waiting_repair',
          received_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
)`);
        db.run(`CREATE TABLE IF NOT EXISTS motherboards (
          batch_id TEXT PRIMARY KEY, source_station TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'waiting_repair', received_at TEXT NOT NULL, updated_at TEXT NOT NULL
        )`);
        db.run(`CREATE TABLE IF NOT EXISTS motherboard_members (
          id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id TEXT NOT NULL, sn TEXT NOT NULL,
          slot INTEGER, incoming_result TEXT NOT NULL DEFAULT 'NG', defect_code TEXT,
          repair_status TEXT NOT NULL DEFAULT 'waiting', updated_at TEXT NOT NULL,
          UNIQUE(batch_id, sn)
        )`);
        db.run(`CREATE TABLE IF NOT EXISTS repair_records (
          id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id TEXT, sn TEXT NOT NULL,
          action TEXT NOT NULL, result TEXT, defect_code TEXT, repair_method TEXT,
          operator TEXT, started_at TEXT NOT NULL, completed_at TEXT, mes_synced INTEGER NOT NULL DEFAULT 0
        )`);
        db.run(`CREATE TABLE IF NOT EXISTS ng_migrations (
          id INTEGER PRIMARY KEY AUTOINCREMENT, migration_key TEXT NOT NULL UNIQUE,
          batch_id TEXT, sn TEXT NOT NULL, slot INTEGER, source_station TEXT NOT NULL,
          destination_station TEXT NOT NULL, defect_code TEXT, status TEXT NOT NULL DEFAULT 'received',
          migrated_at TEXT NOT NULL, completed_at TEXT, mes_synced INTEGER NOT NULL DEFAULT 0
        )`);
        db.run(`CREATE TABLE IF NOT EXISTS motherboard_migration_state (
          batch_id TEXT PRIMARY KEY, source_station TEXT NOT NULL, destination_station TEXT NOT NULL,
          member_count INTEGER NOT NULL DEFAULT 0, ng_count INTEGER NOT NULL DEFAULT 0,
          status TEXT NOT NULL DEFAULT 'received', migrated_at TEXT NOT NULL, updated_at TEXT NOT NULL
        )`);
        if (batchId) {
          const nowIso = new Date().toISOString();
          db.run(`INSERT INTO motherboards(batch_id,source_station,status,received_at,updated_at)
            VALUES(?,?,'waiting_repair',?,?) ON CONFLICT(batch_id) DO UPDATE SET
            source_station=excluded.source_station,status='waiting_repair',updated_at=excluded.updated_at`,
            [batchId, sourceStation ?? 'unknown', nowIso, nowIso]);
          db.run(`INSERT INTO motherboard_members(batch_id,sn,slot,incoming_result,defect_code,repair_status,updated_at)
            VALUES(?,?,?,'NG',?,'waiting',?) ON CONFLICT(batch_id,sn) DO UPDATE SET
            slot=excluded.slot,defect_code=excluded.defect_code,repair_status='waiting',updated_at=excluded.updated_at`,
            [batchId, sn, slot ?? null, defectCode ?? 'NG', nowIso]);
          db.run(`INSERT INTO ng_migrations
            (migration_key,batch_id,sn,slot,source_station,destination_station,defect_code,status,migrated_at)
            VALUES(?,?,?,?,?,'manu_rework',?,'received',?) ON CONFLICT(migration_key) DO UPDATE SET
            status='received',defect_code=excluded.defect_code,migrated_at=excluded.migrated_at`,
            [`${batchId}:${sn}:manu_rework`, batchId, sn, slot ?? null, sourceStation ?? 'unknown', defectCode ?? 'NG', nowIso]);
          db.run(`INSERT INTO motherboard_migration_state
            (batch_id,source_station,destination_station,member_count,ng_count,status,migrated_at,updated_at)
            VALUES(?,?,'manu_rework',1,1,'received',?,?) ON CONFLICT(batch_id) DO UPDATE SET
            source_station=excluded.source_station,destination_station='manu_rework',
            member_count=(SELECT COUNT(*) FROM motherboard_members WHERE batch_id=excluded.batch_id),
            ng_count=(SELECT COUNT(*) FROM motherboard_members WHERE batch_id=excluded.batch_id AND incoming_result='NG'),
            status='received',updated_at=excluded.updated_at`,
            [batchId, sourceStation ?? 'unknown', nowIso, nowIso]);
        }
        db.run(
          `INSERT INTO incoming_ng
             (sn, source_station, batch_id, slot, defect_code, defect_reason, status, received_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, 'waiting_repair', ?, ?)
           ON CONFLICT(sn) DO UPDATE SET
             source_station=excluded.source_station,
             batch_id=excluded.batch_id,
             slot=excluded.slot,
             defect_code=excluded.defect_code,
             defect_reason=excluded.defect_reason,
             status='waiting_repair',
             updated_at=excluded.updated_at`,
          [sn, sourceStation ?? "manu_ict", batchId ?? null, slot ?? null, defectCode ?? "ICT_FAIL", defectReason ?? null, Date.now(), Date.now()],
          function (err) {
            if (err) reject(err);
            else resolve(this.changes);
          },
        );
      });
      db.close();
    });
    res.status(201).json(mutateEnvelope({ sn, dbPath: repairDbPath, status: "waiting_repair" }));
  } catch (err) {
    console.error("POST /rework/local-ng:", err.message);
    res.status(500).json(errorEnvelope("LOCAL_SQLITE_ERROR", err.message));
  }
});

// POST /api/rework/upload — 上报考修记录
api.post("/rework/upload", async (req, res) => {
  try {
    const { sn, sourceStation, sourceLine, routeTo, defectCode, defectReason, materialCode, repairCount, operator } = req.body?.payload ?? req.body ?? {};
    if (!sn) return res.status(400).json(errorEnvelope("VALIDATION", "sn required"));

    // 检查是否已修复（防止重复上报）
    const existing = (await query(
      `SELECT id, result FROM rework.rework_records WHERE sn = $1 AND result = 'repaired' ORDER BY created_at DESC LIMIT 1`,
      [sn]
    )).rows[0];
    if (existing) {
      return res.status(409).json(errorEnvelope("ALREADY_REPAIRED", `SN ${sn} 已修复，rework record id=${existing.id}`));
    }

    const r = await query(
      `INSERT INTO rework.rework_records
       (sn, source_station, source_line, route_to, defect_code, defect_reason, material_code, repair_count, result, operator, repaired_at)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'open',$9,NULL)
       RETURNING id`,
      [sn, sourceStation ?? null, sourceLine ?? null, routeTo ?? null, defectCode ?? null, defectReason ?? null, materialCode ?? null, repairCount ?? 1, operator ?? null],
    );
    res.status(201).json(mutateEnvelope({ reworkRecordId: r.rows[0]?.id }));
  } catch (err) {
    console.error("POST /rework/upload:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /api/rework/clear-ng — 修复成功后清除 ng_pool + 标记 repair_status
api.post("/rework/clear-ng", async (req, res) => {
  try {
    const { sn, repairResult, operator, batchId, originStation, defectCode, returnStation } = req.body?.payload ?? req.body ?? {};
    if (!sn) return res.status(400).json(errorEnvelope("VALIDATION", "sn required"));

    const normalizedResult = repairResult === "pass" ? "repaired" : "scrapped";

    if (normalizedResult === "repaired") {
      await ngRevivalAuditColumnsReady;
      const approved = await query(`SELECT revival_id,batch_id,origin_station,return_station FROM ng_revival_audit
        WHERE sn=$1 AND approval_status='APPROVED' ORDER BY approved_at DESC LIMIT 1`, [sn]);
      if (!approved.rows.length) {
        const pending = await query(`INSERT INTO ng_revival_audit
          (sn,batch_id,origin_station,defect_code,repair_result,return_station,operator_name,approval_status,revived_at)
          VALUES ($1,$2,$3,$4,$5,$6,$7,'PENDING_QUALITY',NOW()) RETURNING revival_id AS "revivalId"`,
          [sn, batchId ?? null, originStation ?? null, defectCode ?? null,
           normalizedResult, returnStation ?? null, operator ?? null]);
        return res.status(202).json({ ok: true, approvalRequired: true,
          revivalId: pending.rows[0]?.revivalId, sn, status: "PENDING_QUALITY" });
      }
    }

    // 1. 更新 rework_records 结果
    await query(
      `UPDATE rework.rework_records SET result = $1, repaired_at = now(), operator = $2, updated_at = now()
       WHERE ctid = (SELECT ctid FROM rework.rework_records
         WHERE sn = $3 AND result = 'open' ORDER BY created_at DESC LIMIT 1)`,
      [normalizedResult, operator ?? null, sn],
    );

    // 2. 清除 mes.ng_pool 中该 SN（清除NG标记）
    // A repaired NG stays active until its origin station confirms physical receipt by scanner.

    // 3. 更新 ng_defect_records repair_status
    if (normalizedResult !== "repaired") await query(
      `UPDATE ng_defect_records SET repair_status = $1, updated_at = now()
       WHERE sn = $2 AND (repair_status = 'pending' OR repair_status IS NULL)`,
      [normalizedResult, sn],
    );

    // 4. Immutable NG revival audit: repaired NG must never disappear without history.
    await ngRevivalAuditColumnsReady;
    await query(`UPDATE ng_revival_audit SET approval_status='RETURN_PENDING'
      WHERE revival_id=(SELECT revival_id FROM ng_revival_audit WHERE sn=$1 AND approval_status='APPROVED'
        ORDER BY approved_at DESC LIMIT 1)`, [sn]);

    if (normalizedResult === "repaired") {
      // Approval + repair only creates a return order. NG release waits for the origin receipt scan.
      const revival=await query(`SELECT revival_id,batch_id,origin_station,return_station FROM ng_revival_audit
        WHERE sn=$1 AND approval_status='RETURN_PENDING' ORDER BY approved_at DESC LIMIT 1`,[sn]);
      const revivalRow=revival.rows[0]||{};
      const returnBatchId=String(batchId||revivalRow.batch_id||sn);
      let destinationStation=String(returnStation||revivalRow.return_station||originStation||revivalRow.origin_station||"").trim();
      let motherboard={batchId:returnBatchId,subBoards:[{sn,result:"PASS",revived:true}]};
      const incoming=await query(`SELECT source_station,motherboard FROM station_route_requests
        WHERE batch_id=$1 AND destination_station='manu_rework'
        ORDER BY submitted_at DESC LIMIT 1`,[returnBatchId]);
      if(incoming.rows.length){
        destinationStation=destinationStation||String(incoming.rows[0].source_station||"");
        if(incoming.rows[0].motherboard?.subBoards?.length) motherboard=incoming.rows[0].motherboard;
      }
      if(!destinationStation) return res.status(409).json(errorEnvelope("RETURN_STATION_REQUIRED",
        "revived NG must return to its origin station; origin station is missing"));
      await query(`UPDATE station_route_requests SET status='COMPLETED',completed_at=NOW(),notification_status='REPAIR_COMPLETED'
        WHERE batch_id=$1 AND destination_station='manu_rework' AND status='REPAIR_IN_PROGRESS'`,[returnBatchId]);
      const members=Array.isArray(motherboard.subBoards)?motherboard.subBoards:[];
      await stationHandoverReady;
      await query(`INSERT INTO station_handover_transfers
        (batch_id,source_station,destination_station,destination_type,motherboard,member_count,status,sent_at,received_at,accepted_by,alarmed_at)
        VALUES($1,'manu_rework',$2,'REPAIR_RETURN',$3,$4,'WAITING_RECEIPT',NOW(),NULL,NULL,NULL)
        ON CONFLICT(batch_id,source_station,destination_station) DO UPDATE SET
          destination_type='REPAIR_RETURN',motherboard=EXCLUDED.motherboard,member_count=EXCLUDED.member_count,
          status='WAITING_RECEIPT',sent_at=NOW(),received_at=NULL,accepted_by=NULL,alarmed_at=NULL`,
        [returnBatchId,destinationStation,JSON.stringify(motherboard),members.length]);
      await stationRouteRequestReady;
      await query(`INSERT INTO station_route_requests
        (batch_id,source_station,destination_code,destination_station,workflow_code,motherboard,status,
         submitted_by,processed_at,notification_status,detail)
        VALUES($1,'manu_rework','RETURN_TO_ORIGIN',$2,'MES_REPAIR_RETURN',$3,'WAITING_RECEIPT',$4,NOW(),'SENT',$5)`,
        [returnBatchId,destinationStation,JSON.stringify(motherboard),operator||'manu_rework',
         JSON.stringify({sn,revivalId:revivalRow.revival_id,reason:'APPROVED_NG_REVIVAL_RETURN'})]);
      await commitStationBucket('manu_rework','process',[{stage:'REPAIR_RETURN_WAITING_RECEIPT',batchId:returnBatchId,
        destinationStationCode:destinationStation,memberCount:members.length,updatedAt:Date.now()}]);
      await commitStationBucket(destinationStation,'process',[{stage:'REPAIR_RETURN_INCOMING',batchId:returnBatchId,
        sourceStationCode:'manu_rework',memberCount:members.length,updatedAt:Date.now()}]);
      neuralBroadcast({from:'mes_server',to:'*',type:'REPAIR_RETURN_WAITING_RECEIPT',priority:'critical',
        stationCode:'manu_rework',payload:{batchId:returnBatchId,sourceStationCode:'manu_rework',
          destinationStationCode:destinationStation,memberCount:members.length,timeoutSeconds:120}});
    }

    // Record SN journey: repair completed
    await recordSnJourney({
      sn, batchId, workOrderCode: batchId, eventType: normalizedResult === 'repaired' ? 'NG_REPAIRED' : 'NG_SCRAPPED',
      eventStage: 'REPAIR', stationCode: 'manu_rework', stationName: '维修站',
      result: normalizedResult === 'repaired' ? 'REPAIRED' : 'SCRAPPED',
      defectCode, defectDescription: null, operator, actor: null,
      detail: { repairResult: normalizedResult, originStation, returnStation }
    });

    // 5. SSE广播维修闭环事件
    neuralBroadcast({
      from: 'mes_server', to: '*', type: normalizedResult === 'repaired' ? 'REPAIR_TEST_COMPLETED' : 'REPAIR_SCRAPPED',
      priority: 'critical', stationCode: 'manu_rework',
      payload: { sn, repairResult: normalizedResult, operator, batchId, originStation, defectCode, returnStation }
    });

    res.json(mutateEnvelope({ sn, result: normalizedResult }));
  } catch (err) {
    console.error("POST /rework/clear-ng:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

api.get("/rework/revival-board", async (_req, res) => {
  try {
    await ngRevivalAuditColumnsReady;
    const result = await query(`SELECT revival_id AS "revivalId",sn,batch_id AS "batchId",
      origin_station AS "originStation",defect_code AS "defectCode",repair_result AS "repairResult",
      return_station AS "returnStation",operator_name AS operator,approval_status AS "approvalStatus",
      approver,approval_reason AS "approvalReason",approved_at AS "approvedAt",
      quality_approver AS "qualityApprover",quality_approved_at AS "qualityApprovedAt",
      line_leader_approver AS "lineLeaderApprover",line_leader_approved_at AS "lineLeaderApprovedAt",
      revived_at AS "revivedAt"
      FROM ng_revival_audit ORDER BY revived_at DESC LIMIT 500`);
    res.json({ ok: true, items: result.rows });
  } catch (err) {
    res.status(500).json(errorEnvelope("REVIVAL_BOARD_FAILED", err.message));
  }
});

api.post("/rework/revival-board/:id/approve", async (req, res) => {
  try {
    const approver = String(req.body?.approver || "").trim();
    const reason = String(req.body?.reason || "").trim();
    const role = String(req.body?.role || "").trim().toUpperCase();
    if (!approver || !reason || !["QUALITY", "LINE_LEADER"].includes(role))
      return res.status(400).json(errorEnvelope("VALIDATION", "role, approver and reason required"));
    await ngRevivalAuditColumnsReady;
    const result = role === "QUALITY"
      ? await query(`UPDATE ng_revival_audit SET approval_status='PENDING_LINE_LEADER',quality_approver=$2,
          quality_approved_at=NOW(),approval_reason=$3 WHERE revival_id=$1 AND approval_status='PENDING_QUALITY'
          RETURNING revival_id AS "revivalId",sn`, [req.params.id, approver, reason])
      : await query(`UPDATE ng_revival_audit SET approval_status='APPROVED',line_leader_approver=$2,
          line_leader_approved_at=NOW(),approver=$2,approved_at=NOW(),approval_reason=$3
          WHERE revival_id=$1 AND approval_status='PENDING_LINE_LEADER'
          RETURNING revival_id AS "revivalId",sn`, [req.params.id, approver, reason]);
    if (!result.rows.length) return res.status(409).json(errorEnvelope("INVALID_STATE", "request is not pending"));
    res.json({ ok: true, ...result.rows[0], status: role === "QUALITY" ? "PENDING_LINE_LEADER" : "APPROVED" });
  } catch (err) {
    res.status(500).json(errorEnvelope("REVIVAL_APPROVAL_FAILED", err.message));
  }
});

// GET /mes/rework/dashboard — 回修站实时监控（L005）
api.get("/mes/rework/dashboard", async (req, res) => {
  try {
    const line = (await query(
      `SELECT id, internal_code AS code, name_zh, name_en, name_vi, status
       FROM production_lines WHERE internal_code = 'L005' LIMIT 1`
    )).rows[0];
    if (!line) return res.status(404).json(errorEnvelope("NOT_FOUND", "Rework line not found"));

    // 今日返修统计
    const todayStats = (await query(`
      SELECT
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE result = 'repaired') AS repaired,
        COUNT(*) FILTER (WHERE result = 'scrapped') AS scrapped,
        COUNT(*) FILTER (WHERE result = 'open') AS in_progress
      FROM rework.rework_records
      WHERE created_at > NOW() - INTERVAL '1 day'
    `)).rows[0];

    // 待处理（open）
    const openRecords = (await query(`
      SELECT id, sn, source_station, source_line, defect_code, defect_reason,
             repair_count, result, operator, created_at
      FROM rework.rework_records
      WHERE result = 'open'
      ORDER BY created_at DESC
      LIMIT 50
    `)).rows;

    // 最近完成的10条
    const recentRecords = (await query(`
      SELECT id, sn, source_station, source_line, defect_code, repair_count,
             result, operator, repaired_at, created_at
      FROM rework.rework_records
      WHERE result IN ('repaired', 'scrapped')
      ORDER BY repaired_at DESC
      LIMIT 10
    `)).rows;

    // L005 回修站状态（REWORK-01）
    const stationStats = (await query(`
      SELECT s.id, s.code, s.name_zh, s.name_en, s.name_vi, s.status,
             COUNT(se.id) FILTER (WHERE se.occurred_at > NOW() - INTERVAL '1 day') AS today_events
      FROM stations s
      LEFT JOIN station_events se ON se.station_id = s.id
      WHERE s.line_id = $1
      GROUP BY s.id, s.code, s.name_zh, s.name_en, s.name_vi, s.status
    `, [line.id])).rows;

    res.json(envelope({
      line: {
        id: line.id,
        code: line.code,
        nameZh: line.name_zh,
        nameEn: line.name_en,
        nameVi: line.name_vi,
        status: line.status,
      },
      todayStats: {
        total: parseInt(todayStats?.total ?? 0),
        repaired: parseInt(todayStats?.repaired ?? 0),
        scrapped: parseInt(todayStats?.scrapped ?? 0),
        inProgress: parseInt(todayStats?.in_progress ?? 0),
      },
      openRecords: openRecords.map(r => ({
        id: r.id,
        sn: r.sn,
        sourceStation: r.source_station,
        sourceLine: r.source_line,
        defectCode: r.defect_code,
        defectReason: r.defect_reason,
        repairCount: r.repair_count,
        operator: r.operator,
        createdAt: r.created_at,
      })),
      recentRecords: recentRecords.map(r => ({
        id: r.id,
        sn: r.sn,
        sourceStation: r.source_station,
        sourceLine: r.source_line,
        defectCode: r.defect_code,
        repairCount: r.repair_count,
        result: r.result,
        operator: r.operator,
        repairedAt: r.repaired_at,
        createdAt: r.created_at,
      })),
      stations: stationStats.map(s => ({
        id: s.id,
        code: s.code,
        nameZh: s.name_zh,
        nameEn: s.name_en,
        nameVi: s.name_vi,
        status: s.status,
        todayEvents: parseInt(s.today_events ?? 0),
      })),
    }));
  } catch (err) {
    console.error("GET /mes/rework/dashboard:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/mes/manu-line/dashboard — route defined in src/routes/manu-line.js

// GET /api/mes/ng-check — 查询某个 SN 在指定工站是否有 NG 记录（分板站拦截 ICT/FCT NG）
// Only blocks pending/scrapped NG — repaired boards pass through
api.get("/mes/ng-check", async (req, res) => {
  try {
    const { sn, stations } = req.query;
    if (!sn) return res.status(400).json(errorEnvelope("MISSING_SN", "Parameter 'sn' is required"));
    const stationList = stations ? stations.split(",").map(s => s.trim()).filter(Boolean)
      : ['manu_ict', 'manu_fct', 'manu_depanel', 'manu_assem_ate', 'manu_supersonic',
         'manu_agingcab', 'manu_hivolt_ate', 'manu_package_ate', 'manu_shellbinding'];
    const [ngR, eventR] = await Promise.all([
      query(`
        SELECT station_code, sn, result, channel, error_code, repair_status,
               to_char(created_at, 'YYYY-MM-DD HH24:MI:SS') as occurred_at
        FROM ng_defect_records
        WHERE UPPER(sn) = UPPER($1)
          AND station_code = ANY($2::text[])
          AND COALESCE(repair_status, 'pending') IN ('pending', 'scrapped')
        ORDER BY created_at DESC
      `, [sn, stationList]),
      query(`
        SELECT station_code, event_type, received_at, payload
        FROM station_production_events
        WHERE station_code = ANY($2::text[])
          AND event_type IN ('FCT_PROCESS','NG_DEFECT','STATION_TEST_RESULT','ICT_PROCESS')
          AND payload::text ILIKE '%' || $1 || '%'
        ORDER BY received_at DESC LIMIT 500
      `, [sn, stationList]),
    ]);
    const eventNg = [];
    for (const row of eventR.rows) {
      const payload = row.payload && typeof row.payload === 'object' ? row.payload : {};
      const boards = Array.isArray(payload.subBoards) ? payload.subBoards : [];
      for (const board of boards) {
        if (String(board.sn || '').trim().toUpperCase() !== String(sn).trim().toUpperCase()) continue;
        const result = String(board.result || board.finalResult || '').trim().toUpperCase();
        const confirmed = board.isConfirmedNG === true || ['NG','FAIL','FAILED','NOK'].includes(result);
        if (!confirmed) continue;
        eventNg.push({
          station_code: row.station_code, sn, result: 'fail',
          error_code: board.errorCode || board.defectCode || '',
          repair_status: 'pending', source: 'MOTHERBOARD_EVENT',
          motherboard_sn: payload.mainSn || payload.pcbSerial || payload.motherboardId || '',
          event_type: row.event_type, occurred_at: row.received_at,
        });
      }
    }
    const records = [...ngR.rows, ...eventNg];
    res.json({ found: records.length > 0, sn, records });
  } catch (err) {
    console.error("GET /api/mes/ng-check:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// ── Public station status (display-board topology page) ─────────────────────
// No JWT required. Queries station_heartbeats / station_events / ng_defect_records.
// If tables/columns are missing, returns static fallback so display board renders.
api.get("/mes/andon-board", async (req, res) => {
  const { line = 'MANUAL-LINE' } = req.query;
  const stationOrder = [
    'manu_pda','manu_aio','wave_solder','manu_ict','manu_fct',
    'manu_depanel','manu_shellbinding','manu_assem_ate','manu_supersonic',
    'manu_agingcab','manu_hivolt_ate','manu_package_ate',
    'manu_case_binding','manu_pallet_binding','manu_rework'
  ];

  let heartbeatMap = {};
  let ngMap = {};
  let lastEventMap = {};

  try {
    const heartR = await query(`
      SELECT station_code, MAX(last_seen) as last_heartbeat
      FROM station_heartbeats
      WHERE last_seen > NOW() - INTERVAL '5 minutes'
      GROUP BY station_code
    `);
    for (const r of heartR.rows) heartbeatMap[r.station_code] = r.last_heartbeat;
  } catch (e) {
    console.warn("/api/mes/andon-board heartbeat:", e.message);
  }

  try {
    const ngR = await query(`
      SELECT station_code, COUNT(*)::int as ng_count
      FROM ng_defect_records
      WHERE created_at > NOW() - INTERVAL '2 hours'
        AND result IN ('fail', 'ng', 'rework')
      GROUP BY station_code
    `);
    for (const r of ngR.rows) ngMap[r.station_code] = r.ng_count;
  } catch (e) {
    console.warn("/api/mes/andon-board ng_defect:", e.message);
  }

  try {
    const lastEventR = await query(`
      SELECT station_code, MAX(occurred_at) as last_event
      FROM station_events
      WHERE occurred_at > NOW() - INTERVAL '5 minutes'
      GROUP BY station_code
    `);
    for (const r of lastEventR.rows) lastEventMap[r.station_code] = r.last_event;
  } catch (e) {
    console.warn("/api/mes/andon-board station_events:", e.message);
  }

  const stations = stationOrder.map((code, idx) => {
    const lastHb = heartbeatMap[code];
    const ngCount = ngMap[code] ?? 0;
    const lastEvent = lastEventMap[code];
    const now = new Date();

    let status = 'offline';
    if (lastHb) {
      const elapsed = (now - new Date(lastHb)) / 1000;
      if (elapsed < 30) status = 'running';
      else if (elapsed < 120) status = 'idle';
      else if (elapsed < 600) status = 'stale';
    }

    return {
      stationCode: code,
      sequenceOrder: idx + 1,
      status,
      ngCount,
      isOnline: !!lastHb,
      lastEvent: lastEvent || null,
    };
  });

  const totalNG = stations.reduce((s, st) => s + st.ngCount, 0);
  const runningCount = stations.filter(st => st.status === 'running').length;
  const lineStatus = totalNG > 0 ? 'ng' : runningCount > 0 ? 'running' : 'idle';

  res.json({
    line,
    lineStatus,
    totalNG,
    stations,
    lineNameZh: line === 'MANUAL-LINE' ? '手动线' : line,
    updatedAt: new Date().toISOString(),
  });
});

// ── JWT Authentication (applied to all routes below) ──────────────────
// Mirrors formulas from 仓库电子元器件寿命管参考 Excel:
//   到期日期(I) = 生产日期(F) + 封存有效期月(H)
//   已使用时间(J) = DATEDIF(F, TODAY(), "m")
//   剩余寿命(K) = H - J
//   剩余天数(L) = I - TODAY()

// GET /api/lifecycle/summary — aggregate counts by alert level
api.get("/lifecycle/summary", async (req, res) => {
  try {
    const { alert } = req.query;
    // Compute remaining_days per lot from view, then count by level
    const today = new Date().toISOString().slice(0, 10);
    let whereClause = "";
    if (alert === "EXPIRED")        whereClause = `WHERE remaining_days <= 0`;
    else if (alert === "RED_L3")    whereClause = `WHERE remaining_days BETWEEN 1 AND 30`;
    else if (alert === "BLUE_L2")   whereClause = `WHERE remaining_days BETWEEN 31 AND 90`;
    else if (alert === "YELLOW_L1") whereClause = `WHERE remaining_days BETWEEN 91 AND 180`;
    else if (alert === "NORMAL")     whereClause = `WHERE remaining_days > 180`;

    // Derive alert level from remaining_days in SQL (avoids JavaScript date drift)
    const rows = await pgPool.query(`
      SELECT
        COUNT(*) FILTER (WHERE remaining_days <= 0)                            AS expired,
        COUNT(*) FILTER (WHERE remaining_days BETWEEN 1 AND 30)                AS red_l3,
        COUNT(*) FILTER (WHERE remaining_days BETWEEN 31 AND 90)               AS blue_l2,
        COUNT(*) FILTER (WHERE remaining_days BETWEEN 91 AND 180)              AS yellow_l1,
        COUNT(*) FILTER (WHERE remaining_days > 180 OR remaining_days IS NULL) AS normal,
        COUNT(*)::int AS total
      FROM v_material_lifecycle
    `);
    res.json({ success: true, data: rows.rows[0] });
  } catch (err) {
    console.error("GET /api/lifecycle/summary:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/lifecycle/lots — all lots with computed lifecycle fields
// Query params: alert (EXPIRED|RED_L3|BLUE_L2|YELLOW_L1|NORMAL), materialType, supplier, limit, offset
api.get("/lifecycle/lots", async (req, res) => {
  try {
    const { alert, materialType, supplier, lotNo, limit = 100, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;

    if (alert === "EXPIRED")        { conditions.push(`remaining_days <= 0`); }
    else if (alert === "RED_L3")    { conditions.push(`remaining_days BETWEEN 1 AND 30`); }
    else if (alert === "BLUE_L2")   { conditions.push(`remaining_days BETWEEN 31 AND 90`); }
    else if (alert === "YELLOW_L1") { conditions.push(`remaining_days BETWEEN 91 AND 180`); }
    else if (alert === "NORMAL")    { conditions.push(`remaining_days > 180`); }

    if (materialType) { conditions.push(`m.material_type = $${idx++}`); params.push(materialType); }
    if (supplier)     { conditions.push(`s.name_zh LIKE $${idx++}`); params.push(`%${supplier}%`); }
    if (lotNo)        { conditions.push(`ml.lot_no ILIKE $${idx++}`); params.push(`%${lotNo}%`); }

    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const data = await pgPool.query(`
      SELECT
        ml.id,
        ml.lot_no                                  AS "lotNo",
        m.code                                     AS "materialCode",
        m.name_zh                                  AS "materialNameZh",
        m.name_en                                  AS "materialNameEn",
        m.name_vi                                  AS "materialNameVi",
        m.material_type                            AS "materialType",
        m.uom,
        ml.manufacturing_date                      AS "manufacturingDate",
        ml.received_at                             AS "receivedAt",
        FLOOR(m.shelf_life_days / 30.44)::int      AS "shelfLifeMonths",
        (ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date
                                                   AS "expiryDate",
        ml.iqc_status                              AS "iqcStatus",
        COALESCE(ml.received_qty, 0)                        AS qty,
        COALESCE(ml.reserved_qty, 0)               AS "reservedQty",
        sl.code                                    AS "locationCode",
        s.name_zh                                  AS "supplierName",
        -- Remaining days (may be negative = overdue)
        (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE)::int
                                                   AS "remainingDays",
        -- Alert level derived in SQL
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0
            THEN 'EXPIRED'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30
            THEN 'RED_L3'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 90
            THEN 'BLUE_L2'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 180
            THEN 'YELLOW_L1'
          ELSE 'NORMAL'
        END                                        AS "alertLevel",
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0
            THEN '超期隔离'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30
            THEN '三级预警(红)'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 90
            THEN '二级预警(蓝)'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 180
            THEN '一级预警(黄)'
          ELSE '正常在用'
        END                                        AS "statusLabel"
      FROM material_lots ml
      JOIN materials m ON m.id = ml.material_id
      LEFT JOIN storage_locations sl ON sl.id = ml.storage_location_id
      LEFT JOIN suppliers s ON s.id = ml.supplier_id
      ${where}
      ORDER BY
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0
            THEN 0
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30
            THEN 1
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 90
            THEN 2
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 180
            THEN 3
          ELSE 4
        END,
        (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) ASC
      LIMIT $${idx} OFFSET $${idx + 1}
    `, [...params, Number(limit), Number(offset)]);
    res.json({ success: true, data: data.rows });
  } catch (err) {
    console.error("GET /api/lifecycle/lots:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/lifecycle/export — 物料有效期管控台账 Excel，带公式
// Mirrors Sheet1 of 仓库电子元器件寿命管参考:
//   J列(已使用月) = DATEDIF(F列, TODAY(), "m")
//   K列(剩余寿命月) = H列 - J列
//   L列(剩余天数) = I列 - TODAY()
//   M列(预警) = IF(L<=0,"超期",IF(L<=30,"三级预警(红)",IF(L<=90,"二级预警(蓝)",IF(L<=180,"一级预警(黄)","正常"))))
api.get("/lifecycle/export", async (req, res) => {
  try {
    const { alert, materialType, supplier, lotNo } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;

    if (alert === "EXPIRED")        { conditions.push(`remaining_days <= 0`); }
    else if (alert === "RED_L3")    { conditions.push(`remaining_days BETWEEN 1 AND 30`); }
    else if (alert === "BLUE_L2")   { conditions.push(`remaining_days BETWEEN 31 AND 90`); }
    else if (alert === "YELLOW_L1") { conditions.push(`remaining_days BETWEEN 91 AND 180`); }
    else if (alert === "NORMAL")    { conditions.push(`remaining_days > 180`); }
    if (materialType) { conditions.push(`m.material_type = $${idx++}`); params.push(materialType); }
    if (supplier)     { conditions.push(`s.name_zh LIKE $${idx++}`); params.push(`%${supplier}%`); }
    if (lotNo)        { conditions.push(`ml.lot_no ILIKE $${idx++}`); params.push(`%${lotNo}%`); }

    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const data = await pgPool.query(`
      SELECT
        ml.lot_no                                  AS "lotNo",
        m.code                                     AS "materialCode",
        m.name_zh                                  AS "materialNameZh",
        m.name_en                                  AS "materialNameEn",
        m.material_type                            AS "materialType",
        ml.manufacturing_date                      AS "manufacturingDate",
        ml.received_at                             AS "receivedAt",
        FLOOR(m.shelf_life_days / 30.44)::int      AS "shelfLifeMonths",
        (ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date
                                                   AS "expiryDate",
        COALESCE(ml.received_qty, 0)               AS qty,
        m.uom,
        s.name_zh                                  AS "supplierName",
        (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE)::int
                                                   AS "remainingDays",
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0
            THEN '超期隔离'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30
            THEN '三级预警(红)'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 90
            THEN '二级预警(蓝)'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 180
            THEN '一级预警(黄)'
          ELSE '正常在用'
        END                                        AS "statusLabel"
      FROM material_lots ml
      JOIN materials m ON m.id = ml.material_id
      LEFT JOIN suppliers s ON s.id = ml.supplier_id
      ${where}
      ORDER BY
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0 THEN 0
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30 THEN 1
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 90 THEN 2
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 180 THEN 3
          ELSE 4
        END,
        (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) ASC
      LIMIT 5000
    `, params);

    const rows = data.rows;
    const wb = XLSX.utils.book_new();

    // ── Sheet 1: 物料有效期管控台账 ────────────────────────
    // Columns: A=序号 B=物料编码 C=物料名称 D=规格 E=物料类别
    //          F=生产日期 G=入库日期 H=封存有效期(月) I=到期日期
    //          J=已使用月(公式) K=剩余寿命月(公式) L=剩余天数(公式)
    //          M=库存数量 N=单位 O=供应商 P=当前状态 Q=备注

    const dataStart = 5;
    const lastRow = rows.length + dataStart - 1;

    const ws = {
      "!ref": `A1:Q${lastRow}`,
      "!cols": [
        { wch: 6 },  { wch: 14 }, { wch: 28 }, { wch: 24 }, { wch: 10 },
        { wch: 13 }, { wch: 13 }, { wch: 14 }, { wch: 13 },
        { wch: 12 }, { wch: 12 }, { wch: 12 },
        { wch: 10 }, { wch: 6 },  { wch: 14 }, { wch: 14 }, { wch: 20 },
      ],
      "!merges": [{ s: { r: 0, c: 0 }, e: { r: 0, c: 16 } }],
      "!rows": {},
    };

    // Row 1 – title (merged A1:Q1)
    ws["A1"] = { t: "s", v: "物料有效期管控台账" };

    // Row 2 – summary COUNTIF formulas
    const cntF = `COUNTIF(P${dataStart}:P${lastRow},`;
    ws["A2"] = { t: "str", f: `COUNTIF(P${dataStart}:P${lastRow},"超期隔离")&" 超期"` };
    ws["B2"] = { t: "str", f: `COUNTIF(P${dataStart}:P${lastRow},"三级预警(红)")&" 三级预警"` };
    ws["C2"] = { t: "str", f: `COUNTIF(P${dataStart}:P${lastRow},"二级预警(蓝)")&" 二级预警"` };
    ws["D2"] = { t: "str", f: `COUNTIF(P${dataStart}:P${lastRow},"一级预警(黄)")&" 一级预警"` };
    ws["E2"] = { t: "str", f: `COUNTIF(P${dataStart}:P${lastRow},"正常在用")&" 正常"` };
    ws["Q2"] = { t: "str", v: `生成时间: ${new Date().toLocaleString("zh-CN", { timeZone: "Asia/Ho_Chi_Minh" })}` };

    // Row 4 – headers
    const hdrs = [
      "序号", "批次号", "物料编码", "物料名称", "物料类别",
      "生产日期", "入库日期", "封存有效期(月)", "到期日期",
      "已使用月", "剩余寿命(月)", "剩余天数",
      "库存数量", "单位", "供应商", "当前状态", "备注",
    ];
    "ABCDEFGHIJKLMNOPQ".split("").forEach((col, i) => {
      ws[`${col}4`] = { t: "s", v: hdrs[i] };
    });

    // Rows 5+ – data
    rows.forEach((r, i) => {
      const rn = dataStart + i;
      const vals = [
        i + 1,
        r.lotNo || "",
        r.materialCode || "",
        r.materialNameZh || "",
        r.materialType || "",
        r.manufacturingDate ? String(r.manufacturingDate).slice(0, 10) : "",
        r.receivedAt ? String(r.receivedAt).slice(0, 10) : "",
        r.shelfLifeMonths ?? "",
        r.expiryDate ? String(r.expiryDate).slice(0, 10) : "",
        null, // J: 已使用月 formula
        null, // K: 剩余寿命月 formula
        null, // L: 剩余天数 formula
        r.qty ?? 0,
        r.uom || "",
        r.supplierName || "",
        r.statusLabel || "",
        "",
      ];
      "ABCDEFGHIJKLMNOPQ".split("").forEach((col, ci) => {
        if (ci === 9) {
          ws[`J${rn}`] = { t: "n", f: `DATEDIF(F${rn},TODAY(),"m")` };
        } else if (ci === 10) {
          ws[`K${rn}`] = { t: "n", f: `H${rn}-J${rn}` };
        } else if (ci === 11) {
          ws[`L${rn}`] = { t: "n", f: `I${rn}-TODAY()` };
        } else {
          ws[`${col}${rn}`] = vals[ci] === "" ? { t: "s", v: "" } : { t: "s", v: String(vals[ci]) };
        }
      });
    });

    XLSX.utils.book_append_sheet(wb, ws, "物料有效期管控台账");

    // ── Sheet 2: 筛选条件参考 ────────────────────────────
    const ws2Data = [
      ["筛选条件"],
      ["预警等级", alert || "全部"],
      ["物料类别", materialType || "全部"],
      ["供应商", supplier || "全部"],
      ["批次号", lotNo || "全部"],
      [],
      ["说明"],
      ["已使用月公式: =DATEDIF(生产日期,TODAY(),\"m\")"],
      ["剩余寿命(月): 封存有效期(月) - 已使用月"],
      ["剩余天数公式: =到期日期-TODAY()"],
      ["预警规则: ≤0超期 / ≤30三级预警(红) / ≤90二级预警(蓝) / ≤180一级预警(黄) / >180正常"],
    ];
    const ws2 = XLSX.utils.aoa_to_sheet(ws2Data);
    ws2["!cols"] = [{ wch: 14 }, { wch: 40 }];
    XLSX.utils.book_append_sheet(wb, ws2, "筛选条件参考");

    const buf = XLSX.write(wb, { bookType: "xlsx", type: "buffer" });
    const filename = `lifecycle_${new Date().toISOString().slice(0,10)}.xlsx`;
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"; filename*=UTF-8''${encodeURIComponent(filename)}`);
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Length", buf.length);
    res.end(buf);
  } catch (err) {
    console.error("GET /api/lifecycle/export:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/lifecycle/alerts — shortcut for the near-expiry + overdue lots
// Returns EXPIRED + RED_L3 + BLUE_L2 lots (most urgent)
api.get("/lifecycle/alerts", async (req, res) => {
  try {
    const data = await pgPool.query(`
      SELECT
        ml.id,
        ml.lot_no                                  AS "lotNo",
        m.code                                     AS "materialCode",
        m.name_zh                                  AS "materialNameZh",
        m.material_type                            AS "materialType",
        m.uom,
        ml.manufacturing_date                      AS "manufacturingDate",
        FLOOR(m.shelf_life_days / 30.44)::int      AS "shelfLifeMonths",
        (ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date
                                                   AS "expiryDate",
        COALESCE(ml.received_qty, 0)                        AS qty,
        s.name_zh                                  AS "supplierName",
        (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE)::int
                                                   AS "remainingDays",
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0
            THEN 'EXPIRED'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30
            THEN 'RED_L3'
          ELSE 'BLUE_L2'
        END                                        AS "alertLevel",
        CASE
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 0
            THEN '超期隔离'
          WHEN (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 30
            THEN '三级预警(红)'
          ELSE '二级预警(蓝)'
        END                                        AS "statusLabel"
      FROM material_lots ml
      JOIN materials m ON m.id = ml.material_id
      LEFT JOIN suppliers s ON s.id = ml.supplier_id
      WHERE (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) <= 90
      ORDER BY (DATE((ml.manufacturing_date + (m.shelf_life_days || ' days')::interval)::date) - CURRENT_DATE) ASC
    `);
    res.json({ success: true, data: data.rows });
  } catch (err) {
    console.error("GET /api/lifecycle/alerts:", err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

