// POST /mes/stagnation/thresholds — upsert
app.post("/mes/stagnation/thresholds", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { stationCode, stationType, lineCode, warningMinutes = 60,
            alertMinutes = 120, criticalMinutes = 240, autoEscalate = true } = req.body?.payload ?? {};

    if (!stationCode) return res.status(400).json(errorEnvelope("VALIDATION", "stationCode required"));

    const result = await query(`
      INSERT INTO stagnation_thresholds (station_code, station_type, line_code, warning_minutes, alert_minutes, critical_minutes, auto_escalate)
      VALUES ($1,$2,$3,$4,$5,$6,$7)
      ON CONFLICT (station_code) DO UPDATE SET
        station_type = EXCLUDED.station_type,
        line_code = EXCLUDED.line_code,
        warning_minutes = EXCLUDED.warning_minutes,
        alert_minutes = EXCLUDED.alert_minutes,
        critical_minutes = EXCLUDED.critical_minutes,
        auto_escalate = EXCLUDED.auto_escalate,
        updated_at = now()
      RETURNING station_code AS "stationCode", station_type AS "stationType",
                line_code AS "lineCode", warning_minutes AS "warningMinutes",
                alert_minutes AS "alertMinutes", critical_minutes AS "criticalMinutes",
                auto_escalate AS "autoEscalate", status
    `, [stationCode, stationType ?? null, lineCode ?? null, warningMinutes, alertMinutes, criticalMinutes, autoEscalate]);

    res.status(201).json(mutateEnvelope(result.rows[0]));
  } catch (err) {
    console.error("POST /mes/stagnation/thresholds:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// PATCH /mes/stagnation/:id/resolve
app.patch("/mes/stagnation/:id/resolve", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const { notes, operatorId } = req.body?.payload ?? {};

    const existing = await query(`SELECT id, status FROM product_stagnation_logs WHERE id = $1`, [id]);
    if (existing.rows.length === 0) return res.status(404).json(errorEnvelope("NOT_FOUND", "Stagnation log not found"));

    await query(`
      UPDATE product_stagnation_logs
      SET status = 'resolved', resolved_at = now(), resolved_by = $2, notes = COALESCE(notes || E'\\n' || $3, notes, $3), updated_at = now()
      WHERE id = $1
    `, [id, operatorId ?? null, notes ?? ""]);

    res.json(mutateEnvelope({ id: Number(id), status: "resolved" }));
  } catch (err) {
    console.error("PATCH /mes/stagnation/:id/resolve:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

