app.get("/mes/lines/:lineCode", requirePermission("mes.view"), async (req, res) => {
  try {
    const line = (await query(
      `SELECT pl.id, pl.internal_code AS "lineCode", pl.name_zh AS "nameZh",
              pl.name_en AS "nameEn", pl.name_vi AS "nameVi", pl.status
       FROM production_lines pl WHERE pl.internal_code = $1`,
      [req.params.lineCode],
    )).rows[0];
    if (!line) return res.status(404).json(errorEnvelope("NOT_FOUND", "Line not found"));

    const currentRun = (await query(
      `SELECT wo.id, wo.code AS "workOrderCode", wo.status, wo.planned_qty AS "plannedQty",
              wo.completed_qty AS "completedQty", p.code AS "productCode"
       FROM work_orders wo JOIN products p ON p.id = wo.product_id
       WHERE wo.line_id = $1 AND wo.status = 'running'
       ORDER BY wo.updated_at DESC LIMIT 1`,
      [line.id],
    )).rows[0] ?? null;

    const recentEvents = (await query(
      `SELECT se.id, se.event_type AS "eventType", se.result,
              se.occurred_at AS "occurredAt", s.code AS "stationCode"
       FROM station_events se JOIN stations s ON s.id = se.station_id
       WHERE s.line_id = $1
       ORDER BY se.occurred_at DESC LIMIT 20`,
      [line.id],
    )).rows;

    const lineStations = (await query(
      `SELECT s.id, s.code, st.code AS "stationType",
              s.name_zh AS "nameZh", s.name_en AS "nameEn", s.name_vi AS "nameVi",
              s.required_scan AS "requiredScan", s.sequence_order AS "sequenceOrder"
       FROM stations s
       LEFT JOIN station_types st ON st.id = s.station_type_id
       WHERE s.line_id = $1
       ORDER BY s.sequence_order NULLS LAST, s.id`,
      [line.id],
    )).rows;

    const stationRuntime = (await query(
      `WITH ordered AS (
         SELECT s.id,s.code,se.occurred_at,
                LAG(se.occurred_at) OVER (PARTITION BY s.id ORDER BY se.occurred_at) AS previous_event_at
         FROM stations s
         LEFT JOIN station_events se ON se.station_id=s.id AND se.occurred_at >= CURRENT_DATE
         WHERE s.line_id=$1
       ), stats AS (
         SELECT id,code,MAX(occurred_at) AS last_event_at,
                COALESCE(SUM(CASE WHEN previous_event_at IS NOT NULL
                  THEN LEAST(EXTRACT(EPOCH FROM (occurred_at-previous_event_at))/60.0,10) ELSE 0 END),0) AS runtime_minutes
         FROM ordered GROUP BY id,code
       )
       SELECT st.id,st.code AS "stationCode",st.last_event_at AS "lastEventAt",
              hb.last_seen AS "lastSeen",
              CASE WHEN hb.last_seen >= NOW()-INTERVAL '2 minutes'
                         AND st.last_event_at >= NOW()-INTERVAL '10 minutes' THEN 'RUNNING'
                   WHEN hb.last_seen IS NULL OR hb.last_seen < NOW()-INTERVAL '2 minutes' THEN 'OFFLINE'
                   ELSE 'STOPPED' END AS status,
              ROUND(st.runtime_minutes,1) AS "runtimeMinutesToday",
              ROUND(GREATEST(EXTRACT(EPOCH FROM (NOW()-CURRENT_DATE))/60.0-st.runtime_minutes,0),1) AS "inferredStopMinutesToday",
              'EVENT_HEARTBEAT_INFERENCE' AS "timeSource"
       FROM stats st LEFT JOIN station_heartbeats hb ON hb.station_code=st.code
       ORDER BY st.code`, [line.id]
    )).rows;

    const runtimeMinutes = stationRuntime.map(row => Number(row.runtimeMinutesToday || 0));
    const inferredStopMinutes = stationRuntime.map(row => Number(row.inferredStopMinutesToday || 0));
    const workingMinutesToday = runtimeMinutes.length ? runtimeMinutes.reduce((a,b) => a+b, 0) / runtimeMinutes.length : 0;
    const stoppedMinutesToday = inferredStopMinutes.length ? inferredStopMinutes.reduce((a,b) => a+b, 0) / inferredStopMinutes.length : 0;
    const stationKpi = {
      workingHoursToday: Number((workingMinutesToday / 60).toFixed(2)),
      stoppedHoursToday: Number((stoppedMinutesToday / 60).toFixed(2)),
      availabilityPct: Number((workingMinutesToday + stoppedMinutesToday > 0 ? workingMinutesToday / (workingMinutesToday + stoppedMinutesToday) * 100 : 0).toFixed(1)),
      source: "EVENT_HEARTBEAT_INFERENCE"
    };
    res.json(envelope({ line, currentRun, recentEvents, stations: lineStations, stationRuntime, stationKpi }));
  } catch (err) {
    console.error("GET /mes/lines/:lineCode:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

