// ── MES PCB Serials ────────────────────────────────────────────

app.get("/mes/pcb-serials", requirePermission("mes.view"), async (req, res) => {
  try {
    const { workOrderCode, lineCode, status, limit = 100, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;
    if (workOrderCode) { conditions.push(`wo.code = $${idx++}`); params.push(workOrderCode); }
    if (lineCode) { conditions.push(`pl.internal_code = $${idx++}`); params.push(lineCode); }
    if (status) { conditions.push(`ps.status = $${idx++}`); params.push(status); }
    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const data = await query(
      `SELECT ps.id, ps.serial_no AS "serialNo", ps.status, ps.created_at AS "createdAt",
              wo.code AS "workOrderCode", pl.internal_code AS "lineCode",
              p.code AS "productCode"
       FROM pcb_serials ps
       JOIN work_orders wo ON wo.id = ps.work_order_id
       JOIN production_lines pl ON pl.id = wo.line_id
       JOIN products p ON p.id = wo.product_id
       ${where} ORDER BY ps.created_at DESC LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)],
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /mes/pcb-serials:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.post("/mes/pcb-serials", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { serialNo, workOrderCode } = req.body?.payload ?? {};
    if (!serialNo || !workOrderCode) {
      return res.status(400).json(errorEnvelope("VALIDATION", "serialNo and workOrderCode required"));
    }
    const wo = (await query("SELECT id FROM work_orders WHERE code = $1", [workOrderCode])).rows[0];
    if (!wo) return res.status(400).json(errorEnvelope("VALIDATION", "work order not found"));
    const r = await query(
      `INSERT INTO pcb_serials (serial_no, work_order_id, status) VALUES ($1, $2, 'wip') RETURNING id`,
      [serialNo, wo.id],
    );
    res.status(201).json(mutateEnvelope({ id: r.rows[0].id, serialNo, workOrderCode, status: "wip" }));
  } catch (err) {
    if (err.code === "23505") return res.status(409).json(errorEnvelope("DUPLICATE", "serial already exists"));
    console.error("POST /mes/pcb-serials:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.get("/mes/pcb-serials/:serialNo", requirePermission("mes.view"), async (req, res) => {
  try {
    const pcb = (await query(
      `SELECT ps.id, ps.serial_no AS "serialNo", ps.status, ps.created_at AS "createdAt",
              wo.code AS "workOrderCode", wo.id AS "workOrderId"
       FROM pcb_serials ps LEFT JOIN work_orders wo ON wo.id = ps.work_order_id
       WHERE ps.serial_no = $1`,
      [req.params.serialNo],
    )).rows[0];
    if (!pcb) return res.status(404).json(errorEnvelope("NOT_FOUND", "PCB serial not found"));

    const events = (await query(
      `SELECT se.id, se.event_type AS "eventType", se.result,
              se.occurred_at AS "occurredAt", s.code AS "stationCode", s.station_type AS "stationType",
              u.username AS operator
       FROM station_events se
       JOIN stations s ON s.id = se.station_id
       LEFT JOIN users u ON u.id = se.operator_id
       WHERE se.pcb_serial_id = $1
       ORDER BY se.occurred_at ASC`,
      [pcb.id],
    )).rows;

    res.json(envelope({ pcb, events }));
  } catch (err) {
    console.error("GET /mes/pcb-serials/:serialNo:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// ── MES Downtime ───────────────────────────────────────────────

app.get("/mes/downtimes", requirePermission("mes.view"), async (req, res) => {
  try {
    const { lineCode, status, limit = 50, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;
    if (lineCode) { conditions.push(`pl.internal_code = $${idx++}`); params.push(lineCode); }
    if (status) { conditions.push(`de.status = $${idx++}`); params.push(status); }
    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const data = await query(
      `SELECT de.id, de.downtime_no AS "downtimeNo", de.reason_code AS "reasonCode",
              de.reason_detail AS "reasonDetail", de.start_at AS "startAt", de.end_at AS "endAt",
              de.status, de.closed_at AS "closedAt",
              pl.internal_code AS "lineCode", u.username AS operator
       FROM downtime_events de
       LEFT JOIN production_lines pl ON pl.id = de.line_id
       LEFT JOIN users u ON u.id = de.operator_id
       ${where} ORDER BY de.start_at DESC LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)],
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /mes/downtimes:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.post("/mes/downtimes", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { lineCode, stationCode, reasonCode, reasonDetail, operator } = req.body?.payload ?? {};
    if (!lineCode || !reasonCode || !operator) {
      return res.status(400).json(errorEnvelope("VALIDATION", "lineCode, reasonCode, operator required"));
    }
    const line = (await query("SELECT id FROM production_lines WHERE internal_code = $1", [lineCode])).rows[0];
    if (!line) return res.status(400).json(errorEnvelope("VALIDATION", "line not found"));
    let stationId = null;
    if (stationCode) {
      const st = (await query("SELECT id FROM stations WHERE code = $1", [stationCode])).rows[0];
      if (st) stationId = st.id;
    }
    const op = (await query("SELECT id FROM users WHERE username = $1", [operator])).rows[0];
    if (!op) return res.status(400).json(errorEnvelope("VALIDATION", "operator not found"));

    const downtimeNo = `DT-${Date.now()}`;
    const r = await query(
      `INSERT INTO downtime_events (downtime_no, asset_id, line_id, station_id, reason_code, reason_detail, start_at, status, action_taken, result, operator_id)
       VALUES ($1, 0, $2, $3, $4, $5, now(), 'open', '', 'open', $6) RETURNING id`,
      [downtimeNo, line.id, stationId, reasonCode, reasonDetail ?? null, op.id],
    );
    res.status(201).json(mutateEnvelope({ id: r.rows[0].id, downtimeNo, lineCode, stationCode, reasonCode, status: "open" }));
  } catch (err) {
    console.error("POST /mes/downtimes:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.patch("/mes/downtimes/:id", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { action, actionTaken, operator } = req.body?.payload ?? {};
    if (action !== "close") return res.status(400).json(errorEnvelope("VALIDATION", "action must be 'close'"));
    let opId = null;
    if (operator) {
      const op = (await query("SELECT id FROM users WHERE username = $1", [operator])).rows[0];
      if (op) opId = op.id;
    }
    const r = await query(
      `UPDATE downtime_events SET status = 'closed', end_at = now(), action_taken = $1,
              operator_id = COALESCE($2, operator_id), closed_at = now(), result = 'closed'
       WHERE id = $3 AND status = 'open' RETURNING downtime_no AS "downtimeNo"`,
      [actionTaken ?? "", opId, req.params.id],
    );
    if (r.rows.length === 0) return res.status(404).json(errorEnvelope("NOT_FOUND", "downtime not found or already closed"));
    res.json(mutateEnvelope({ id: Number(req.params.id), downtimeNo: r.rows[0].downtimeNo, status: "closed" }));
  } catch (err) {
    console.error("PATCH /mes/downtimes/:id:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

