app.get("/quality/defect-pareto", async (req, res) => {
  try {
    const { station, fromDate, toDate } = req.query;
    const conditions = ["qi.result = 'FAIL'"];
    const params = [];
    let idx = 1;
    if (station) { conditions.push(`qi.station_type = $${idx++}`); params.push(station); }
    if (fromDate) { conditions.push(`qi.occurred_at >= $${idx++}`); params.push(fromDate); }
    if (toDate) { conditions.push(`qi.occurred_at <= $${idx++}`); params.push(toDate); }
    const where = "WHERE " + conditions.join(" AND ");
    const data = await query(
      `SELECT qi.station_type AS station, qi.result, COUNT(*)::int AS cnt
       FROM quality_inspections qi ${where}
       GROUP BY qi.station_type, qi.result ORDER BY cnt DESC`,
      params,
    );
    res.json(envelope(data.rows));
  } catch (err) {
    console.error("GET /quality/defect-pareto:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

