app.get("/traceability/:traceKey", async (req, res) => {
  try {
    const { traceKey } = req.params;
    const data = await query(
      `SELECT te.id, te.event_type AS "eventType", te.reference_no AS "ref",
              te.status, te.actor, te.occurred_at AS "occurredAt", te.event_payload AS "details"
       FROM traceability_events te
       WHERE te.reference_no = $1 OR te.trace_key = $1
       ORDER BY te.occurred_at ASC`,
      [traceKey],
    );
    res.json(envelope({ traceKey, events: data.rows }));
  } catch (err) {
    console.error("GET /traceability/:traceKey:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.get("/traceability/events", async (req, res) => {
  try {
    const { eventType, traceKey, limit = 100, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;
    if (eventType) { conditions.push(`te.event_type = $${idx++}`); params.push(eventType); }
    if (traceKey) { conditions.push(`(te.reference_no = $${idx} OR te.trace_key = $${idx})`); params.push(traceKey); idx++; }
    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const data = await query(
      `SELECT te.id, te.event_type AS "eventType", te.reference_no AS "ref",
              te.status, te.actor, te.occurred_at AS "occurredAt", te.event_payload AS "details",
              te.trace_key AS "traceKey"
       FROM traceability_events te ${where} ORDER BY te.occurred_at DESC LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)],
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /traceability/events:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.post("/traceability/events", async (req, res) => {
  try {
    const body    = req.body;
    const payload = body.payload ?? body;
    const eventType = payload?.eventType ?? payload?.event_type ?? 'UNSET';
    const traceKey = payload?.traceKey || payload?.trace_key || `AUTO-${randomUUID()}`;
    const refNo    = payload?.ref || payload?.reference_no || eventType || 'EVENT';
    const result = await query(
      `INSERT INTO traceability_events (event_type, reference_no, status, actor, event_payload, trace_key)
       VALUES ($1, $2, $3, $4, $5, $6) RETURNING id`,
      [eventType, refNo, payload?.status || 'active', payload?.actor, payload?.details ?? {}, traceKey],
    );
    res.status(201).json(mutateEnvelope({ id: result.rows[0].id }));
  } catch (err) {
    console.error("POST /traceability/events:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

