app.patch("/wms/inventory-control/sla/:processKey", requirePermission("wms.execute"), async (req, res) => {
  try {
    const processKey = String(req.params.processKey ?? "").trim().toUpperCase();
    const slaMinutes = Number(req.body?.slaMinutes);
    const warningPercent = Number(req.body?.warningPercent ?? 80);
    if (!processKey || !Number.isInteger(slaMinutes) || slaMinutes <= 0 || !Number.isInteger(warningPercent) || warningPercent < 1 || warningPercent > 99) {
      return res.status(400).json(errorEnvelope("VALIDATION", "valid processKey, positive integer slaMinutes and warningPercent 1-99 required"));
    }
    const updated = await query(
      `INSERT INTO wms_process_sla_rules(process_key, sla_minutes, warning_percent, updated_by, updated_at)
       VALUES($1,$2,$3,$4,NOW())
       ON CONFLICT(process_key) DO UPDATE SET sla_minutes=EXCLUDED.sla_minutes,
         warning_percent=EXCLUDED.warning_percent, updated_by=EXCLUDED.updated_by, updated_at=NOW()
       RETURNING *`,
      [processKey, slaMinutes, warningPercent, req.user?.username ?? "system"],
    );
    res.json(mutateEnvelope(updated.rows[0]));
  } catch (err) {
    console.error("PATCH /wms/inventory-control/sla/:processKey:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// Complete QR/lot trace: current balance plus every immutable movement and WO use.
app.get("/wms/material-trace", requirePermission("wms.view"), async (req, res) => {
  try {
    const qr = String(req.query.qr ?? "").trim();
    if (!qr) return res.status(400).json(errorEnvelope("VALIDATION", "qr required"));
    await receivingQrRegistrationReady;
    const lotR = await query(`
      SELECT ml.id, ml.lot_no AS "lotNo", ml.label_id AS "materialQr",
             ml.received_qty::numeric AS "remainingQty", ml.reserved_qty::numeric AS "lineSideQty",
             (ml.received_qty-ml.reserved_qty)::numeric AS "warehouseQty",
             ml.received_at AS "receivedAt",
             m.code AS "materialCode", m.name_zh AS "materialName", ml.iqc_status AS "iqcStatus", sl.code AS "locationCode",
             qr.pallet_qr AS "palletQr"
      FROM material_lots ml
      JOIN materials m ON m.id=ml.material_id
      LEFT JOIN storage_locations sl ON sl.id=ml.storage_location_id
      LEFT JOIN wms_receiving_qr_registrations qr ON qr.material_lot_id=ml.id
      WHERE ml.lot_no=$1 OR ml.label_id=$1 OR m.code=$1 OR m.id::text=$1 OR qr.material_qr=$1 OR qr.pallet_qr=$1
      ORDER BY ml.id DESC LIMIT 1`, [qr]);
    const lot = lotR.rows[0];
    if (!lot) return res.status(404).json(errorEnvelope("NOT_FOUND", `No material or pallet found for '${qr}'`));
    const txR = await query(`
      SELECT it.id,it.tx_no AS "txNo",it.action,it.qty::numeric,it.occurred_at AS "occurredAt",
             wo.code AS "workOrderCode",fl.code AS "fromLocation",tl.code AS "toLocation",
             u.username AS operator,it.reference_type AS "referenceType",it.reference_no AS "referenceNo"
      FROM inventory_transactions it
      LEFT JOIN work_orders wo ON wo.id=it.work_order_id
      LEFT JOIN storage_locations fl ON fl.id=it.from_location_id
      LEFT JOIN storage_locations tl ON tl.id=it.to_location_id
      LEFT JOIN users u ON u.id=it.operator_id
      WHERE it.material_lot_id=$1 ORDER BY it.occurred_at DESC,it.id DESC LIMIT 500`, [lot.id]);
    const usedByWoR = await query(`
      SELECT COALESCE(wo.code,'UNASSIGNED') AS "workOrderCode",SUM(it.qty)::numeric AS "usedQty"
      FROM inventory_transactions it LEFT JOIN work_orders wo ON wo.id=it.work_order_id
      WHERE it.material_lot_id=$1 AND it.action='CONSUME'
      GROUP BY COALESCE(wo.code,'UNASSIGNED') ORDER BY SUM(it.qty) DESC`, [lot.id]);
    const [iqcR,pdaR,approvalR] = await Promise.all([
      query(`SELECT to_jsonb(i) AS record FROM iqc_inspections i WHERE i.material_lot_id=$1 ORDER BY COALESCE(i.finished_at,i.occurred_at,i.created_at) DESC`,[lot.id]),
      query(`SELECT to_jsonb(p) AS record FROM pda_inspection_records p WHERE p.material_lot_id=$1 ORDER BY p.scanned_at DESC`,[lot.id]),
      query(`SELECT to_jsonb(a) AS record FROM iqc_special_approvals a JOIN iqc_inspections i ON i.id=a.inspection_id WHERE i.material_lot_id=$1 ORDER BY a.submitted_at DESC`,[lot.id])
    ]);
    const positionR=await query(`SELECT id,position_type AS "positionType",area_code AS "areaCode",location_code AS "locationCode",x,z,
      work_order_code AS "workOrderCode",movement_type AS "movementType",operator,occurred_at AS "occurredAt"
      FROM wms_material_position_history WHERE material_lot_id=$1 ORDER BY occurred_at DESC,id DESC`,[lot.id]);
    const documents=[...iqcR.rows,...pdaR.rows].flatMap(x=>{
      const r=x.record??{}; const values=[r.attachments,r.photo_url,r.photoUrl,r.consume_image_url].filter(Boolean);
      return values.flatMap(v=>Array.isArray(v)?v:[v]);
    });
    res.json({ data: { ...lot, isPartial: Number(lot.remainingQty)>0 && txR.rows.some(x=>x.action==='CONSUME'),
      usedByWorkOrder: usedByWoR.rows, movements: txR.rows, positions:positionR.rows,
      quality:{iqcStatus:lot.iqcStatus,inspections:iqcR.rows.map(x=>x.record),pdaInspections:pdaR.rows.map(x=>x.record),specialApprovals:approvalR.rows.map(x=>x.record),documents} } });
  } catch (err) {
    console.error("GET /wms/material-trace:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.patch("/admin/users/:id/role", requirePermission("admin.roles"), async (req, res) => {
  try {
    const userId = String(req.params.id ?? "").trim();
    const roleKey = String(req.body?.roleKey ?? "").trim();
    if (!userId || !roleKey) {
      return res.status(400).json(errorEnvelope("VALIDATION", "user id and roleKey required"));
    }
    const target = (await query(
      `SELECT u.id,u.username,u.display_name AS "displayName",r.code AS "oldRole"
       FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=$1`,
      [userId],
    )).rows[0];
    if (!target) return res.status(404).json(errorEnvelope("NOT_FOUND", "User not found"));
    if (target.username === "MENG_YING" && roleKey !== "admin") {
      return res.status(409).json(errorEnvelope("PROTECTED_SUPER_ADMIN", "Factory manager authorization cannot be removed"));
    }
    const role = (await query("SELECT id,code FROM roles WHERE code=$1", [roleKey])).rows[0];
    if (!role) return res.status(404).json(errorEnvelope("NOT_FOUND", "Role not found"));
    const updated = (await query(
      `UPDATE users SET role_id=$1,updated_at=NOW() WHERE id=$2
       RETURNING id,username,display_name AS "displayName",status,locale`,
      [role.id, userId],
    )).rows[0];
    await writeAuditLog({
      actorId: req.user?.userId,
      action: "USER_ROLE_ASSIGNED",
      entityType: "user",
      entityId: userId,
      referenceNo: target.username,
      payload: { oldRole: target.oldRole, newRole: roleKey, assignedBy: req.user?.username },
      ipAddress: req.ip,
      userAgent: req.headers["user-agent"],
    });
    res.json(mutateEnvelope({ ...updated, roleKey }));
  } catch (err) {
    console.error("PATCH /admin/users/:id/role:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

app.get("/admin/audit-logs", async (req, res) => {
  try {
    const { actor, eventType, fromDate, toDate, limit = 50, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;
    if (actor) { conditions.push(`al.actor = $${idx++}`); params.push(actor); }
    if (eventType) { conditions.push(`al.event_type = $${idx++}`); params.push(eventType); }
    if (fromDate) { conditions.push(`al.occurred_at >= $${idx++}`); params.push(fromDate); }
    if (toDate) { conditions.push(`al.occurred_at <= $${idx++}`); params.push(toDate); }
    const where = conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";
    const data = await query(
      `SELECT al.id, al.event_type AS "eventType", al.status, al.actor,
              al.occurred_at AS "occurredAt", al.details
       FROM audit_logs al ${where} ORDER BY al.occurred_at DESC LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)],
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /admin/audit-logs:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

