/**
 * POST /ai/query/inventory — Natural-language inventory query with live DB context.
 * Body: { query: string, locale?: string }
 * Automatically fetches current material lots from DB to provide context.
 */
app.post("/ai/query/inventory", requirePermission("ai.query"), async (req, res) => {
  try {
    const { query: userQuery, locale } = req.body ?? {};
    if (!userQuery) return res.status(400).json(errorEnvelope("VALIDATION", "query required"));

    // Fetch live inventory snapshot for context
    const lotsRes = await query(
      `SELECT m.code AS "materialCode", ml.lot_no AS "lotNo",
              ml.received_qty - COALESCE(ml.reserved_qty, 0) AS qty,
              ml.iqc_status AS "iqcStatus", sl.code AS "locationCode"
       FROM material_lots ml
       JOIN materials m ON m.id = ml.material_id
       LEFT JOIN storage_locations sl ON sl.id = ml.storage_location_id
        WHERE ml.lot_status = 'open'
       ORDER BY ml.created_at DESC LIMIT 50`,
    );

    const reply = await askInventoryQuery(userQuery, lotsRes.rows, {
      locale: locale ?? req.user?.locale ?? "zh-CN",
    });
    res.json(envelope({ reply }));
  } catch (err) {
    console.error("POST /ai/query/inventory:", err.message);
    res.status(500).json(errorEnvelope("AI_ERROR", err.message));
  }
});

