api.post("/hr/payroll/batches/:id/calculate",requirePermission("hr.salary"),async(req,res)=>{
  const client=await pgPool.connect();try{
    const p=req.body?.payload??req.body??{};await client.query("BEGIN");
    const batch=(await client.query("SELECT * FROM hr_payroll_batches WHERE id=$1 AND status IN('DRAFT','CALCULATED') FOR UPDATE",[req.params.id])).rows[0];
    if(!batch)throw new Error("Only draft or calculated batch may be recalculated");
    await client.query("DELETE FROM hr_payroll_items WHERE batch_id=$1",[batch.id]);
    await client.query(`INSERT INTO hr_payroll_items(batch_id,salary_record_id,employee_id,base_salary,attendance_pay,overtime_pay,
      allowances,bonuses,deductions,tax,insurance,gross_salary,net_salary,payment_method,calculation_snapshot)
      SELECT $1,s.id,s.employee_id,s.base_salary,
        GREATEST(s.base_salary-COALESCE(s.deduction_absent,0),0),
        COALESCE(s.ot_hours,0)*COALESCE(s.base_salary,0)/240*COALESCE(s.ot_rate,1.5),
        COALESCE(s.allowances_total,0),
        COALESCE(s.bonus_performance,0)+COALESCE(s.bonus_attendance,0)+COALESCE(s.bonus_other,0),
        COALESCE(s.deduction_late,0)+COALESCE(s.deduction_absent,0)+COALESCE(s.deduction_other,0),
        COALESCE(s.personal_tax,0),
        COALESCE(s.social_insurance,0)+COALESCE(s.health_insurance,0)+COALESCE(s.unemployment_ins,0),
        s.gross_salary,s.net_salary,
        CASE WHEN pp.preferred_method='BANK' AND pp.verified_status='VERIFIED' THEN 'BANK' ELSE 'CASH' END,
        to_jsonb(s)
      FROM salary_records s JOIN employees e ON e.id=s.employee_id
      LEFT JOIN hr_employee_payment_profiles pp ON pp.employee_id=e.id
      WHERE s.year=$2 AND s.month=$3`,[batch.id,batch.year,batch.month]);
    const totals=(await client.query(`SELECT COUNT(*)::int employee_count,COALESCE(SUM(gross_salary),0) total_gross,
      COALESCE(SUM(deductions+tax+insurance),0) total_deductions,COALESCE(SUM(net_salary),0) total_net
      FROM hr_payroll_items WHERE batch_id=$1`,[batch.id])).rows[0];
    if(!totals.employee_count)throw new Error("No salary records found for payroll period");
    await client.query(`INSERT INTO hr_payroll_source_reconciliations(batch_id,check_type,result,expected_value,actual_value,message)
      VALUES($1,'SALARY_RECORD_COVERAGE','PASS',$2,$3,'All available salary records were captured')`,
      [batch.id,JSON.stringify({period:`${batch.year}-${String(batch.month).padStart(2,"0")}`}),JSON.stringify({employeeCount:totals.employee_count})]);
    await client.query(`INSERT INTO hr_payroll_source_reconciliations(batch_id,check_type,result,expected_value,actual_value,message)
      VALUES($1,'NET_PAY_CONTROL',CASE WHEN $2>=0 THEN 'PASS' ELSE 'FAIL' END,$3,$4,'Gross, deductions and net totals reconciled')`,
      [batch.id,Number(totals.total_net),JSON.stringify({gross:totals.total_gross,deductions:totals.total_deductions}),JSON.stringify({net:totals.total_net})]);
    const row=(await client.query(`UPDATE hr_payroll_batches SET status='CALCULATED',employee_count=$2,total_gross=$3,
      total_deductions=$4,total_net=$5,source_cutoff_at=NOW(),calculated_at=NOW(),updated_at=NOW() WHERE id=$1 RETURNING *`,
      [batch.id,totals.employee_count,totals.total_gross,totals.total_deductions,totals.total_net])).rows[0];
    await client.query(`INSERT INTO hr_payroll_audit(batch_id,event_type,actor,detail)VALUES($1,'CALCULATED',$2,$3)`,
      [batch.id,String(p.actor??"HR"),JSON.stringify(totals)]);
    await client.query("COMMIT");res.json(mutateEnvelope(row));
  }catch(error){await client.query("ROLLBACK").catch(()=>{});res.status(409).json(errorEnvelope("PAYROLL_CALCULATE_FAILED",error.message));}finally{client.release();}
});

api.post("/hr/payroll/batches/:id/decision",requirePermission("hr.salary"),async(req,res)=>{
  const client=await pgPool.connect();try{
    const p=req.body?.payload??req.body??{},role=String(p.approvalRole??"").toUpperCase(),decision=String(p.decision??"").toUpperCase();
    if(!["HR","FINANCE"].includes(role)||!["APPROVE","REJECT"].includes(decision))throw new Error("Valid approvalRole and decision required");
    await client.query("BEGIN");const batch=(await client.query("SELECT * FROM hr_payroll_batches WHERE id=$1 FOR UPDATE",[req.params.id])).rows[0];
    if(!batch)throw new Error("Payroll batch not found");
    if(role==="HR"&&batch.status!=="CALCULATED")throw new Error("HR approval requires CALCULATED batch");
    if(role==="FINANCE"&&batch.status!=="HR_APPROVED")throw new Error("Finance approval requires HR approval");
    await client.query(`INSERT INTO hr_payroll_approvals(batch_id,approval_role,decision,actor,comment)VALUES($1,$2,$3,$4,$5)`,
      [batch.id,role,decision,String(p.actor??role),String(p.comment??"Reviewed")]);
    const status=decision==="REJECT"?"DRAFT":role==="HR"?"HR_APPROVED":"FINANCE_APPROVED";
    const row=(await client.query("UPDATE hr_payroll_batches SET status=$2,updated_at=NOW() WHERE id=$1 RETURNING *",[batch.id,status])).rows[0];
    await client.query(`INSERT INTO hr_payroll_audit(batch_id,event_type,actor,detail)VALUES($1,'APPROVAL_DECISION',$2,$3)`,
      [batch.id,String(p.actor??role),JSON.stringify({role,decision,status})]);
    await client.query("COMMIT");res.json(mutateEnvelope(row));
  }catch(error){await client.query("ROLLBACK").catch(()=>{});res.status(409).json(errorEnvelope("PAYROLL_DECISION_FAILED",error.message));}finally{client.release();}
});

api.post("/hr/payroll/items/:id/pay",requirePermission("hr.salary"),async(req,res)=>{
  const client=await pgPool.connect();try{
    const p=req.body?.payload??req.body??{};await client.query("BEGIN");
    const item=(await client.query(`SELECT i.*,b.status batch_status FROM hr_payroll_items i
      JOIN hr_payroll_batches b ON b.id=i.batch_id WHERE i.id=$1 FOR UPDATE`,[req.params.id])).rows[0];
    if(!item||!["FINANCE_APPROVED","PAYING","PARTIALLY_PAID"].includes(item.batch_status))throw new Error("Finance-approved payroll item required");
    if(item.payment_status==="PAID")throw new Error("Payroll item already paid");
    const method=String(p.paymentMethod??item.payment_method).toUpperCase(),status=method==="CASH"?"PROCESSING":"PAID";
    const paymentNo=`PAYMENT-${Date.now()}-${randomUUID().slice(0,6).toUpperCase()}`;
    const payment=(await client.query(`INSERT INTO hr_payroll_payments(payment_no,batch_id,payroll_item_id,payment_method,amount,bank_reference,status,paid_by,paid_at)
      VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,
      [paymentNo,item.batch_id,item.id,method,item.net_salary,p.bankReference??null,status,String(p.actor??"FINANCE"),status==="PAID"?new Date():null])).rows[0];
    await client.query("UPDATE hr_payroll_items SET payment_method=$2,payment_status=$3,paid_at=$4 WHERE id=$1",
      [item.id,method,status,status==="PAID"?new Date():null]);
    await client.query("UPDATE hr_payroll_batches SET status='PAYING',updated_at=NOW() WHERE id=$1",[item.batch_id]);
    await client.query(`INSERT INTO hr_payroll_audit(batch_id,event_type,actor,detail)VALUES($1,'PAYMENT_CREATED',$2,$3)`,
      [item.batch_id,String(p.actor??"FINANCE"),JSON.stringify({paymentId:payment.id,employeeId:item.employee_id,method,status})]);
    await client.query("COMMIT");res.json(mutateEnvelope(payment));
  }catch(error){await client.query("ROLLBACK").catch(()=>{});res.status(409).json(errorEnvelope("PAYROLL_PAYMENT_FAILED",error.message));}finally{client.release();}
});

api.post("/hr/payroll/payments/:id/receive",requirePermission("hr.salary"),async(req,res)=>{
  const client=await pgPool.connect();try{
    const p=req.body?.payload??req.body??{};await client.query("BEGIN");
    const payment=(await client.query(`SELECT p.*,i.employee_id FROM hr_payroll_payments p JOIN hr_payroll_items i ON i.id=p.payroll_item_id
      WHERE p.id=$1 AND p.payment_method='CASH' AND p.status='PROCESSING' FOR UPDATE`,[req.params.id])).rows[0];
    if(!payment)throw new Error("Pending cash payment not found");
    await client.query(`INSERT INTO hr_payroll_cash_receipts(payment_id,employee_id,received_amount,receiver_badge,signature_method,witness_badge)
      VALUES($1,$2,$3,$4,$5,$6)`,[payment.id,payment.employee_id,payment.amount,p.receiverBadge,p.signatureMethod??"EMPLOYEE_BADGE",p.witnessBadge??null]);
    await client.query("UPDATE hr_payroll_payments SET status='PAID',paid_at=NOW() WHERE id=$1",[payment.id]);
    await client.query("UPDATE hr_payroll_items SET payment_status='PAID',paid_at=NOW() WHERE id=$1",[payment.payroll_item_id]);
    await client.query(`INSERT INTO hr_payroll_audit(batch_id,event_type,actor,detail)VALUES($1,'CASH_RECEIVED',$2,$3)`,
      [payment.batch_id,String(p.receiverBadge),JSON.stringify({paymentId:payment.id,employeeId:payment.employee_id})]);
    await client.query("COMMIT");res.json(mutateEnvelope({paymentId:payment.id,status:"PAID"}));
  }catch(error){await client.query("ROLLBACK").catch(()=>{});res.status(409).json(errorEnvelope("PAYROLL_RECEIPT_FAILED",error.message));}finally{client.release();}
});

api.post("/hr/payroll/batches/:id/close",requirePermission("hr.salary"),async(req,res)=>{
  const client=await pgPool.connect();try{
    const p=req.body?.payload??req.body??{};await client.query("BEGIN");
    const batch=(await client.query("SELECT * FROM hr_payroll_batches WHERE id=$1 FOR UPDATE",[req.params.id])).rows[0];
    if(!batch)throw new Error("Payroll batch not found");
    const unpaid=Number((await client.query("SELECT COUNT(*) count FROM hr_payroll_items WHERE batch_id=$1 AND payment_status<>'PAID'",[batch.id])).rows[0].count);
    if(unpaid)throw new Error(`${unpaid} payroll items are not paid or received`);
    const sums=(await client.query("SELECT COALESCE(SUM(tax),0) tax,COALESCE(SUM(insurance),0) insurance FROM hr_payroll_items WHERE batch_id=$1",[batch.id])).rows[0];
    const exportNo=`PAYGL-${batch.year}${String(batch.month).padStart(2,"0")}`;
    const period=(await client.query(`SELECT id FROM fiscal_periods WHERE $1::date BETWEEN start_date AND end_date LIMIT 1`,
      [`${batch.year}-${String(batch.month).padStart(2,"0")}-01`])).rows[0];
    const journal=(await client.query(`INSERT INTO gl_journal_entries(entry_no,source_type,source_no,entry_type,period_id,posting_date,
      currency_code,exchange_rate,memo,status,posted_at)
      VALUES($1,'HR_PAYROLL',$2,'PAYROLL_ACCRUAL',$3,($4::date+INTERVAL '1 month - 1 day')::date,'VND',1,$5,'posted',NOW())
      RETURNING id`,[`GL-${exportNo}`,batch.batch_no,period?.id??null,`${batch.year}-${String(batch.month).padStart(2,"0")}-01`,`Payroll ${batch.batch_no}`])).rows[0];
    await client.query(`INSERT INTO gl_journal_lines(entry_id,line_no,account_id,description,debit_amount,credit_amount)
      SELECT $1,1,id,$2,$3,0 FROM gl_accounts WHERE code='5110'`,[journal.id,`Payroll expense ${batch.batch_no}`,batch.total_gross]);
    await client.query(`INSERT INTO gl_journal_lines(entry_id,line_no,account_id,description,debit_amount,credit_amount)
      SELECT $1,2,id,$2,0,$3 FROM gl_accounts WHERE code='2300'`,[journal.id,`Payroll tax ${batch.batch_no}`,sums.tax]);
    await client.query(`INSERT INTO gl_journal_lines(entry_id,line_no,account_id,description,debit_amount,credit_amount)
      SELECT $1,3,id,$2,0,$3 FROM gl_accounts WHERE code='2500'`,
      [journal.id,`Payroll and insurance payable ${batch.batch_no}`,Number(batch.total_gross)-Number(sums.tax)]);
    await client.query(`INSERT INTO hr_payroll_accounting_exports(batch_id,export_no,payroll_expense,employee_payable,tax_payable,insurance_payable,journal_entry_id,status,posted_at)
      VALUES($1,$2,$3,$4,$5,$6,$7,'POSTED',NOW())`,[batch.id,exportNo,batch.total_gross,batch.total_net,sums.tax,sums.insurance,journal.id]);
    const row=(await client.query("UPDATE hr_payroll_batches SET status='LOCKED',paid_at=NOW(),locked_at=NOW(),updated_at=NOW() WHERE id=$1 RETURNING *",[batch.id])).rows[0];
    await client.query("UPDATE salary_records SET status='paid',paid_at=NOW(),updated_at=NOW() WHERE year=$1 AND month=$2",[batch.year,batch.month]);
    await client.query(`INSERT INTO hr_payroll_audit(batch_id,event_type,actor,detail)VALUES($1,'BATCH_LOCKED',$2,$3)`,
      [batch.id,String(p.actor??"FINANCE"),JSON.stringify({exportNo})]);
    await client.query("COMMIT");res.json(mutateEnvelope(row));
  }catch(error){await client.query("ROLLBACK").catch(()=>{});res.status(409).json(errorEnvelope("PAYROLL_CLOSE_FAILED",error.message));}finally{client.release();}
});

