api.get("/hr/employees/:code", requirePermission("hr.view"), async (req, res) => {
  try {
    const emp = (await query(
      `SELECT e.id, e.code, e.display_name AS "displayName",
              COALESCE(NULLIF(e.name_zh,''), e.full_name_zh) AS name_zh,
              COALESCE(NULLIF(e.name_en,''), e.full_name_en) AS name_en,
              COALESCE(NULLIF(e.name_vi,''), e.full_name_vi) AS name_vi,
              e.gender, e.phone, e.email, e.hire_date AS "hireDate",
              e.date_of_birth AS "dateOfBirth", e.id_card_no AS "idCardNo", e.address,
              e.status, e.termination_date AS "terminationDate",
              d.id AS "departmentId", d.code AS "departmentCode",
              d.name_zh AS "departmentNameZh", d.name_en AS "departmentNameEn", d.name_vi AS "departmentNameVi",
              p.id AS "positionId", p.name_zh AS "positionTitleZh",
              p.name_en AS "positionTitleEn", p.name_vi AS "positionTitleVi",
              p.level AS "positionLevel",
              m.id AS "managerId", m.full_name_zh AS "managerNameZh",
              m.full_name_en AS "managerNameEn", m.full_name_vi AS "managerNameVi"
       FROM employees e
       JOIN departments d ON d.id = e.department_id
       JOIN positions p ON p.id = e.position_id
       LEFT JOIN employees m ON m.id = e.reports_to_id
       WHERE e.code = $1`,
      [req.params.code]
    )).rows[0];
    if (!emp) return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));

    const history = (await query(
      `SELECT ewh.id, ewh.event_type AS "eventType", ewh.effective_date AS "effectiveDate",
              ewh.reason,
              fd.code AS "fromDepartmentCode", fd.name_zh AS "fromDepartmentName",
              td.code AS "toDepartmentCode", td.name_zh AS "toDepartmentName",
              fp.name_zh AS "fromPositionTitle", tp.name_zh AS "toPositionTitle"
       FROM employee_work_history ewh
       LEFT JOIN departments fd ON fd.id = ewh.from_department_id
       LEFT JOIN departments td ON td.id = ewh.to_department_id
       LEFT JOIN positions fp ON fp.id = ewh.from_position_id
       LEFT JOIN positions tp ON tp.id = ewh.to_position_id
       WHERE ewh.employee_id = $1
       ORDER BY ewh.effective_date DESC`,
      [emp.id]
    )).rows;

    res.json(envelope({ ...emp, workHistory: history }));
  } catch (err) {
    console.error("GET /hr/employees/:code:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

