// ── HR Attendance Stats & Rules ──────────────────────────────────────

// GET /hr/attendance
api.get("/hr/attendance", requirePermission("hr.view"), async (req, res) => {
  try {
    const { date, employeeId, limit = 500, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    let idx = 1;
    if (date) {
      conditions.push(`a.date = $${idx++}`);
      params.push(date);
    }
    if (employeeId) {
      conditions.push(`a.employee_id = $${idx++}`);
      params.push(Number(employeeId));
    }
    const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
    const total = await query(`SELECT count(*)::int AS total FROM attendance_records a ${where}`, params);
    const data = await query(
      `SELECT a.id, a.date, a.clock_in AS "clockIn", a.clock_out AS "clockOut", a.status,
              e.code AS "employeeCode",
              COALESCE(NULLIF(e.name_zh,''), e.full_name_zh, e.full_name) AS "employeeNameZh",
              d.name_zh AS "departmentName", p.name_zh AS "positionTitle"
       FROM attendance_records a
       JOIN employees e ON e.id = a.employee_id
       LEFT JOIN departments d ON d.id = e.department_id
       LEFT JOIN positions p ON p.id = e.position_id
       ${where}
       ORDER BY a.date DESC, e.code
       LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)],
    );
    res.json(listEnvelope(data.rows, total.rows[0]?.total ?? 0));
  } catch (err) {
    console.error("GET /hr/attendance:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/attendance/stats
api.get("/hr/attendance/stats", requirePermission("hr.view"), async (req, res) => {
  try {
    const { employee_id, year, month } = req.query;
    let sql = `SELECT s.*, e.name_zh AS emp_name, e.employee_no, d.name_zh AS dept_name
               FROM hr_attendance_monthly_stats s
               LEFT JOIN employees e ON e.id = s.employee_id
               LEFT JOIN departments d ON d.id = e.department_id
               WHERE 1=1`;
    const params = [];
    if (employee_id) { params.push(Number(employee_id)); sql += ` AND s.employee_id = $${params.length}`; }
    if (year) { params.push(Number(year)); sql += ` AND s.year = $${params.length}`; }
    if (month) { params.push(Number(month)); sql += ` AND s.month = $${params.length}`; }
    sql += " ORDER BY s.year DESC, s.month DESC, e.department_id";
    const rows = await query(sql, params);
    res.json(listEnvelope(rows.rows));
  } catch (err) {
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /hr/attendance/stats/compute
api.post("/hr/attendance/stats/compute", requirePermission("hr.edit"), async (req, res) => {
  try {
    const { year, month } = req.body;
    if (!year || !month) return res.status(400).json(errorEnvelope("VALIDATION_ERROR", "year and month required"));
    // Aggregate from hr_attendance_records -> hr_attendance_monthly_stats
    const upsert = `INSERT INTO hr_attendance_monthly_stats
      (employee_id, year, month, normal_days, absent_days, late_count, late_minutes,
       early_count, early_minutes, ot_hours, leave_days, holiday_days, work_days, attendance_rate, punctuality_rate)
    SELECT
      employee_id, $1, $2,
      count(CASE WHEN status = 'normal' THEN 1 END)::numeric,
      count(CASE WHEN status = 'absent' THEN 1 END)::numeric,
      count(CASE WHEN status = 'late' THEN 1 END),
      coalesce(sum(late_minutes),0),
      count(CASE WHEN status = 'early' THEN 1 END),
      coalesce(sum(early_minutes),0),
      coalesce(sum(ot_hours),0),
      count(CASE WHEN status = 'leave' THEN 1 END)::numeric,
      count(CASE WHEN status = 'holiday' THEN 1 END)::numeric,
      count(CASE WHEN status NOT IN ('absent') THEN 1 END)::numeric,
      round(count(CASE WHEN status NOT IN ('absent','leave') THEN 1 END)::numeric * 100 / nullif(count(*),0), 2),
      round(count(CASE WHEN status NOT IN ('late','early','absent','leave') THEN 1 END)::numeric * 100 / nullif(count(*),0), 2)
    FROM hr_attendance_records
    WHERE work_date >= DATE_TRUNC('month', DATE '$1-$2-01')
      AND work_date < DATE_TRUNC('month', DATE '$1-$2-01') + INTERVAL '1 month'
    GROUP BY employee_id
    ON CONFLICT(employee_id, year, month) DO UPDATE SET
      normal_days = EXCLUDED.normal_days, absent_days = EXCLUDED.absent_days,
      late_count = EXCLUDED.late_count, late_minutes = EXCLUDED.late_minutes,
      early_count = EXCLUDED.early_count, early_minutes = EXCLUDED.early_minutes,
      ot_hours = EXCLUDED.ot_hours, leave_days = EXCLUDED.leave_days,
      holiday_days = EXCLUDED.holiday_days, work_days = EXCLUDED.work_days,
      attendance_rate = EXCLUDED.attendance_rate, punctuality_rate = EXCLUDED.punctuality_rate,
      computed_at = now()`;
    await query(upsert, [String(year), String(month).padStart(2,'0')]);
    res.json({ success: true, message: `Attendance stats computed for ${year}-${month}` });
  } catch (err) {
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

