// POST /hr/onboarding/employees/:empId/start
api.post("/hr/onboarding/employees/:empId/start", requirePermission("hr.edit"), async (req, res) => {
  try {
    const { template_id, join_date, mentor_id } = req.body;
    const empId = Number(req.params.empId);
    const joinDt = join_date || new Date().toISOString().slice(0, 10);
    const onb = await query(
      `INSERT INTO hr_employee_onboarding (employee_id, template_id, join_date, mentor_id)
       VALUES ($1,$2,$3,$4) RETURNING *`,
      [empId, template_id ? Number(template_id) : null, joinDt, mentor_id ? Number(mentor_id) : null]
    );
    const onbId = onb.rows[0].id;
    if (template_id) {
      const tasks = await query(`SELECT * FROM hr_onboarding_template_tasks WHERE template_id = $1 ORDER BY sort_order`, [Number(template_id)]);
      for (const task of tasks.rows) {
        const dueDate = new Date(joinDt);
        dueDate.setDate(dueDate.getDate() + task.due_days);
        await query(
          `INSERT INTO hr_onboarding_task_instances (onboarding_id, template_task_id, task_name_zh, task_category, assignee_role, due_date)
           VALUES ($1,$2,$3,$4,$5,$6)`,
          [onbId, task.id, task.task_name_zh, task.task_category, task.assignee_role, dueDate.toISOString().slice(0,10)]
        );
      }
    }
    await query(`UPDATE employees SET status = 'probation' WHERE id = $1`, [empId]);
    res.json(envelope(onb.rows[0]));
  } catch (err) {
    if (err.code === '23505') return res.status(409).json(errorEnvelope("DUPLICATE", "Onboarding already started"));
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// PATCH /hr/onboarding/tasks/:id/complete
api.patch("/hr/onboarding/tasks/:id/complete", requirePermission("hr.edit"), async (req, res) => {
  try {
    const { remarks } = req.body;
    const result = await query(
      `UPDATE hr_onboarding_task_instances SET status = 'completed', completed_at = now(), remarks = COALESCE($1, remarks)
       WHERE id = $2 RETURNING *`,
      [remarks, Number(req.params.id)]
    );
    if (!result.rows[0]) return res.status(404).json(errorEnvelope("NOT_FOUND"));
    const pending = await query(`SELECT count(*) AS cnt FROM hr_onboarding_task_instances WHERE onboarding_id = $1 AND status = 'pending' AND is_mandatory = true`, [result.rows[0].onboarding_id]);
    if (Number(pending.rows[0].cnt) === 0) {
      await query(`UPDATE hr_employee_onboarding SET overall_status = 'completed', completed_at = now() WHERE id = $1`, [result.rows[0].onboarding_id]);
    }
    res.json(envelope(result.rows[0]));
  } catch (err) {
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

