// ── MES Stagnation Tracking ───────────────────────────────────────────

// GET /mes/stagnation - Get stagnation logs
// Mirrors the Excel 产品呆滞管控 sheet filter layout:
//   Customer · Model · From Station · To Station · Overdue Months · Line · PO
const retiredDuplicateStagnationListHandler = async (req, res) => {
  try {
    const {
      status, level, lineCode, stationCode,
      customer, model,
      fromStation, toStation,
      overdueMonthsMin,
      poNumber,
      limit = 500, offset = 0,
    } = req.query;
    const conditions = ["1=1"];
    const params = [];
    let idx = 1;
    if (status)      { conditions.push(`psl.status = $${idx++}`);         params.push(status); }
    if (level)       { conditions.push(`psl.stagnation_level = $${idx++}`); params.push(level); }
    if (lineCode)    { conditions.push(`psl.line_code = $${idx++}`);        params.push(lineCode); }
    if (stationCode) { conditions.push(`psl.station_code = $${idx++}`);     params.push(stationCode); }
    if (customer)    { conditions.push(`psl.customer_code ILIKE $${idx++}`); params.push(`%${customer}%`); }
    if (model)       { conditions.push(`psl.product_model ILIKE $${idx++}`); params.push(`%${model}%`); }
    if (fromStation) { conditions.push(`fs.code ILIKE $${idx++}`);          params.push(`%${fromStation}%`); }
    if (toStation)   { conditions.push(`ts.code ILIKE $${idx++}`);          params.push(`%${toStation}%`); }
    if (overdueMonthsMin) {
      const minMinutes = Number(overdueMonthsMin) * 30 * 24 * 60;
      conditions.push(`psl.stagnation_minutes >= $${idx++}`); params.push(minMinutes);
    }
    if (poNumber) { conditions.push(`wo.code ILIKE $${idx++}`); params.push(`%${poNumber}%`); }
    const where = "WHERE " + conditions.join(" AND ");
    const data = await query(
      `SELECT psl.id, psl.sn, psl.pcb_no, psl.station_code, psl.line_code,
              psl.stagnation_minutes, psl.stagnation_level, psl.status,
              psl.customer_code, psl.product_model, psl.laser_qr_date,
              psl.created_at, psl.resolved_at, psl.notes,
              wo.code  AS "workOrderCode",
              fs.code  AS "fromStationCode",
              ts.code  AS "toStationCode",
              -- Excel column H: overdue time in months (stagnation_minutes / 30days)
              ROUND(psl.stagnation_minutes::numeric / (30.0 * 24 * 60), 1) AS "overdueMonths",
              -- WH location: placeholder until PCB warehouse-location tracking is implemented
              'N/A'  AS "whLocation"
       FROM product_stagnation_logs psl
       LEFT JOIN work_orders     wo  ON wo.id  = psl.work_order_id
       LEFT JOIN stations        fs  ON fs.id  = psl.from_station_id
       LEFT JOIN stations        ts  ON ts.id  = psl.to_station_id
       ${where}
       ORDER BY psl.stagnation_minutes DESC, psl.created_at DESC
       LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)]
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /mes/stagnation:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
};

// GET /mes/stagnation/alerts - Get active alerts
app.get("/mes/stagnation/alerts", requirePermission("mes.view"), async (req, res) => {
  try {
    const { lineCode } = req.query;
    const conditions = ["psl.status = 'open'"];
    const params = [];
    let idx = 1;
    if (lineCode) { conditions.push(`psl.line_code = $${idx++}`); params.push(lineCode); }
    const where = "WHERE " + conditions.join(" AND ");
    const data = await query(
      `SELECT psl.id, psl.sn, psl.pcb_no, psl.station_code, psl.line_code,
              psl.stagnation_minutes, psl.stagnation_level, psl.status,
              psl.customer_code, psl.product_model, psl.laser_qr_date,
              psl.created_at,
              wo.code AS "workOrderCode",
              st.warning_minutes, st.alert_minutes, st.critical_minutes
       FROM product_stagnation_logs psl
       LEFT JOIN work_orders wo ON wo.id = psl.work_order_id
       LEFT JOIN stagnation_thresholds st ON st.station_code = psl.station_code
       ${where}
       ORDER BY
         CASE psl.stagnation_level
           WHEN 'critical' THEN 1
           WHEN 'alert' THEN 2
           WHEN 'warning' THEN 3
           ELSE 4
         END,
         psl.stagnation_minutes DESC`
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /mes/stagnation/alerts:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

