// GET /mes/station-flow - Get station flow records
app.get("/mes/station-flow", requirePermission("mes.view"), async (req, res) => {
  try {
    const { sn, pcbNo, lineCode, fromDate, toDate, limit = 200, offset = 0 } = req.query;
    const conditions = ["1=1"];
    const params = [];
    let idx = 1;
    if (sn) { conditions.push(`sfr.sn = $${idx++}`); params.push(sn); }
    if (pcbNo) { conditions.push(`sfr.pcb_no = $${idx++}`); params.push(pcbNo); }
    if (lineCode) { conditions.push(`sfr.line_code = $${idx++}`); params.push(lineCode); }
    if (fromDate) { conditions.push(`sfr.arrival_time >= $${idx++}`); params.push(fromDate); }
    if (toDate) { conditions.push(`sfr.arrival_time <= $${idx++}`); params.push(toDate); }
    const where = "WHERE " + conditions.join(" AND ");
    const data = await query(
      `SELECT sfr.id, sfr.sn, sfr.pcb_no, sfr.station_code, sfr.station_type, sfr.line_code,
              sfr.event_type, sfr.arrival_time, sfr.departure_time, sfr.dwell_minutes,
              sfr.is_stagnation, sfr.stagnation_level, sfr.result,
              sfr.operator_name, sfr.machine_code, sfr.next_station_code,
              sfr.product_model, sfr.po_number, sfr.quality_check_result,
              wo.code AS "workOrderCode"
       FROM station_flow_records sfr
       LEFT JOIN work_orders wo ON wo.id = sfr.work_order_id
       ${where}
       ORDER BY sfr.arrival_time ASC
       LIMIT $${idx} OFFSET $${idx + 1}`,
      [...params, Number(limit), Number(offset)]
    );
    res.json(listEnvelope(data.rows));
  } catch (err) {
    console.error("GET /mes/station-flow:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /mes/trace/:sn - Full traceability by SN
app.get("/mes/trace/:sn", requirePermission("mes.view"), async (req, res) => {
  try {
    const { sn } = req.params;
    // Get PCB info
    const pcb = (await query(
      `SELECT ps.id, ps.serial_no AS "serialNo", ps.pcb_no, ps.status,
              wo.code AS "workOrderCode", wo.planned_qty, wo.completed_qty,
              p.code AS "productCode", p.name_zh AS "productName",
              pl.internal_code AS "lineCode"
       FROM pcb_serials ps
       LEFT JOIN work_orders wo ON wo.id = ps.work_order_id
       LEFT JOIN products p ON p.id = wo.product_id
       LEFT JOIN production_lines pl ON pl.id = wo.line_id
       WHERE ps.serial_no = $1`,
      [sn]
    )).rows[0];

    if (!pcb) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "PCB serial not found"));
    }

    // Get station flow
    const flow = (await query(
      `SELECT sfr.id, sfr.station_code, sfr.station_type, sfr.line_code,
              sfr.event_type, sfr.arrival_time, sfr.departure_time, sfr.dwell_minutes,
              sfr.is_stagnation, sfr.stagnation_level, sfr.result,
              sfr.operator_name, sfr.machine_code, sfr.quality_check_result,
              sfr.pcb_no, sfr.laser_qr_date,
              wo.code AS "workOrderCode"
       FROM station_flow_records sfr
       LEFT JOIN work_orders wo ON wo.id = sfr.work_order_id
       WHERE sfr.sn = $1
       ORDER BY sfr.arrival_time ASC`,
      [sn]
    )).rows;

    // Get stagnation logs
    const stagnation = (await query(
      `SELECT id, station_code, line_code, stagnation_minutes, stagnation_level, status, created_at
       FROM product_stagnation_logs
       WHERE sn = $1 AND status = 'open'
       ORDER BY created_at DESC`,
      [sn]
    )).rows;

    // Get scrap records
    const scraps = (await query(
      `SELECT id, scrap_station, line_code, scrap_reason_code, scrap_reason_detail, responsible_person, status, created_at
       FROM product_scraps
       WHERE sn = $1
       ORDER BY created_at DESC`,
      [sn]
    )).rows;

    res.json(envelope({ pcb, flow, stagnation, scraps }));
  } catch (err) {
    console.error("GET /mes/trace/:sn:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /mes/events/upstream-check/:pcbSerial?stationCode=XXX
// Returns NG/duplicate history from upstream stations for a given SN.
// Used by downstream stations to catch boards that already failed upstream.
app.get("/mes/events/upstream-check/:pcbSerial", async (req, res) => {
  try {
    const { pcbSerial } = req.params;
    const requestedStationCode = req.query.stationCode;
    const requestedLineCode = req.query.lineCode || 'L004';
    const stationCode = canonicalStationCode(requestedStationCode, requestedLineCode);

    if (!stationCode) {
      return res.status(400).json(errorEnvelope("VALIDATION", "stationCode query param required"));
    }

    // 1. Look up this station's line and sequence order
    const seqR = await query(
      `SELECT ss.sequence_order, ss.line_code, ss.parent_line_code,
              pl.name_zh AS line_name_zh
       FROM station_sequences ss
       LEFT JOIN production_lines pl ON pl.internal_code = ss.line_code
       WHERE ss.station_code = $1`,
      [stationCode],
    );
    if (seqR.rows.length === 0) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", `Station '${stationCode}' not in station_sequences`));
    }
    const { sequence_order, line_code, parent_line_code, line_name_zh } = seqR.rows[0];

    // 2. Build list of upstream station codes:
    //    - Same line with sequence_order < current
    //    - Parent line (all stations)
    const upstreamCodes = [];
    if (parent_line_code) {
      const parentStations = await query(
        `SELECT station_code FROM station_sequences WHERE line_code = $1`,
        [parent_line_code],
      );
      upstreamCodes.push(...parentStations.rows.map(r => r.station_code));
    }
    const sameLineUpstream = await query(
      `SELECT station_code FROM station_sequences
       WHERE line_code = $1 AND sequence_order < $2`,
      [line_code, sequence_order],
    );
    upstreamCodes.push(...sameLineUpstream.rows.map(r => r.station_code));

    if (upstreamCodes.length === 0) {
      return res.json(envelope({ hasNg: false, hasPass: false, upstreamEvents: [], stationCode, pcbSerial, hasDuplicate: false }));
    }

    // 3. Look up PCB id for this serial
    const pcbR = await query(`SELECT id FROM pcb_serials WHERE serial_no = $1`, [pcbSerial]);
    const pcbId = pcbR.rows[0]?.id;

    if (!pcbId) {
      return res.json(envelope({ hasNg: false, hasPass: false, upstreamEvents: [], stationCode, pcbSerial, note: "SN not yet registered", hasDuplicate: false }));
    }

    // Look up stationId for the current station (needed for failCount query)
    const stationR = await query(`SELECT id FROM stations WHERE code = $1`, [stationCode]);
    const stationId = stationR.rows[0]?.id;

    // 4. Get all station_events for this SN from upstream stations
    const eventsR = await query(
      `SELECT se.id, se.event_type AS "eventType", se.result,
              se.occurred_at AS "occurredAt", se.traceability_key AS "traceKey",
              s.code AS "stationCode", ss.sequence_order,
              u.display_name AS "operatorName"
       FROM station_events se
       JOIN stations s ON s.id = se.station_id
       JOIN station_sequences ss ON ss.station_code = s.code
       LEFT JOIN users u ON u.id = se.operator_id
       WHERE se.pcb_serial_id = $1
         AND s.code = ANY($2::varchar[])
       ORDER BY ss.sequence_order ASC`,
      [pcbId, upstreamCodes],
    );

    const upstreamEvents = eventsR.rows;

    // Enrich fail events with repair_status from ng_defect_records
    if (upstreamEvents.some(e => e.result === 'fail')) {
      const sn = pcbSerial;
      const ngR = await query(
        `SELECT station_code, repair_status FROM ng_defect_records
         WHERE sn = $1 AND result = 'fail' AND station_code = ANY($2::varchar[])
         ORDER BY occurred_at DESC`,
        [sn, upstreamCodes],
      );
      // Map station_code -> repair_status (most recent per station)
      const statusMap = {};
      for (const row of ngR.rows) {
        if (!statusMap[row.station_code]) statusMap[row.station_code] = row.repair_status;
      }
      for (const evt of upstreamEvents) {
        if (evt.result === 'fail') {
          evt.repairStatus = statusMap[evt.stationCode] ?? 'pending';
        }
      }
    }

    // 5. Check for PENDING NG records — only pending NG blocks downstream entry (repaired/scrapped are cleared)
    let pendingNgCount = 0;
    if (pcbId) {
      const ngR = await query(
        `SELECT COUNT(*) AS cnt FROM ng_defect_records
         WHERE sn = (SELECT serial_no FROM pcb_serials WHERE id = $1)
           AND station_code = ANY($2::varchar[])
           AND repair_status = 'pending'`,
        [pcbId, upstreamCodes],
      );
      pendingNgCount = parseInt(ngR.rows[0]?.cnt ?? "0", 10);
    }
    const hasNg   = pendingNgCount > 0;
    const hasPass = upstreamEvents.some(e => e.result === 'pass');

    // Retest enforcement: count FAIL events at THIS station (ICT/FCT rule: 2 fails → must repair)
    // Query separately because upstreamEvents only contains events from UPSTREAM stations
    let thisStationFailCount = 0;
    if (pcbId && stationId) {
      const thisStationR = await query(
        `SELECT COUNT(*) AS cnt FROM station_events
         WHERE pcb_serial_id = $1 AND station_id = $2 AND result = 'fail'`,
        [pcbId, stationId],
      );
      thisStationFailCount = parseInt(thisStationR.rows[0]?.cnt ?? "0", 10);
    }
    const mustRepair = thisStationFailCount >= 2;

    // Check for duplicate SN attempts in sn_duplicate_attempts
    let hasDuplicate = false;
    let duplicateInfo = null;
    if (pcbSerial) {
      const dupR = await query(
        `SELECT id, station_code, action, decision, operator, attempted_at AS occurred_at
         FROM sn_duplicate_attempts
         WHERE sn = $1 AND station_code = ANY($2::varchar[])
         ORDER BY attempted_at DESC LIMIT 1`,
        [pcbSerial, upstreamCodes],
      );
      if (dupR.rows.length > 0) {
        hasDuplicate = true;
        duplicateInfo = dupR.rows[0];
      }
    }

    res.json(envelope({
      hasNg,
      hasPass,
      upstreamEvents,
      stationCode,
      lineCode: line_code,
      lineName: line_name_zh,
      pcbSerial,
      upstreamStationCodes: upstreamCodes,
      verdict: hasNg ? "BLOCK_NG" : hasPass ? "OK" : "UNKNOWN",
      // Retest tracking
      failCount: thisStationFailCount,
      mustRepair,
      // Repair workflow: number of pending NG records blocking this board
      pendingNgCount,
      // Duplicate SN tracking
      hasDuplicate,
      duplicateInfo,
    }));
  } catch (err) {
    console.error("GET /mes/events/upstream-check:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

