app.post("/mes/material-feeder-assignments", requirePermission("mes.execute"), async (req, res) => {
  try {
    const p = req.body?.payload ?? req.body ?? {};
    const required = ["lineCode", "machineCode", "channelCode", "slotNo", "feederCode", "materialCode"];
    const missing = required.filter((key) => !String(p[key] ?? "").trim());
    if (missing.length) return res.status(400).json(errorEnvelope("VALIDATION", `${missing.join(", ")} required`));
    const result = await query(
      `INSERT INTO mes_material_feeder_assignments
       (line_code,machine_code,channel_code,slot_no,feeder_code,material_code,work_order_code,created_by)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id`,
      [p.lineCode, p.machineCode, p.channelCode, p.slotNo, p.feederCode, p.materialCode, p.workOrderCode || null, req.user?.username || "MES"]
    );
    res.status(201).json({ item: { id: result.rows[0].id } });
  } catch (err) {
    console.error("POST /mes/material-feeder-assignments:", err.message);
    res.status(409).json(errorEnvelope("ASSIGNMENT_CONFLICT", err.message));
  }
});

// POST /mes/fool-proof-rules
app.post("/mes/fool-proof-rules", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { stationId, lineId, feederSlot, materialId, materialReelCode, ruleType, notes } = req.body?.payload ?? {};
    if (!stationId || !feederSlot) {
      return res.status(400).json(errorEnvelope("VALIDATION", "stationId and feederSlot required"));
    }
    const result = await query(
      `INSERT INTO fool_proof_rules (station_id, line_id, feeder_slot, material_id, material_reel_code, rule_type, notes, created_by)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
       RETURNING id`,
      [stationId, lineId || null, feederSlot, materialId || null, materialReelCode || null, ruleType || 'material', notes || null, req.user?.username]
    );
    res.status(201).json(mutateEnvelope({ id: result.rows[0].id }));
  } catch (err) {
    if (err.code === "23505") return res.status(409).json(errorEnvelope("CONFLICT", "Rule already exists for this station+slot"));
    console.error("POST /mes/fool-proof-rules:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// PATCH /mes/fool-proof-rules/:id
app.patch("/mes/fool-proof-rules/:id", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const { materialId, materialReelCode, ruleType, status, notes } = req.body?.payload ?? {};
    const fields = [];
    const vals = [];
    let idx = 1;
    if (materialId       !== undefined) { fields.push(`material_id = $${idx++}`);       vals.push(materialId); }
    if (materialReelCode !== undefined) { fields.push(`material_reel_code = $${idx++}`); vals.push(materialReelCode); }
    if (ruleType         !== undefined) { fields.push(`rule_type = $${idx++}`);           vals.push(ruleType); }
    if (status           !== undefined) { fields.push(`status = $${idx++}`);              vals.push(status); }
    if (notes            !== undefined) { fields.push(`notes = $${idx++}`);               vals.push(notes); }
    fields.push(`updated_at = now()`);
    vals.push(Number(id));
    const result = await query(
      `UPDATE fool_proof_rules SET ${fields.join(", ")} WHERE id = $${idx} RETURNING id`,
      vals
    );
    if (!result.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Rule not found"));
    res.json(mutateEnvelope({ id: Number(id) }));
  } catch (err) {
    console.error("PATCH /mes/fool-proof-rules:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// DELETE /mes/fool-proof-rules/:id
app.delete("/mes/fool-proof-rules/:id", requirePermission("mes.execute"), async (req, res) => {
  try {
    const { id } = req.params;
    const result = await query(`DELETE FROM fool_proof_rules WHERE id = $1 RETURNING id`, [Number(id)]);
    if (!result.rows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Rule not found"));
    res.json(mutateEnvelope({ id: Number(id), deleted: true }));
  } catch (err) {
    console.error("DELETE /mes/fool-proof-rules:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

