// POST /api/sql — execute raw SQL against GM_WareHouse
// Body: { sql: string }
// Returns: { columns: string[], rows[], rowCount, duration }
api.post("/sql", async (req, res) => {
  try {
    const { sql } = req.body ?? {};
    if (!sql?.trim()) {
      return res.status(400).json({ error: { code: "BAD_REQUEST", message: "sql is required" } });
    }
    const trimmed = sql.trim();
    const start = Date.now();

    // Detect query type
    const firstWord = trimmed.split(/\s+/)[0].toUpperCase();
    const isSelect = firstWord === "SELECT";

    if (isSelect) {
      const rows = await sqlQuery(trimmed);
      const duration = Date.now() - start;
      res.json({
        columns: rows.length > 0 ? Object.keys(rows[0]) : [],
        rows,
        rowCount: rows.length,
        duration,
        type: "SELECT",
      });
    } else {
      // INSERT/UPDATE/DELETE/EXEC — use TDS rowcount
      const conn = (await import("mssql")).default;
      const pool = await conn.connect({
        server: "192.168.0.110",
        port: 1433,
        user: "sa",
        password: "abc@123",
        database: "GM_WareHouse",
        options: { encrypt: false, trustServerCertificate: true },
      });
      const result = await pool.request().query(trimmed);
      await pool.close();
      const duration = Date.now() - start;
      res.json({
        columns: [],
        rows: [],
        rowCount: result.rowsAffected[0] ?? 0,
        duration,
        type: firstWord,
        message: `${firstWord} — ${result.rowsAffected[0]} row(s) affected`,
      });
    }
  } catch (err) {
    console.error("POST /api/sql:", err.message);
    res.status(500).json({ error: { code: "SERVER_ERROR", message: err.message } });
  }
});

// GET /api/shelf/racks — 2 racks × 2 sides × 700 bins, with occupancy from Sys_CellsInfo
// Returns: { racks: [{ code, side, bins: [{binCode, row, col, occupied, serialNumber, materialCode}]}] }
api.get("/shelf/racks", async (req, res) => {
  try {
    // Fetch all bins ordered by side + bin number
    const allBins = await sqlQuery(`
      SELECT F_BinCode AS binCode, F_IsLock AS isLock
      FROM T_BASE_BIN
      ORDER BY F_BinCode
    `);

    // Fetch all cell data keyed by position
    const allCells = await sqlQuery(`
      SELECT Area, Colu, Layer, Point, SerialNumber, MaterialCode, Used
      FROM Sys_CellsInfo
      ORDER BY Area, Layer, Point
    `);

    // Map side prefix → area number(s)
    const SIDE_TO_AREAS = {
      L001A: [1],
      L001B: [2],
      L002A: [3],
      L002B: [4],
      L003A: [5],
      L003B: [6],
    };

    // Build cells-by-side: side → sorted cells array
    const cellsBySide = new Map();
    for (const [side, areas] of Object.entries(SIDE_TO_AREAS)) {
      cellsBySide.set(side, allCells.filter((c) => areas.includes(c.Area)));
    }

    // 700 bins per side → 100 cols × 7 layers (matches physical layout)
    const COLS = 100;
    const ROWS = 7;

    // For each side, pair bins with cells by position index
    const racks = [];
    for (const [side, sideCells] of cellsBySide.entries()) {
      const sideBins = allBins.filter((b) => b.binCode.startsWith(side));
      const bins = sideBins.map((bin, i) => {
        const row = Math.floor(i / COLS);
        const col = i % COLS;
        const cell = sideCells[i]; // positional match
        return {
          binCode: bin.binCode,
          row,
          col,
          occupied: cell != null && cell.Used === 3,
          serialNumber: cell && cell.SerialNumber || null,
          materialCode: cell && cell.MaterialCode || null,
          area: cell && cell.Area || null,
        };
      });
      const rackCode = side.slice(0, 4); // L001 or L002
      const rackSide = side.endsWith("A") ? "A" : "B";
      const existing = racks.find((r) => r.code === rackCode);
      if (existing) {
        existing.sides.push({ code: side, side: rackSide, bins });
      } else {
        racks.push({ code: rackCode, sides: [{ code: side, side: rackSide, bins }] });
      }
    }

    // Sort racks and sides
    racks.sort((a, b) => a.code.localeCompare(b.code));
    for (const rack of racks) {
      (rack).sides.sort((a, b) => a.side.localeCompare(b.side));
    }

    res.json(envelope({ racks, stats: { totalBins: allBins.length, totalCells: allCells.length } }));
  } catch (err) {
    console.error("GET /api/shelf/racks:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});


// GET /mes/heartbeats/stream — SSE stream of all station heartbeats, updated every 10s
app.get("/mes/heartbeats/stream", (req, res) => {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();

  const send = async () => {
    try {
      const now = Date.now();
      const WARN_MS = 30_000, DEAD_MS = 60_000;
      const rows = (await query(`
        SELECT sh.station_code AS "stationCode", sh.last_seen AS "lastSeen",
               sh.line_code AS "lineCode", sh.last_operator AS "lastOperator",
               ss.sequence_order AS "sequenceOrder"
        FROM station_heartbeats sh
        LEFT JOIN station_sequences ss ON ss.station_code = sh.station_code
        ORDER BY sh.line_code NULLS LAST, ss.sequence_order NULLS LAST, sh.station_code
      `)).rows;
      const heartbeats = rows.map(r => {
        const elapsed = now - new Date(r.lastSeen).getTime();
        const status = elapsed > DEAD_MS ? 'dead' : elapsed > WARN_MS ? 'warning' : 'alive';
        return { ...r, status, elapsedMs: elapsed };
      });
      const byLine = {};
      for (const h of heartbeats) {
        const lc = h.lineCode ?? 'unknown';
        if (!byLine[lc]) byLine[lc] = { alive: 0, warning: 0, dead: 0 };
        byLine[lc][h.status]++;
      }
      res.write(`data: ${JSON.stringify({ heartbeats, byLine, total: heartbeats.length, now: new Date(now).toISOString() })}

`);
    } catch { /* client may be gone */ }
  };

  send();
  const interval = setInterval(send, 10_000);
  const heartbeat_comment = setInterval(() => { try { res.write(": heartbeat\n"); } catch (_) { /* client gone */ } }, 25_000);
  req.on("close", () => { clearInterval(interval); clearInterval(heartbeat_comment); });
});

