// ── Shift Swap ──────────────────────────────────────────────────────
api.get("/hr/swap/requests", async (req) => {
  const { status, requester_id, date_from, date_to } = req.query;
  let sql = `SELECT r.*,
    e1.name_zh as requester_name_zh, e1.employee_no as requester_emp_no,
    e2.name_zh as swap_partner_name_zh
    FROM hr_shift_swap_requests r
    LEFT JOIN hr_employees e1 ON r.requester_id=e1.id
    LEFT JOIN hr_employees e2 ON r.swap_partner_id=e2.id
    WHERE 1=1`;
  const params = [];
  if (status) { sql += ` AND r.status=$${params.length+1}`; params.push(status); }
  if (requester_id) { sql += ` AND r.requester_id=$${params.length+1}`; params.push(Number(requester_id)); }
  if (date_from) { sql += ` AND r.original_shift_date>=$${params.length+1}`; params.push(date_from); }
  if (date_to) { sql += ` AND r.original_shift_date<=$${params.length+1}`; params.push(date_to); }
  sql += ` ORDER BY r.created_at DESC`;
  return db.query(sql, params).then(r => ({ items: r.rows }));
});

