api.post("/hr/skill/ratings", async (req) => {
  const { employee_id, category_id, period_year, period_month, details, rated_by, rater_name } = req.body;
  if (!employee_id || !category_id || !period_year || !period_month) return { error: "缺少必填字段" };
  // Calculate total score
  let total = 0;
  for (const d of (details||[])) {
    total += (d.actual_score || 0) * (d.weight || 1);
  }
  // Determine skill level
  const levelRow = await db.query(
    `SELECT * FROM hr_skill_levels WHERE category_id=$1 AND $2 BETWEEN score_min AND score_max ORDER BY sort_order DESC LIMIT 1`,
    [category_id, total]
  );
  const level = levelRow.rows[0];
  const r = await db.query(
    `INSERT INTO hr_employee_skill_rating (employee_id,category_id,period_year,period_month,total_score,skill_level_id,skill_level_name,rated_by,rated_at,status)
     VALUES ($1,$2,$3,$4,$5,$6,$7,$8,now(),'published')
     ON CONFLICT (employee_id,category_id,period_year,period_month) DO UPDATE SET
       total_score=EXCLUDED.total_score, skill_level_id=EXCLUDED.skill_level_id, skill_level_name=EXCLUDED.skill_level_name,
       rated_by=EXCLUDED.rated_by, rated_at=now(), updated_at=now()
     RETURNING *`,
    [employee_id, category_id, period_year, period_month, total, level?.id||null, level?.level_name_zh||null, rated_by||null, rater_name||'']
  );
  const rating = r.rows[0];
  // Insert details
  if (details && details.length > 0) {
    for (const d of details) {
      await db.query(
        `INSERT INTO hr_skill_rating_details (skill_rating_id,skill_item_id,item_name_zh,max_score,actual_score,weight,weighted_score,data_source,data_value)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
        [rating.id, d.skill_item_id, d.item_name_zh||'', d.max_score||100, d.actual_score||0, d.weight||1, (d.actual_score||0)*(d.weight||1), d.data_source||'manual', d.data_value||null]
      );
    }
  }
  return { item: rating };
});

