api.get("/hr/teamwork/ratings", async (req) => {
  const { employee_id, year, month, dept_id } = req.query;
  let sql = `SELECT r.*, e.name_zh as emp_name, e.employee_no as emp_no FROM hr_employee_teamwork_rating r LEFT JOIN hr_employees e ON r.employee_id=e.id WHERE 1=1`;
  const params = [];
  if (employee_id) { sql += ` AND r.employee_id=$${params.length+1}`; params.push(Number(employee_id)); }
  if (year) { sql += ` AND r.period_year=$${params.length+1}`; params.push(Number(year)); }
  if (month) { sql += ` AND r.period_month=$${params.length+1}`; params.push(Number(month)); }
  sql += ` ORDER BY r.period_year DESC, r.period_month DESC, r.employee_id`;
  return db.query(sql, params).then(r => ({ items: r.rows }));
});

api.post("/hr/teamwork/ratings", async (req) => {
  const { employee_id, period_year, period_month, details, rater_id, rater_name } = req.body;
  if (!employee_id || !period_year || !period_month) return { error: "缺少必填字段" };
  // Calculate overall score and light status
  let total = 0, count = 0;
  for (const d of (details||[])) {
    total += d.metric_score || 0;
    count++;
  }
  const avg = count > 0 ? total / count : 0;
  let light_status = 'green';
  let light_reason = '表现良好';
  if (avg < 60) { light_status = 'red'; light_reason = '多项指标低于标准'; }
  else if (avg < 75) { light_status = 'yellow'; light_reason = '部分指标需改善'; }
  const r = await db.query(
    `INSERT INTO hr_employee_teamwork_rating (employee_id,period_year,period_month,overall_score,light_status,light_reason,rater_id,rater_name,rated_at)
     VALUES ($1,$2,$3,$4,$5,$6,$7,$8,now())
     ON CONFLICT (employee_id,period_year,period_month) DO UPDATE SET
       overall_score=EXCLUDED.overall_score, light_status=EXCLUDED.light_status, light_reason=EXCLUDED.light_reason,
       rater_id=EXCLUDED.rater_id, rater_name=EXCLUDED.rater_name, rated_at=now(), updated_at=now()
     RETURNING *`,
    [employee_id, period_year, period_month, avg, light_status, light_reason, rater_id||null, rater_name||'']
  );
  const rating = r.rows[0];
  // Insert details
  if (details && details.length > 0) {
    for (const d of details) {
      await db.query(
        `INSERT INTO hr_teamwork_rating_details (teamwork_rating_id,metric_id,metric_name_zh,target_value,actual_value,metric_score)
         VALUES ($1,$2,$3,$4,$5,$6)`,
        [rating.id, d.metric_id, d.metric_name_zh||'', d.target_value||0, d.actual_value||0, d.metric_score||0]
      );
    }
  }
  return { item: rating };
});

