// ── Helpers for HR ─────────────────────────────────────────────────────
// Returns 'YYYY-MM-DD' in Vietnam timezone (UTC+7), used for work_date
function localDate() {
  const now = new Date();
  const utc = now.getTime() + now.getTimezoneOffset() * 60_000;
  const vn = new Date(utc + 7 * 3600_000);
  return vn.toISOString().split("T")[0];
}

 // GET /hr/employees — list employees with department + position
api.get("/hr/employees", async (req, res) => {
  try {
    const { department_id, status, search } = req.query;
    let sql = `
      SELECT e.id, e.employee_no, e.name_zh, e.name_en, e.name_vi,
             e.gender, e.birth_date, e.phone, e.email,
             e.department_id, d.name_zh AS dept_name_zh, d.name_vi AS dept_name_vi,
             e.position_title, e.employment_type, e.join_date,
             e.probation_end_date, e.status, e.avatar_url
      FROM hr_employees e
      LEFT JOIN hr_departments d ON d.id = e.department_id
      WHERE 1=1
    `;
    const params = [];
    if (department_id) { params.push(department_id); sql += ` AND e.department_id = $${params.length}`; }
    if (status)       { params.push(status);       sql += ` AND e.status = $${params.length}`; }
    if (search)       {
      params.push(`%${search}%`);
      sql += ` AND (e.name_zh ILIKE $${params.length} OR e.name_vi ILIKE $${params.length} OR e.employee_no ILIKE $${params.length})`;
    }
    sql += " ORDER BY e.employee_no";
    const rows = (await query(sql, params)).rows;
    res.json(envelope({ items: rows, total: rows.length }));
  } catch (err) {
    console.error("GET /hr/employees:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

