// POST /hr/employees/:id/avatar — upload employee avatar
const UPLOADS_DIR = path.join(__dirname, "../../apps/web/public/uploads/avatars");

api.post("/hr/employees/:id/avatar", async (req, res) => {
  try {
    // Ensure upload directory exists
    if (!fs.existsSync(UPLOADS_DIR)) fs.mkdirSync(UPLOADS_DIR, { recursive: true });

    const { id } = req.params;

    // Check if employee exists
    const empRows = (await query("SELECT id, code FROM hr_employees WHERE id = $1", [id])).rows;
    if (!empRows.length) return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));

    // Multer-like manual parsing (handle FormData with file)
    // We'll accept base64 or multipart via Busboy — for simplicity, use raw body
    // Client sends base64 in JSON payload
    const { avatar_base64, filename } = req.body || {};
    if (!avatar_base64) return res.status(400).json(errorEnvelope("BAD_REQUEST", "avatar_base64 required"));

    const ext = filename ? filename.split(".").pop() : "jpg";
    const safeExt = ext.replace(/[^a-z0-9]/gi, "").toLowerCase() || "jpg";
    const fileName = `emp_${id}_${Date.now()}.${safeExt}`;
    const filePath = path.join(UPLOADS_DIR, fileName);

    const buffer = Buffer.from(avatar_base64, "base64");
    fs.writeFileSync(filePath, buffer);

    const avatarUrl = `/uploads/avatars/${fileName}`;

    // Update employee record
    await query("UPDATE hr_employees SET avatar_url = $1, updated_at = NOW() WHERE id = $2", [avatarUrl, id]);

    res.json({ data: { item: { employeeId: Number(id), avatar_url: avatarUrl } } });
  } catch (err) {
    console.error("POST /hr/employees/:id/avatar:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/shift-schedules — by date range
// Query: ?date=2026-06-23&employee_id=5
api.get("/hr/shift-schedules", async (req, res) => {
  try {
    const { date, employee_id, department_id } = req.query;
    let sql = `
      SELECT ss.id, ss.employee_id, ss.shift_id, ss.schedule_date, ss.status, ss.remark,
             e.employee_no, e.name_zh, e.name_vi,
             d.id AS dept_id, d.name_zh AS dept_name_zh,
             s.code AS shift_code, s.name_zh AS shift_name_zh, s.name_vi AS shift_name_vi,
             s.start_time, s.end_time, s.night_shift
      FROM hr_shift_schedules ss
      JOIN hr_employees e ON e.id = ss.employee_id
      JOIN hr_shifts s ON s.id = ss.shift_id
      LEFT JOIN hr_departments d ON d.id = e.department_id
      WHERE 1=1
    `;
    const params = [];
    if (date)         { params.push(date);         sql += ` AND ss.schedule_date = $${params.length}`; }
    if (employee_id) { params.push(employee_id);  sql += ` AND ss.employee_id = $${params.length}`; }
    if (department_id) { params.push(department_id); sql += ` AND e.department_id = $${params.length}`; }
    sql += " ORDER BY ss.schedule_date, d.name_zh, e.name_zh";
    const rows = (await query(sql, params)).rows;
    res.json(envelope({ items: rows, total: rows.length }));
  } catch (err) {
    console.error("GET /hr/shift-schedules:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

