// POST /hr/attendance/clock-in
// Body: { employee_id, shift_id? }
// If shift_id omitted, finds today's schedule or defaults to DAY shift
api.post("/hr/attendance/clock-in", async (req, res) => {
  try {
    const { employee_id, shift_id } = req.body ?? {};
    if (!employee_id) return res.status(400).json(errorEnvelope("VALIDATION", "employee_id required"));

    const today = localDate();
    let actualShiftId = shift_id;

    if (!actualShiftId) {
      const sched = (await query(`
        SELECT shift_id FROM hr_shift_schedules
        WHERE employee_id = $1 AND schedule_date = $2
      `, [employee_id, today])).rows[0];
      if (sched) actualShiftId = sched.shift_id;
    }
    if (!actualShiftId) {
      const dayShift = (await query(`SELECT id FROM hr_shifts WHERE code = 'DAY' LIMIT 1`)).rows[0];
      if (dayShift) actualShiftId = dayShift.id;
    }
    if (!actualShiftId) return res.status(400).json(errorEnvelope("VALIDATION", "No shift found for today. Pass shift_id."));

    const toVietnamStr = () => {
      return new Date(Date.now() + 7 * 3600_000).toISOString().slice(0, 19).replace('T', ' ');
    };
    const vnNowStr = toVietnamStr();
    const rows = (await query(`
      INSERT INTO hr_attendance_records (employee_id, shift_id, work_date, clock_in, status)
      VALUES ($1, $2, ($3 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
              ($4 AT TIME ZONE 'Asia/Ho_Chi_Minh')::timestamp, 'normal')
      ON CONFLICT (employee_id, work_date)
        DO UPDATE SET clock_in = COALESCE(hr_attendance_records.clock_in, EXCLUDED.clock_in),
                      shift_id = COALESCE(hr_attendance_records.shift_id, EXCLUDED.shift_id)
      RETURNING
        id, employee_id, shift_id,
        work_date::text        AS work_date,
        TO_CHAR(clock_in, 'YYYY-MM-DD HH24:MI:SS') AS clock_in,
        TO_CHAR(clock_out, 'YYYY-MM-DD HH24:MI:SS') AS clock_out,
        status, actual_work_hours,
        late_minutes, early_minutes, ot_hours, remark,
        created_at::text AS created_at
    `, [employee_id, actualShiftId, today, vnNowStr])).rows;

    res.status(201).json(envelope(rows[0]));
  } catch (err) {
    console.error("POST /hr/attendance/clock-in:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /hr/attendance/clock-out
// Body: { employee_id }
// Computes actual_work_hours, detects late/early, flags OT if beyond shift end
api.post("/hr/attendance/clock-out", async (req, res) => {
  try {
    const { employee_id } = req.body ?? {};
    if (!employee_id) return res.status(400).json(errorEnvelope("VALIDATION", "employee_id required"));

    const today = localDate();
    const toVietnamStr = () => new Date(Date.now() + 7 * 3600_000).toISOString().slice(0, 19).replace('T', ' ');
    const vnNowStr = toVietnamStr();

    const rec = (await query(`
      SELECT a.id, a.employee_id, a.shift_id,
             a.work_date::text AS work_date,
             TO_CHAR(a.clock_in AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD HH24:MI:SS') AS clock_in,
             TO_CHAR(a.clock_out AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD HH24:MI:SS') AS clock_out,
             s.start_time, s.end_time, s.work_hours, s.night_shift, s.break_minutes
      FROM hr_attendance_records a
      JOIN hr_shifts s ON s.id = a.shift_id
      WHERE a.employee_id = $1 AND a.work_date = ($2 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
    `, [employee_id, today])).rows[0];

    if (!rec) return res.status(404).json(errorEnvelope("NOT_FOUND", "No attendance record for today. Clock in first."));

    // Parse as local Vietnam time (no UTC offset)
    const clockIn  = rec.clock_in  ? new Date(`${rec.clock_in}`) : null;
    const clockOut = new Date(Date.now() + 7 * 3600_000);
    let actualHours = 0, lateMinutes = 0, earlyMinutes = 0, otHours = 0;
    let status = rec.status ?? "normal";

    if (clockIn) {
      // Parse shift times in Vietnam timezone: HH:MM:SS → combine with today Vietnam date
      const vnToday = new Date(Date.now() + 7 * 3600_000).toISOString().slice(0, 10);
      const shiftStart = new Date(`${vnToday}T${rec.start_time}:00`);
      const shiftEnd   = new Date(`${vnToday}T${rec.end_time}:00`);
      // Night shift: end is next day
      const endForCalc = rec.night_shift
        ? new Date(new Date(vnToday).getTime() + 86400_000 + (shiftEnd.getTime() - shiftStart.getTime()))
        : shiftEnd;

      const workedMs = clockOut.getTime() - clockIn.getTime();
      const breakMs  = (rec.break_minutes ?? 0) * 60_000;
      actualHours = parseFloat(((workedMs - breakMs) / 3_600_000).toFixed(2));

      // Late: clock-in after shift start
      if (clockIn > shiftStart) {
        lateMinutes = Math.round((clockIn.getTime() - shiftStart.getTime()) / 60_000);
        if (lateMinutes > 0) status = "late";
      }

      // Early leave: clock-out before shift end (minus grace)
      const graceMs = 15 * 60_000;
      if (clockOut.getTime() < endForCalc.getTime() - graceMs) {
        earlyMinutes = Math.round((endForCalc.getTime() - clockOut.getTime() - graceMs) / 60_000);
        if (status !== "late") status = "early";
      }

      // OT: worked beyond shift end (use endForCalc for night shift)
      if (clockOut > endForCalc) {
        otHours = parseFloat(((clockOut.getTime() - endForCalc.getTime()) / 3_600_000).toFixed(2));
        if (otHours > 0) status = "ot";
      }
    }

    const rows = (await query(`
      UPDATE hr_attendance_records
      SET clock_out = ($1 AT TIME ZONE 'Asia/Ho_Chi_Minh')::timestamp,
          actual_work_hours = $2,
          late_minutes = $3,
          early_minutes = $4,
          ot_hours = $5,
          status = $6
      WHERE employee_id = $7 AND work_date = ($8 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
      RETURNING
        id, employee_id, shift_id,
        work_date::text        AS work_date,
        TO_CHAR(clock_in, 'YYYY-MM-DD HH24:MI:SS') AS clock_in,
        TO_CHAR(clock_out, 'YYYY-MM-DD HH24:MI:SS') AS clock_out,
        status, actual_work_hours,
        late_minutes, early_minutes, ot_hours, remark,
        created_at::text AS created_at
    `, [vnNowStr, actualHours, lateMinutes, earlyMinutes, otHours, status, employee_id, today])).rows;

    res.json(envelope(rows[0]));
  } catch (err) {
    console.error("POST /hr/attendance/clock-out:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /hr/attendance/sync
// Body: { records: [{ employee_id, date, clock_in?, clock_out?, status? }] }
//考勤机批量推送打卡记录到attendance_records（分区表），Upsert on (employee_id, date)
api.post("/hr/attendance/sync", async (req, res) => {
  try {
    const { records = [] } = req.body ?? {};
    if (!Array.isArray(records) || records.length === 0) {
      return res.status(400).json(errorEnvelope("VALIDATION", "records array required"));
    }
    for (const r of records) {
      if (!r.employee_id || !r.date) {
        return res.status(400).json(errorEnvelope("VALIDATION", "employee_id and date required for each record"));
      }
    }

    const results = [];
    for (const r of records) {
      // Resolve shift_id: use today's schedule or default to DAY shift
      const dateVal = r.date;
      let shiftId = r.shift_id || null;
      if (!shiftId) {
        const sched = (await query(`
          SELECT shift_id FROM hr_shift_schedules
          WHERE employee_id = $1 AND schedule_date = $2::date
        `, [r.employee_id, dateVal])).rows[0];
        if (sched) shiftId = sched.shift_id;
      }
      if (!shiftId) {
        const dayShift = (await query(`SELECT id FROM hr_shifts WHERE code = 'DAY' LIMIT 1`)).rows[0];
        if (dayShift) shiftId = dayShift.id;
      }
      if (!shiftId) { results.push({ error: "no shift found" }); continue; }

      // Parse clock_in/out as "HH:MI:SS" Vietnam time strings
      // PostgreSQL stores as timestamptz by combining with work_date using AT TIME ZONE
      const toVnStr = (t) => {
        if (!t) return null;
        return t; // "HH:MI:SS" — stored as time-only, combined with work_date in SQL
      };

      const ciStr = toVnStr(r.clock_in);
      const coStr = toVnStr(r.clock_out);

      // Compute late/early/OT using minutes-based math (handles night shifts)
      const shiftInfo = (await query(`
        SELECT s.id, s.start_time, s.end_time, s.work_hours, s.night_shift, s.break_minutes
        FROM hr_shifts s WHERE s.id = $1
      `, [shiftId])).rows[0];

      let actualHours = null, lateMin = 0, earlyMin = 0, otHrs = 0;
      if (ciStr && coStr) {
        const [ciH, ciM] = ciStr.split(":").map(Number);
        const [coH, coM] = coStr.split(":").map(Number);
        let ciMins = ciH * 60 + ciM;
        let coMins = coH * 60 + coM;

        // Night shift: if clock-out < clock-in, assume next day
        const nightShift = shiftInfo.night_shift || false;
        if (nightShift && coMins < ciMins) coMins += 24 * 60;

        const workedMins = coMins - ciMins;
        const breakMins = shiftInfo.break_minutes ?? 0;
        actualHours = parseFloat(((workedMins - breakMins) / 60).toFixed(2));

        // Late: compare to shift start
        const [ssH, ssM] = shiftInfo.start_time.split(":").map(Number);
        const shiftStartMins = ssH * 60 + ssM;
        if (ciMins > shiftStartMins) lateMin = ciMins - shiftStartMins;

        // Early leave: compare to shift end (with 15-min grace)
        const [seH, seM] = shiftInfo.end_time.split(":").map(Number);
        let shiftEndMins = seH * 60 + seM;
        if (nightShift && shiftEndMins < shiftStartMins) shiftEndMins += 24 * 60;
        const graceMins = 15;
        if (coMins < shiftEndMins - graceMins) earlyMin = shiftEndMins - graceMins - coMins;

        // OT: beyond shift end
        if (coMins > shiftEndMins) otHrs = parseFloat(((coMins - shiftEndMins) / 60).toFixed(2));
      }
      const status = r.status || "normal";

      // ciStr/coStr are "HH:MI:SS" or null
      // Combine with work_date before casting to timestamptz; null means keep old value
      const ciVal = ciStr ? `${dateVal} ${ciStr}` : null;
      const coVal = coStr ? `${dateVal} ${coStr}` : null;

      const row = (await query(`
        INSERT INTO hr_attendance_records
          (employee_id, shift_id, work_date, clock_in, clock_out, status,
           actual_work_hours, late_minutes, early_minutes, ot_hours)
        VALUES (
          $1, $2,
          ($3 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
          COALESCE($4::timestamptz, clock_in),
          COALESCE($5::timestamptz, clock_out),
          $6,
          $7,
          $8, $9, $10
        )
        ON CONFLICT (employee_id, work_date) DO UPDATE SET
          clock_in       = COALESCE(EXCLUDED.clock_in,  hr_attendance_records.clock_in),
          clock_out      = COALESCE(EXCLUDED.clock_out, hr_attendance_records.clock_out),
          status         = COALESCE(EXCLUDED.status,    hr_attendance_records.status),
          actual_work_hours = EXCLUDED.actual_work_hours,
          late_minutes   = EXCLUDED.late_minutes,
          early_minutes  = EXCLUDED.early_minutes,
          ot_hours       = EXCLUDED.ot_hours
        RETURNING
          id, employee_id,
          work_date::text AS work_date,
          TO_CHAR(clock_in,  'YYYY-MM-DD HH24:MI:SS') AS clock_in,
          TO_CHAR(clock_out, 'YYYY-MM-DD HH24:MI:SS') AS clock_out,
          status, actual_work_hours, late_minutes, early_minutes, ot_hours
      `, [r.employee_id, shiftId, dateVal,
          ciVal, coVal,
          status,
          actualHours,
          lateMin, earlyMin, otHrs])).rows[0];
      results.push(row);
    }

    res.status(200).json(envelope({ synced: results.length, records: results }));
  } catch (err) {
    console.error("POST /hr/attendance/sync:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/attendance/daily — attendance summary by shift for a given date
// Query: ?date=2026-06-23&department_id=3
api.get("/hr/attendance/daily", async (req, res) => {
  try {
    const { date = localDate(), department_id } = req.query;

    let sql = `
      SELECT
        a.employee_id, a.shift_id,
        e.employee_no, e.name_zh, e.name_vi,
        d.id AS dept_id, d.name_zh AS dept_name_zh,
        s.code AS shift_code, s.name_zh AS shift_name_zh,
        s.start_time, s.end_time, s.night_shift,
        a.work_date::text AS work_date,
        TO_CHAR(a.clock_in, 'YYYY-MM-DD HH24:MI:SS')  AS clock_in,
        TO_CHAR(a.clock_out, 'YYYY-MM-DD HH24:MI:SS') AS clock_out,
        a.actual_work_hours, a.status,
        a.late_minutes, a.early_minutes, a.ot_hours, a.remark
      FROM hr_attendance_records a
      JOIN hr_employees e ON e.id = a.employee_id
      JOIN hr_shifts s ON s.id = a.shift_id
      LEFT JOIN hr_departments d ON d.id = e.department_id
      WHERE a.work_date = ($1 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
    `;
    const params = [date];
    if (department_id) { params.push(department_id); sql += ` AND e.department_id = $${params.length}`; }
    sql += " ORDER BY d.name_zh, s.start_time, e.name_zh";

    const rows = (await query(sql, params)).rows;
    res.json(envelope({ items: rows, total: rows.length, date }));
  } catch (err) {
    console.error("GET /hr/attendance/daily:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/attendance/monthly/:employeeId — monthly attendance detail
// Query: ?year=2026&month=6
api.get("/hr/attendance/monthly/:employeeId", async (req, res) => {
  try {
    const { employeeId } = req.params;
    const { year = new Date().getFullYear(), month = new Date().getMonth() + 1 } = req.query;

    const startDate = `${year}-${String(month).padStart(2, "0")}-01`;
    const endDate    = `${year}-${String(month).padStart(2, "0")}-31`;

    const rows = (await query(`
      SELECT
        a.work_date::text, a.status,
        s.code AS shift_code, s.name_zh AS shift_name_zh,
        TO_CHAR(a.clock_in, 'YYYY-MM-DD HH24:MI:SS')  AS clock_in,
        TO_CHAR(a.clock_out, 'YYYY-MM-DD HH24:MI:SS') AS clock_out,
        a.actual_work_hours, a.late_minutes, a.early_minutes, a.ot_hours
      FROM hr_attendance_records a
      JOIN hr_shifts s ON s.id = a.shift_id
      WHERE a.employee_id = $1
        AND a.work_date >= ($2 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
        AND a.work_date <= ($3 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
      ORDER BY a.work_date
    `, [employeeId, startDate, endDate])).rows;

    // Summary
    const summary = {
      total_days:   rows.length,
      normal_days:  rows.filter(r => r.status === "normal").length,
      late_days:    rows.filter(r => r.status === "late").length,
      early_days:   rows.filter(r => r.status === "early").length,
      absent_days:  rows.filter(r => r.status === "absent").length,
      leave_days:   rows.filter(r => r.status === "leave").length,
      ot_days:      rows.filter(r => r.status === "ot").length,
      total_ot_hours: rows.reduce((sum, r) => sum + (r.ot_hours ?? 0), 0),
      total_late_minutes: rows.reduce((sum, r) => sum + (r.late_minutes ?? 0), 0),
      total_work_hours: rows.reduce((sum, r) => sum + (r.actual_work_hours ?? 0), 0),
    };

    res.json(envelope({ records: rows, summary, year, month }));
  } catch (err) {
    console.error("GET /hr/attendance/monthly:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/attendance/shift-summary — daily summary grouped by shift
// Query: ?date=2026-06-23
api.get("/hr/attendance/shift-summary", async (req, res) => {
  try {
    const { date = localDate() } = req.query;
    const rows = (await query(`
      SELECT
        a.shift_id,
        s.code AS shift_code, s.name_zh AS shift_name_zh, s.name_vi AS shift_name_vi,
        s.start_time, s.end_time, s.night_shift,
        COUNT(DISTINCT a.employee_id) AS headcount,
        COUNT(DISTINCT CASE WHEN a.status = 'normal' THEN a.employee_id END) AS normal_count,
        COUNT(DISTINCT CASE WHEN a.status = 'late'   THEN a.employee_id END) AS late_count,
        COUNT(DISTINCT CASE WHEN a.status = 'early'  THEN a.employee_id END) AS early_count,
        COUNT(DISTINCT CASE WHEN a.status = 'absent' THEN a.employee_id END) AS absent_count,
        COUNT(DISTINCT CASE WHEN a.status = 'leave'  THEN a.employee_id END) AS leave_count,
        SUM(COALESCE(a.ot_hours, 0))          AS total_ot_hours,
        SUM(COALESCE(a.actual_work_hours, 0)) AS total_work_hours
      FROM hr_attendance_records a
      JOIN hr_shifts s ON s.id = a.shift_id
      WHERE a.work_date = ($1 AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
      GROUP BY a.shift_id, s.code, s.name_zh, s.name_vi, s.start_time, s.end_time, s.night_shift
      ORDER BY s.start_time
    `, [date])).rows;
    res.json(envelope({ items: rows, total: rows.length, date }));
  } catch (err) {
    console.error("GET /hr/attendance/shift-summary:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/leave-balances/:employeeId — leave balance for current year
api.get("/hr/leave-balances/:employeeId", async (req, res) => {
  try {
    const { employeeId } = req.params;
    const year = new Date().getFullYear();
    const rows = (await query(`
      SELECT lb.*, lt.code, lt.name_zh, lt.name_vi, lt.paid_leave
      FROM hr_leave_balances lb
      JOIN hr_leave_types lt ON lt.id = lb.leave_type_id
      WHERE lb.employee_id = $1 AND lb.year = $2
      ORDER BY lt.sort_order
    `, [employeeId, year])).rows;
    res.json(envelope({ items: rows, total: rows.length, year }));
  } catch (err) {
    console.error("GET /hr/leave-balances:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/departments — list departments
api.get("/hr/departments", async (req, res) => {
  try {
    const rows = (await query(`
      SELECT d.*, e.name_zh AS manager_name
      FROM hr_departments d
      LEFT JOIN hr_employees e ON e.id = d.manager_employee_id
      ORDER BY d.code
    `)).rows;
    res.json(envelope({ items: rows, total: rows.length }));
  } catch (err) {
    console.error("GET /hr/departments:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});


