    let sql = `SELECT tpd.*, c.name_zh as course_name_zh, tp.name_zh as plan_name_zh, u.name as trainer_name FROM hr_training_plan_detail tpd LEFT JOIN hr_training_courses c ON tpd.course_id=c.id LEFT JOIN hr_training_plans tp ON tpd.plan_id=tp.id LEFT JOIN hr_employees u ON tpd.trainer_id=u.id WHERE 1=1`;
    const params = [];
    if (plan_id) { sql += ` AND tpd.plan_id=?`; params.push(plan_id); }
