api.get("/hr/cert/types", authenticate, async (req, res) => {
  try {
    const { is_active, station_code } = req.query;
    let sql = `SELECT ct.*, (SELECT COUNT(*) FROM hr_employee_certification ec WHERE ec.cert_type_id=ct.id AND ec.status='active') as active_count FROM hr_certification_type ct WHERE 1=1`;
    const params = [];
    if (is_active !== undefined) {
      sql += ` AND ct.is_active=?`;
      params.push(["true", "1", 1, true].includes(is_active) ? 1 : 0);
    }
    if (station_code) { sql+=` AND (ct.station_code=? OR ct.station_code IS NULL)`; params.push(station_code); }
    sql += ` ORDER BY ct.code`;
    const { rows } = await query(sql, params);
    res.json({ success:true, data:rows });
  } catch (err) { res.status(500).json({ success:false, error:err.message }); }
});

