api.get("/hr/training/tracking", authenticate, async (req, res) => {
  try {
    const { employee_id, tracking_type, date_from, date_to } = req.query;
    let sql = `SELECT tt.*, e.name_zh as emp_name, e.employee_no as emp_no, d.name_zh as dept_name FROM hr_training_tracking tt JOIN hr_employees e ON tt.employee_id=e.id LEFT JOIN hr_departments d ON e.department_id=d.id WHERE 1=1`;
    const params = [];
    if (employee_id)  { sql+=` AND tt.employee_id=?`;  params.push(employee_id); }
    if (tracking_type){ sql+=` AND tt.tracking_type=?`; params.push(tracking_type); }
    if (date_from)    { sql+=` AND tt.tracking_date>=?`; params.push(date_from); }
    if (date_to)      { sql+=` AND tt.tracking_date<=?`; params.push(date_to); }
    sql += ` ORDER BY tt.tracking_date DESC`;
    const { rows } = await query(sql, params);
    res.json({ success:true, data:rows });
  } catch (err) { res.status(500).json({ success:false, error:err.message }); }
});

