// GET /api/agents/bus-stats — queue health + per-agent message stats
api.get("/agents/bus-stats", async (_req, res) => {
  try {
    // Ensure inter_agent_messages table exists (idempotent init from agent-bus.js)
    await db.query(`
      CREATE TABLE IF NOT EXISTS inter_agent_messages (
        id              BIGSERIAL PRIMARY KEY,
        message_id      VARCHAR(64)  NOT NULL UNIQUE,
        source_agent    VARCHAR(32) NOT NULL,
        target_agent    VARCHAR(32) NOT NULL,
        message_type    VARCHAR(32) NOT NULL,
        subject         VARCHAR(128) NOT NULL,
        payload         JSONB       NOT NULL DEFAULT '{}',
        correlation_id  VARCHAR(64),
        priority        VARCHAR(16)  DEFAULT 'normal',
        status          VARCHAR(16)  DEFAULT 'pending',
        created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
        processed_at    TIMESTAMPTZ,
        expires_at      TIMESTAMPTZ,
        error_message   TEXT
      );
      CREATE INDEX IF NOT EXISTS idx_iam_target_status
        ON inter_agent_messages (target_agent, status, created_at DESC);
      CREATE INDEX IF NOT EXISTS idx_iam_source
        ON inter_agent_messages (source_agent, created_at DESC);
      CREATE INDEX IF NOT EXISTS idx_iam_subject
        ON inter_agent_messages (subject);
      CREATE INDEX IF NOT EXISTS idx_iam_priority
        ON inter_agent_messages (priority, created_at);
      CREATE INDEX IF NOT EXISTS idx_iam_correlation
        ON inter_agent_messages (correlation_id);
    `);

    const HOUR = "NOW() - INTERVAL '1 hour'";

    // Overall queue health
    const [statusCounts, byAgentResult, recentActivity] = await Promise.all([
      db.query(`
        SELECT status, COUNT(*)::int AS cnt
        FROM inter_agent_messages
        WHERE created_at >= NOW() - INTERVAL '1 hour'
        GROUP BY status
      `),
      db.query(`
        SELECT target_agent, COUNT(*)::int AS cnt
        FROM inter_agent_messages
        WHERE status = 'pending' AND created_at >= NOW() - INTERVAL '1 hour'
        GROUP BY target_agent
        ORDER BY cnt DESC
      `),
      db.query(`
        SELECT
          source_agent,
          target_agent,
          subject,
          message_type,
          status,
          priority,
          created_at,
          processed_at,
          error_message
        FROM inter_agent_messages
        WHERE created_at >= NOW() - INTERVAL '1 hour'
        ORDER BY created_at DESC
        LIMIT 100
      `),
    ]);

    const stats = { pending: 0, processing: 0, completed: 0, failed: 0, dead: 0, total: 0 };
    for (const row of statusCounts.rows) {
      stats[row.status] = row.cnt;
      stats.total += row.cnt;
    }

    const byAgent = {};
    for (const row of byAgentResult.rows) {
      byAgent[row.target_agent] = row.cnt;
    }

    res.json(envelope({
      stats,
      byAgent,
      recentMessages: recentActivity.rows,
    }));
  } catch (err) {
    console.error("GET /agents/bus-stats:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/agents/messages — query messages with filters
// Query: ?source=&target=&subject=&status=&from=&to=&limit=50
api.get("/agents/messages", async (req, res) => {
  try {
    const {
      source, target, subject, status,
      from = new Date(Date.now() - 3600000).toISOString(),
      to = new Date().toISOString(),
      limit = 50,
    } = req.query;

    const conditions = ["created_at BETWEEN $1::timestamptz AND $2::timestamptz"];
    const params = [from, to];
    let p = 3;

    if (source)  { conditions.push(`source_agent = $${p++}`); params.push(source); }
    if (target)  { conditions.push(`target_agent = $${p++}`); params.push(target); }
    if (subject) { conditions.push(`subject LIKE $${p++}`); params.push(`%${subject}%`); }
    if (status)  { conditions.push(`status = $${p++}`); params.push(status); }

    const result = await db.query(`
      SELECT message_id, source_agent, target_agent, message_type,
             subject, payload, priority, status, created_at,
             processed_at, error_message
      FROM inter_agent_messages
      WHERE ${conditions.join(" AND ")}
      ORDER BY created_at DESC
      LIMIT $${p}
    `, [...params, Number(limit)]);

    res.json(envelope({ items: result.rows, total: result.rowCount }));
  } catch (err) {
    console.error("GET /agents/messages:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

