// POST /service/chat/:agentId — Chat with a service agent
// Body: { message: string, locale?: string, history?: [{role, content}] }
api.post("/service/chat/:agentId", async (req, res) => {
  try {
    const { agentId } = req.params;
    const { message, locale = "zh-CN", history = [] } = req.body ?? {};

    if (!message?.trim()) {
      return res.status(400).json(errorEnvelope("VALIDATION_ERROR", "message is required"));
    }

    const agent = SERVICE_AGENTS.find((a) => a.id === agentId);
    if (!agent) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", `Agent ${agentId} not found`));
    }

    const result = await askServiceAgent(agentId, message, { locale, conversationHistory: history });

    if (result.error) {
      return res.status(502).json(errorEnvelope("LLM_ERROR", result.error));
    }

    res.json(envelope({
      text: result.text,
      agent: { id: agentId, name: agent.name, style: agent.style },
    }));
  } catch (err) {
    console.error("POST /service/chat/:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});




// ── Employee QR Code Management ─────────────────────────────────────
// QR payload = JSON {employee_id, issued_at, expires_at}
// Hash = HMAC-SHA256 of payload (secret = QR_CODE_SECRET env or JWT_SECRET)
// QR content = base64url({payload, hash}) — client decodes to verify

function buildQrPayload(employeeId, issuedAt, expiresAt) {
  return JSON.stringify({ employee_id: employeeId, issued_at: issuedAt, expires_at: expiresAt });
}

function buildQrContent(employeeId, expiresAt) {
  const issuedAt = new Date().toISOString();
  const payload = buildQrPayload(employeeId, issuedAt, expiresAt);
  const secret = process.env.QR_CODE_SECRET ?? JWT_SECRET;
  const hash = createHmac("sha256", secret).update(payload).digest("hex");
  const combined = JSON.stringify({ payload, hash });
  return Buffer.from(combined).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}


// POST /hr/employees/:id/qr-code — generate (or re-generate) a QR code for an employee
api.post("/hr/employees/:id/qr-code", requirePermission("hr.view"), async (req, res) => {
  try {
    const employeeId = parseInt(req.params.id, 10);
    const requestedValidDays = Number(req.body?.validDays ?? 365);
    const validDays = Number.isInteger(requestedValidDays) && requestedValidDays >= 1 && requestedValidDays <= 3650
      ? requestedValidDays
      : 365;
    const expiresAt = new Date(Date.now() + validDays * 86400000).toISOString();

    const empResult = await query(
      `SELECT e.id, e.code AS employee_no,
              COALESCE(NULLIF(e.name_zh,''), e.full_name_zh) AS name_zh,
              COALESCE(NULLIF(e.name_vi,''), e.full_name_vi) AS name_vi,
              e.gender, e.phone, p.name_zh AS position_title,
              e.hire_date AS join_date, e.date_of_birth AS birth_date
       FROM employees e
       LEFT JOIN positions p ON p.id = e.position_id
       WHERE e.id = $1`,
      [employeeId]
    );
    if (!empResult.rows.length) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));
    }
    const emp = empResult.rows[0];

    // Build QR content and hash
    const qrContent = buildQrContent(employeeId, expiresAt);
    const secret = process.env.QR_CODE_SECRET ?? JWT_SECRET;
    const payload = buildQrPayload(employeeId, new Date().toISOString(), expiresAt);
    const hash = createHmac("sha256", secret).update(payload).digest("hex");

    // Generate PNG and store in qr_image
    const { generateEmployeeQrPng } = await import("./src/employeeQr.js");
    const pngBuffer = await generateEmployeeQrPng({
      employeeId,
      employeeNo: emp.employee_no,
      nameZh: emp.name_zh,
      nameVi: emp.name_vi ?? "",
      gender: emp.gender ?? "",
      phone: emp.phone ?? "",
      position: emp.position_title ?? "",
      hireDate: emp.join_date ? String(emp.join_date).slice(0, 10) : "",
      birthDate: emp.birth_date ? String(emp.birth_date).slice(0, 10) : "",
      qrContent,
      expiresAt,
    });

    await query(
      `UPDATE employees SET qr_code_hash = $1, qr_code_issued_at = now(), qr_code_expires_at = $2, qr_image = $3 WHERE id = $4`,
      [hash, expiresAt, pngBuffer, employeeId]
    );

    await writeAuditLog({
      actorId: req.user?.userId ?? null,
      action: "EMPLOYEE_QR_ISSUED",
      entityType: "employee_qr_code",
      entityId: employeeId,
      referenceNo: `emp-qr.${emp.employee_no}`,
    });

    res.status(201).json(mutateEnvelope({
      employeeId,
      employeeCode: emp.employee_no,
      employeeNameZh: emp.name_zh,
      qrContent,
      expiresAt,
      validDays,
    }));
  } catch (err) {
    console.error("POST /hr/employees/:id/qr-code:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/employees/:id/qr-code — get current active QR code info for an employee
api.get("/hr/employees/:id/qr-code", requirePermission("hr.view"), async (req, res) => {
  try {
    const employeeId = parseInt(req.params.id, 10);
    const result = await query(
      `SELECT id, code AS employee_no,
              COALESCE(NULLIF(name_zh,''), full_name_zh) AS name_zh,
              qr_code_hash, qr_code_issued_at, qr_code_expires_at, qr_image
       FROM employees WHERE id = $1`,
      [employeeId]
    );
    if (!result.rows.length) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));
    }
    const emp = result.rows[0];
    const hasActiveQr = !!(emp.qr_image && (!emp.qr_code_expires_at || new Date(emp.qr_code_expires_at) > new Date()));
    const qrContent = hasActiveQr ? buildQrContent(employeeId, emp.qr_code_expires_at) : null;

    res.json(envelope({
      employeeId: emp.id,
      employeeCode: emp.employee_no,
      employeeNameZh: emp.name_zh,
      hasActiveQr,
      qrContent,
      issuedAt: emp.qr_code_issued_at,
      expiresAt: emp.qr_code_expires_at,
    }));
  } catch (err) {
    console.error("GET /hr/employees/:id/qr-code:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/employees/:id/qr-image — download PNG stored in qr_image column
api.get("/hr/employees/:id/qr-image", requirePermission("hr.view"), async (req, res) => {
  try {
    const employeeId = parseInt(req.params.id, 10);
    const result = await query(
      `SELECT code AS employee_no,
              COALESCE(NULLIF(name_zh,''), full_name_zh) AS name_zh,
              qr_image FROM employees WHERE id = $1`,
      [employeeId]
    );
    if (!result.rows.length) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));
    }
    const emp = result.rows[0];
    if (!emp.qr_image) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "QR image not generated yet"));
    }
    res.setHeader("Content-Type", "image/png");
    res.setHeader("Content-Disposition", `attachment; filename="QR_${emp.employee_no}.png"`);
    res.send(emp.qr_image);
  } catch (err) {
    console.error("GET /hr/employees/:id/qr-image:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// DELETE /hr/employees/:id/qr-code — revoke current QR code
api.delete("/hr/employees/:id/qr-code", requirePermission("hr.view"), async (req, res) => {
  try {
    const employeeId = parseInt(req.params.id, 10);
    const empResult = await query("SELECT id, code AS employee_no FROM employees WHERE id = $1", [employeeId]);
    if (!empResult.rows.length) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));
    }
    const employee = empResult.rows[0];

    await query(
      `UPDATE employees SET qr_code_hash = NULL, qr_code_issued_at = NULL, qr_code_expires_at = NULL, qr_image = NULL WHERE id = $1`,
      [employeeId]
    );

    await writeAuditLog({
      actorId: req.user?.userId ?? null,
      action: "EMPLOYEE_QR_REVOKED",
      entityType: "employee_qr_code",
      entityId: employeeId,
      referenceNo: `emp-qr.${employee.employee_no}`,
    });

    res.json(mutateEnvelope({ employeeId, revoked: true }));
  } catch (err) {
    console.error("DELETE /hr/employees/:id/qr-code:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /hr/employees/qr-code/scan — record a QR code scan event (station integration — no JWT required)
api.post("/hr/employees/qr-code/scan", async (req, res) => {
  try {
    const { qr_content, device_id, location_code } = req.body?.payload ?? {};
    if (!qr_content) {
      return res.status(400).json(errorEnvelope("VALIDATION", "qr_content required"));
    }

    let payload, hash;
    try {
      const combined = Buffer.from(qr_content.replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8");
      const parsed = JSON.parse(combined);
      payload = parsed.payload;
      hash = parsed.hash;
    } catch {
      return res.status(400).json(errorEnvelope("VALIDATION", "Invalid QR code format"));
    }

    const secret = process.env.QR_CODE_SECRET ?? JWT_SECRET;
    const expectedHash = createHmac("sha256", secret).update(payload).digest("hex");
    if (hash !== expectedHash) {
      return res.status(401).json(errorEnvelope("UNAUTHORIZED", "QR code signature mismatch"));
    }

    const { employee_id, issued_at, expires_at } = JSON.parse(payload);
    const now = new Date();

    if (new Date(expires_at) < now) {
      return res.status(401).json(errorEnvelope("EXPIRED", "QR code has expired"));
    }

    await query(
      `INSERT INTO employee_qr_code_audit (employee_id, action, qr_code_hash, scanned_at, scanner_device, ip_address, created_at)
       VALUES ($1, 'SCANNED', $2, now(), $3, $4, now())`,
      [employee_id, hash, device_id ?? null, req.ip ?? null]
    );

    const empResult = await query(
      `SELECT e.id, e.code AS employee_no,
              COALESCE(NULLIF(e.name_zh,''), e.full_name_zh) AS name_zh,
              e.department_id, d.name_zh AS dept_name_zh,
              p.name_zh AS position_title, e.status
       FROM employees e
       LEFT JOIN departments d ON d.id = e.department_id
       LEFT JOIN positions p ON p.id = e.position_id
       WHERE e.id = $1`,
      [employee_id]
    );
    if (!empResult.rows.length) {
      return res.status(404).json(errorEnvelope("NOT_FOUND", "Employee not found"));
    }
    const emp = empResult.rows[0];

    res.json(envelope({
      scanResult: "VALID",
      employeeId: emp.id,
      employeeCode: emp.employee_no,
      employeeNameZh: emp.name_zh,
      departmentNameZh: emp.dept_name_zh,
      positionTitleZh: emp.position_title,
      employeeStatus: emp.status,
      scannedAt: now.toISOString(),
    }));
  } catch (err) {
    console.error("POST /hr/employees/qr-code/scan:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/employees/:id/qr-code/audit — get scan history for an employee's QR code
api.get("/hr/employees/:id/qr-code/audit", requirePermission("hr.view"), async (req, res) => {
  try {
    const employeeId = parseInt(req.params.id, 10);
    const { limit = 50, offset = 0 } = req.query;
    const data = await query(
      `SELECT id, action, qr_code_hash, scanned_at, scanner_device, ip_address, created_at
       FROM employee_qr_code_audit
       WHERE employee_id = $1
       ORDER BY created_at DESC
       LIMIT $2 OFFSET $3`,
      [employeeId, Number(limit), Number(offset)]
    );
    const countResult = await query("SELECT count(*) AS total FROM employee_qr_code_audit WHERE employee_id = $1", [employeeId]);
    res.json(listEnvelope(data.rows, Number(countResult.rows[0]?.total) || 0));
  } catch (err) {
    console.error("GET /hr/employees/:id/qr-code/audit:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /hr/employees/qr-code/batch — get QR code status for multiple employees (for batch print)
api.get("/hr/employees/qr-code/batch", requirePermission("hr.view"), async (req, res) => {
  try {
    const { ids } = req.query;
    if (!ids) {
      return res.status(400).json(errorEnvelope("VALIDATION", "ids query param required"));
    }
    const idList = ids.split(",").map((id) => parseInt(id.trim(), 10)).filter((id) => !isNaN(id));
    if (!idList.length) {
      return res.status(400).json(errorEnvelope("VALIDATION", "no valid ids provided"));
    }

    const placeholders = idList.map((_, i) => `$${i + 1}`).join(", ");
    const result = await query(
      `SELECT e.id, e.code AS employee_no,
              COALESCE(NULLIF(e.name_zh,''), e.full_name_zh) AS name_zh,
              COALESCE(NULLIF(e.name_vi,''), e.full_name_vi) AS name_vi,
              e.qr_code_hash, e.qr_code_issued_at, e.qr_code_expires_at, e.qr_image
       FROM employees e
       WHERE e.id IN (${placeholders})
       ORDER BY e.employee_no`,
      idList
    );

    const items = result.rows.map((emp) => {
      const hasActiveQr = !!(emp.qr_image && (!emp.qr_code_expires_at || new Date(emp.qr_code_expires_at) > new Date()));
      return {
        ...emp,
        hasActiveQr,
        qrContent: hasActiveQr ? buildQrContent(emp.id, emp.qr_code_expires_at) : null,
      };
    });

    res.json(listEnvelope(items, items.length));
  } catch (err) {
    console.error("GET /hr/employees/qr-code/batch:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

