// GET /api/mes/station-time-rules — Sheet5: 时效管控 rules
api.get("/mes/station-time-rules", async (req, res) => {
  try {
    const { lineCode, ruleCode } = req.query;
    let sql = `SELECT id, rule_code, rule_name_zh, rule_name_en, description,
                       from_station_code, to_station_code, line_code,
                       max_minutes, warn_minutes, critical_minutes, action_on_exceed, notes
                FROM station_time_rules WHERE 1=1`;
    const params = [];
    if (ruleCode) { params.push(ruleCode); sql += ` AND rule_code = $${params.length}`; }
    if (lineCode) { params.push(lineCode); sql += ` AND (line_code = $${params.length} OR line_code IS NULL)`; }
    sql += ` ORDER BY rule_code`;
    const result = await query(sql, params);
    res.json(listEnvelope(result.rows, result.rows.length));
  } catch (err) {
    console.error("GET /mes/station-time-rules:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/mes/trace/sn/:sn — Sheet3: 追溯要求 — full traceability for a SN
api.get("/mes/trace/sn/:sn", async (req, res) => {
  try {
    const { sn } = req.params;
    const { workOrderId } = req.query;

    // Station flow timeline
    let flowSql = `SELECT sfr.id, sfr.sn, sfr.station_code, sfr.line_code,
                          sfr.arrival_time, sfr.departure_time, sfr.dwell_minutes,
                          sfr.result, sfr.operator_name, sfr.machine_code,
                          sfr.is_stagnation, sfr.stagnation_level,
                          sfr.po_number, sfr.product_model, sfr.quality_check_result,
                          ss.station_name_zh
                   FROM station_flow_records sfr
                   LEFT JOIN station_sequences ss ON ss.station_code = sfr.station_code AND ss.line_code = sfr.line_code
                   WHERE sfr.sn = $1`;
    const flowParams = [sn];
    if (workOrderId) { flowParams.push(workOrderId); flowSql += ` AND sfr.work_order_id = $${flowParams.length}`; }
    flowSql += ` ORDER BY sfr.arrival_time ASC LIMIT 500`;
    const flowResult = await query(flowSql, flowParams);

    // NG defect records
    const ngResult = await query(
      `SELECT ng.id, ng.sn, ng.station_code, ng.line_name AS line_code,
              ng.error_code AS defect_code, ng.defect_desc AS defect_description,
              ng.operator, ng.created_at
       FROM ng_defect_records ng
       WHERE ng.sn = $1 ORDER BY ng.created_at ASC`,
      [sn]
    );

    // Work order info
    const woResult = flowResult.rows.length > 0 && flowResult.rows[0].work_order_id
      ? await query(`SELECT id, code, material_code, material_name, quantity FROM work_orders WHERE id = $1`,
          [flowResult.rows[0].work_order_id])
      : { rows: [] };

    // Stats
    const stats = {
      totalStations: flowResult.rows.length,
      passCount: flowResult.rows.filter(r => r.result === 'PASS').length,
      failCount: flowResult.rows.filter(r => r.result === 'FAIL').length,
      ngCount: ngResult.rows.length,
      stagnationCount: flowResult.rows.filter(r => r.is_stagnation).length,
      totalDwellMinutes: flowResult.rows.reduce((s, r) => s + (r.dwell_minutes || 0), 0),
    };

    res.json(envelope({ sn, workOrderId: flowResult.rows[0]?.work_order_id || null, stats, flowTimeline: flowResult.rows, ngRecords: ngResult.rows, workOrder: woResult.rows[0] || null }));
  } catch (err) {
    console.error("GET /mes/trace/sn:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/mes/retest-flow/:sn — Sheet4: 复测要求 — ICT/FCT FAIL → retest → repair flow
api.get("/mes/retest-flow/:sn", async (req, res) => {
  try {
    const { sn } = req.params;
    const result = await query(
      `SELECT sfr.id, sfr.sn, sfr.station_code, sfr.line_code,
              sfr.arrival_time, sfr.departure_time, sfr.result, sfr.operator_name
       FROM station_flow_records sfr
       WHERE sfr.sn = $1 AND sfr.station_code IN ('ICT-01', 'FCT-01')
       ORDER BY sfr.arrival_time ASC`,
      [sn]
    );
    const records = result.rows;
    let retestStatus = 'PASS';
    let consecutiveFail = 0;
    for (const r of records) {
      if (r.result === 'FAIL') consecutiveFail++; else consecutiveFail = 0;
    }
    if (consecutiveFail >= 2) retestStatus = 'REPAIR';
    else if (records.length > 0 && records[records.length - 1].result === 'FAIL') retestStatus = 'FAIL';
    else if (records.some(r => r.result === 'FAIL')) retestStatus = 'RETEST';
    res.json(envelope({ sn, retestStatus, records }));
  } catch (err) {
    console.error("GET /mes/retest-flow:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

