// GET /api/equipment-archives
api.get("/equipment-archives", async (req, res) => {
  try {
    const { rows } = await query(`SELECT * FROM equipment_archives ORDER BY equipment_code`);
    res.json({ data: { items: rows, total: rows.length } });
  } catch (err) {
    console.error("GET /equipment-archives:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/equipment-archives/stats/summary
api.get("/equipment-archives/stats/summary", async (req, res) => {
  try {
    const { rows } = await query(`
      SELECT
        count(*)::int AS total,
        count(*) FILTER (WHERE current_status = 'running') AS running,
        count(*) FILTER (WHERE current_status = 'idle') AS idle,
        count(*) FILTER (WHERE current_status = 'maintenance') AS maintenance,
        count(*) FILTER (WHERE current_status = 'repair') AS repair,
        count(*) FILTER (WHERE current_status = 'decommissioned') AS decommissioned,
        COALESCE(sum(cumulative_running_hours), 0)::float AS total_hours,
        COALESCE(avg(cumulative_running_hours), 0)::float AS avg_hours
      FROM equipment_archives
    `);
    const s = rows[0];
    res.json({ data: {
      total: parseInt(s.total ?? 0),
      running: parseInt(s.running ?? 0),
      idle: parseInt(s.idle ?? 0),
      maintenance: parseInt(s.maintenance ?? 0),
      repair: parseInt(s.repair ?? 0),
      decommissioned: parseInt(s.decommissioned ?? 0),
      totalHours: parseFloat((s.total_hours ?? 0).toFixed(1)),
      avgHours: parseFloat((s.avg_hours ?? 0).toFixed(1)),
    }});
  } catch (err) {
    console.error("GET /equipment-archives/stats/summary:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/equipment-archives/:id
api.get("/equipment-archives/:id", async (req, res) => {
  try {
    const { rows } = await query(`SELECT * FROM equipment_archives WHERE id = $1`, [req.params.id]);
    if (!rows[0]) { res.status(404).json(errorEnvelope("NOT_FOUND", "Equipment archive not found")); return; }
    res.json({ data: rows[0] });
  } catch (err) {
    console.error("GET /equipment-archives/:id:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

