// ── Manager Reply Engine ───────────────────────────────────────────
// Each reply function queries real database tables via pgPool
// Helper: safe DB query that returns empty array on error
async function dbq(sql, params=[]) {
  try { const r = await pgPool.query(sql, params); return r.rows; } catch(e) { return []; }
}

