async function generateManagerReply(managerId, message) {
  const mgrReplies = MANAGER_REPLIES[managerId];
  if (!mgrReplies) {
    return { reply: `已收到您的消息。`, managerStatus: "online" };
  }

  // Try keyword matching
  for (const rule of mgrReplies.rules) {
    if (rule.kw.some(kw => message.toLowerCase().includes(kw.toLowerCase()))) {
      const reply = await rule.reply(message);
      return { reply, managerStatus: "busy" };
    }
  }

  // Fallback
  const fallbackReply = await mgrReplies.fallback(message);
  return { reply: fallbackReply, managerStatus: "online" };
}

// Inter-manager communication + human → manager communication
api.post("/managers/message", express.json(), async (req, res) => {
  const { from, to, message } = req.body;
  if (!to || !message) return res.status(400).json({ error: { code: "BAD_REQUEST", message: "to and message required" } });
  const sender = from ?? "human";
  console.log(`[MANAGER CHAT] ${sender} → ${to}: ${message}`);

  // Log to audit if table exists
  try {
    await pgPool.query(
      `INSERT INTO wms_manager_audit (agent, decision_type, input_data, output_decision, executed, executor)
       VALUES ($1, $2, $3, $4, true, $5)`,
      ["dashboard", "MANAGER_MESSAGE", JSON.stringify({ from: sender, to }), JSON.stringify({ message }), "dashboard-user"]
    );
  } catch (_) { /* table may not exist */ }

  // Find the manager
  const target = ALL_MANAGERS.find(m => m.id === to);
  const targetName = target ? (target.nameZh ?? target.name) : to;

  // Generate auto-reply from manager (queries real DB tables)
  const { reply, managerStatus } = await generateManagerReply(to, message);

  res.json({
    data: {
      msg: `消息已发送给 ${targetName}`,
      from: sender, to, message,
      reply: { from: to, text: reply, status: managerStatus },
      timestamp: new Date().toISOString(),
    },
    meta: { serverTime: new Date().toISOString() }
  });
});

// Get manager detail (skills, files, recent activity)
api.get("/managers/detail/:id", async (req, res) => {
  const mgr = ALL_MANAGERS.find(m => m.id === req.params.id);
  if (!mgr) return res.status(404).json({ error: { code: "NOT_FOUND", message: "Manager not found" } });

  // Try to get recent audit log from DB
  let recentDecisions = [];
  try {
    const r = await pgPool.query(
      `SELECT decision_type, input_data, created_at FROM wms_manager_audit
       WHERE agent LIKE $1 ORDER BY created_at DESC LIMIT 10`,
      [`%${mgr.id.split("-")[0]}%`]
    );
    recentDecisions = r.rows;
  } catch (_) {}

  res.json({ data: { ...mgr, recentDecisions }, meta: { serverTime: new Date().toISOString() } });
});

// Human → Manager quick actions
api.post("/managers/action", express.json(), async (req, res) => {
  const { managerId, action, params } = req.body;
  if (!managerId || !action) return res.status(400).json({ error: { code: "BAD_REQUEST", message: "managerId and action required" } });
  console.log(`[MANAGER ACTION] ${managerId} → ${action} ${JSON.stringify(params ?? {})}`);
  res.json({
    data: { msg: `已向 ${managerId} 下达指令: ${action}`, managerId, action, params, timestamp: new Date().toISOString() },
    meta: { serverTime: new Date().toISOString() }
  });
});

