async function resolveArchiveCategory(sourceKey) {
  const catCode = ARCHIVE_SOURCE_CATEGORY[sourceKey];
  if (!catCode) return null;
  const r = await query("SELECT id FROM archive_categories WHERE code = $1", [catCode]);
  return r.rows.length ? r.rows[0].id : null;
}

// Helper: create an archive entry from report data
async function createArchiveEntry(sourceKey, rows, params, userAgent, archivedBy) {
  const categoryId = await resolveArchiveCategory(sourceKey);
  if (!categoryId) throw new Error(`Unknown category for source: ${sourceKey}`);

  const paramJson = params ? JSON.stringify(params) : "{}";
  const result = await query(
    `INSERT INTO document_archives
       (category_id, archive_type, source_key, snapshot_data, row_count, parameter_snapshot, user_agent, archived_by)
     VALUES ($1, 'report', $2, $3::jsonb, $4, $5::jsonb, $6, $7)
     RETURNING id, archived_at, checksum, expires_at`,
    [categoryId, sourceKey, JSON.stringify(rows), rows.length, paramJson, userAgent, archivedBy ?? null]
  );
  return result.rows[0];
}

// GET /api/archives/categories — list category tree with counts
api.get("/archives/categories", authenticateJWT, requirePermission("reports.view"), async (_req, res) => {
  try {
    const result = await query(`
      WITH archived AS (
        SELECT category_id, COUNT(*) AS cnt,
          MIN(archived_at) AS oldest, MAX(archived_at) AS newest
        FROM document_archives GROUP BY category_id
      )
      SELECT c.id, c.code, c.name_zh, c.name_en, c.name_vi,
        c.parent_id, c.sort_order, c.icon,
        COALESCE(a.cnt, 0) AS archive_count,
        a.oldest, a.newest
      FROM archive_categories c
      LEFT JOIN archived a ON a.category_id = c.id
      ORDER BY c.sort_order, c.id
    `);
    res.json(envelope(result.rows));
  } catch (err) {
    console.error("GET /archives/categories:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/archives — list archives (filtered, paginated)
api.get("/archives", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const { source, category, dateFrom, dateTo, limit = 50, offset = 0 } = req.query;
    const conds = [];
    const vals = [];
    let idx = 1;
    if (source) { conds.push(`a.source_key = $${idx++}`); vals.push(source); }
    if (category) { conds.push(`ac.code = $${idx++}`); vals.push(category); }
    if (dateFrom) { conds.push(`a.archived_at >= $${idx++}`); vals.push(dateFrom); }
    if (dateTo) { conds.push(`a.archived_at <= $${idx++}`); vals.push(dateTo); }
    const where = conds.length ? " WHERE " + conds.join(" AND ") : "";

    const rowsResult = await query(`
      SELECT a.id, a.archive_type, a.source_key, a.source_id,
        a.title_zh, a.title_en, a.title_vi,
        ac.code AS category_code, ac.name_zh AS category_name_zh,
        a.row_count, a.archived_by, a.archived_at, a.expires_at,
        a.is_pinned, a.checksum, a.user_agent,
        CASE WHEN a.expires_at < NOW() THEN 'expired' ELSE 'active' END AS retention_status
      FROM document_archives a
      JOIN archive_categories ac ON ac.id = a.category_id
      ${where}
      ORDER BY a.archived_at DESC
      LIMIT ${Number(limit)} OFFSET ${Number(offset)}
    `, vals);

    const countResult = await query(`
      SELECT COUNT(*)::int AS total FROM document_archives a
      JOIN archive_categories ac ON ac.id = a.category_id ${where}
    `, vals);

    res.json(listEnvelope(rowsResult.rows, countResult.rows[0]?.total ?? 0));
  } catch (err) {
    console.error("GET /archives:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /api/archives/from-report — archive a specific report's current data
api.post("/archives/from-report", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const { reportKey, period } = req.body;
    if (!reportKey) return res.status(400).json(errorEnvelope("VALIDATION", "reportKey required"));

    const def = REPORT_MAP[reportKey];
    if (!def) return res.status(404).json(errorEnvelope("NOT_FOUND", `Report '${reportKey}' not found`));

    // Fetch current report data (same logic as GET /reports/:reportKey)
    const usePeriod = def.hasPeriod && (period === "weekly" || period === "monthly") ? period : null;
    let sql, values;
    if (usePeriod) {
      const pg = buildPeriodGroupedQuery(def.view, usePeriod, req.query, []);
      sql = pg.sql; values = pg.values;
    } else {
      sql = `SELECT * FROM ${def.view} LIMIT 5000`;
      values = undefined;
    }
    const result = await query(sql, values);
    const rows = result.rows;

    const archive = await createArchiveEntry(
      reportKey, rows,
      { period: usePeriod, ...req.query },
      `user:${req.user.username}`,
      req.user.userId
    );

    // Log snapshot
    await query(
      `INSERT INTO archive_snapshots (snapshot_type, source_key, description, total_archived, status, started_by)
       VALUES ('manual', $1, $2, 1, 'completed', $3)`,
      [reportKey, `Manual archive of ${reportKey}: ${rows.length} rows`, `user:${req.user.username}`]
    );

    res.json(envelope({
      id: archive.id, reportKey,
      rowCount: rows.length,
      archivedAt: archive.archived_at,
      checksum: archive.checksum,
      expiresAt: archive.expires_at,
    }));
  } catch (err) {
    console.error("POST /archives/from-report:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// POST /api/archives/run-snapshot — batch archive ALL reports
api.post("/archives/run-snapshot", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const { period } = req.body; // optional: "weekly" | "monthly"
    const userAgent = `user:${req.user.username}`;
    const results = [];
    let totalArchived = 0;

    for (const def of REPORT_DEFS) {
      const usePeriod = def.hasPeriod && (period === "weekly" || period === "monthly") ? period : null;
      try {
        let sql, values;
        if (usePeriod) {
          const pg = buildPeriodGroupedQuery(def.view, usePeriod, {}, []);
          sql = pg.sql; values = pg.values;
        } else {
          sql = `SELECT * FROM ${def.view} LIMIT 5000`;
          values = undefined;
        }
        const result = await query(sql, values);
        if (result.rows.length === 0) {
          results.push({ key: def.key, status: "skipped", rows: 0 });
          continue;
        }
        const archive = await createArchiveEntry(def.key, result.rows, { period: usePeriod }, userAgent, req.user.userId);
        results.push({ key: def.key, status: "archived", rows: result.rows.length, id: archive.id });
        totalArchived++;
      } catch (e) {
        results.push({ key: def.key, status: "failed", error: e.message });
      }
    }

    await query(
      `INSERT INTO archive_snapshots (snapshot_type, description, total_archived, status, started_by)
       VALUES ($1, $2, $3, $4, $5)`,
      ["manual",
       `Batch snapshot: ${totalArchived}/${REPORT_DEFS.length} archived`,
       totalArchived,
       results.some(r => r.status === "failed") ? "partial" : "completed",
       userAgent]
    );

    res.json(envelope({ total: REPORT_DEFS.length, archived: totalArchived, details: results }));
  } catch (err) {
    console.error("POST /archives/run-snapshot:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/archives/analysis/trend — trend analysis query
api.get("/archives/analysis/trend", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const { source, metric, period = "weekly", dateFrom, dateTo } = req.query;
    if (!source || !metric) return res.status(400).json(errorEnvelope("VALIDATION", "source and metric required"));

    const grpExpr = period === "monthly"
      ? "DATE_TRUNC('month', archived_at)::date"
      : period === "daily"
        ? "DATE_TRUNC('day', archived_at)::date"
        : "DATE_TRUNC('week', archived_at)::date";

    const dw = dateFrom || "1970-01-01";
    const dt = dateTo || "2100-01-01";

    const result = await query(`
      SELECT id, archived_at, ${grpExpr} AS period_start, snapshot_data, row_count
      FROM document_archives
      WHERE source_key = $1 AND archived_at >= $2 AND archived_at <= $3
      ORDER BY archived_at ASC
    `, [source, dw, dt]);
    const rows = result.rows;

    // Extract metric values per period (use latest archive in each period)
    const periodMap = {};
    for (const row of rows) {
      const key = row.period_start;
      if (!periodMap[key]) periodMap[key] = [];
      periodMap[key].push(row);
    }

    const series = [];
    for (const [periodStart, archives] of Object.entries(periodMap)) {
      const latest = archives.reduce((a, b) => a.archived_at > b.archived_at ? a : b);
      const sd = typeof latest.snapshot_data === "string"
        ? JSON.parse(latest.snapshot_data) : latest.snapshot_data;
      const dataRows = sd?.rows || sd || [];
      const vals = dataRows.map(r => Number(r[metric])).filter(v => !isNaN(v));
      if (vals.length > 0) {
        series.push({
          period: periodStart,
          value: vals.reduce((a, b) => a + b, 0) / vals.length,
          sum: vals.reduce((a, b) => a + b, 0),
          count: vals.length,
          archiveId: latest.id,
        });
      }
    }

    const values = series.map(s => s.value);
    const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
    const stddev = values.length > 1
      ? Math.sqrt(values.reduce((sum, v) => sum + (v - avg) ** 2, 0) / values.length)
      : 0;
    const anomalies = values.length > 2
      ? series.filter(s => Math.abs(s.value - avg) > 2 * stddev)
          .map(s => ({ period: s.period, value: s.value, expected: avg, deviation: s.value - avg }))
      : [];

    res.json(envelope({
      source, metric, period,
      dataPoints: series.length,
      stats: { avg: Math.round(avg * 100) / 100, stddev: Math.round(stddev * 100) / 100,
               min: Math.min(...values), max: Math.max(...values) },
      anomalies,
      series,
    }));
  } catch (err) {
    console.error("GET /archives/analysis/trend:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/archives/analysis/compare — comparison across groups
api.get("/archives/analysis/compare", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const { source, metric, groups } = req.query;
    if (!source || !metric || !groups) {
      return res.status(400).json(errorEnvelope("VALIDATION", "source, metric, and groups required"));
    }

    const groupCols = groups.split(",");
    const rows = await query(`
      SELECT id, archived_at, snapshot_data FROM document_archives
      WHERE source_key = $1 ORDER BY archived_at DESC LIMIT 10
    `, [source]);

    if (!rows.rows.length) return res.json(envelope({ source, metric, comparisons: {} }));

    const latest = rows.rows[0];
    const sd = typeof latest.snapshot_data === "string"
      ? JSON.parse(latest.snapshot_data) : latest.snapshot_data;
    const dataRows = sd?.rows || sd || [];

    const comparisons = {};
    for (const grp of groupCols) {
      const grpMap = {};
      for (const row of dataRows) {
        const dim = row[grp];
        const val = Number(row[metric]);
        if (dim === undefined || isNaN(val)) continue;
        if (!grpMap[dim]) grpMap[dim] = { sum: 0, count: 0 };
        grpMap[dim].sum += val;
        grpMap[dim].count++;
      }
      comparisons[grp] = Object.entries(grpMap).map(([dim, data]) => ({
        group: dim, total: data.sum, avg: data.sum / data.count, count: data.count,
      }));
    }

    res.json(envelope({ source, metric, groups: groupCols, archiveId: latest.id, archivedAt: latest.archived_at, comparisons }));
  } catch (err) {
    console.error("GET /archives/analysis/compare:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/archives/analysis/cross — cross-domain correlation
api.get("/archives/analysis/cross", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const { x, y, metricX, metricY, period = "weekly", dateFrom, dateTo } = req.query;
    if (!x || !y) return res.status(400).json(errorEnvelope("VALIDATION", "x and y source keys required"));

    const grpExpr = period === "monthly"
      ? "DATE_TRUNC('month', archived_at)::date"
      : "DATE_TRUNC('week', archived_at)::date";
    const dw = dateFrom || "1970-01-01";
    const dt = dateTo || "2100-01-01";

    const xRows = await query(`
      SELECT archived_at, ${grpExpr} AS period_start, snapshot_data
      FROM document_archives WHERE source_key = $1 AND archived_at >= $2 AND archived_at <= $3
      ORDER BY archived_at ASC
    `, [x, dw, dt]);
    const yRows = await query(`
      SELECT archived_at, ${grpExpr} AS period_start, snapshot_data
      FROM document_archives WHERE source_key = $1 AND archived_at >= $2 AND archived_at <= $3
      ORDER BY archived_at ASC
    `, [y, dw, dt]);

    // Extract values per period
    function extractPerPeriod(rows, metric) {
      const map = {};
      for (const row of rows.rows) {
        const sd = typeof row.snapshot_data === "string" ? JSON.parse(row.snapshot_data) : row.snapshot_data;
        const dr = sd?.rows || sd || [];
        const vals = dr.map(r => Number(r[metric])).filter(v => !isNaN(v));
        const avg = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
        map[row.period_start] = avg;
      }
      return map;
    }

    const xMap = extractPerPeriod(xRows, metricX || "row_count");
    const yMap = extractPerPeriod(yRows, metricY || "row_count");

    const allPeriods = [...new Set([...Object.keys(xMap), ...Object.keys(yMap)])].sort();
    const aligned = allPeriods.map(p => ({ period: p, [x]: xMap[p] ?? null, [y]: yMap[p] ?? null }));
    const paired = aligned.filter(a => a[x] !== null && a[y] !== null);

    let correlation = null;
    if (paired.length >= 3) {
      const n = paired.length;
      const meanX = paired.reduce((s, p) => s + p[x], 0) / n;
      const meanY = paired.reduce((s, p) => s + p[y], 0) / n;
      const num = paired.reduce((s, p) => s + (p[x] - meanX) * (p[y] - meanY), 0);
      const denX = Math.sqrt(paired.reduce((s, p) => s + (p[x] - meanX) ** 2, 0));
      const denY = Math.sqrt(paired.reduce((s, p) => s + (p[y] - meanY) ** 2, 0));
      correlation = denX && denY ? num / (denX * denY) : 0;
    }

    res.json(envelope({
      x: { source: x, metric: metricX || "row_count" },
      y: { source: y, metric: metricY || "row_count" },
      period, dataPoints: paired.length,
      correlation: correlation ? Math.round(correlation * 1000) / 1000 : null,
      correlationStrength: correlation === null ? "insufficient_data"
        : Math.abs(correlation) > 0.7 ? "strong" : Math.abs(correlation) > 0.4 ? "moderate" : "weak",
      series: aligned,
    }));
  } catch (err) {
    console.error("GET /archives/analysis/cross:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

// GET /api/archives/retention — retention report
api.get("/archives/retention", authenticateJWT, requirePermission("reports.view"), async (req, res) => {
  try {
    const days = Number(req.query.days) || 30;
    const rows = await query(`
      SELECT ac.code AS category_code, COUNT(*) AS expiring_count,
        MAX(a.row_count) AS max_rows, MIN(a.expires_at) AS first_expiry
      FROM document_archives a
      JOIN archive_categories ac ON ac.id = a.category_id
      WHERE a.expires_at BETWEEN NOW() AND NOW() + INTERVAL '1 day' * $1
        AND NOT a.is_pinned
      GROUP BY ac.code ORDER BY COUNT(*) DESC
    `, [days]);
    const total = rows.rows.reduce((s, r) => s + Number(r.expiring_count), 0);
    res.json(envelope({ expiringWithinDays: days, totalRecords: total, byCategory: rows.rows }));
  } catch (err) {
    console.error("GET /archives/retention:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  }
});

