// ── Auto-archive hook: called after each report GET ────────────
// This runs asynchronously and does not block the response.
async function autoArchiveReport(reportKey, rows, queryParams, username) {
  try {
    // Only archive non-empty results
    if (!rows || rows.length === 0) return;
    // Check if this report key has a category mapping
    if (!ARCHIVE_SOURCE_CATEGORY[reportKey]) return;

    const usePeriod = REPORT_MAP[reportKey]?.hasPeriod &&
      (queryParams.period === "weekly" || queryParams.period === "monthly")
      ? queryParams.period : null;

    await createArchiveEntry(
      reportKey, rows,
      { period: usePeriod, ...queryParams },
      `user:${username}`,
      null // archived_by left null for auto-archives triggered by the system
    );
  } catch (e) {
    // Silent: auto-archive failure should never break the report response
    console.warn(`[auto-archive] ${reportKey}: ${e.message}`);
  }
}

