async function getSignedInEmployee(req) {
  const username = String(req.user?.username || "").trim();
  if (!username) return null;
  return (await query(
    `SELECT id, code,
            COALESCE(NULLIF(name_zh,''), NULLIF(name_vi,''), NULLIF(name_en,''), display_name, code) AS name,
            to_char(date_of_birth, 'YYYY-MM-DD') AS date_of_birth,
            gender, phone, address, emergency_contact, emergency_phone, avatar_url,
            EXTRACT(YEAR FROM age(CURRENT_DATE, date_of_birth))::int AS age
       FROM employees
      WHERE upper(code)=upper($1) AND status='active'`,
    [username]
  )).rows[0] || null;
}

