app.post("/hr/leave/request", async (req, res) => {
  try {
    const { employeeId, leaveType, startDate, endDate, daysCount, reason } = req.body;
    if (!employeeId || !leaveType || !startDate || !endDate || !daysCount)
      return res.json({ success: false, error: "缺少参数" });
    const row = await query(
      `INSERT INTO hr_leave_requests
         (employee_id, leave_type, start_date, end_date, days_count, reason, status)
       VALUES ($1,$2,$3,$4,$5,$6,'pending_group_leader')
       RETURNING id, created_at`,
      [employeeId, leaveType, startDate, endDate, daysCount, reason || null]
    );
    // 发通知给班组长
    const leaders = await query(
      `SELECT ta.leader_id FROM hr_team_assignments ta WHERE ta.employee_id=$1`,
      [employeeId]
    );
    for (const ldr of leaders.rows) {
      await query(
        `INSERT INTO hr_notifications (recipient_id, type, title_zh, body_zh, data_json)
         VALUES ($1,'leave_new','新请假申请','员工提交了请假申请',
                 json_object('leaveId', $2, 'employeeId', $1))`,
        [ldr.leader_id, row.rows[0].id]
      );
    }
    res.json({ success: true, leaveId: row.rows[0].id, createdAt: row.rows[0].created_at });
  } catch(err) { res.json({ success: false, error: err.message }); }
});

