// 班组长：审批请假（通过/拒绝）
api.post("/hr/leave/approve", authenticate, async (req, res) => {
  try {
    const { leaveId, result, reason } = req.body;
    // result: 'approved' or 'rejected'
    const nextStatus = result === 'approved' ? 'pending_hr' : 'rejected';
    await query(
      `UPDATE hr_leave_requests
       SET status=$1, group_leader_id=$2, group_leader_result=$3,
           group_leader_reason=$4, group_leader_at=datetime('now','localtime'),
           updated_at=datetime('now','localtime')
       WHERE id=$5`,
      [nextStatus, req.user?.employeeId, result, reason || null, leaveId]
    );
    // 发通知给员工和HR
    const leave = (await query(`SELECT employee_id FROM hr_leave_requests WHERE id=$1`, [leaveId])).rows[0];
    const notifType = result === 'approved' ? 'leave_approved' : 'leave_rejected';
    await query(
      `INSERT INTO hr_notifications (recipient_id, type, title_zh, body_zh, data_json)
       VALUES ($1, $2, $3, $4, json_object('leaveId', $5))`,
      [leave.employee_id, notifType,
       result === 'approved' ? '请假已通过初审' : '请假已被拒绝',
       result === 'approved' ? '班组长已审批，等待HR最终确认' : '班组长拒绝：' + (reason||''),
       leaveId]
    );
    if (result === 'approved') {
      // 通知HR
      const hrs = await query(`SELECT id FROM hr_employees WHERE role='hr' LIMIT 5`);
      for (const hr of hrs.rows) {
        await query(
          `INSERT INTO hr_notifications (recipient_id, type, title_zh, body_zh, data_json)
           VALUES ($1,'leave_new','请假申请待HR审批','班组长已通过，等待HR最终审批',
                   json_object('leaveId', $2))`,
          [hr.id, leaveId]
        );
      }
    }
    res.json({ success: true });
  } catch(err) { res.json({ success: false, error: err.message }); }
});

