// 考勤统计（团队或个人）
app.get("/hr/attendance/stats", authenticate, async (req, res) => {
  try {
    const { scope, employeeId, startDate, endDate } = req.query;
    const params = [];
    let where = "WHERE 1=1";
    if (scope === 'team') {
      const leaderId = req.user?.employeeId;
      where += ` AND c.employee_id IN (SELECT employee_id FROM hr_team_assignments WHERE leader_id=$${params.length+1})`;
      params.push(leaderId);
    } else if (employeeId) {
      where += ` AND c.employee_id=$${params.length+1}`;
      params.push(employeeId);
    }
    if (startDate) { where += ` AND date(c.checkin_time) >= $${params.length+1}`; params.push(startDate); }
    if (endDate)   { where += ` AND date(c.checkin_time) <= $${params.length+1}`; params.push(endDate); }
    const rows = await query(
      `SELECT c.employee_id, e.code AS emp_no,
              COALESCE(NULLIF(e.name_zh,''), e.full_name_zh) AS emp_name,
              date(c.checkin_time) AS checkin_date,
              c.checkin_type, c.checkin_time,
              CASE WHEN c.face_result='fail' THEN 1 ELSE 0 END AS face_failed
       FROM hr_mobile_checkin c
       JOIN hr_employees e ON c.employee_id = e.id
       ${where}
       ORDER BY c.checkin_time DESC
       LIMIT 500`,
      params
    );
    // 汇总统计
    const summary = {};
    for (const r of rows.rows) {
      const key = r.employee_id;
      if (!summary[key]) summary[key] = { emp_no: r.emp_no, emp_name: r.emp_name, total: 0, face_fail: 0 };
      summary[key].total++;
      summary[key].face_fail += r.face_failed;
    }
    res.json({ success: true, records: rows.rows, summary: Object.values(summary) });
  } catch(err) { res.json({ success: false, error: err.message }); }
});

