      todayInspections: Number(todayInspections.rows[0]?.cnt ?? 0),
      overdueInspections: Number(overdueInspections.rows[0]?.cnt ?? 0),
      avgDowntimeMinutes: Number(avgDowntime.rows[0]?.avg ?? 0),
