// ── MES Missioner proxy endpoints ────────────────────────────────────
// Allows station-agent browser app to tunnel DB/OPC-UA/Modbus queries through the backend

// POST /api/proxy/db-query — run SQL against MySQL or PostgreSQL
app.post("/api/proxy/db-query", async (req, res) => {
  const { host, port, database, username, password, sql, databaseType = 'postgresql' } = req.body;
  if (!sql || !host) { res.status(400).json({ error: 'host and sql are required' }); return; }
  const start = Date.now();
  try {
    if (databaseType === 'mysql') {
      const { default: mysql } = await import('mysql2');
      const conn = await mysql.createConnection({ host, port: port || 3306, user: username, password, database, connectTimeout: 5000 });
      const [rows] = await conn.query(sql);
      await conn.end();
      res.json({ rows, rowCount: Array.isArray(rows) ? rows.length : 0, durationMs: Date.now() - start });
    } else {
      const pool = new pg.Pool({ host, port: port || 5432, database, user: username, password, max: 1, idleTimeoutMillis: 5000, connectionTimeoutMillis: 5000 });
      const result = await pool.query(sql);
      await pool.end();
      res.json({ rows: result.rows, rowCount: result.rowCount, durationMs: Date.now() - start });
    }
  } catch (err) {
    res.status(500).json({ error: String(err instanceof Error ? err.message : err) });
  }
});

// POST /api/proxy/opcua-read — read from OPC-UA server
app.post("/api/proxy/opcua-read", async (req, res) => {
  const { endpoint, nodeId, username, password } = req.body;
  if (!endpoint || !nodeId) { res.status(400).json({ error: 'endpoint and nodeId are required' }); return; }
  try {
    const { OPCUAClient } = await import('node-opcua');
    const client = OPCUAClient.create({ endpointMustExist: false, connectionStrategy: { maxRetry: 2, initialDelay: 1000 } });
    await client.connect(endpoint);
    const sessionOpts = username ? { userName: username, password: password || '' } : undefined;
    const session = await client.getSession(sessionOpts);
    const dv = await session.read({ nodeId, attributeId: 13 });
    await session.close();
    await client.disconnect();
    res.json({ value: dv.value?.value, statusCode: dv.statusCode?.toString(), timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: `OPC-UA proxy error: ${err instanceof Error ? err.message : err}` });
  }
});

// POST /api/proxy/modbus-read — read Modbus TCP registers
app.post("/api/proxy/modbus-read", async (req, res) => {
  const { host, port = 502, unitId = 1, registers = [] } = req.body;
  if (!host) { res.status(400).json({ error: 'host is required' }); return; }
  try {
    const { ModbusRTU } = await import('modbus-serial');
    const client = new ModbusRTU();
    await client.connectTCP(host, { port });
    client.setID(unitId);
    const results = [];
    for (const reg of registers) {
      const r = await client.readHoldingRegisters(reg.address, reg.count);
      const values = Array.from(r.data);
      results.push({ name: reg.name, address: reg.address, values, value: values.length === 1 ? values[0] : values });
    }
    client.close(() => {});
    res.json({ registers: results, durationMs: 0 });
  } catch (err) {
    res.status(500).json({ error: `Modbus proxy error: ${err instanceof Error ? err.message : err}` });
  }
});

