// ── SPA fallback: serve index.html for all non-API routes ──────────
// Canonical WMS closed-loop governance.
const closureRequiredRoles = (caseType, riskLevel) => {
  if (["SCRAP", "MASTER_DATA_CHANGE"].includes(caseType) || riskLevel === "CRITICAL") {
    return ["WAREHOUSE_SUPERVISOR", "QUALITY_MANAGER", "FINANCE"];
  }
  if (caseType === "SPECIAL_RELEASE") return ["QUALITY_MANAGER"];
  return ["WAREHOUSE_SUPERVISOR"];
};

async function appendClosureAudit(client, { caseId = null, handoverId = null, action, actor, oldState = null, newState = null, detail = {} }) {
  const previous = (await client.query(
    `SELECT event_hash FROM wms_closed_loop_audit
     WHERE ($1::bigint IS NULL OR case_id=$1) ORDER BY id DESC LIMIT 1`, [caseId]
  )).rows[0]?.event_hash ?? null;
  const canonical = JSON.stringify({ caseId, handoverId, action, actor, oldState, newState, detail, previous });
  const eventHash = createHash("sha256").update(canonical).digest("hex");
  await client.query(
    `INSERT INTO wms_closed_loop_audit
       (case_id,handover_id,action,actor_badge,old_state,new_state,detail,previous_hash,event_hash)
     VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
    [caseId,handoverId,action,actor,oldState,newState,JSON.stringify(detail),previous,eventHash]
  );
}

app.get("/wms/closure/dashboard", requirePermission("wms.view"), async (_req, res) => {
  try {
    const metrics = (await query("SELECT * FROM v_wms_closed_loop_dashboard")).rows[0] ?? {};
    const processMetrics = await query(`
      SELECT 'receiving' AS key,
             COUNT(*) FILTER (WHERE action='RECEIVE' AND occurred_at>=NOW()-INTERVAL '24 hours')::int AS "completed24h",
             0::int AS "openCount" FROM inventory_transactions
      UNION ALL SELECT 'iqc',
             COUNT(*) FILTER (WHERE iqc_status='released' AND updated_at>=NOW()-INTERVAL '24 hours')::int,
             COUNT(*) FILTER (WHERE iqc_status IN('pending','hold'))::int FROM material_lots
      UNION ALL SELECT 'putaway',
             COUNT(*) FILTER (WHERE iqc_status='released' AND storage_location_id IS NOT NULL AND updated_at>=NOW()-INTERVAL '24 hours')::int,
             COUNT(*) FILTER (WHERE iqc_status='released' AND storage_location_id IS NULL AND received_qty>0)::int FROM material_lots
      UNION ALL SELECT 'issue',
             COUNT(*) FILTER (WHERE action='ISSUE_TO_LINE' AND occurred_at>=NOW()-INTERVAL '24 hours')::int,
             0::int FROM inventory_transactions
      UNION ALL SELECT 'consumption',
             COUNT(*) FILTER (WHERE action='CONSUME' AND occurred_at>=NOW()-INTERVAL '24 hours')::int,
             0::int FROM inventory_transactions
      UNION ALL SELECT 'returns',
             COUNT(*) FILTER (WHERE action='RETURN_FROM_LINE' AND occurred_at>=NOW()-INTERVAL '24 hours')::int,
             0::int FROM inventory_transactions
      UNION ALL SELECT 'reconciliation',
             COUNT(*) FILTER (WHERE status='CLOSED' AND closed_at>=NOW()-INTERVAL '24 hours')::int,
             COUNT(*) FILTER (WHERE case_type='INVENTORY_DIFFERENCE' AND status NOT IN('CLOSED','CANCELLED','REJECTED'))::int FROM wms_closure_cases
      UNION ALL SELECT 'audit',
             COUNT(*) FILTER (WHERE created_at>=NOW()-INTERVAL '24 hours')::int,
             0::int FROM wms_closed_loop_audit`);
    const gateItems = await query(`
      SELECT 'iqc' AS "processKey",lot_no AS "entityKey",iqc_status AS state,
             received_qty AS quantity,created_at AS "openedAt",
             FLOOR(EXTRACT(EPOCH FROM (NOW()-created_at))/60)::int AS "ageMinutes",
             (created_at<NOW()-INTERVAL '120 minutes') AS overdue
      FROM material_lots WHERE iqc_status IN('pending','hold')
      UNION ALL
      SELECT 'putaway',lot_no,'WAITING_LOCATION',received_qty,updated_at,
             FLOOR(EXTRACT(EPOCH FROM (NOW()-updated_at))/60)::int,
             (updated_at<NOW()-INTERVAL '60 minutes')
      FROM material_lots WHERE iqc_status='released' AND storage_location_id IS NULL AND received_qty>0
      ORDER BY overdue DESC,"ageMinutes" DESC LIMIT 250`);
    const overdueTotals=(await query(`SELECT
      COUNT(*) FILTER (WHERE iqc_status IN('pending','hold') AND created_at<NOW()-INTERVAL '120 minutes')::int AS iqc,
      COUNT(*) FILTER (WHERE iqc_status='released' AND storage_location_id IS NULL AND received_qty>0 AND updated_at<NOW()-INTERVAL '60 minutes')::int AS putaway
      FROM material_lots`)).rows[0]??{};
    const cases = await query(
      `SELECT id,case_no AS "caseNo",case_type AS "caseType",entity_type AS "entityType",
              entity_key AS "entityKey",reason_code AS "reasonCode",risk_level AS "riskLevel",
              status,requested_by AS "requestedBy",requested_at AS "requestedAt",
              expected_qty AS "expectedQty",actual_qty AS "actualQty",difference_qty AS "differenceQty"
       FROM wms_closure_cases WHERE status NOT IN ('CLOSED','CANCELLED','REJECTED')
       ORDER BY CASE risk_level WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END,requested_at LIMIT 200`
    );
    const handovers = await query(
      `SELECT id,handover_no AS "handoverNo",entity_type AS "entityType",entity_key AS "entityKey",
              quantity,from_domain AS "fromDomain",to_domain AS "toDomain",status,
              sender_badge AS "senderBadge",receiver_badge AS "receiverBadge",
              sent_at AS "sentAt",received_at AS "receivedAt",due_at AS "dueAt",
              (status='IN_TRANSIT' AND due_at<NOW()) AS overdue
       FROM wms_custody_handovers WHERE status IN ('CREATED','IN_TRANSIT') ORDER BY due_at LIMIT 200`
    );
    const processPolicy={
      receiving:{owner:"WAREHOUSE_RECEIVING",slaMinutes:30,tab:"receiving"},
      iqc:{owner:"IQC",slaMinutes:120,tab:"iqcClosedLoop"},
      putaway:{owner:"WAREHOUSE_PUTAWAY",slaMinutes:60,tab:"putaway"},
      issue:{owner:"WAREHOUSE_ISSUE",slaMinutes:30,tab:"issue"},
      consumption:{owner:"PRODUCTION",slaMinutes:30,tab:"pdaConsumption"},
      returns:{owner:"WAREHOUSE_RETURN",slaMinutes:30,tab:"returnReceive"},
      reconciliation:{owner:"WAREHOUSE_CONTROL",slaMinutes:240,tab:"cycleCount"},
      audit:{owner:"WMS_CONTROL",slaMinutes:1440,tab:"transactions"},
    };
    const overdueByProcess={iqc:Number(overdueTotals.iqc??0),putaway:Number(overdueTotals.putaway??0)};
    res.json(envelope({ metrics, processes: processMetrics.rows.map(row=>({
      ...row,...processPolicy[row.key],overdueCount:overdueByProcess[row.key]??0,
      status:Number(row.openCount)>0?'ATTENTION':'CONTROLLED'
    })), gateItems:gateItems.rows, cases: cases.rows, handovers: handovers.rows }));
  } catch (error) {
    res.status(500).json(errorEnvelope("WMS_CLOSURE_DASHBOARD_FAILED", error.message));
  }
});

