app.get("/hr/mobile/swap/pending-confirmation/:employeeId", async (req, res) => {
  try {
    const { employeeId } = req.params;
    // status=supervisor_approved means supervisor approved, waiting for partner confirmation
    const [rows] = await pool.query(`
      SELECT ss.*, e1.name as requester_name, e1.code as requester_code
      FROM hr_shift_swaps ss
      LEFT JOIN hr_employees e1 ON ss.requester_id = e1.id
      WHERE ss.target_employee_id = ? AND ss.status = 'supervisor_approved'
      ORDER BY ss.created_at DESC
    `, [employeeId]);
    res.json(rows);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Q4: 被替岗人确认替岗
app.post("/hr/mobile/swap/confirm/:id", async (req, res) => {
  try {
    const { id } = req.params;
    const { partner_id } = req.body;
    // Verify the confirmer is the correct partner
    const [existing] = await pool.query(
      `UPDATE hr_shift_swaps SET status = 'partner_confirmed', partner_confirmed_at = NOW()
       WHERE id = ? AND target_employee_id = ? AND status = 'supervisor_approved'
       RETURNING *`,
      [id, partner_id]
    );
    if (!existing[0]?.affectedRows && existing[0]?.affectedRows !== 0) {
      // Try raw approach
      const [check] = await pool.query(`SELECT * FROM hr_shift_swaps WHERE id = ? AND target_employee_id = ? AND status = 'supervisor_approved'`, [id, partner_id]);
      if (!check.length) return res.status(400).json({ error: '无权确认或状态已变更' });
      await pool.query(`UPDATE hr_shift_swaps SET status = 'partner_confirmed', partner_confirmed_at = NOW() WHERE id = ?`, [id]);
    }
    // Notify requester
    const [swap] = await pool.query(`SELECT * FROM hr_shift_swaps WHERE id = ?`, [id]);
    if (swap.length) {
      await pool.query(
        `INSERT INTO hr_notifications (employee_id, title, body, type, is_read, created_at)
         VALUES (?, '【替岗已确认】', CONCAT('对方已确认您的替岗申请，将于 ', shift_date, ' 生效。'), 'swap_confirmed', 0, NOW())`,
        [swap[0].requester_id, swap[0].shift_date]
      );
    }
    res.json({ success: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Q4: 被替岗人拒绝替岗
app.post("/hr/mobile/swap/reject/:id", async (req, res) => {
  try {
    const { id } = req.params;
    const { partner_id, remark } = req.body;
    const [check] = await pool.query(
      `SELECT * FROM hr_shift_swaps WHERE id = ? AND target_employee_id = ? AND status = 'supervisor_approved'`,
      [id, partner_id]
    );
    if (!check.length) return res.status(400).json({ error: '无权操作或状态已变更' });
    await pool.query(
      `UPDATE hr_shift_swaps SET status = 'partner_rejected', partner_rejected_at = NOW(), remark = ? WHERE id = ?`,
      [remark || '对方拒绝', id]
    );
    // Notify requester
    const [swap] = await pool.query(`SELECT * FROM hr_shift_swaps WHERE id = ?`, [id]);
    if (swap.length) {
      await pool.query(
        `INSERT INTO hr_notifications (employee_id, title, body, type, is_read, created_at)
         VALUES (?, '【替岗被拒绝】', CONCAT('对方拒绝了您的替岗申请（', shift_date, '）。原因：', ?), 'swap_rejected', 0, NOW())`,
        [swap[0].requester_id, remark || '对方拒绝']
      );
    }
    res.json({ success: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

