// GET /finance/loss-analysis — 损耗分析（综合NG+报废+补偿）
api.get('/finance/loss-analysis', authenticateJWT, requirePermission('finance.cost.read'), async(req, res)=>{
  try{
    const{from,to}=req.query;
    const f=from?`'${from}'`:"NOW()-INTERVAL '30 days'";
    const t=to?`'${to}'`:'NOW()';
    const byType=await query(`
      SELECT event_type, COUNT(*) as count,
        COALESCE(SUM(loss_amount_usd),0) as total_loss,
        COALESCE(AVG(loss_amount_usd),0) as avg_loss
      FROM material_financial_events
      WHERE event_type IN ('NG_LOSS','SCRAP','COMPENSATION_REQUEST')
        AND occurred_at BETWEEN ${f} AND ${t}
      GROUP BY event_type ORDER BY total_loss DESC`);
    const topLoss=await query(`
      SELECT mfe.material_code, mfe.material_name_zh as material_name,
        SUM(mfe.loss_amount_usd)::float as total_loss,
        COUNT(*)::int as event_count
      FROM material_financial_events mfe
      WHERE mfe.loss_amount_usd>0 AND mfe.occurred_at BETWEEN ${f} AND ${t}
      GROUP BY mfe.material_code, mfe.material_name_zh ORDER BY total_loss DESC LIMIT 20`);
    res.json({success:true,byType:byType.rows,topLossMaterials:topLoss.rows,from,to});
  }catch(err){res.status(500).json(errorEnvelope('SERVER_ERROR',err.message));}
});

const mesWmsAcknowledgementWatchdog=setInterval(async()=>{
  try{
    const timedOut=await query(`UPDATE mes_wms_exchange_events e SET delivery_state=CASE
      WHEN attempt_count>=COALESCE(c.max_attempts,5) THEN 'QUARANTINED' ELSE 'PENDING' END,
      quarantine_reason=CASE WHEN attempt_count>=COALESCE(c.max_attempts,5) THEN 'ACKNOWLEDGEMENT_TIMEOUT' ELSE NULL END,
      last_error='ACKNOWLEDGEMENT_TIMEOUT',next_attempt_at=now()+make_interval(secs=>LEAST(300,POWER(2,LEAST(attempt_count,8))::int)),
      delivering_at=NULL,updated_at=now() FROM mes_wms_event_catalog c WHERE c.event_type=e.event_type
      AND e.delivery_state='DELIVERING' AND e.delivering_at<now()-make_interval(secs=>c.acknowledgement_timeout_seconds)
      RETURNING e.event_id,e.destination_node,e.delivery_state,e.attempt_count`);
    for(const row of timedOut.rows) neuralBroadcast({from:'mes_wms_exchange',to:'*',type:'MES_WMS_ACK_TIMEOUT',priority:'critical',
      payload:{eventId:row.event_id,destinationNode:row.destination_node,state:row.delivery_state,attemptCount:row.attempt_count}});
  }catch(error){console.error('MES/WMS acknowledgement watchdog:',error.message);}
},30000);
mesWmsAcknowledgementWatchdog.unref();

// Line leaders have five minutes to decide how to handle a reconciled offline
// violation. MES does not stop the line automatically; it keeps escalating the
// audible/visual alarm to production supervision until a decision is recorded.
const smtOfflineViolationWatchdog = setInterval(async () => {
  try {
    const overdue = await query(
      `SELECT event_id,work_order_code,machine_code,slot_no,material_code,lot_no,
              leader_deadline_at
       FROM smt_pda_offline_events
       WHERE review_status='VIOLATION' AND leader_decision IS NULL
         AND leader_deadline_at<=NOW()
       ORDER BY leader_deadline_at`
    );
    for (const row of overdue.rows) {
      neuralBroadcast({
        from: "smt_pda_offline_watchdog", to: "*",
        type: "SMT_OFFLINE_VIOLATION_OVERDUE", priority: "critical",
        payload: { ...row, escalation: "PRODUCTION_SUPERVISOR", lineStoppedAutomatically: false }
      });
    }
  } catch (error) {
    console.error("SMT offline violation watchdog:", error.message);
  }
}, 30_000);
smtOfflineViolationWatchdog.unref();

