// List equipment assets with filters
api.get('/equipment/assets', authenticateJWT, async (req, res) => {
  try {
    const { status, criticality, category, line, search, page = 1, limit = 50 } = req.query;
    let where = ['1=1'];
    const params = [];
    let pi = 1;
    if (status) { where.push(`ea.status = $${pi++}`); params.push(status); }
    if (criticality) { where.push(`ea.criticality = $${pi++}`); params.push(criticality); }
    if (category) { where.push(`ec.code = $${pi++}`); params.push(category); }
    if (line) { where.push(`pl.internal_code = $${pi++}`); params.push(line); }
    if (search) { where.push(`(ea.asset_code ILIKE $${pi} OR ea.name_zh ILIKE $${pi} OR ea.serial_no ILIKE $${pi})`); params.push(`%${search}%`); pi++; }
    const offset = (Number(page) - 1) * Number(limit);
    const { rows } = await query(
      `SELECT ea.*, ec.name_zh as category_zh, ec.code as category_code,
              em.vendor_name, em.model_name, pl.internal_code as line_code,
              s.code as station_code, el.name_zh as location_name
       FROM equipment_assets ea
       LEFT JOIN equipment_categories ec ON ec.id = ea.category_id
       LEFT JOIN equipment_models em ON em.id = ea.model_id
       LEFT JOIN production_lines pl ON pl.id = ea.line_id
       LEFT JOIN stations s ON s.id = ea.station_id
       LEFT JOIN equipment_locations el ON el.id = ea.location_id
       WHERE ${where.join(' AND ')}
       ORDER BY ea.asset_code
       LIMIT ${Number(limit)} OFFSET ${offset}`, params);
    const cnt = await query(`SELECT count(*) FROM equipment_assets ea LEFT JOIN equipment_categories ec ON ec.id=ea.category_id LEFT JOIN production_lines pl ON pl.id=ea.line_id WHERE ${where.join(' AND ')}`, params);
    res.json({ success: true, data: rows, total: Number(cnt.rows[0].count), page: Number(page), limit: Number(limit) });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

