// Update equipment asset
api.patch('/equipment/assets/:id', authenticateJWT, async (req, res) => {
  try {
    const { id } = req.params;
    const b = req.body;
    const fields = [];
    const params = [];
    let pi = 1;
    const map = { nameZh:'name_zh', nameEn:'name_en', nameVi:'name_vi', categoryId:'category_id', modelId:'model_id', lineId:'line_id', stationId:'station_id', locationId:'location_id', serialNo:'serial_no', criticality:'criticality', purchasePrice:'purchase_price', currency:'currency', depreciationYears:'depreciation_years', currentValue:'current_value', installDate:'install_date', commissionedDate:'commissioned_date', warrantyExpiry:'warranty_expiry', manufacturer:'manufacturer', manufactureDate:'manufacture_date', ratedPowerKw:'rated_power_kw', ratedVoltage:'rated_voltage', ratedSpeed:'rated_speed', dimensions:'dimensions', weightKg:'weight_kg', softwareVersion:'software_version', firmwareVersion:'firmware_version', parentAssetId:'parent_asset_id', qrCode:'qr_code', responsibleEngineerId:'responsible_engineer_id', status:'status', importCustomsNo:'import_customs_no', originCertificateNo:'origin_certificate_no', vnInspectionCertNo:'vn_inspection_cert_no' };
    for (const [k, col] of Object.entries(map)) {
      if (b[k] !== undefined) { fields.push(`${col} = $${pi++}`); params.push(b[k]); }
    }
    if (fields.length === 0) return res.json({ success: false, error: 'No fields to update' });
    fields.push(`updated_at = now()`);
    params.push(id);
    const { rows } = await query(`UPDATE equipment_assets SET ${fields.join(', ')} WHERE id = $${pi} RETURNING *`, params);
    if (!rows[0]) return res.status(404).json({ success: false, error: 'Not found' });
    res.json({ success: true, data: rows[0] });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

