    if (status) { where.push(`wo.status = $${pi++}`); params.push(status); }
    if (priority) { where.push(`wo.priority = $${pi++}`); params.push(priority); }
    if (urgency) { where.push(`wo.urgency_level = $${pi++}`); params.push(urgency); }
    if (woType) { where.push(`wo.wo_type = $${pi++}`); params.push(woType); }
    if (equipmentId) { where.push(`wo.equipment_id = $${pi++}`); params.push(equipmentId); }
    if (technician) { where.push(`wo.assigned_technician ILIKE $${pi++}`); params.push(`%${technician}%`); }
    if (dateFrom) { where.push(`wo.issue_time >= $${pi++}`); params.push(dateFrom); }
    if (dateTo) { where.push(`wo.issue_time <= $${pi++}`); params.push(dateTo); }
    const offset = (Number(page) - 1) * Number(limit);
    const { rows } = await query(
      `SELECT wo.*, ea.asset_code, ea.name_zh as equipment_name,
              fc.code as fault_code, fc.name_zh as fault_code_name
       FROM maintenance_work_orders wo
       LEFT JOIN equipment_assets ea ON ea.id = wo.equipment_id
       LEFT JOIN fault_codes fc ON fc.id = wo.fault_code_id
       WHERE ${where.join(' AND ')}
       ORDER BY wo.issue_time DESC
       LIMIT ${Number(limit)} OFFSET ${offset}`, params);
    const cnt = await query(`SELECT count(*) FROM maintenance_work_orders wo WHERE ${where.join(' AND ')}`, params);
    res.json({ success: true, data: rows, total: Number(cnt.rows[0].count), page: Number(page), limit: Number(limit) });
