// Complete repair
api.patch('/equipment/work-orders/:id/complete', authenticateJWT, async (req, res) => {
  try {
    const b = req.body;
    const totalCost = (b.repairCostLabor || 0) + (b.repairCostParts || 0) + (b.repairCostExternal || 0);
    const { rows } = await query(
      `UPDATE maintenance_work_orders SET
         status='completed', completed_at=now(), real_cause=$1, resolution_notes=$2,
         root_cause_category=$3, parts_used=$4, downtime_minutes=$5,
         repair_cost_labor=$6, repair_cost_parts=$7, repair_cost_external=$8, repair_cost_total=$9,
         is_external_repair=$10, external_vendor=$11, external_wo_no=$12, external_cost=$13,
         trial_pieces=$14, updated_at=now()
       WHERE id=$15 RETURNING *`,
      [b.realCause, b.resolutionNotes, b.rootCauseCategory, JSON.stringify(b.partsUsed || []), b.downtimeMinutes || 0,
       b.repairCostLabor || 0, b.repairCostParts || 0, b.repairCostExternal || 0, totalCost,
       b.isExternalRepair || false, b.externalVendor, b.externalWoNo, b.externalCost,
       b.trialPieces || 0, req.params.id]);
    if (!rows[0]) return res.status(404).json({ success: false, error: 'Not found' });
    // Update equipment stats
    if (rows[0].equipment_id) {
      await query(`UPDATE equipment_assets SET total_repair_count = total_repair_count + 1, total_repair_cost = total_repair_cost + $1 WHERE id = $2`, [totalCost, rows[0].equipment_id]);
    }
    res.json({ success: true, data: rows[0] });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

