// Escalate
api.patch('/equipment/work-orders/:id/escalate', authenticateJWT, async (req, res) => {
  try {
    const b = req.body;
    const { rows } = await query(
      `UPDATE maintenance_work_orders SET
         escalation_level = LEAST(escalation_level + 1, 4),
         escalated_at = now(), escalated_to = $1, updated_at = now()
       WHERE id=$2 RETURNING *`,
      [b.escalatedTo, req.params.id]);
    if (!rows[0]) return res.status(404).json({ success: false, error: 'Not found' });
    res.json({ success: true, data: rows[0] });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

// Work order stats (MTBF/MTTR/cost)
api.get('/equipment/work-orders/stats', authenticateJWT, async (req, res) => {
  try {
    const { days = 90 } = req.query;
    const stats = await query(
      `SELECT
         count(*) FILTER (WHERE status IN ('fixed','completed','closed')) as total_completed,
         count(*) FILTER (WHERE status NOT IN ('fixed','completed','closed')) as total_open,
         avg(downtime_minutes) FILTER (WHERE downtime_minutes > 0) as avg_downtime,
         sum(repair_cost_total) as total_cost,
         avg(repair_cost_total) FILTER (WHERE repair_cost_total > 0) as avg_cost_per_repair,
         count(*) FILTER (WHERE urgency_level = 'line_down') as line_down_count,
         count(*) FILTER (WHERE sla_breached) as sla_breached_count
       FROM maintenance_work_orders WHERE issue_time >= now() - $1::interval`, [`${days} days`]);
    // MTBF/MTTR per equipment
    const mtbf = await query(
      `SELECT ea.asset_code, ea.name_zh,
              count(wo.id) as repair_count,
              avg(wo.downtime_minutes) as mttr_minutes,
              sum(wo.repair_cost_total) as total_cost,
              ea.cumulative_runtime_hours,
              case when count(wo.id) > 0 and ea.cumulative_runtime_hours > 0
                then round((ea.cumulative_runtime_hours / count(wo.id))::numeric, 1) else null end as mtbf_hours
       FROM equipment_assets ea
       LEFT JOIN maintenance_work_orders wo ON wo.equipment_id = ea.id AND wo.issue_time >= now() - $1::interval
       GROUP BY ea.id, ea.asset_code, ea.name_zh, ea.cumulative_runtime_hours
       HAVING count(wo.id) > 0
       ORDER BY repair_count DESC LIMIT 20`, [`${days} days`]);
    // Fault pareto
    const pareto = await query(
      `SELECT fcc.name_zh as category, count(*) as cnt
       FROM maintenance_work_orders wo
       JOIN fault_codes fc ON fc.id = wo.fault_code_id
       JOIN fault_code_subcategories fsc ON fsc.id = fc.subcategory_id
       JOIN fault_code_categories fcc ON fcc.id = fsc.category_id
       WHERE wo.issue_time >= now() - $1::interval
       GROUP BY fcc.name_zh ORDER BY cnt DESC`, [`${days} days`]);
    res.json({ success: true, summary: stats.rows[0], mtbf_mttr: mtbf.rows, fault_pareto: pareto.rows });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

// ═══ Fault Codes (Q16-B) ═══

api.get('/equipment/fault-codes', authenticateJWT, async (req, res) => {
  try {
    const { rows } = await query(
      `SELECT fcc.id as category_id, fcc.code as category_code, fcc.name_zh as category_name,
              fsc.id as subcategory_id, fsc.code as subcategory_code, fsc.name_zh as subcategory_name,
              fc.id, fc.code, fc.name_zh, fc.name_en, fc.name_vi, fc.typical_cause, fc.typical_fix,
              fc.root_cause_category, fc.applicable_equipment_types, fc.severity
       FROM fault_code_categories fcc
       JOIN fault_code_subcategories fsc ON fsc.category_id = fcc.id
       JOIN fault_codes fc ON fc.subcategory_id = fsc.id
       WHERE fcc.status = 'active' AND fsc.status = 'active' AND fc.status = 'active'
       ORDER BY fcc.sort_order, fsc.sort_order, fc.sort_order`);
    // Build tree
    const tree = {};
    for (const r of rows) {
      if (!tree[r.category_code]) tree[r.category_code] = { id: r.category_id, code: r.category_code, name: r.category_name, children: {} };
      if (!tree[r.category_code].children[r.subcategory_code]) tree[r.category_code].children[r.subcategory_code] = { id: r.subcategory_id, code: r.subcategory_code, name: r.subcategory_name, items: [] };
      tree[r.category_code].children[r.subcategory_code].items.push(r);
    }
    res.json({ success: true, data: Object.values(tree).map(c => ({ ...c, children: Object.values(c.children) })) });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

