// ═══ PM Execution (Q3-D) ═══

api.get('/equipment/pm-executions', authenticateJWT, async (req, res) => {
  try {
    const { assetId, level, result, dateFrom, dateTo, page = 1, limit = 50 } = req.query;
    let where = ['1=1'];
    const params = [];
    let pi = 1;
    if (assetId) { where.push(`pe.asset_id = $${pi++}`); params.push(assetId); }
    if (level) { where.push(`pe.pm_level = $${pi++}`); params.push(level); }
    if (result) { where.push(`pe.result = $${pi++}`); params.push(result); }
    if (dateFrom) { where.push(`pe.scheduled_date >= $${pi++}`); params.push(dateFrom); }
    if (dateTo) { where.push(`pe.scheduled_date <= $${pi++}`); params.push(dateTo); }
    const offset = (Number(page) - 1) * Number(limit);
    const { rows } = await query(
      `SELECT pe.*, ea.asset_code, ea.name_zh as equipment_name,
              pt.template_name_zh, u.display_name as executor_name
       FROM pm_execution_records pe
       LEFT JOIN equipment_assets ea ON ea.id = pe.asset_id
       LEFT JOIN pm_templates pt ON pt.id = pe.template_id
       LEFT JOIN users u ON u.id = pe.executor_id
       WHERE ${where.join(' AND ')}
       ORDER BY pe.scheduled_date DESC, pe.created_at DESC
       LIMIT ${Number(limit)} OFFSET ${offset}`, params);
    const cnt = await query(`SELECT count(*) FROM pm_execution_records pe WHERE ${where.join(' AND ')}`, params);
    res.json({ success: true, data: rows, total: Number(cnt.rows[0].count) });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

api.post('/equipment/pm-executions', authenticateJWT, async (req, res) => {
  try {
    const b = req.body;
    const now = new Date();
    const execNo = `PM-${now.toISOString().slice(2, 10).replace(/-/g, '')}-${String(Math.floor(Math.random() * 9999)).padStart(4, '0')}`;
    const { rows } = await query(
      `INSERT INTO pm_execution_records (execution_no, template_id, asset_id, pm_level, trigger_type, scheduled_date, actual_start, executor_id, result)
       VALUES ($1,$2,$3,$4,$5,$6,now(),$7,'in_progress') RETURNING *`,
      [execNo, b.templateId, b.assetId, b.pmLevel, b.triggerType || 'manual', b.scheduledDate || now.toISOString().slice(0, 10), req.user?.id]);
    // Auto-create execution items from template tasks
    if (b.templateId) {
      const tasks = await query(`SELECT * FROM pm_template_tasks WHERE template_id = $1 AND status = 'active' ORDER BY task_no`, [b.templateId]);
      for (const t of tasks.rows) {
        await query(
          `INSERT INTO pm_execution_items (execution_id, template_task_id, task_no, task_name, standard_value)
           VALUES ($1,$2,$3,$4,$5)`,
          [rows[0].id, t.id, t.task_no, t.task_name_zh, t.standard_value]);
      }
    }
    res.json({ success: true, data: rows[0] });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

// Complete PM execution with checklist results
api.patch('/equipment/pm-executions/:id/complete', authenticateJWT, async (req, res) => {
  try {
    const b = req.body;
    // Update items
    if (b.items && Array.isArray(b.items)) {
      for (const item of b.items) {
        await query(
          `UPDATE pm_execution_items SET result=$1, measured_value=$2, notes=$3, checked_at=now(), photo_urls=$4 WHERE execution_id=$5 AND task_no=$6`,
          [item.result || 'ok', item.measuredValue, item.notes, item.photoUrls || [], req.params.id, item.taskNo]);
      }
    }
    const hasNG = b.items?.some(i => i.result === 'ng');
    const { rows } = await query(
      `UPDATE pm_execution_records SET
         result=$1, actual_end=now(), first_article_result=$2, abnormal_description=$3, notes=$4, updated_at=now()
       WHERE id=$5 RETURNING *`,
      [hasNG ? 'abnormal' : 'completed', b.firstArticleResult || 'na', b.abnormalDescription, b.notes, req.params.id]);
    if (!rows[0]) return res.status(404).json({ success: false, error: 'Not found' });
    // Update equipment PM count
    if (rows[0].asset_id) {
      await query(`UPDATE equipment_assets SET total_pm_count = total_pm_count + 1 WHERE id = $1`, [rows[0].asset_id]);
    }
    res.json({ success: true, data: rows[0] });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

