// ═══ P3: Equipment Health Score + OEE (Q8-D) ═══

api.get('/equipment/health', authenticateJWT, async (req, res) => {
  try {
    const { lineId } = req.query;
    let lineFilter = '';
    const params = [];
    if (lineId) { lineFilter = 'AND ea.line_id = $1'; params.push(lineId); }
    // Health score = weighted: availability(40%) + reliability(30%) + maintenance(20%) + age(10%)
    const { rows } = await query(`
      SELECT ea.id, ea.asset_code, ea.name_zh, ea.criticality, ea.status,
             ea.cumulative_runtime_hours, ea.total_repair_count, ea.total_repair_cost, ea.total_pm_count,
             ea.purchase_date, ea.warranty_expiry,
             ec.name_zh as category_name, pl.internal_code as line_code,
             -- Recent failures (90d)
             (SELECT count(*) FROM maintenance_work_orders wo WHERE wo.equipment_id = ea.id AND wo.issue_time >= now() - interval '90 days') as failures_90d,
             (SELECT avg(wo.downtime_minutes) FROM maintenance_work_orders wo WHERE wo.equipment_id = ea.id AND wo.issue_time >= now() - interval '90 days' AND wo.downtime_minutes > 0) as avg_downtime_90d,
             -- PM compliance (30d)
             (SELECT count(*) FROM pm_execution_records pe WHERE pe.asset_id = ea.id AND pe.scheduled_date >= current_date - 30 AND pe.result = 'completed') as pm_done_30d,
             (SELECT count(*) FROM pm_execution_records pe WHERE pe.asset_id = ea.id AND pe.scheduled_date >= current_date - 30) as pm_total_30d,
             -- Open work orders
             (SELECT count(*) FROM maintenance_work_orders wo WHERE wo.equipment_id = ea.id AND wo.status NOT IN ('fixed','closed','completed')) as open_wos
      FROM equipment_assets ea
      LEFT JOIN equipment_categories ec ON ec.id = ea.category_id
      LEFT JOIN production_lines pl ON pl.id = ea.line_id
      WHERE ea.status != 'scrapped' ${lineFilter}
      ORDER BY ea.criticality, ea.asset_code
    `, params);

    // Calculate health scores
    const scored = rows.map(r => {
      const failures = Number(r.failures_90d) || 0;
      const avgDown = Number(r.avg_downtime_90d) || 0;
      const pmDone = Number(r.pm_done_30d) || 0;
      const pmTotal = Number(r.pm_total_30d) || 0;
      const openWOs = Number(r.open_wos) || 0;
      const runtimeH = Number(r.cumulative_runtime_hours) || 0;
      // Availability score (0-100): based on status + open WOs
      let availability = 100;
      if (r.status === 'fault' || r.status === 'repair') availability = 20;
      else if (r.status === 'maintenance') availability = 60;
      else if (r.status === 'offline' || r.status === 'idle') availability = 70;
      availability -= openWOs * 10;
      availability = Math.max(0, Math.min(100, availability));
      // Reliability score: based on failure frequency
      let reliability = Math.max(0, 100 - failures * 15 - (avgDown > 60 ? 20 : avgDown > 30 ? 10 : 0));
      // Maintenance score: PM compliance
      let maintenance = pmTotal > 0 ? Math.round((pmDone / pmTotal) * 100) : 80;
      // Age score: depreciation
      let age = 90;
      if (r.purchase_date) {
        const years = (Date.now() - new Date(r.purchase_date).getTime()) / (365.25 * 24 * 3600 * 1000);
        age = Math.max(30, 100 - years * 7);
      }
      const healthScore = Math.round(availability * 0.4 + reliability * 0.3 + maintenance * 0.2 + age * 0.1);
      const grade = healthScore >= 90 ? 'A' : healthScore >= 75 ? 'B' : healthScore >= 60 ? 'C' : healthScore >= 40 ? 'D' : 'F';
      return {
        ...r,
        health_score: healthScore,
        grade,
        availability_score: Math.round(availability),
        reliability_score: Math.round(reliability),
        maintenance_score: Math.round(maintenance),
        age_score: Math.round(age),
        failures_90d: failures,
        avg_downtime_90d: Math.round(avgDown),
        pm_compliance: pmTotal > 0 ? Math.round((pmDone / pmTotal) * 100) : null,
        open_wos: openWOs,
      };
    });

    // Summary stats
    const avgHealth = scored.length ? Math.round(scored.reduce((s, r) => s + r.health_score, 0) / scored.length) : 0;
    const gradeDistribution = { A: 0, B: 0, C: 0, D: 0, F: 0 };
    scored.forEach(r => gradeDistribution[r.grade]++);
    const criticalAlerts = scored.filter(r => r.grade === 'F' || (r.criticality === 'A' && r.health_score < 60));

    res.json({
      success: true,
      summary: { avg_health: avgHealth, total: scored.length, grade_distribution: gradeDistribution, critical_alerts: criticalAlerts.length },
      data: scored,
      critical_alerts: criticalAlerts,
    });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

