api.get('/equipment/andon', authenticateJWT, async (req, res) => {
  try {
    const { lineId } = req.query;
    let lineFilter = '';
    const params = [];
    if (lineId) { lineFilter = 'WHERE ea.line_id = $1'; params.push(lineId); }
    // All active equipment with real-time status
    const equipment = await query(`
      SELECT ea.id, ea.asset_code, ea.name_zh, ea.criticality, ea.status,
             ec.name_zh as category_name, pl.internal_code as line_code,
             s.code as station_code,
             (SELECT wo.wo_no FROM maintenance_work_orders wo WHERE wo.equipment_id = ea.id AND wo.status NOT IN ('fixed','closed','completed') ORDER BY wo.issue_time DESC LIMIT 1) as active_wo,
             (SELECT wo.fault_description FROM maintenance_work_orders wo WHERE wo.equipment_id = ea.id AND wo.status NOT IN ('fixed','closed','completed') ORDER BY wo.issue_time DESC LIMIT 1) as active_fault,
             (SELECT wo.urgency_level FROM maintenance_work_orders wo WHERE wo.equipment_id = ea.id AND wo.status NOT IN ('fixed','closed','completed') ORDER BY wo.issue_time DESC LIMIT 1) as active_urgency
      FROM equipment_assets ea
      LEFT JOIN equipment_categories ec ON ec.id = ea.category_id
      LEFT JOIN production_lines pl ON pl.id = ea.line_id
      LEFT JOIN stations s ON s.id = ea.station_id
      ${lineFilter}
      ORDER BY pl.internal_code, ea.asset_code
    `, params);
    // Active alerts (unresolved WOs)
    const alerts = await query(`
      SELECT wo.id, wo.wo_no, wo.fault_description, wo.urgency_level, wo.priority, wo.status, wo.issue_time, wo.assigned_technician,
             ea.asset_code, ea.name_zh as equipment_name, ea.criticality
      FROM maintenance_work_orders wo
      JOIN equipment_assets ea ON ea.id = wo.equipment_id
      WHERE wo.status NOT IN ('fixed','closed','completed')
      ORDER BY CASE wo.urgency_level WHEN 'line_down' THEN 0 WHEN 'speed_reduced' THEN 1 WHEN 'can_continue' THEN 2 ELSE 3 END, wo.issue_time DESC
      LIMIT 20
    `);
    // Today's PM status
    const pmToday = await query(`
      SELECT pe.*, ea.asset_code, ea.name_zh as equipment_name
      FROM pm_execution_records pe
      JOIN equipment_assets ea ON ea.id = pe.asset_id
      WHERE pe.scheduled_date = current_date
      ORDER BY pe.result, pe.scheduled_date
    `);
    res.json({
      success: true,
      timestamp: new Date().toISOString(),
      equipment: equipment.rows,
      alerts: alerts.rows,
      pm_today: pmToday.rows,
      stats: {
        total: equipment.rows.length,
        running: equipment.rows.filter(e => ['active', 'online'].includes(e.status)).length,
        fault: equipment.rows.filter(e => ['fault', 'repair'].includes(e.status)).length,
        maintenance: equipment.rows.filter(e => e.status === 'maintenance').length,
        idle: equipment.rows.filter(e => ['idle', 'offline'].includes(e.status)).length,
        active_alerts: alerts.rows.length,
      }
    });
  } catch (err) { res.status(500).json({ success: false, error: err.message }); }
});

