// SSE endpoint for station-level real-time updates
// Uses polling + change detection to send BATCH_UPDATE only when data changes
const stationSseState = new Map(); // stationCode → { lastHash, interval }

app.get("/api/station/sse/:stationCode", (req, res) => {
  const { stationCode } = req.params;
  const cleanCode = String(stationCode || '').trim().toLowerCase();
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();

  // Welcome message
  res.write(`data: ${JSON.stringify({ type: "CONNECTED", stationCode: cleanCode, msg: `SSE connected for station ${cleanCode}` })}\n\n`);

  let lastHash = "";
  let interval;

  // Send snapshot + start polling
  ;(async () => {
    try {
      const buckets = await readStationBuckets(cleanCode);
      const hash = hashBuckets(buckets);
      lastHash = hash;
      stationSseState.set(cleanCode, { lastHash, interval: null });
      res.write(`data: ${JSON.stringify({ type: "SNAPSHOT_REFRESH", stationCode: cleanCode, timestamp: Date.now(), buckets })}\n\n`);
    } catch (_e) { /* non-fatal */ }
  })();

  // Poll every 2 seconds for changes
  interval = setInterval(async () => {
    try {
      const buckets = await readStationBuckets(cleanCode);
      const hash = hashBuckets(buckets);
      if (hash !== lastHash) {
        lastHash = hash;
        stationSseState.set(cleanCode, { lastHash, interval });
        res.write(`data: ${JSON.stringify({ type: "BATCH_UPDATE", stationCode: cleanCode, timestamp: Date.now(), buckets })}\n\n`);
      }
    } catch (_e) { /* non-fatal */ }
  }, 2000);

  // Heartbeat every 30s
  const heartbeat = setInterval(() => {
    try { res.write(": heartbeat\n\n"); } catch { clearInterval(heartbeat); clearInterval(interval); stationSseState.delete(cleanCode); }
  }, 30000);

  req.on("close", () => { clearInterval(heartbeat); clearInterval(interval); stationSseState.delete(cleanCode); });
});

// Lightweight hash for bucket change detection
function hashBuckets(buckets) {
  const str = JSON.stringify({
    p: (buckets.pending_ng || []).length,
    c: (buckets.confirmed_ng || []).length,
    pa: (buckets.pass || []).length,
    s: JSON.stringify(buckets.stats || {}),
  });
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  return `h${h >>> 0}`;
}



// Depanel NG migration — specialized endpoint with sourceStation pre-set to manu_depanel
// Same logic as main /api/station/maintenance-handovers but scoped to Depanel
app.post("/api/station/maintenance-handovers/depanel", async (req, res) => {
  // Force sourceStation = manu_depanel and forward to main handler
  const body = req.body || {};
  const payload = { ...body, sourceStation: "manu_depanel", sourceStationName: String(body.sourceStationName || "manu_depanel") };
  // Rewrite the request body for the main handler
  const originalBody = req.body;
  req.body = payload;
  // Call the main handler via a slight detour — we re-use the same logic inline
  // so we don't double-wrap. The logic below mirrors the main endpoint.
  try {
    await Promise.all([stationRouteRequestReady, stationHandoverReady, stationRepairWorkOrderReady]);
    const { sourceStation, sourceStationName, ngSn, batchId, members, motherboard, firstDetectedAt,
            repairDeadlineAt, defectType, defectCode, confirmedBy, confirmedRole, submittedBy, submittedRole,
            ngCategory, clickedAt } = req.body || {};
    const cleanStation = String(sourceStation || "manu_depanel").trim();
    const cleanStationName = String(sourceStationName || cleanStation).trim();
    const cleanNgSn = String(ngSn || "").trim().toUpperCase();
    const cleanBatchId = String(batchId || cleanNgSn).trim();
    const cleanMembers = Array.isArray(members) ? members : [];
    const cleanMotherboard = motherboard || { batchId: cleanBatchId, mainSn: cleanNgSn, subBoards: cleanMembers.length ? cleanMembers : [{ sn: cleanNgSn, result: "FAIL" }] };
    const firstDetectedAtMs = Number(firstDetectedAt || clickedAt || Date.now());
    const repairDeadlineAtMs = Number(repairDeadlineAt || firstDetectedAtMs + 120 * 60 * 1000);
    if (!cleanStation || !cleanNgSn) return res.status(400).json(errorEnvelope("VALIDATION", "sourceStation and ngSn required"));
    // Depanel-specific validation: look up confirmed NG
    const depanelState = await readStationBuckets("manu_depanel");
    const selected = depanelState.confirmed_ng.find(item =>
      String(item.sn || "").trim().toUpperCase() === cleanNgSn || String(item.batchId || "") === cleanBatchId);
    const cleanDefectType = String(defectType || defectCode || selected?.defectCode || ngCategory || "").trim().toUpperCase();
    const validationRoutes = { ICT_ONLY_NG: ["manu_ict"], FCT_ONLY_NG: ["manu_fct"], ICT_FCT_NG: ["manu_ict", "manu_fct"] };
    const returnStations = validationRoutes[cleanDefectType];
    if (!selected) return res.status(409).json(errorEnvelope("DEPANEL_CONFIRMED_NG_NOT_FOUND", "SN must exist in Depanel confirmed NG box before migration"));
    if (!returnStations) return res.status(422).json(errorEnvelope("DEPANEL_NG_TYPE_REQUIRED", "Depanel NG type must be ICT_ONLY_NG, FCT_ONLY_NG, or ICT_FCT_NG"));
    cleanMotherboard.subBoards = (Array.isArray(cleanMotherboard.subBoards) ? cleanMotherboard.subBoards : [{ sn: cleanNgSn, result: "FAIL" }]).map(board => ({
      ...board,
      defectCode: cleanDefectType,
      ngType: cleanDefectType,
      originStationCode: "manu_depanel",
      returnStationCode: returnStations[0],
      returnStations,
      validationRoute: returnStations,
      validationRule: returnStations.length > 1 ? "ICT_THEN_FCT" : "ORIGIN_TEST_POSITION_ONLY",
    }));
    cleanMotherboard.depanelNgType = cleanDefectType;
    cleanMotherboard.validationRoute = returnStations;
    // Check for existing route request
    const existing = await query(`SELECT request_id, submitted_at FROM station_route_requests WHERE batch_id=$1 AND source_station=$2 AND destination_station='manu_rework' AND status IN('WAITING_RECEIPT','REPAIR_IN_PROGRESS') ORDER BY submitted_at DESC LIMIT 1`, [cleanBatchId, cleanStation]);
    let requestId, submittedAt;
    if (existing.rows.length) { requestId = existing.rows[0].request_id; submittedAt = existing.rows[0].submitted_at; }
    else {
      const created = await query(`INSERT INTO station_route_requests (batch_id,source_station,destination_code,destination_station,workflow_code,motherboard,status,submitted_by,processed_at,notification_status,extra_data,submitted_at) VALUES ($1,$2,'MAINTENANCE','manu_rework','MES_REPAIR_HANDOVER',$3,'WAITING_RECEIPT',$4,NOW(),'SENT',$5,TO_TIMESTAMP($6::double precision/1000)) RETURNING request_id,submitted_at`, [cleanBatchId, cleanStation, JSON.stringify(cleanMotherboard), String(confirmedBy || submittedBy || "").trim(), JSON.stringify({ sourceStation: cleanStation, sourceStationName: cleanStationName, ngSn: cleanNgSn, depanelNgType: cleanDefectType }), Date.now()]);
      requestId = created.rows[0].request_id; submittedAt = created.rows[0].submitted_at;
    }
    const eventPayload = { requestId, batchId: cleanBatchId, sourceStation: cleanStation, ngSn: cleanNgSn, depanelNgType: cleanDefectType, returnStations, memberCount: cleanMotherboard.subBoards.length, submittedBy: confirmedBy || submittedBy, submittedRole: confirmedRole || submittedRole };
    neuralBroadcast({ from: "mes_server", to: "*", type: "MAINTENANCE_HANDOVER_BILL_CREATED", priority: "critical", stationCode: cleanStation, payload: eventPayload });
    neuralBroadcast({ from: "mes_server", to: cleanStation, type: "ORIGIN_NG_MIGRATION_CONFIRMED", priority: "important", stationCode: cleanStation, payload: eventPayload });
    neuralBroadcast({ from: "mes_server", to: "manu_rework", type: "MAINTENANCE_NG_TASK_RECEIVED", priority: "critical", stationCode: "manu_rework", payload: { ...eventPayload, repairDeadlineAt: repairDeadlineAtMs } });
    // Also create repair work order
    let repairWorkOrderNo;
    try {
      const woResult = await query(`INSERT INTO station_repair_work_orders (work_order_no,request_id,batch_id,sn,defect_code,defect_type,source_station,destination_station,status,submitted_by,submitted_role,priority,due_at) VALUES ($1,$2,$3,$4,$5,$6,$7,'manu_rework','WAITING_REPAIR',$8,$9,'STANDARD',TO_TIMESTAMP($10::double precision/1000)) RETURNING work_order_no`, [`REPAIR-${cleanBatchId}-${Date.now()}`, requestId, cleanBatchId, cleanNgSn, cleanDefectType, cleanDefectType, cleanStation, String(confirmedBy || submittedBy || "").trim(), String(confirmedRole || submittedRole || "").trim(), repairDeadlineAtMs]);
      repairWorkOrderNo = woResult.rows[0]?.work_order_no;
    } catch (_woErr) { /* non-fatal — WO creation is secondary */ }
    res.json({ ok: true, code: "DEPANEL_NG_MIGRATED", requestId, batchId: cleanBatchId, depanelNgType: cleanDefectType, returnStations, repairWorkOrderNo, submittedAt });
  } catch (err) {
    console.error("POST /api/station/maintenance-handovers/depanel:", err.message);
    res.status(500).json(errorEnvelope("SERVER_ERROR", err.message));
  } finally {
    req.body = originalBody; // restore
  }
});


// Broadcast a BATCH_UPDATE event when station buckets change
// Components call this after writing to /api/station/bucket-snapshots
app.post("/api/station/sse/broadcast", async (req, res) => {
  const { stationCode, eventType = "BATCH_UPDATE" } = req.body || {};
  if (!stationCode) return res.status(400).json(errorEnvelope("VALIDATION", "stationCode required"));
  const cleanCode = String(stationCode).trim().toLowerCase();
  try {
    const buckets = await readStationBuckets(cleanCode);
    neuralBroadcast({
      from: "mes_server",
      to: `station:${cleanCode}`,
      type: eventType,
      stationCode: cleanCode,
      payload: { buckets },
      priority: "info",
    });
    res.json({ success: true, stationCode: cleanCode });
  } catch (e) {
    res.status(500).json(errorEnvelope("SERVER_ERROR", e.message));
  }
});

// Repair station integration boundary. MES remains the authority: this API
// only composes current MES/WMS/QMS facts and appends auditable commands.
app.get("/api/repair-station/context", async (req, res) => {
  const sn = String(req.query.sn || "").trim().toUpperCase();
  const workOrderNo = String(req.query.workOrderNo || "").trim();
  if (!sn && !workOrderNo) return res.status(400).json(errorEnvelope("VALIDATION", "sn or workOrderNo required"));
  const safe = async (fallback, fn) => { try { return await fn(); } catch (error) { return { ...fallback, available: false, error: error.message }; } };
  const mes = await safe({ available: false, workOrder: null, events: [] }, async () => {
    const wo = await query(`SELECT work_order_no AS "workOrderNo",ng_sn AS "sn",source_station AS "sourceStation",destination_station AS "destinationStation",status,repair_result AS "repairResult",priority,due_at AS "dueAt",repair_started_at AS "repairStartedAt",repair_completed_at AS "repairCompletedAt" FROM station_repair_work_orders WHERE ($1='' OR work_order_no=$1) AND ($2='' OR UPPER(ng_sn)=UPPER($2)) ORDER BY created_at DESC LIMIT 1`, [workOrderNo, sn]);
    const eventParams = []; const eventWhere = [];
    if (sn) { eventParams.push(sn); eventWhere.push(`UPPER(payload->>'sn')=UPPER($${eventParams.length})`); }
    if (workOrderNo) { eventParams.push(workOrderNo); eventWhere.push(`payload->>'repairWorkOrderNo'=$${eventParams.length}`); }
    const events = await query(`SELECT event_id AS "eventId",event_type AS "eventType",payload,received_at AS "receivedAt" FROM station_production_events WHERE ${eventWhere.join(" OR ")} ORDER BY received_at DESC LIMIT 100`, eventParams);
    return { available: true, workOrder: wo.rows[0] || null, events: events.rows };
  });
  const wms = await safe({ available: false, lots: [] }, async () => {
    const rows = await query(`SELECT ml.lot_no AS "lotNo",ml.label_id AS "labelId",m.code AS "materialCode",m.name_zh AS "materialName",ml.iqc_status AS "iqcStatus",ml.lot_status AS "lotStatus",ml.received_qty AS "receivedQty",COALESCE(ml.reserved_qty,0) AS "reservedQty" FROM material_lots ml LEFT JOIN materials m ON m.id=ml.material_id WHERE ($1='' OR UPPER(ml.lot_no)=UPPER($1) OR UPPER(COALESCE(ml.label_id,''))=UPPER($1)) ORDER BY ml.created_at DESC LIMIT 50`, [String(req.query.lotNo || "").trim()]);
    return { available: true, lots: rows.rows };
  });
  const qms = await safe({ available: false, case: null, evidence: [] }, async () => {
    const cases = await query(`SELECT id,case_no AS "caseNo",sn,work_order_code AS "workOrderCode",station_code AS "stationCode",status,defect_code AS "defectCode",defect_desc AS "defectDescription",qty,repair_count AS "repairCount",retest_count AS "retestCount",repair_station AS "repairStation",updated_at AS "updatedAt" FROM qms_ng_cases WHERE ($1='' OR UPPER(sn)=UPPER($1)) AND ($2='' OR work_order_code=$2) ORDER BY updated_at DESC LIMIT 1`, [sn, workOrderNo]);
    const evidence = await query(`SELECT event_id AS "eventId",payload,received_at AS "receivedAt" FROM station_production_events WHERE event_type='REPAIR_QMS_EVIDENCE_ATTACHED' AND ($1='' OR UPPER(payload->>'sn')=UPPER($1)) ORDER BY received_at DESC LIMIT 100`, [sn]);
    return { available: true, case: cases.rows[0] || null, evidence: evidence.rows };
  });
  res.json({ ok: true, data: { sn, workOrderNo, mes, wms, qms, generatedAt: new Date().toISOString() } });
});

app.post("/api/repair-station/commands", async (req, res) => {
  const body = req.body || {};
  const eventId = String(body.eventId || "").trim();
  const type = String(body.type || "").trim().toUpperCase();
  const stationCode = String(body.stationCode || "manu_rework").trim();
  const sn = String(body.sn || "").trim().toUpperCase();
  const operator = String(body.operator || "").trim();
  const allowed = new Set(["REPAIR_STARTED", "MATERIAL_USAGE_RECORDED", "QMS_EVIDENCE_ATTACHED", "RETEST_REQUESTED"]);
  if (!eventId || eventId.length > 160 || !allowed.has(type) || !stationCode || !sn || !operator) {
    return res.status(400).json(errorEnvelope("VALIDATION", "eventId, allowed type, stationCode, sn and operator are required"));
  }
  const payload = body.payload && typeof body.payload === "object" ? body.payload : {};
  if (JSON.stringify(payload).length > 16000) return res.status(413).json(errorEnvelope("PAYLOAD_TOO_LARGE", "repair command payload exceeds 16KB"));
  if (type === "MATERIAL_USAGE_RECORDED" && (!String(payload.materialCode || "").trim() || !String(payload.lotNo || "").trim() || Number(payload.quantity) <= 0)) {
    return res.status(400).json(errorEnvelope("INVALID_MATERIAL_USAGE", "materialCode, lotNo and positive quantity are required"));
  }
  try {
    await stationEventLedgerReady;
    const eventPayload = { eventId, type, authority: "MES", stationCode, sn, workOrderNo: String(body.workOrderNo || "").trim() || null, operator, payload, occurredAt: String(body.occurredAt || new Date().toISOString()) };
    const inserted = await query(`INSERT INTO station_production_events(event_id,station_code,event_type,payload) VALUES($1,$2,$3,$4) ON CONFLICT(event_id) DO NOTHING RETURNING event_id`, [eventId, stationCode, `REPAIR_${type}`, JSON.stringify(eventPayload)]);
    if (inserted.rows.length) neuralBroadcast({ from: "repair_station", to: "mes_server", type: `REPAIR_${type}`, stationCode, priority: "important", payload: eventPayload });
    res.status(inserted.rows.length ? 201 : 200).json(envelope({ accepted: true, replay: !inserted.rows.length, eventId, authority: "MES" }));
  } catch (error) {
    res.status(500).json(errorEnvelope("REPAIR_COMMAND_FAILED", error.message));
  }
});

// Export a traceable repair workbook. The workbook contains facts and file
// references only; it never changes MES/WMS/QMS state.
app.get("/api/repair-station/work-orders", async (req, res) => {
  try {
    const stationCode = String(req.query.stationCode || "").trim();
    const limit = Math.min(Math.max(Number(req.query.limit) || 10, 1), 100);
    const params = [limit];
    const where = ["1=1"];
    if (stationCode) { params.unshift(stationCode); where.push(`(r.source_station=$1 OR r.destination_station=$1)`); }
    const limitParam = `$${params.length}`;
    const rows = await query(`SELECT r.work_order_no AS "repairWorkOrderNo",r.ng_sn AS "sn",r.batch_id AS "batchId",r.source_station AS "sourceStation",r.destination_station AS "destinationStation",r.status,r.created_at AS "issuedAt",r.received_at AS "receivedAt",r.repair_started_at AS "repairStartedAt",r.repair_completed_at AS "repairCompletedAt",r.updated_at AS "updatedAt",COUNT(*) OVER (PARTITION BY r.batch_id) AS "batchWoCount",MIN(r.created_at) OVER (PARTITION BY r.batch_id) AS "batchStartedAt",MAX(r.updated_at) OVER (PARTITION BY r.batch_id) AS "batchLastUpdatedAt",(SELECT COALESCE(json_agg(json_build_object('sn',r2.ng_sn,'workOrderNo',r2.work_order_no,'status',r2.status) ORDER BY r2.created_at),'[]'::json) FROM station_repair_work_orders r2 WHERE r2.batch_id=r.batch_id) AS "batchMembers",COALESCE(q.qty,1) AS quantity FROM station_repair_work_orders r LEFT JOIN LATERAL (SELECT qty FROM qms_ng_cases WHERE UPPER(sn)=UPPER(r.ng_sn) ORDER BY updated_at DESC LIMIT 1) q ON TRUE WHERE ${where.join(" AND ")} ORDER BY r.created_at DESC LIMIT ${limitParam}`, params);
    res.json({ ok: true, items: rows.rows });
  } catch (error) { res.status(500).json(errorEnvelope("REPAIR_WO_QUERY_FAILED", error.message)); }
});

app.get("/api/repair-station/export", async (req, res) => {
  try {
    const status = String(req.query.status || "").trim();
    const stationCode = String(req.query.stationCode || "").trim();
    const limit = Math.min(Math.max(Number(req.query.limit) || 5000, 1), 5000);
    const params = []; const conditions = ["1=1"];
    if (status) { params.push(status); conditions.push(`r.status=$${params.length}`); }
    if (stationCode) { params.push(stationCode); conditions.push(`r.destination_station=$${params.length}`); }
    params.push(limit);
    const workOrders = (await query(`SELECT r.work_order_no AS "workOrderNo",r.ng_sn AS "sn",r.batch_id AS "batchId",r.source_station AS "sourceStation",r.destination_station AS "destinationStation",r.status,r.repair_result AS "repairResult",r.priority,r.due_at AS "dueAt",r.submitted_by AS "submittedBy",r.repair_operator AS "repairOperator",r.repair_method AS "repairMethod",r.repair_started_at AS "repairStartedAt",r.repair_completed_at AS "repairCompletedAt",r.created_at AS "createdAt",r.updated_at AS "updatedAt",r.route_request_id AS "requestId" FROM station_repair_work_orders r WHERE ${conditions.join(" AND ")} ORDER BY r.created_at DESC LIMIT $${params.length}`, params)).rows;
    const sns = workOrders.map(row => String(row.sn || "")).filter(Boolean);
    const wos = workOrders.map(row => String(row.workOrderNo || "")).filter(Boolean);
    const batches = workOrders.map(row => String(row.batchId || "")).filter(Boolean);
    const [ngRows, materialRows, eventRows, handoverRows, qmsRows] = sns.length ? await Promise.all([
      query(`SELECT ng_defect_id AS "ngDefectId",sn,batch_id AS "batchId",station_code AS "stationCode",defect_code AS "defectCode",defect_description AS "defectDescription",result,repair_status AS "repairStatus",operator,created_at AS "createdAt" FROM ng_defect_records WHERE UPPER(sn)=ANY($1::text[]) ORDER BY created_at`, [sns.map(value => value.toUpperCase())]),
      query(`SELECT usage_id AS "usageId",work_order_no AS "workOrderNo",ng_sn AS "sn",material_code AS "materialCode",material_name AS "materialName",quantity,unit,operator,detail,recorded_at AS "recordedAt" FROM station_repair_material_usage WHERE work_order_no=ANY($1::text[]) ORDER BY recorded_at`, [wos]),
      query(`SELECT event_id AS "eventId",event_type AS "eventType",station_code AS "stationCode",payload,received_at AS "receivedAt" FROM station_production_events WHERE payload->>'repairWorkOrderNo'=ANY($1::text[]) OR payload->>'workOrderNo'=ANY($1::text[]) OR UPPER(payload->>'sn')=ANY($2::text[]) ORDER BY received_at`, [wos, sns.map(value => value.toUpperCase())]),
      query(`SELECT request_id AS "requestId",batch_id AS "batchId",source_station AS "sourceStation",destination_station AS "destinationStation",workflow_code AS "workflowCode",status,submitted_by AS "submittedBy",submitted_at AS "submittedAt",processed_at AS "processedAt",completed_at AS "completedAt",notification_status AS "notificationStatus",detail FROM station_route_requests WHERE batch_id=ANY($1::text[]) ORDER BY submitted_at`, [batches]),
      query(`SELECT id,case_no AS "caseNo",sn,work_order_code AS "workOrderCode",station_code AS "stationCode",status,defect_code AS "defectCode",defect_desc AS "defectDescription",qty,repair_count AS "repairCount",retest_count AS "retestCount",repair_station AS "repairStation",updated_at AS "updatedAt" FROM qms_ng_cases WHERE UPPER(sn)=ANY($1::text[]) ORDER BY updated_at`, [sns.map(value => value.toUpperCase())]),
    ]) : [{ rows: [] }, { rows: [] }, { rows: [] }, { rows: [] }, { rows: [] }];
    const events = eventRows.rows || [];
    const attachmentRefs = [];
    for (const event of events) {
      const payload = event.payload || {};
      const values = [["attachment", payload.attachmentUrl], ["file", payload.fileUrl], ["photo", payload.photoUrl], ["evidence", payload.evidenceUrl], ...(Array.isArray(payload.attachments) ? payload.attachments.map(item => ["attachment", item]) : [])];
      for (const [kind, value] of values) {
        const reference = typeof value === "string" ? value.trim() : String(value?.url || "").trim();
        if (reference) attachmentRefs.push({ eventId: event.eventId, kind, reference });
      }
    }
    const wb = XLSX.utils.book_new();
    const addSheet = (name, rows) => XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows.length ? rows : [{ info: "No records" }]), name);
    addSheet("WorkOrders", workOrders);
    addSheet("NGEvents", ngRows.rows);
    addSheet("RepairMaterials", materialRows.rows);
    addSheet("RepairEvents", events.map(row => ({ ...row, payload: JSON.stringify(row.payload || {}) })));
    addSheet("Handovers", handoverRows.rows);
    addSheet("QMSCases", qmsRows.rows);
    addSheet("RelatedFiles", attachmentRefs);
    const buffer = XLSX.write(wb, { bookType: "xlsx", type: "buffer" });
    const filename = `repair_work_orders_${new Date().toISOString().slice(0, 10)}.xlsx`;
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"; filename*=UTF-8''${encodeURIComponent(filename)}`);
    res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    res.setHeader("Content-Length", buffer.length);
    res.end(buffer);
  } catch (error) {
    console.error("GET /api/repair-station/export:", error.message);
    res.status(500).json(errorEnvelope("REPAIR_EXPORT_FAILED", error.message));
  }
});
